namespace {

	template <typename TCommand>
	bool SourceJSConCommandFlagIsSet(TCommand* const pCommandBase, const int nFlag) {
		if constexpr (requires(TCommand* pCommand) { pCommand->IsFlagSet(nFlag); }) {
			return pCommandBase->IsFlagSet(nFlag);
		} else {
			return pCommandBase->IsBitSet(nFlag);
		}
	}

	int SourceJSGetConCommandFlags(ConCommandBase* const pCommandBase) {
		constexpr std::size_t kBitsPerByte = 8;
		constexpr std::size_t kFlagBitCount = sizeof(int) * kBitsPerByte;

		if (!pCommandBase) {
			return 0;
		}

		unsigned int unFlags = 0;
		for (std::size_t unBit = 0; unBit < kFlagBitCount; ++unBit) {
			const unsigned int unFlag = static_cast<unsigned int>(1) << unBit;
			if (SourceJSConCommandFlagIsSet(pCommandBase, static_cast<int>(unFlag))) {
				unFlags |= unFlag;
			}
		}

		return static_cast<int>(unFlags);
	}

	template <typename TCommand>
	bool SourceJSRemoveConCommandFlagsForType(TCommand* const pCommandBase, const int nFlags) {
		if constexpr (requires(TCommand* pCommand) { pCommand->RemoveFlags(0); }) {
			pCommandBase->RemoveFlags(nFlags);
			return true;
		}

		return nFlags == 0;
	}

	bool SourceJSSetConCommandFlags(ConCommandBase* const pCommandBase, const int nFlags) {
		if (!pCommandBase) {
			return false;
		}

		const int nCurrentFlags = SourceJSGetConCommandFlags(pCommandBase);
		if (!SourceJSRemoveConCommandFlagsForType(pCommandBase, nCurrentFlags & ~nFlags)) {
			return false;
		}

		pCommandBase->AddFlags(nFlags & ~nCurrentFlags);

		return true;
	}

	void SourceJSAddConCommandFlags(ConCommandBase* const pCommandBase, const int nFlags) {
		if (!pCommandBase) {
			return;
		}

		pCommandBase->AddFlags(nFlags);
	}

	bool SourceJSRemoveConCommandFlags(ConCommandBase* const pCommandBase, const int nFlags) {
		if (!pCommandBase) {
			return false;
		}

		return SourceJSRemoveConCommandFlagsForType(pCommandBase, nFlags);
	}

} // namespace
#ifdef SOURCEJS_HAS_DATAMAPS
// SDK headers declare this operation, but plugin-linked SDK libraries do not provide it.
// Define the SDK member itself so its real private fields are used without a layout alias.
void variant_t::SetEntity(CBaseEntity* const pBaseEntity) {
	eVal.Set(pBaseEntity);
	fieldType = FIELD_EHANDLE;
}
#endif // SOURCEJS_HAS_DATAMAPS

