	// Number-valued sizes and SDK integer fields must remain exactly representable.
	// Do not apply this Number limit to native-address or 64-bit BigInt values.
	constexpr double kMaximumSafeNumberInteger = static_cast<double>((std::uint64_t(1) << std::numeric_limits<double>::digits) - 1);

	static_assert(std::numeric_limits<double>::radix == 2);
	static_assert(std::numeric_limits<double>::digits < std::numeric_limits<std::uint64_t>::digits);

