		EntityFactoryKeyValue(EntityFactoryKeyValue&& Other) noexcept;

		EntityFactoryKeyValue& operator=(EntityFactoryKeyValue const& Other) = default;
		EntityFactoryKeyValue& operator=(EntityFactoryKeyValue&& Other) = default;

		std::string m_strKey;
		EntityFactoryKeyValueType m_Type;
		std::string m_strValue;
