		v8::Local<v8::String> MakeString(v8::Isolate* const pIsolate, char const* const pszValue) {
			if (!pIsolate) {
				return {};
			}

			char const* const pszSafeValue = pszValue ? pszValue : "";
			v8::MaybeLocal<v8::String> const MaybeLocalString = v8::String::NewFromUtf8(pIsolate, pszSafeValue, v8::NewStringType::kNormal);
			v8::Local<v8::String> LocalString {};
			if (!MaybeLocalString.ToLocal(&LocalString)) {
				return {};
			}

			return LocalString;
		}

		v8::Local<v8::String> MakeString(v8::Isolate* const pIsolate, std::string const& strValue) {
			constexpr std::size_t kMaximumStringByteCount = static_cast<std::size_t>(std::numeric_limits<int>::max());

			const std::size_t unValueByteCount = strValue.size();
			if (!pIsolate || (unValueByteCount > kMaximumStringByteCount)) {
				return {};
			}

			v8::MaybeLocal<v8::String> const MaybeLocalString = v8::String::NewFromUtf8(pIsolate, strValue.data(), v8::NewStringType::kNormal, static_cast<int>(unValueByteCount));
			v8::Local<v8::String> LocalString {};
			if (!MaybeLocalString.ToLocal(&LocalString)) {
				return {};
			}

			return LocalString;
		}

		v8::Local<v8::Array> MakeStringArray(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, std::vector<std::string> const& vecValues) {
			constexpr std::size_t kMaximumArrayLength = static_cast<std::size_t>(std::numeric_limits<int>::max());

			const std::size_t unStringCount = vecValues.size();
			if (!pIsolate || LocalContext.IsEmpty() || (unStringCount > kMaximumArrayLength) || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
				return {};
			}

			v8::Local<v8::Array> const LocalArray = v8::Array::New(pIsolate, static_cast<int>(unStringCount));
			if (LocalArray.IsEmpty() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
				return {};
			}

			for (std::size_t unStringIndex = 0; unStringIndex < unStringCount; ++unStringIndex) {
				v8::Local<v8::String> const LocalString = MakeString(pIsolate, vecValues[unStringIndex]);
				if (LocalString.IsEmpty() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					return {};
				}

				v8::Maybe<bool> const MaybeCreatedProperty = LocalArray->CreateDataProperty(LocalContext, static_cast<std::uint32_t>(unStringIndex), LocalString);
				if (MaybeCreatedProperty.IsNothing() || !MaybeCreatedProperty.FromJust() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					return {};
				}
			}

			return LocalArray;
		}

		std::string ValueToString(v8::Isolate* const pIsolate, v8::Local<v8::Value> const LocalValue) {
			if (!pIsolate || LocalValue.IsEmpty()) {
				return {};
			}

			v8::String::Utf8Value UTF8Value(pIsolate, LocalValue);
			char const* const pszEncodedValue = *UTF8Value;
			if (!pszEncodedValue) {
				return {};
			}

			return std::string(pszEncodedValue, static_cast<std::size_t>(UTF8Value.length()));
		}

		bool SetValue(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalObject, char const* const pszName, v8::Local<v8::Value> const LocalValue) {
			if (!pIsolate || LocalContext.IsEmpty() || LocalObject.IsEmpty() || LocalValue.IsEmpty()) {
				return false;
			}

			v8::Local<v8::String> const LocalName = MakeString(pIsolate, pszName);
			if (LocalName.IsEmpty()) {
				return false;
			}

			v8::Maybe<bool> const MaybeSetResult = LocalObject->Set(LocalContext, LocalName, LocalValue);
			if (MaybeSetResult.IsNothing()) {
				return false;
			}

			return MaybeSetResult.FromJust();
		}

		bool SetString(v8::Isolate* const pIsolate, v8::Local<v8::Context> LocalContext, v8::Local<v8::Object> LocalObject, char const* const pszName, char const* const pszValue) {
			return SetValue(pIsolate, LocalContext, LocalObject, pszName, MakeString(pIsolate, pszValue));
		}

		bool SetString(v8::Isolate* const pIsolate, v8::Local<v8::Context> LocalContext, v8::Local<v8::Object> LocalObject, char const* const pszName, std::string const& strValue) {
			return SetValue(pIsolate, LocalContext, LocalObject, pszName, MakeString(pIsolate, strValue));
		}

		bool SetBoolean(v8::Isolate* const pIsolate, v8::Local<v8::Context> LocalContext, v8::Local<v8::Object> LocalObject, char const* const pszName, const bool bValue) {
			return SetValue(pIsolate, LocalContext, LocalObject, pszName, v8::Boolean::New(pIsolate, bValue));
		}

		bool SetInteger(v8::Isolate* const pIsolate, v8::Local<v8::Context> LocalContext, v8::Local<v8::Object> LocalObject, char const* const pszName, const int nValue) {
			return SetValue(pIsolate, LocalContext, LocalObject, pszName, v8::Integer::New(pIsolate, nValue));
		}

		bool SetFunction(v8::Isolate* const pIsolate, v8::Local<v8::Context> LocalContext, v8::Local<v8::Object> LocalObject, char const* const pszName, v8::FunctionCallback Callback, v8::Local<v8::Value> LocalData) {
			if (!pIsolate || LocalContext.IsEmpty() || LocalObject.IsEmpty()) {
				return false;
			}

			v8::Local<v8::Function> LocalFunction {};
			if (!v8::Function::New(LocalContext, Callback, LocalData).ToLocal(&LocalFunction)) {
				return false;
			}

			return SetValue(pIsolate, LocalContext, LocalObject, pszName, LocalFunction);
		}

		void ThrowError(v8::Isolate* const pIsolate, char const* const pszMessage) {
			if (!pIsolate || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
				return;
			}

			v8::Local<v8::String> const LocalMessage = MakeString(pIsolate, pszMessage);
			if (pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
				return;
			}

			if (LocalMessage.IsEmpty()) {
				// V8 accepts an empty thrown value, but not an empty Error message handle.
				pIsolate->ThrowException({});
				return;
			}

			pIsolate->ThrowException(v8::Exception::Error(LocalMessage));
		}

		void ThrowTypeError(v8::Isolate* const pIsolate, char const* const pszMessage) {
			if (!pIsolate || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
				return;
			}

			v8::Local<v8::String> const LocalMessage = MakeString(pIsolate, pszMessage);
			if (pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
				return;
			}

			if (LocalMessage.IsEmpty()) {
				// V8 accepts an empty thrown value, but not an empty TypeError message handle.
				pIsolate->ThrowException({});
				return;
			}

			pIsolate->ThrowException(v8::Exception::TypeError(LocalMessage));
		}

