		void CallEntityInputByIndex(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, const int nEntityIndex, const int nNameArgumentIndex, const int nValueArgumentIndex, const int nDelayArgumentIndex, char const* const pszOperation, char const* const pszSignature) {
			constexpr float kDefaultInputDelay = 0.0f;

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate || (nNameArgumentIndex < 0) || (nValueArgumentIndex < 0) || (nDelayArgumentIndex < 0) || !pszOperation || !pszSignature) {
				return;
			}

			if (CallbackInformation.Length() <= nNameArgumentIndex) {
				ThrowError(pIsolate, pszSignature);
				return;
			}

			if (!CallbackInformation[nNameArgumentIndex]->IsString()) {
				ThrowError(pIsolate, pszSignature);
				return;
			}

			std::string const strInputName = ValueToString(pIsolate, CallbackInformation[nNameArgumentIndex]);
			if (strInputName.empty()) {
				std::string const strInputNameMessage = std::string(pszOperation) + " expects a non-empty input name.";
				ThrowError(pIsolate, strInputNameMessage.c_str());
				return;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				return;
			}

			variant_t InputValue {};
			if (CallbackInformation.Length() > nValueArgumentIndex) {
				if (!VariantFromValue(pIsolate, LocalContext, CallbackInformation[nValueArgumentIndex], pszOperation, InputValue)) {
					return;
				}
			}

			float flInputDelay = kDefaultInputDelay;
			if ((CallbackInformation.Length() > nDelayArgumentIndex) && !IsValueNullish(CallbackInformation[nDelayArgumentIndex])) {
				std::string const strInputDelayMessage = std::string(pszOperation) + " expects a finite delay.";
				if (!CallbackInformation[nDelayArgumentIndex]->IsNumber()) {
					ThrowError(pIsolate, strInputDelayMessage.c_str());
					return;
				}

				if (!GetFloatArgument(pIsolate, LocalContext, CallbackInformation[nDelayArgumentIndex], strInputDelayMessage.c_str(), flInputDelay)) {
					return;
				}
			}

			if (!IsEntityAcceptInputAvailable()) {
				std::string const strUnavailableMessage = std::string(pszOperation) + " requires CBaseEntity::AcceptInput() in the selected Source SDK branch.";
				ThrowError(pIsolate, strUnavailableMessage.c_str());
				return;
			}

			auto* const pBaseEntity = GetBaseEntityFromIndex(nEntityIndex);
			if (!pBaseEntity) {
				std::string const strInvalidEntityMessage = std::string(pszOperation) + " expects a valid entity.";
				ThrowError(pIsolate, strInvalidEntityMessage.c_str());
				return;
			}

			CallbackInformation.GetReturnValue().Set(ScheduleEntityInput(nEntityIndex, strInputName, InputValue, flInputDelay));
		}

		void EntityCallInputMethodCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) try {
			constexpr int kInputNameArgumentIndex = 0;
			constexpr int kInputValueArgumentIndex = 1;
			constexpr int kInputDelayArgumentIndex = 2;
			constexpr char kOperationName[] = "Entity.CallEntityInput()";
			constexpr char kUsageErrorMessage[] = "Entity.CallEntityInput(strInputName, InputValue?, flInputDelay?) expects a non-empty input name string.";

			int nEntityIndex = -1;
			if (!ReadEntityIndex(CallbackInformation, nEntityIndex)) {
				return;
			}

			CallEntityInputByIndex(CallbackInformation, nEntityIndex, kInputNameArgumentIndex, kInputValueArgumentIndex, kInputDelayArgumentIndex, kOperationName, kUsageErrorMessage);
		} catch (...) {
			ThrowError(CallbackInformation.GetIsolate(), "Entity.CallEntityInput() failed because a native C++ exception occurred.");
		}

		void CallEntityInputCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) try {
			constexpr int kEntityArgumentIndex = 0;
			constexpr int kInputNameArgumentIndex = 1;
			constexpr int kInputValueArgumentIndex = 2;
			constexpr int kInputDelayArgumentIndex = 3;
			constexpr int kRequiredArgumentCount = kInputNameArgumentIndex + 1;
			constexpr char kOperationName[] = "entities.CallEntityInput()";
			constexpr char kUsageErrorMessage[] = "entities.CallEntityInput(EntityReference, strInputName, InputValue?, flInputDelay?) expects an entity and non-empty input name string.";
			constexpr char kInvalidEntityErrorMessage[] = "entities.CallEntityInput() expects a valid entity.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				return;
			}

			if (CallbackInformation.Length() < kRequiredArgumentCount) {
				ThrowError(pIsolate, kUsageErrorMessage);
				return;
			}

			int nEntityIndex = -1;
			if (!ReadEntityIndex(pIsolate, LocalContext, CallbackInformation[kEntityArgumentIndex], nEntityIndex)) {
				return;
			}

			if (nEntityIndex < 0) {
				ThrowError(pIsolate, kInvalidEntityErrorMessage);
				return;
			}

			CallEntityInputByIndex(CallbackInformation, nEntityIndex, kInputNameArgumentIndex, kInputValueArgumentIndex, kInputDelayArgumentIndex, kOperationName, kUsageErrorMessage);
		} catch (...) {
			ThrowError(CallbackInformation.GetIsolate(), "entities.CallEntityInput() failed because a native C++ exception occurred.");
		}

