			constexpr char kAPIName[] = "Player.ExecuteClientCommand()";
			constexpr char kCommandArgumentError[] = "Player.ExecuteClientCommand(strCommand, bServerSide?) expects a command string.";
			constexpr char kServerSideArgumentError[] = "Player.ExecuteClientCommand(strCommand, bServerSide?) expects a boolean bServerSide value.";

