		bool GetEngineServerAddressFromValue(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Value> LocalValue, std::uintptr_t& unAddressOut) {
			constexpr char kAddressPropertyName[] = "Address";

			if (!pIsolate || LocalContext.IsEmpty() || LocalValue.IsEmpty()) {
				return false;
			}

			if (LocalValue->IsObject()) {
				v8::Local<v8::String> const LocalAddressPropertyName = MakeString(pIsolate, kAddressPropertyName);
				if (LocalAddressPropertyName.IsEmpty()) {
					return false;
				}

				v8::Local<v8::Value> LocalAddressValue {};
				if (!LocalValue.As<v8::Object>()->Get(LocalContext, LocalAddressPropertyName).ToLocal(&LocalAddressValue)) {
					return false;
				}

				LocalValue = LocalAddressValue;
			}

			return GetAddressSizedUnsignedIntegerFromValue(LocalValue, unAddressOut);
		}

		IServer* GetIServerFromValue(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Value> const LocalValue) {
			std::uintptr_t unAddress = 0;
			if (!GetEngineServerAddressFromValue(pIsolate, LocalContext, LocalValue, unAddress) || (unAddress == 0)) {
				return nullptr;
			}

			return reinterpret_cast<IServer*>(unAddress);
		}

		IServer* RequireIServerFromThis(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, char const* const pszAPIName) {
			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate || !pszAPIName || !*pszAPIName) {
				return nullptr;
			}

			v8::TryCatch AddressFailure(pIsolate);
			auto* const pEngineServer = GetIServerFromValue(pIsolate, pIsolate->GetCurrentContext(), CallbackInformation.This());
			if (AddressFailure.HasCaught()) {
				AddressFailure.ReThrow();
				return nullptr;
			}

			if (!pEngineServer) {
				std::string const strMessage = std::string(pszAPIName) + " requires a valid IServer address.";
				ThrowError(pIsolate, strMessage.c_str());
				AddressFailure.ReThrow();
			}

			return pEngineServer;
		}

