		void GetIServerClientCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) try {
			constexpr int kClientIndexArgumentIndex = 0;
			constexpr int kInvalidClientIndex = -1;
			constexpr char kOperation[] = "engines/server Server.GetClient()";
			constexpr char kClientIndexMessage[] = "engines/server Server.GetClient(nClientIndex) expects an integer client slot.";
			constexpr char kClientRangeMessage[] = "engines/server Server.GetClient(nClientIndex) received an out-of-range client slot.";
			constexpr char kNullClientMessage[] = "The selected SDK IServer returned a null IClient address.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			if (CallbackInformation.Length() <= kClientIndexArgumentIndex) {
				ThrowError(pIsolate, kClientIndexMessage);
				return;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				return;
			}

			int nClientIndex = kInvalidClientIndex;
			if (!GetInt32Argument(pIsolate, LocalContext, CallbackInformation[kClientIndexArgumentIndex], kClientIndexMessage, nClientIndex)) {
				return;
			}

			auto* const pEngineServer = RequireIServerFromThis(CallbackInformation, kOperation);
			if (!pEngineServer) {
				return;
			}

			if ((nClientIndex < 0) || (nClientIndex >= pEngineServer->GetClientCount())) {
				ThrowError(pIsolate, kClientRangeMessage);
				return;
			}

			auto* const pClient = pEngineServer->GetClient(nClientIndex);
			if (!pClient) {
				ThrowError(pIsolate, kNullClientMessage);
				return;
			}

			v8::Local<v8::Object> const LocalClientObject = MakeIServerClientObject(pIsolate, LocalContext, pClient, nClientIndex);
			if (LocalClientObject.IsEmpty()) {
				return;
			}

			CallbackInformation.GetReturnValue().Set(LocalClientObject);
		} catch (...) {
			ThrowError(CallbackInformation.GetIsolate(), "engines/server Server.GetClient() failed because a native C++ exception occurred.");
		}

