		void SetIServerTimescaleCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) try {
			constexpr int kTimescaleArgumentIndex = 0;
			constexpr double kDefaultTimescale = 0.0;
			constexpr char kOperation[] = "engines/server Server.SetServerTimescale()";
			constexpr char kTimescaleMessage[] = "engines/server Server.SetServerTimescale(dblServerTimescale) expects a finite number.";
			constexpr char kUnavailableMessage[] = "The selected SDK IServer does not expose SetTimescale().";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			if (CallbackInformation.Length() <= kTimescaleArgumentIndex) {
				ThrowError(pIsolate, kTimescaleMessage);
				return;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				return;
			}

			double dblServerTimescale = kDefaultTimescale;
			if (!GetNumberArgument(pIsolate, LocalContext, CallbackInformation[kTimescaleArgumentIndex], kTimescaleMessage, dblServerTimescale)) {
				return;
			}

			if (!std::isfinite(dblServerTimescale) || (std::fabs(dblServerTimescale) > static_cast<double>(std::numeric_limits<float>::max()))) {
				ThrowError(pIsolate, kTimescaleMessage);
				return;
			}

			auto* const pEngineServer = RequireIServerFromThis(CallbackInformation, kOperation);
			if (!pEngineServer) {
				return;
			}

			if (!SetIServerTimescale(pEngineServer, static_cast<float>(dblServerTimescale))) {
				ThrowError(pIsolate, kUnavailableMessage);
				return;
			}

			CallbackInformation.GetReturnValue().Set(true);
		} catch (...) {
			ThrowError(CallbackInformation.GetIsolate(), "engines/server Server.SetServerTimescale() failed because a native C++ exception occurred.");
		}

		void DisconnectIServerClientCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) try {
			constexpr int kClientArgumentIndex = 0;
			constexpr int kReasonArgumentIndex = 1;
			constexpr int kInvalidClientIndex = -1;

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				return;
			}

			auto* const pEngineServer = RequireIServerFromThis(CallbackInformation, "engines/server Server.DisconnectClient()");
			if (!pEngineServer) {
				return;
			}

			IClient* pClient = nullptr;
			if ((CallbackInformation.Length() > kClientArgumentIndex) && CallbackInformation[kClientArgumentIndex]->IsInt32()) {
				int nClientIndex = kInvalidClientIndex;
				if (!GetInt32Argument(pIsolate, LocalContext, CallbackInformation[kClientArgumentIndex], "engines/server Server.DisconnectClient(Client, strReason?) expects a client slot or IClient BigInt address.", nClientIndex)) {
					return;
				}

				if ((nClientIndex >= 0) && (nClientIndex < pEngineServer->GetClientCount())) {
					pClient = pEngineServer->GetClient(nClientIndex);
				}
			} else if (CallbackInformation.Length() > kClientArgumentIndex) {
				v8::TryCatch ClientAddressFailure(pIsolate);
				pClient = GetIServerClientFromValue(pIsolate, LocalContext, CallbackInformation[kClientArgumentIndex]);
				if (ClientAddressFailure.HasCaught()) {
					ClientAddressFailure.ReThrow();
					return;
				}
			}

			if (!pClient) {
				ThrowError(pIsolate, "engines/server Server.DisconnectClient(Client, strReason?) expects a valid client slot or IClient BigInt address.");
				return;
			}

			std::string strReason = "Disconnected by SourceJS.";
			if ((CallbackInformation.Length() > kReasonArgumentIndex) && !IsValueNullish(CallbackInformation[kReasonArgumentIndex])) {
				if (!CallbackInformation[kReasonArgumentIndex]->IsString()) {
					ThrowError(pIsolate, "engines/server Server.DisconnectClient(Client, strReason?) strReason must be a string.");
					return;
				}

				strReason = ValueToString(pIsolate, CallbackInformation[kReasonArgumentIndex]);
			}

			pEngineServer->DisconnectClient(pClient, strReason.c_str());
			CallbackInformation.GetReturnValue().Set(true);
		} catch (...) {
			ThrowError(CallbackInformation.GetIsolate(), "engines/server Server.DisconnectClient() failed because a native C++ exception occurred.");
		}

