		void SendClientCommandCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) try {
			constexpr int kPlayerArgumentIndex = 0;
			constexpr int kCommandArgumentIndex = 1;
			constexpr int kServerSideArgumentIndex = 2;
			constexpr int kRequiredArgumentCount = kCommandArgumentIndex + 1;
			constexpr int kInvalidPlayerIndex = -1;
			constexpr char kAPIName[] = "commands.Send()";
			constexpr char kArgumentsError[] = "commands.Send(Player, strCommand, bServerSide?) expects a player index or object, command string, and optional boolean.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				return;
			}

			if (CallbackInformation.Length() < kRequiredArgumentCount) {
				ThrowError(pIsolate, kArgumentsError);
				return;
			}

			v8::Local<v8::Value> const LocalPlayerValue = CallbackInformation[kPlayerArgumentIndex];
			v8::Local<v8::Value> const LocalCommandValue = CallbackInformation[kCommandArgumentIndex];
			if (LocalPlayerValue.IsEmpty() || LocalCommandValue.IsEmpty() || !LocalCommandValue->IsString()) {
				ThrowError(pIsolate, kArgumentsError);
				return;
			}

			int nPlayerIndex = kInvalidPlayerIndex;
			if (!ReadEntityIndex(pIsolate, LocalContext, LocalPlayerValue, nPlayerIndex)) {
				return;
			}

			std::string const strCommand = ValueToString(pIsolate, LocalCommandValue);
			bool bServerSide = false;

			if (CallbackInformation.Length() > kServerSideArgumentIndex) {
				v8::Local<v8::Value> const LocalServerSideValue = CallbackInformation[kServerSideArgumentIndex];
				if (LocalServerSideValue.IsEmpty()) {
					ThrowError(pIsolate, kArgumentsError);
					return;
				}

				const bool bHasServerSideValue = !IsValueNullish(LocalServerSideValue);
				if (bHasServerSideValue && !LocalServerSideValue->IsBoolean()) {
					ThrowError(pIsolate, kArgumentsError);
					return;
				}

				if (bHasServerSideValue) {
					bServerSide = LocalServerSideValue->BooleanValue(pIsolate);
				}
			}

			CallbackInformation.GetReturnValue().Set(ExecuteClientCommandForPlayerIndex(pIsolate, nPlayerIndex, strCommand, bServerSide, kAPIName));
		} catch (...) {
			ThrowError(CallbackInformation.GetIsolate(), "commands.Send() failed because a native C++ exception occurred.");
		}

