		v8::Local<v8::Object> MakeVectorObject(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, Vector const& VectorValue) {
			v8::Local<v8::Object> const LocalObject = v8::Object::New(pIsolate);
			if (LocalObject.IsEmpty()) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalObject, "X", v8::Number::New(pIsolate, VectorValue.x))) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalObject, "Y", v8::Number::New(pIsolate, VectorValue.y))) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalObject, "Z", v8::Number::New(pIsolate, VectorValue.z))) {
				return {};
			}

			return LocalObject;
		}

		enum class PlayerLiveProperty {
			Name = 0,
			UserID,
			NetworkID,
			RemoteAddress,
			Team,
			Frags,
			Deaths,
			Health,
			MaximumHealth,
			Connected,
			FakeClient,
			Language,
			Dead,
			Origin,
			Weapon,
			Model
		};

		void PlayerGetLivePropertyCallback(v8::Local<v8::Name>, v8::PropertyCallbackInfo<v8::Value> const& PropertyCallbackInformation) try {
			constexpr int kPlayerLivePropertyStride = 32;
			constexpr int kEncodedPlayerIndexOffset = 1;
			constexpr char kPropertyMetadataMessage[] = "Player property metadata is invalid.";
			constexpr char kUnknownPropertyMessage[] = "Unknown Player property.";
			constexpr char kLanguageCVarName[] = "cl_language";

			auto* const pIsolate = PropertyCallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				return;
			}

			v8::Local<v8::Value> const LocalPropertyData = PropertyCallbackInformation.Data();
			if (LocalPropertyData.IsEmpty() || !LocalPropertyData->IsInt32()) {
				ThrowError(pIsolate, kPropertyMetadataMessage);
				return;
			}

			const int nEncodedLiveProperty = LocalPropertyData.As<v8::Int32>()->Value();
			const int nPlayerIndex = nEncodedLiveProperty / kPlayerLivePropertyStride - kEncodedPlayerIndexOffset;
			const PlayerLiveProperty LiveProperty = static_cast<PlayerLiveProperty>(nEncodedLiveProperty % kPlayerLivePropertyStride);
			edict_t* pPlayerEdict = nullptr;
			auto* const pPlayerInformation = GetPlayerInformationFromIndex(nPlayerIndex, &pPlayerEdict);
			const bool bRealConnectedPlayer = pPlayerInformation && pPlayerInformation->IsConnected() && !pPlayerInformation->IsFakeClient() && pPlayerEdict && !pPlayerEdict->IsFree();

			switch (LiveProperty) {
				case PlayerLiveProperty::Name:
					PropertyCallbackInformation.GetReturnValue().Set(MakeString(pIsolate, pPlayerInformation ? pPlayerInformation->GetName() : ""));
					return;

				case PlayerLiveProperty::UserID:
					PropertyCallbackInformation.GetReturnValue().Set(pPlayerInformation ? pPlayerInformation->GetUserID() : -1);
					return;

				case PlayerLiveProperty::NetworkID:
					PropertyCallbackInformation.GetReturnValue().Set(MakeString(pIsolate, pPlayerInformation ? pPlayerInformation->GetNetworkIDString() : ""));
					return;

				case PlayerLiveProperty::RemoteAddress: {
					auto* const pEngineServer = g_Application.GetEngineInterfaces().GetEngine();
					auto* const pNetworkInformation = (pEngineServer && bRealConnectedPlayer) ? pEngineServer->GetPlayerNetInfo(nPlayerIndex) : nullptr;
					PropertyCallbackInformation.GetReturnValue().Set(MakeString(pIsolate, pNetworkInformation ? pNetworkInformation->GetAddress() : ""));
					return;
				}

				case PlayerLiveProperty::Team:
					PropertyCallbackInformation.GetReturnValue().Set(pPlayerInformation ? pPlayerInformation->GetTeamIndex() : 0);
					return;

				case PlayerLiveProperty::Frags:
					PropertyCallbackInformation.GetReturnValue().Set(pPlayerInformation ? pPlayerInformation->GetFragCount() : 0);
					return;

				case PlayerLiveProperty::Deaths:
					PropertyCallbackInformation.GetReturnValue().Set(pPlayerInformation ? pPlayerInformation->GetDeathCount() : 0);
					return;

				case PlayerLiveProperty::Health:
					PropertyCallbackInformation.GetReturnValue().Set(pPlayerInformation ? pPlayerInformation->GetHealth() : 0);
					return;

				case PlayerLiveProperty::MaximumHealth:
					PropertyCallbackInformation.GetReturnValue().Set(pPlayerInformation ? pPlayerInformation->GetMaxHealth() : 0);
					return;

				case PlayerLiveProperty::Connected:
					PropertyCallbackInformation.GetReturnValue().Set(pPlayerInformation && pPlayerInformation->IsConnected());
					return;

				case PlayerLiveProperty::FakeClient:
					PropertyCallbackInformation.GetReturnValue().Set(pPlayerInformation && pPlayerInformation->IsFakeClient());
					return;

				case PlayerLiveProperty::Language:
					PropertyCallbackInformation.GetReturnValue().Set(MakeString(pIsolate, bRealConnectedPlayer ? GetClientConVarValue(nPlayerIndex, kLanguageCVarName) : ""));
					return;

				case PlayerLiveProperty::Dead:
					PropertyCallbackInformation.GetReturnValue().Set(pPlayerInformation && pPlayerInformation->IsDead());
					return;

				case PlayerLiveProperty::Origin:
					PropertyCallbackInformation.GetReturnValue().Set(pPlayerInformation ? MakeVectorObject(pIsolate, LocalContext, pPlayerInformation->GetAbsOrigin()) : v8::Object::New(pIsolate));
					return;

				case PlayerLiveProperty::Weapon:
					PropertyCallbackInformation.GetReturnValue().Set(MakeString(pIsolate, pPlayerInformation ? pPlayerInformation->GetWeaponName() : ""));
					return;

				case PlayerLiveProperty::Model:
					PropertyCallbackInformation.GetReturnValue().Set(MakeString(pIsolate, pPlayerInformation ? pPlayerInformation->GetModelName() : ""));
					return;

				default:
					ThrowError(pIsolate, kUnknownPropertyMessage);
					return;
			}
		} catch (...) {
			ThrowError(PropertyCallbackInformation.GetIsolate(), "Player property failed because a native C++ exception occurred.");
		}

		void PlayerSetLiveProperty(v8::Local<v8::Name>, v8::Local<v8::Value> const LocalPropertyValue, v8::PropertyCallbackInfo<void> const& PropertyCallbackInformation) try {
			constexpr int kPlayerLivePropertyStride = 32;
			constexpr int kEncodedPlayerIndexOffset = 1;
			constexpr int kInvalidTeamIndex = -1;
			constexpr char kContextError[] = "Player property context is unavailable.";
			constexpr char kPropertyMetadataError[] = "Player property metadata is invalid.";
			constexpr char kPropertyTargetError[] = "Player property target is unavailable.";
			constexpr char kNamePropertyName[] = "Player.Name";
			constexpr char kNamePropertyError[] = "Player.Name requires a string.";
			constexpr char kTeamPropertyError[] = "Player.Team requires a non-negative integer.";
			constexpr char kReadOnlyPropertyError[] = "Player live property is read-only.";
#if defined(SOURCEJS_HAS_BASE_ENTITY)
			constexpr char kHealthPropertyError[] = "Player health properties require an integer.";
			constexpr char kHealthPropertyTargetError[] = "Player health property target is unavailable.";
#endif

			auto* const pIsolate = PropertyCallbackInformation.GetIsolate();
			if (!pIsolate || LocalPropertyValue.IsEmpty()) {
				return;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				ThrowError(pIsolate, kContextError);
				return;
			}

			v8::Local<v8::Value> const LocalPropertyMetadata = PropertyCallbackInformation.Data();
			if (LocalPropertyMetadata.IsEmpty() || !LocalPropertyMetadata->IsInt32()) {
				ThrowError(pIsolate, kPropertyMetadataError);
				return;
			}

			const int nEncodedProperty = LocalPropertyMetadata.As<v8::Int32>()->Value();
			const int nPlayerIndex = nEncodedProperty / kPlayerLivePropertyStride - kEncodedPlayerIndexOffset;
			const PlayerLiveProperty LiveProperty = static_cast<PlayerLiveProperty>(nEncodedProperty % kPlayerLivePropertyStride);
			auto* const pPlayerInformation = GetPlayerInformationFromIndex(nPlayerIndex, nullptr);
			if (!pPlayerInformation) {
				ThrowError(pIsolate, kPropertyTargetError);
				return;
			}

			switch (LiveProperty) {
				case PlayerLiveProperty::Name:
					if (!LocalPropertyValue->IsString()) {
						ThrowError(pIsolate, kNamePropertyError);
						return;
					}

					if (!SetPlayerNameForPlayerIndex(pIsolate, nPlayerIndex, ValueToString(pIsolate, LocalPropertyValue), kNamePropertyName)) {
						return;
					}

					return;

				case PlayerLiveProperty::Team: {
					if (!LocalPropertyValue->IsInt32()) {
						ThrowError(pIsolate, kTeamPropertyError);
						return;
					}

					int nTeamIndex = kInvalidTeamIndex;
					if (!GetInt32Argument(pIsolate, LocalContext, LocalPropertyValue, kTeamPropertyError, nTeamIndex)) {
						return;
					}

					if (nTeamIndex < 0) {
						ThrowError(pIsolate, kTeamPropertyError);
						return;
					}

					pPlayerInformation->ChangeTeam(nTeamIndex);
					return;
				}

#if defined(SOURCEJS_HAS_BASE_ENTITY)
				case PlayerLiveProperty::Health:
				case PlayerLiveProperty::MaximumHealth: {
					if (!LocalPropertyValue->IsInt32()) {
						ThrowError(pIsolate, kHealthPropertyError);
						return;
					}

					int nHealth = 0;
					if (!GetInt32Argument(pIsolate, LocalContext, LocalPropertyValue, kHealthPropertyError, nHealth)) {
						return;
					}

					auto* const pPlayerEntity = GetBaseEntityFromIndex(nPlayerIndex);
					if (!pPlayerEntity) {
						ThrowError(pIsolate, kHealthPropertyTargetError);
						return;
					}

					if (LiveProperty == PlayerLiveProperty::Health) {
						pPlayerEntity->SetHealth(nHealth);
					} else {
						pPlayerEntity->SetMaxHealth(nHealth);
					}

					return;
				}
#endif

				default:
					ThrowError(pIsolate, kReadOnlyPropertyError);
					return;
			}
		} catch (...) {
			ThrowError(PropertyCallbackInformation.GetIsolate(), "Player property write failed because a native C++ exception occurred.");
		}

		bool InstallPlayerLiveProperty(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalObject, const int nPlayerIndex, char const* const pszPropertyName, const PlayerLiveProperty LiveProperty) {
			constexpr int kPlayerLivePropertyStride = 32;
			constexpr int kEncodedPlayerIndexOffset = 1;
			constexpr int kMaximumLiveProperty = kPlayerLivePropertyStride - 1;
			constexpr int kMaximumPlayerIndex = (std::numeric_limits<int>::max() - kMaximumLiveProperty) / kPlayerLivePropertyStride - kEncodedPlayerIndexOffset;

			const int nLiveProperty = static_cast<int>(LiveProperty);
			if ((nPlayerIndex < 0) || (nPlayerIndex > kMaximumPlayerIndex) || (nLiveProperty < 0) || (nLiveProperty > kMaximumLiveProperty)) {
				return false;
			}

			v8::Local<v8::String> const LocalPropertyName = MakeString(pIsolate, pszPropertyName);
			if (LocalPropertyName.IsEmpty()) {
				return false;
			}

			const int nEncodedProperty = (nPlayerIndex + kEncodedPlayerIndexOffset) * kPlayerLivePropertyStride + nLiveProperty;

			return LocalObject->SetNativeDataProperty(LocalContext, LocalPropertyName, PlayerGetLivePropertyCallback, PlayerSetLiveProperty, v8::Int32::New(pIsolate, nEncodedProperty)).FromMaybe(false);
		}

		v8::Local<v8::Object> MakePlayerObject(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, const int nEntityIndex) {
			struct PlayerLivePropertyBinding {
				char const* m_pszPropertyName;
				PlayerLiveProperty m_LiveProperty;
			};

			constexpr char kPropertyInstallationError[] = "Failed to install Player live properties.";
			constexpr PlayerLivePropertyBinding kPlayerLivePropertyBindings[] = {
				{ "Name", PlayerLiveProperty::Name },
				{ "UserID", PlayerLiveProperty::UserID },
				{ "NetworkID", PlayerLiveProperty::NetworkID },
				{ "RemoteAddress", PlayerLiveProperty::RemoteAddress },
				{ "Team", PlayerLiveProperty::Team },
				{ "Frags", PlayerLiveProperty::Frags },
				{ "Deaths", PlayerLiveProperty::Deaths },
				{ "Health", PlayerLiveProperty::Health },
				{ "MaximumHealth", PlayerLiveProperty::MaximumHealth },
				{ "Connected", PlayerLiveProperty::Connected },
				{ "FakeClient", PlayerLiveProperty::FakeClient },
				{ "Language", PlayerLiveProperty::Language },
				{ "Dead", PlayerLiveProperty::Dead },
				{ "Origin", PlayerLiveProperty::Origin },
				{ "Weapon", PlayerLiveProperty::Weapon },
				{ "Model", PlayerLiveProperty::Model },
			};

			if (!pIsolate || LocalContext.IsEmpty()) {
				return {};
			}

			v8::Local<v8::Object> const LocalPlayerObject = MakeEntityObject(pIsolate, LocalContext, nEntityIndex);
			if (LocalPlayerObject.IsEmpty()) {
				return {};
			}

			for (auto const& PropertyBinding : kPlayerLivePropertyBindings) {
				v8::TryCatch PropertyInstallationFailure(pIsolate);
				if (!InstallPlayerLiveProperty(pIsolate, LocalContext, LocalPlayerObject, nEntityIndex, PropertyBinding.m_pszPropertyName, PropertyBinding.m_LiveProperty)) {
					if (PropertyInstallationFailure.HasCaught()) {
						PropertyInstallationFailure.ReThrow();
						return {};
					}

					ThrowError(pIsolate, kPropertyInstallationError);
					PropertyInstallationFailure.ReThrow();
					return {};
				}
			}

			v8::Local<v8::Value> const LocalFunctionData = v8::Undefined(pIsolate);
			if (!SetRecordFunction(pIsolate, LocalContext, LocalPlayerObject, "Slay", PlayerSlayMethodCallback, LocalFunctionData)) {
				return {};
			}
#if defined(_WIN32) || defined(__linux__)
			if (!SetRecordFunction(pIsolate, LocalContext, LocalPlayerObject, "Ignite", PlayerIgniteMethodCallback, LocalFunctionData)) {
				return {};
			}
#endif
#if defined(SOURCEJS_HAS_BASE_ENTITY) && (defined(_WIN32) || defined(__linux__))
			if (!SetRecordFunction(pIsolate, LocalContext, LocalPlayerObject, "GetEyeAngles", PlayerGetEyeAnglesMethodCallback, LocalFunctionData) || !SetRecordFunction(pIsolate, LocalContext, LocalPlayerObject, "Teleport", PlayerTeleportMethodCallback, LocalFunctionData)) {
				return {};
			}

			if (!SetRecordFunction(pIsolate, LocalContext, LocalPlayerObject, "AddVelocity", PlayerAddVelocityMethodCallback, LocalFunctionData)) {
				return {};
			}
#endif

			if (!SetRecordFunction(pIsolate, LocalContext, LocalPlayerObject, "ExecuteClientCommand", PlayerExecuteClientCommandMethodCallback, LocalFunctionData)) {
				return {};
			}

			if (!SetRecordFunction(pIsolate, LocalContext, LocalPlayerObject, "SetName", PlayerSetNameMethodCallback, LocalFunctionData)) {
				return {};
			}

			if (!SetRecordFunction(pIsolate, LocalContext, LocalPlayerObject, "Say", PlayerSayMethodCallback, LocalFunctionData)) {
				return {};
			}

			if (!SetRecordFunction(pIsolate, LocalContext, LocalPlayerObject, "SayTeam", PlayerSayTeamMethodCallback, LocalFunctionData)) {
				return {};
			}

			if (!SetRecordFunction(pIsolate, LocalContext, LocalPlayerObject, "Kick", PlayerKickMethodCallback, LocalFunctionData)) {
				return {};
			}

			if (!SetRecordFunction(pIsolate, LocalContext, LocalPlayerObject, "Ban", PlayerBanMethodCallback, LocalFunctionData)) {
				return {};
			}

			if (!SetRecordFunction(pIsolate, LocalContext, LocalPlayerObject, "ChangeTeam", PlayerChangeTeamMethodCallback, LocalFunctionData)) {
				return {};
			}
#if defined(SOURCEJS_HAS_BASE_ENTITY)
			if (!SetRecordFunction(pIsolate, LocalContext, LocalPlayerObject, "GiveNamedItem", PlayerGiveNamedItemMethodCallback, LocalFunctionData)) {
				return {};
			}
#endif

			return LocalPlayerObject;
		}

		IPlayerInfo* RequirePlayerInformationArgument(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, char const* const pszArgumentError, char const* const pszAPIName) {
			constexpr int kPlayerArgumentIndex = 0;
			constexpr int kRequiredArgumentCount = 1;
			constexpr int kInvalidEntityIndex = -1;
			constexpr char kContextError[] = "Player argument context is unavailable.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate || !pszArgumentError || !pszAPIName) {
				return nullptr;
			}

			if (CallbackInformation.Length() < kRequiredArgumentCount) {
				ThrowError(pIsolate, pszArgumentError);
				return nullptr;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				ThrowError(pIsolate, kContextError);
				return nullptr;
			}

			int nEntityIndex = kInvalidEntityIndex;
			if (!ReadEntityIndex(pIsolate, LocalContext, CallbackInformation[kPlayerArgumentIndex], nEntityIndex)) {
				return nullptr;
			}

			return RequirePlayerInformationFromIndex(pIsolate, nEntityIndex, nullptr, pszAPIName);
		}

