		bool ConvertLogMessage(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, std::string& strMessageOut) {
			constexpr int kMessageArgumentIndex = 0;
			constexpr char kStringConversionError[] = "The log message could not be converted to a native string.";
			constexpr char kEmbeddedNullCharacterError[] = "The log message must not contain embedded NUL characters.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return false;
			}

			if (CallbackInformation.Length() <= kMessageArgumentIndex) {
				strMessageOut.clear();
				return true;
			}

			v8::TryCatch ConversionFailure(pIsolate);
			v8::Local<v8::String> LocalString {};
			if (!CallbackInformation[kMessageArgumentIndex]->ToString(pIsolate->GetCurrentContext()).ToLocal(&LocalString)) {
				if (ConversionFailure.HasCaught()) {
					ConversionFailure.ReThrow();
					return false;
				}

				ThrowError(pIsolate, kStringConversionError);
				ConversionFailure.ReThrow();
				return false;
			}

			v8::String::Utf8Value UTF8Value(pIsolate, LocalString);
			char const* const pszEncodedValue = *UTF8Value;
			if (!pszEncodedValue) {
				ThrowError(pIsolate, kStringConversionError);
				ConversionFailure.ReThrow();
				return false;
			}

			const std::size_t unEncodedByteCount = static_cast<std::size_t>(UTF8Value.length());
			if (std::memchr(pszEncodedValue, '\0', unEncodedByteCount)) {
				ThrowError(pIsolate, kEmbeddedNullCharacterError);
				ConversionFailure.ReThrow();
				return false;
			}

			strMessageOut.assign(pszEncodedValue, unEncodedByteCount);

			return true;
		}

		void LogInformationCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) try {
			std::string strMessage {};
			if (!ConvertLogMessage(CallbackInformation, strMessage)) {
				return;
			}

			LogInfo("%s", strMessage.c_str());
		} catch (...) {
			constexpr char kCallbackExceptionError[] = "LogInformationCallback failed with a C++ exception.";

			ThrowError(CallbackInformation.GetIsolate(), kCallbackExceptionError);
		}

