		bool ConvertEventPayload(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, const int nPayloadArgumentIndex, std::string& strPayloadOut) {
			constexpr char kConversionError[] = "The event payload could not be converted to a native string.";
			constexpr char kContextError[] = "The event payload conversion context is unavailable.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return false;
			}

			if (CallbackInformation.Length() <= nPayloadArgumentIndex) {
				strPayloadOut.clear();
				return true;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				ThrowError(pIsolate, kContextError);
				return false;
			}

			v8::TryCatch ConversionFailure(pIsolate);
			v8::Local<v8::String> LocalString {};
			if (!CallbackInformation[nPayloadArgumentIndex]->ToString(LocalContext).ToLocal(&LocalString)) {
				if (ConversionFailure.HasCaught()) {
					ConversionFailure.ReThrow();
					return false;
				}

				ThrowError(pIsolate, kConversionError);
				ConversionFailure.ReThrow();
				return false;
			}

			v8::String::Utf8Value UTF8Value(pIsolate, LocalString);
			char const* const pszEncodedValue = *UTF8Value;
			if (!pszEncodedValue) {
				ThrowError(pIsolate, kConversionError);
				ConversionFailure.ReThrow();
				return false;
			}

			strPayloadOut.assign(pszEncodedValue, static_cast<std::size_t>(UTF8Value.length()));

			return true;
		}

		void EmitRuntimeEventCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) try {
			constexpr int kEventNameArgumentIndex = 0;
			constexpr int kPayloadArgumentIndex = 1;
			constexpr char kArgumentError[] = "listeners.Emit(strEventName, strEventPayload?) expects a non-empty event name and optional string payload.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			if ((CallbackInformation.Length() <= kEventNameArgumentIndex) || !CallbackInformation[kEventNameArgumentIndex]->IsString()) {
				ThrowError(pIsolate, kArgumentError);
				return;
			}

			if ((CallbackInformation.Length() > kPayloadArgumentIndex) && !CallbackInformation[kPayloadArgumentIndex]->IsString()) {
				ThrowError(pIsolate, kArgumentError);
				return;
			}

			std::string const strEventName = ValueToString(pIsolate, CallbackInformation[kEventNameArgumentIndex]);
			if (strEventName.empty()) {
				ThrowError(pIsolate, kArgumentError);
				return;
			}

			auto* const pRuntime = GetRuntimeFromCallbackInformation(CallbackInformation);
			if (!pRuntime) {
				return;
			}

			std::string strEventPayload {};
			if (!ConvertEventPayload(CallbackInformation, kPayloadArgumentIndex, strEventPayload)) {
				return;
			}

			const std::size_t unListenerCount = pRuntime->GetEventCallbackCount(strEventName);

			pRuntime->EmitEvent(strEventName, strEventPayload);

			CallbackInformation.GetReturnValue().Set(v8::Number::New(pIsolate, static_cast<double>(unListenerCount)));
		} catch (...) {
			constexpr char kCallbackExceptionError[] = "EmitRuntimeEventCallback failed with a C++ exception.";

			ThrowError(CallbackInformation.GetIsolate(), kCallbackExceptionError);
		}

