		bool ReadDefinedObjectProperty(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalObject, char const* const pszName, bool& bDefinedOut) {
			if (!pIsolate || LocalContext.IsEmpty() || LocalObject.IsEmpty() || !pszName) {
				return false;
			}

			v8::Local<v8::String> const LocalName = MakeString(pIsolate, pszName);
			if (LocalName.IsEmpty()) {
				return false;
			}

			v8::Local<v8::Value> LocalValue {};
			if (!LocalObject->Get(LocalContext, LocalName).ToLocal(&LocalValue)) {
				return false;
			}

			bDefinedOut = !LocalValue->IsUndefined() && !LocalValue->IsNull();

			return true;
		}

		bool NormalizeEntityHookEntityOption(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalOptions) {
			constexpr int kInvalidEntityIndex = -1;
			constexpr char kEntityOptionPropertyName[] = "Entity";

			if (!pIsolate || LocalContext.IsEmpty() || LocalOptions.IsEmpty()) {
				return false;
			}

			v8::Local<v8::String> const LocalEntityPropertyName = MakeString(pIsolate, kEntityOptionPropertyName);
			if (LocalEntityPropertyName.IsEmpty()) {
				return false;
			}

			v8::MaybeLocal<v8::Value> const MaybeEntityValue = LocalOptions->Get(LocalContext, LocalEntityPropertyName);
			v8::Local<v8::Value> LocalEntityValue {};
			if (!MaybeEntityValue.ToLocal(&LocalEntityValue)) {
				return false;
			}

			if (LocalEntityValue->IsUndefined() || LocalEntityValue->IsNull()) {
				return true;
			}

			int nEntityIndex = kInvalidEntityIndex;
			if (!ReadEntityIndex(pIsolate, LocalContext, LocalEntityValue, nEntityIndex)) {
				return false;
			}

			if (nEntityIndex <= kInvalidEntityIndex) {
				auto* const pBaseEntity = GetEntityBaseEntityFromAddressValue(LocalEntityValue);
				nEntityIndex = GetEntityIndexFromBaseEntity(pBaseEntity);
			}

			if (nEntityIndex <= kInvalidEntityIndex) {
				return false;
			}

			return SetInteger(pIsolate, LocalContext, LocalOptions, kEntityOptionPropertyName, nEntityIndex);
		}

		bool ReadEntityHookCreationOptions(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, const int nCreationArgumentCount, v8::Local<v8::Object>& LocalOptionsOut) {
			constexpr int kEntityArgumentIndex = 0;
			constexpr int kHookIndexArgumentIndex = 1;
			constexpr int kOptionsArgumentIndex = 2;
			constexpr char kEntityOptionPropertyName[] = "Entity";
			constexpr char kHookIndexOptionPropertyName[] = "Index";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return false;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				return false;
			}

			auto NormalizeAndCommitOptions = [pIsolate, LocalContext, &LocalOptionsOut](v8::Local<v8::Object> const LocalCandidateOptions) -> bool {
				if (!NormalizeEntityHookEntityOption(pIsolate, LocalContext, LocalCandidateOptions)) {
					return false;
				}

				LocalOptionsOut = LocalCandidateOptions;

				return true;
			};

			v8::Local<v8::Object> LocalOptions {};
			if ((nCreationArgumentCount > kOptionsArgumentIndex) && CallbackInformation[kHookIndexArgumentIndex]->IsNumber() && CallbackInformation[kOptionsArgumentIndex]->IsObject()) {
				LocalOptions = CallbackInformation[kOptionsArgumentIndex].As<v8::Object>();
				if (!SetValue(pIsolate, LocalContext, LocalOptions, kEntityOptionPropertyName, CallbackInformation[kEntityArgumentIndex])) {
					return false;
				}

				if (!SetValue(pIsolate, LocalContext, LocalOptions, kHookIndexOptionPropertyName, CallbackInformation[kHookIndexArgumentIndex])) {
					return false;
				}

				return NormalizeAndCommitOptions(LocalOptions);
			}

			if ((nCreationArgumentCount > kHookIndexArgumentIndex) && CallbackInformation[kHookIndexArgumentIndex]->IsNumber()) {
				LocalOptions = v8::Object::New(pIsolate);
				if (LocalOptions.IsEmpty()) {
					return false;
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalOptions, kEntityOptionPropertyName, CallbackInformation[kEntityArgumentIndex])) {
					return false;
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalOptions, kHookIndexOptionPropertyName, CallbackInformation[kHookIndexArgumentIndex])) {
					return false;
				}

				return NormalizeAndCommitOptions(LocalOptions);
			}

			if ((nCreationArgumentCount > kHookIndexArgumentIndex) && CallbackInformation[kHookIndexArgumentIndex]->IsObject()) {
				LocalOptions = CallbackInformation[kHookIndexArgumentIndex].As<v8::Object>();
				if (!SetValue(pIsolate, LocalContext, LocalOptions, kEntityOptionPropertyName, CallbackInformation[kEntityArgumentIndex])) {
					return false;
				}

				return NormalizeAndCommitOptions(LocalOptions);
			}

			if ((nCreationArgumentCount > kEntityArgumentIndex) && CallbackInformation[kEntityArgumentIndex]->IsObject()) {
				LocalOptions = CallbackInformation[kEntityArgumentIndex].As<v8::Object>();
				return NormalizeAndCommitOptions(LocalOptions);
			}

			return false;
		}

		bool ReadEntityHookCallbackOptions(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, v8::Local<v8::Object>& LocalOptionsOut, v8::Local<v8::Function>& LocalCallbackOut) {
			constexpr int kEntityArgumentIndex = 0;
			constexpr int kHookIndexArgumentIndex = 1;
			constexpr int kOptionsArgumentIndex = 2;
			constexpr int kExtendedCallbackArgumentIndex = 3;

			if (!CallbackInformation.GetIsolate()) {
				return false;
			}

			auto ReadAndCommitCallbackOptions = [&CallbackInformation, &LocalOptionsOut, &LocalCallbackOut](const int nCallbackArgumentIndex) -> bool {
				v8::Local<v8::Object> LocalOptions {};
				if (!ReadEntityHookCreationOptions(CallbackInformation, nCallbackArgumentIndex, LocalOptions)) {
					return false;
				}

				v8::Local<v8::Function> const LocalCallback = CallbackInformation[nCallbackArgumentIndex].As<v8::Function>();
				if (LocalCallback.IsEmpty()) {
					return false;
				}

				LocalOptionsOut = LocalOptions;
				LocalCallbackOut = LocalCallback;

				return true;
			};

			if ((CallbackInformation.Length() > kExtendedCallbackArgumentIndex) && CallbackInformation[kHookIndexArgumentIndex]->IsNumber() && CallbackInformation[kOptionsArgumentIndex]->IsObject() && CallbackInformation[kExtendedCallbackArgumentIndex]->IsFunction()) {
				return ReadAndCommitCallbackOptions(kExtendedCallbackArgumentIndex);
			}

			if ((CallbackInformation.Length() > kOptionsArgumentIndex) && CallbackInformation[kHookIndexArgumentIndex]->IsObject() && CallbackInformation[kOptionsArgumentIndex]->IsFunction()) {
				return ReadAndCommitCallbackOptions(kOptionsArgumentIndex);
			}

			if ((CallbackInformation.Length() > kHookIndexArgumentIndex) && CallbackInformation[kEntityArgumentIndex]->IsObject() && CallbackInformation[kHookIndexArgumentIndex]->IsFunction()) {
				return ReadAndCommitCallbackOptions(kHookIndexArgumentIndex);
			}

			return false;
		}

		bool ReadEntityHookVTableOption(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalOptions, bool& bUseVTableOut) {
			constexpr char kHookKindOptionPropertyName[] = "Kind";
			constexpr char kFunctionHookKind[] = "FUNCTION";
			constexpr char kVTableHookKind[] = "VTABLE";
			constexpr char kAddressOptionPropertyName[] = "Address";
			constexpr char kEntityOptionPropertyName[] = "Entity";
			constexpr char kObjectAddressOptionPropertyName[] = "ObjectAddress";

			if (!pIsolate || LocalContext.IsEmpty() || LocalOptions.IsEmpty()) {
				return false;
			}

			v8::TryCatch OptionFailure(pIsolate);
			try {
				std::string strHookKind {};
				const bool bHasHookKind = GetObjectString(pIsolate, LocalContext, LocalOptions, kHookKindOptionPropertyName, strHookKind);
				if (OptionFailure.HasCaught()) {
					OptionFailure.ReThrow();
					return false;
				}

				if (bHasHookKind) {
					for (auto& chHookKindCharacter : strHookKind) {
						chHookKindCharacter = static_cast<char>(std::toupper(static_cast<unsigned char>(chHookKindCharacter)));
					}

					if (strHookKind == kFunctionHookKind) {
						bUseVTableOut = false;
						return true;
					}

					if (strHookKind == kVTableHookKind) {
						bUseVTableOut = true;
						return true;
					}
				}

				bool bHasAddress = false;
				if (!ReadDefinedObjectProperty(pIsolate, LocalContext, LocalOptions, kAddressOptionPropertyName, bHasAddress)) {
					if (OptionFailure.HasCaught()) {
						OptionFailure.ReThrow();
					}

					return false;
				}

				if (bHasAddress) {
					bUseVTableOut = false;
					return true;
				}

				bool bHasEntity = false;
				if (!ReadDefinedObjectProperty(pIsolate, LocalContext, LocalOptions, kEntityOptionPropertyName, bHasEntity)) {
					if (OptionFailure.HasCaught()) {
						OptionFailure.ReThrow();
					}

					return false;
				}

				if (bHasEntity) {
					bUseVTableOut = true;
					return true;
				}

				bool bHasObjectAddress = false;
				if (!ReadDefinedObjectProperty(pIsolate, LocalContext, LocalOptions, kObjectAddressOptionPropertyName, bHasObjectAddress)) {
					if (OptionFailure.HasCaught()) {
						OptionFailure.ReThrow();
					}

					return false;
				}

				bUseVTableOut = bHasObjectAddress;

				return true;
			} catch (...) {
				if (OptionFailure.HasCaught()) {
					OptionFailure.ReThrow();
				}

				throw;
			}
		}

		int CreateEntityHookID(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalOptions, const bool bForceVTable) {
			constexpr int kInvalidHookID = 0;

			if (!pIsolate || LocalContext.IsEmpty() || LocalOptions.IsEmpty()) {
				return kInvalidHookID;
			}

			if (!NormalizeEntityHookEntityOption(pIsolate, LocalContext, LocalOptions)) {
				return kInvalidHookID;
			}

			bool bUseVTable = bForceVTable;
			if (!bForceVTable && !ReadEntityHookVTableOption(pIsolate, LocalContext, LocalOptions, bUseVTable)) {
				return kInvalidHookID;
			}

			if (bUseVTable) {
				return g_Application.GetMemoryHookManager().CreateVTable(pIsolate, LocalContext, LocalOptions);
			}

			return g_Application.GetMemoryHookManager().CreateFunction(pIsolate, LocalContext, LocalOptions);
		}

