		bool ReadCommandName(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, const int nNameArgumentIndex, std::string& strCommandNameOut) {
			constexpr char kContextError[] = "Command name conversion context is unavailable.";
			constexpr char kConversionError[] = "Command name could not be converted to a native string.";
			constexpr char kEmbeddedNULNameError[] = "Command names cannot contain NUL characters.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return false;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				ThrowError(pIsolate, kContextError);
				return false;
			}

			v8::TryCatch ConversionFailure(pIsolate);
			v8::Local<v8::String> LocalName {};
			if (!CallbackInformation[nNameArgumentIndex]->ToString(LocalContext).ToLocal(&LocalName)) {
				if (!ConversionFailure.HasCaught()) {
					ThrowError(pIsolate, kConversionError);
				}

				ConversionFailure.ReThrow();
				return false;
			}

			v8::String::Utf8Value UTF8Value(pIsolate, LocalName);
			char const* const pszEncodedName = *UTF8Value;
			if (!pszEncodedName) {
				ThrowError(pIsolate, kConversionError);
				ConversionFailure.ReThrow();
				return false;
			}

			const std::size_t unEncodedNameLength = static_cast<std::size_t>(UTF8Value.length());
			if (std::memchr(pszEncodedName, '\0', unEncodedNameLength)) {
				ThrowError(pIsolate, kEmbeddedNULNameError);
				ConversionFailure.ReThrow();
				return false;
			}

			strCommandNameOut.assign(pszEncodedName, unEncodedNameLength);

			return true;
		}

