		bool InstallCommandReturnBindings(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalTargetModule) {
			constexpr int kContinueResult = 0;
			constexpr int kBlockResult = 1;
			constexpr int kHandledResult = kBlockResult;

			if (!pIsolate || LocalContext.IsEmpty() || LocalTargetModule.IsEmpty()) {
				return false;
			}

			v8::Local<v8::Object> const LocalCommandReturn = v8::Object::New(pIsolate);
			if (LocalCommandReturn.IsEmpty()) {
				return false;
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalCommandReturn, "Continue", v8::Integer::New(pIsolate, kContinueResult))) {
				return false;
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalCommandReturn, "Block", v8::Integer::New(pIsolate, kBlockResult))) {
				return false;
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalCommandReturn, "Handled", v8::Integer::New(pIsolate, kHandledResult))) {
				return false;
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalTargetModule, "CONTINUE", v8::Integer::New(pIsolate, kContinueResult))) {
				return false;
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalTargetModule, "BLOCK", v8::Integer::New(pIsolate, kBlockResult))) {
				return false;
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalTargetModule, "HANDLED", v8::Integer::New(pIsolate, kHandledResult))) {
				return false;
			}

#ifndef SOURCEJS_OLD_CONSOLE_API
			if (!SetRecordProperty(pIsolate, LocalContext, LocalTargetModule, "MAX_COMMAND_LENGTH", v8::Integer::New(pIsolate, CCommand::MaxCommandLength()))) {
				return false;
			}
#endif // !SOURCEJS_OLD_CONSOLE_API

			v8::Local<v8::String> const LocalCommandReturnName = MakeString(pIsolate, "CommandReturn");
			v8::Local<v8::Value> const LocalUndefinedValue = v8::Undefined(pIsolate);
			if (LocalCommandReturnName.IsEmpty() || LocalUndefinedValue.IsEmpty()) {
				return false;
			}

			if (!LocalTargetModule->CreateDataProperty(LocalContext, LocalCommandReturnName, LocalCommandReturn).FromMaybe(false)) {
				return false;
			}

			if (!SetRecordFunction(pIsolate, LocalContext, LocalTargetModule, "GetCommandReturnNumber", GetCommandReturnNumberCallback, LocalUndefinedValue)) {
				return false;
			}

			if (!SetRecordFunction(pIsolate, LocalContext, LocalTargetModule, "GetCommandReturnObject", GetCommandReturnObjectCallback, LocalUndefinedValue)) {
				return false;
			}

			return true;
		}

		bool InstallHookTypeBindings(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalTargetModule) {
			if (!pIsolate || LocalContext.IsEmpty() || LocalTargetModule.IsEmpty()) {
				return false;
			}

			v8::Local<v8::Object> const LocalHookTypeObject = v8::Object::New(pIsolate);
			if (LocalHookTypeObject.IsEmpty()) {
				return false;
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalHookTypeObject, "Pre", v8::Integer::New(pIsolate, HOOKTYPE_PRE))) {
				return false;
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalHookTypeObject, "Post", v8::Integer::New(pIsolate, HOOKTYPE_POST))) {
				return false;
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalTargetModule, "PRE", v8::Integer::New(pIsolate, HOOKTYPE_PRE))) {
				return false;
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalTargetModule, "POST", v8::Integer::New(pIsolate, HOOKTYPE_POST))) {
				return false;
			}

			v8::Local<v8::String> const LocalHookTypeName = MakeString(pIsolate, "HookType");
			if (LocalHookTypeName.IsEmpty()) {
				return false;
			}

			if (!LocalTargetModule->CreateDataProperty(LocalContext, LocalHookTypeName, LocalHookTypeObject).FromMaybe(false)) {
				return false;
			}

			return true;
		}

		bool ReadConVarName(v8::Isolate* const pIsolate, v8::Local<v8::Value> const LocalNameValue, std::string& strConVarNameOut) {
			constexpr char kConversionError[] = "ConVar name could not be encoded as UTF-8.";
			constexpr char kEmbeddedNULNameError[] = "ConVar names cannot contain NUL characters.";

			if (!pIsolate || LocalNameValue.IsEmpty()) {
				return false;
			}

			v8::TryCatch ConversionFailure(pIsolate);
			v8::String::Utf8Value UTF8Value(pIsolate, LocalNameValue);
			char const* const pszEncodedName = *UTF8Value;
			if (!pszEncodedName) {
				ThrowError(pIsolate, kConversionError);
				ConversionFailure.ReThrow();
				return false;
			}

			const std::size_t unEncodedNameLength = static_cast<std::size_t>(UTF8Value.length());
			if (std::memchr(pszEncodedName, '\0', unEncodedNameLength)) {
				ThrowError(pIsolate, kEmbeddedNULNameError);
				ConversionFailure.ReThrow();
				return false;
			}

			strConVarNameOut.assign(pszEncodedName, unEncodedNameLength);

			return true;
		}

