		bool ReadConVarString(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Value> const LocalValue, std::string& strValueOut) {
			constexpr char kConversionError[] = "cvars string argument could not be converted to a native string.";

			v8::TryCatch ConversionFailure(pIsolate);
			v8::Local<v8::String> LocalString {};
			if (!LocalValue->ToString(LocalContext).ToLocal(&LocalString)) {
				if (!ConversionFailure.HasCaught()) {
					ThrowError(pIsolate, kConversionError);
				}

				ConversionFailure.ReThrow();
				return false;
			}

			v8::String::Utf8Value UTF8Value(pIsolate, LocalString);
			char const* const pszValue = *UTF8Value;
			if (ConversionFailure.HasCaught() || !pszValue) {
				if (!ConversionFailure.HasCaught()) {
					ThrowError(pIsolate, kConversionError);
				}

				ConversionFailure.ReThrow();
				return false;
			}

			strValueOut.assign(pszValue, static_cast<std::size_t>(UTF8Value.length()));

			return true;
		}

		void SetConVarCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) try {
			constexpr int kValueArgumentIndex = 1;
			constexpr char kArgumentError[] = "cvars.SetConVar(strConVarName, Value) expects a ConVar name and value.";
			constexpr char kIntegerValueError[] = "cvars.SetConVar(strConVarName, Value) expects an integer value.";
			constexpr char kNumericValueError[] = "cvars.SetConVar(strConVarName, Value) expects a finite numeric value in the float range.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			if (CallbackInformation.Length() <= kValueArgumentIndex) {
				ThrowError(pIsolate, kArgumentError);
				return;
			}

			auto* const pConVar = CVarsRequireConVarFromArguments(CallbackInformation, kArgumentError);
			if (!pConVar) {
				return;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				return;
			}

			if (CallbackInformation[kValueArgumentIndex]->IsInt32()) {
				int nValue = 0;
				if (!GetInt32Argument(pIsolate, LocalContext, CallbackInformation[kValueArgumentIndex], kIntegerValueError, nValue)) {
					return;
				}

				pConVar->SetValue(nValue);

			} else if (CallbackInformation[kValueArgumentIndex]->IsNumber()) {
				float flValue = 0.0f;
				if (!GetFloatArgument(pIsolate, LocalContext, CallbackInformation[kValueArgumentIndex], kNumericValueError, flValue)) {
					return;
				}

				pConVar->SetValue(flValue);

			} else if (CallbackInformation[kValueArgumentIndex]->IsBoolean()) {
				pConVar->SetValue(CallbackInformation[kValueArgumentIndex]->BooleanValue(pIsolate) ? 1 : 0);

			} else {
				std::string strValue {};
				if (!ReadConVarString(pIsolate, LocalContext, CallbackInformation[kValueArgumentIndex], strValue)) {
					return;
				}

				pConVar->SetValue(strValue.c_str());
			}

			CallbackInformation.GetReturnValue().Set(true);
		} catch (...) {
			constexpr char kCallbackExceptionError[] = "SetConVarCallback failed with a C++ exception.";

			ThrowError(CallbackInformation.GetIsolate(), kCallbackExceptionError);
		}

