		void GetPlayerDictionaryEntriesCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) try {
			constexpr int kEntryLength = 2;
			constexpr std::uint32_t kEntityIndexPosition = 0;
			constexpr std::uint32_t kPlayerPosition = 1;
			constexpr char kOperationName[] = "players/dictionary.GetEntries()";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			std::vector<int> vecEntityIndices {};
			if (!CollectPlayerEntityIndices(pIsolate, vecEntityIndices, kAnyTeamIndex, PlayerFakeClientFilter::ANY, PlayerAliveFilter::ANY, kOperationName)) {
				return;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				return;
			}

			v8::Local<v8::Array> const LocalEntryArray = v8::Array::New(pIsolate);
			if (LocalEntryArray.IsEmpty()) {
				return;
			}

			std::uint32_t unOutputIndex = 0;
			for (auto const& nEntityIndex : vecEntityIndices) {
				auto* pEdict = static_cast<edict_t*>(nullptr);
				auto* const pPlayerInformation = GetPlayerInformationFromIndex(nEntityIndex, &pEdict);
				if (!pPlayerInformation || !pPlayerInformation->IsConnected() || !pEdict || pEdict->IsFree()) {
					continue;
				}

				v8::Local<v8::Array> const LocalEntryPair = v8::Array::New(pIsolate, kEntryLength);
				if (LocalEntryPair.IsEmpty()) {
					return;
				}

				v8::Maybe<bool> const MaybeSetEntityIndexResult = LocalEntryPair->CreateDataProperty(LocalContext, kEntityIndexPosition, v8::Integer::New(pIsolate, nEntityIndex));
				if (MaybeSetEntityIndexResult.IsNothing() || !MaybeSetEntityIndexResult.FromJust()) {
					return;
				}

				v8::Local<v8::Object> const LocalPlayer = MakePlayerObject(pIsolate, LocalContext, nEntityIndex);
				if (LocalPlayer.IsEmpty()) {
					return;
				}

				v8::Maybe<bool> const MaybeSetPlayerResult = LocalEntryPair->CreateDataProperty(LocalContext, kPlayerPosition, LocalPlayer);
				if (MaybeSetPlayerResult.IsNothing() || !MaybeSetPlayerResult.FromJust()) {
					return;
				}

				v8::Maybe<bool> const MaybeSetEntryResult = LocalEntryArray->CreateDataProperty(LocalContext, unOutputIndex, LocalEntryPair);
				if (MaybeSetEntryResult.IsNothing() || !MaybeSetEntryResult.FromJust()) {
					return;
				}

				++unOutputIndex;
			}

			CallbackInformation.GetReturnValue().Set(LocalEntryArray);
		} catch (...) {
			ThrowError(CallbackInformation.GetIsolate(), "GetPlayerDictionaryEntriesCallback failed with a C++ exception.");
		}

