		bool InstallVoiceMetadata(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalVoiceObject) {
			if (!pIsolate || LocalContext.IsEmpty() || LocalVoiceObject.IsEmpty()) {
				return false;
			}

			auto* const pVoiceServer = GetVoiceServerInterface();
			const int nGetClientListeningVTableIndex = GetVoiceClientListeningVTableIndex();
			const int nSetClientListeningVTableIndex = GetVoiceSetClientListeningVTableIndex();
			const int nSetClientProximityVTableIndex = GetVoiceSetClientProximityVTableIndex();
			auto* const pGetClientListeningFunctionAddress = GetVoiceVTableFunctionAddress(nGetClientListeningVTableIndex);
			auto* const pSetClientListeningFunctionAddress = GetVoiceVTableFunctionAddress(nSetClientListeningVTableIndex);
			auto* const pSetClientProximityFunctionAddress = GetVoiceVTableFunctionAddress(nSetClientProximityVTableIndex);
			v8::Local<v8::BigInt> const LocalVoiceServerAddress = v8::BigInt::NewFromUnsigned(pIsolate, static_cast<std::uint64_t>(reinterpret_cast<std::uintptr_t>(pVoiceServer)));
			v8::Local<v8::BigInt> const LocalGetClientListeningFunctionAddress = v8::BigInt::NewFromUnsigned(pIsolate, static_cast<std::uint64_t>(reinterpret_cast<std::uintptr_t>(pGetClientListeningFunctionAddress)));
			v8::Local<v8::BigInt> const LocalSetClientListeningFunctionAddress = v8::BigInt::NewFromUnsigned(pIsolate, static_cast<std::uint64_t>(reinterpret_cast<std::uintptr_t>(pSetClientListeningFunctionAddress)));
			v8::Local<v8::BigInt> const LocalSetClientProximityFunctionAddress = v8::BigInt::NewFromUnsigned(pIsolate, static_cast<std::uint64_t>(reinterpret_cast<std::uintptr_t>(pSetClientProximityFunctionAddress)));
			if (LocalVoiceServerAddress.IsEmpty() || LocalGetClientListeningFunctionAddress.IsEmpty() || LocalSetClientListeningFunctionAddress.IsEmpty() || LocalSetClientProximityFunctionAddress.IsEmpty()) {
				return false;
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalVoiceObject, "Address", LocalVoiceServerAddress)) {
				return false;
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalVoiceObject, "GetClientListeningIndex", v8::Integer::New(pIsolate, nGetClientListeningVTableIndex))) {
				return false;
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalVoiceObject, "SetClientListeningIndex", v8::Integer::New(pIsolate, nSetClientListeningVTableIndex))) {
				return false;
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalVoiceObject, "SetClientProximityIndex", v8::Integer::New(pIsolate, nSetClientProximityVTableIndex))) {
				return false;
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalVoiceObject, "GetClientListeningAddress", LocalGetClientListeningFunctionAddress)) {
				return false;
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalVoiceObject, "SetClientListeningAddress", LocalSetClientListeningFunctionAddress)) {
				return false;
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalVoiceObject, "SetClientProximityAddress", LocalSetClientProximityFunctionAddress)) {
				return false;
			}

			return true;
		}

		v8::Local<v8::Object> MakeVoiceServerObject(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Value> const LocalRuntimeData) {
			if (!pIsolate || LocalContext.IsEmpty() || LocalRuntimeData.IsEmpty()) {
				return {};
			}

			v8::Local<v8::Object> const LocalVoiceServerObject = v8::Object::New(pIsolate);
			if (LocalVoiceServerObject.IsEmpty()) {
				return {};
			}

			if (!InstallVoiceMetadata(pIsolate, LocalContext, LocalVoiceServerObject)) {
				return {};
			}

			if (!InstallVoiceFunctions(pIsolate, LocalContext, LocalVoiceServerObject, LocalRuntimeData)) {
				return {};
			}

			return LocalVoiceServerObject;
		}

