		bool CollectEntityIndices(v8::Isolate* const pIsolate, std::vector<int>& vecEntityIndicesOut, std::string const& strClassNameFilter, char const* const pszOperationName) {
			constexpr std::size_t kFirstEntityIndex = 0;

			if (!pIsolate || !pszOperationName) {
				return false;
			}

			auto* const pGlobalVariables = RequireEntityGlobals(pIsolate, pszOperationName);
			if (!pGlobalVariables) {
				return false;
			}

			std::vector<int> vecEntityIndices = vecEntityIndicesOut;
			const std::size_t unEntityCount = (pGlobalVariables->maxEntities > 0) ? static_cast<std::size_t>(pGlobalVariables->maxEntities) : 0;
			for (std::size_t unEntityIndex = kFirstEntityIndex; unEntityIndex < unEntityCount; ++unEntityIndex) {
				const int nEntityIndex = static_cast<int>(unEntityIndex);
				auto* const pEdict = GetEdictFromEntityIndex(nEntityIndex);
				if (!pEdict || pEdict->IsFree()) {
					continue;
				}

				char const* const pszEntityClassName = pEdict->GetClassName();
				std::string const strEntityClassName = pszEntityClassName ? pszEntityClassName : "";
				if (!strClassNameFilter.empty() && (strEntityClassName != strClassNameFilter)) {
					continue;
				}

				vecEntityIndices.push_back(nEntityIndex);
			}

			vecEntityIndicesOut = std::move(vecEntityIndices);

			return true;
		}

		v8::Local<v8::Array> MakeEntityArrayFromIndices(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, std::vector<int> const& vecEntityIndices) {
			constexpr std::size_t kMaximumEntityCount = std::numeric_limits<std::uint32_t>::max();

			if (!pIsolate || LocalContext.IsEmpty()) {
				return {};
			}

			if (vecEntityIndices.size() > kMaximumEntityCount) {
				return {};
			}

			v8::Local<v8::Array> const LocalEntityArray = v8::Array::New(pIsolate);
			if (LocalEntityArray.IsEmpty()) {
				return {};
			}

			std::uint32_t unOutputIndex = 0;
			for (auto const& nEntityIndex : vecEntityIndices) {
				auto* const pEdict = GetEdictFromEntityIndex(nEntityIndex);
				if (!pEdict || pEdict->IsFree()) {
					continue;
				}

				v8::Local<v8::Object> const LocalEntityObject = MakeEntityObject(pIsolate, LocalContext, nEntityIndex);
				if (LocalEntityObject.IsEmpty()) {
					return {};
				}

				v8::Maybe<bool> const MaybeSetResult = LocalEntityArray->CreateDataProperty(LocalContext, unOutputIndex, LocalEntityObject);
				if (MaybeSetResult.IsNothing() || !MaybeSetResult.FromJust()) {
					return {};
				}

				++unOutputIndex;
			}

			return LocalEntityArray;
		}

		bool ContainsString(std::vector<std::string> const& vecValues, std::string const& strValue) {
			for (std::size_t unValueIndex = 0; unValueIndex < vecValues.size(); ++unValueIndex) {
				if (vecValues[unValueIndex] == strValue) {
					return true;
				}
			}

			return false;
		}

		v8::Local<v8::Array> MakeEntityClassNameArray(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, CGlobalVars* const pGlobalVariables) {
			constexpr std::size_t kFirstEntityIndex = 0;
			constexpr std::size_t kMaximumClassNameCount = std::numeric_limits<std::uint32_t>::max();

			if (!pIsolate || LocalContext.IsEmpty() || !pGlobalVariables) {
				return {};
			}

			v8::Local<v8::Array> const LocalClassNameArray = v8::Array::New(pIsolate);
			if (LocalClassNameArray.IsEmpty()) {
				return {};
			}

			std::vector<std::string> vecClassNames {};
			const std::size_t unEntityCount = (pGlobalVariables->maxEntities > 0) ? static_cast<std::size_t>(pGlobalVariables->maxEntities) : 0;
			for (std::size_t unEntityIndex = kFirstEntityIndex; unEntityIndex < unEntityCount; ++unEntityIndex) {
				const int nEntityIndex = static_cast<int>(unEntityIndex);
				auto* const pEdict = GetEdictFromEntityIndex(nEntityIndex);
				if (!pEdict || pEdict->IsFree()) {
					continue;
				}

				char const* const pszClassName = pEdict->GetClassName();
				std::string const strClassName = pszClassName ? pszClassName : "";
				if (strClassName.empty() || ContainsString(vecClassNames, strClassName)) {
					continue;
				}

				vecClassNames.push_back(strClassName);
			}

			if (vecClassNames.size() > kMaximumClassNameCount) {
				return {};
			}

			for (std::size_t unClassNameIndex = 0; unClassNameIndex < vecClassNames.size(); ++unClassNameIndex) {
				v8::Local<v8::String> const LocalClassName = MakeString(pIsolate, vecClassNames[unClassNameIndex]);
				if (LocalClassName.IsEmpty()) {
					return {};
				}

				v8::Maybe<bool> const MaybeSetResult = LocalClassNameArray->CreateDataProperty(LocalContext, static_cast<std::uint32_t>(unClassNameIndex), LocalClassName);
				if (MaybeSetResult.IsNothing() || !MaybeSetResult.FromJust()) {
					return {};
				}
			}

			return LocalClassNameArray;
		}

