		void GetAllDictionaryEntitiesCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) try {
			constexpr std::size_t kMaximumEntityCount = std::numeric_limits<int>::max();
			constexpr char kOperationName[] = "entities/dictionary.GetAllEntities()";
			constexpr char kCountPropertyName[] = "Count";
			constexpr char kClassNameFilter[] = "";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			std::vector<int> vecEntityIndices {};
			if (!CollectEntityIndices(pIsolate, vecEntityIndices, kClassNameFilter, kOperationName)) {
				return;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				return;
			}

			v8::Local<v8::Object> const LocalEntityDictionary = v8::Object::New(pIsolate);
			if (LocalEntityDictionary.IsEmpty()) {
				return;
			}

			std::size_t unEntityCount = 0;
			for (auto const& nEntityIndex : vecEntityIndices) {
				auto* const pEdict = GetEdictFromEntityIndex(nEntityIndex);
				if (!pEdict || pEdict->IsFree()) {
					continue;
				}

				std::string const strEntityIndex = std::to_string(nEntityIndex);
				v8::Local<v8::Object> const LocalEntity = MakeEntityObject(pIsolate, LocalContext, nEntityIndex);
				if (LocalEntity.IsEmpty()) {
					return;
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalEntityDictionary, strEntityIndex.c_str(), LocalEntity)) {
					return;
				}

				++unEntityCount;
			}

			if (unEntityCount > kMaximumEntityCount) {
				return;
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalEntityDictionary, kCountPropertyName, v8::Integer::New(pIsolate, static_cast<int>(unEntityCount)))) {
				return;
			}

			CallbackInformation.GetReturnValue().Set(LocalEntityDictionary);
		} catch (...) {
			ThrowError(CallbackInformation.GetIsolate(), "GetAllDictionaryEntitiesCallback failed with a C++ exception.");
		}

