			if ((CallbackInformation.Length() > kEntityArgumentIndex) && !GetEntityIndexFromValue(pIsolate, LocalContext, CallbackInformation[kEntityArgumentIndex], nEntityIndex)) {
				return;
			}

			CallbackInformation.GetReturnValue().Set(nEntityIndex);
