		void GetPlayerIndexFromNetworkIDCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) try {
			constexpr int kNetworkIDArgumentIndex = 0;
			constexpr int kRequiredArgumentCount = kNetworkIDArgumentIndex + 1;
			constexpr int kInvalidEntityIndex = -1;
			constexpr std::size_t kFirstPlayerEntityIndex = 1;
			constexpr char kArgumentError[] = "players/helpers.GetIndexFromNetworkID(strNetworkID) expects a network ID string.";
			constexpr char kEmptyNetworkIDError[] = "players/helpers.GetIndexFromNetworkID(strNetworkID) expects a non-empty network ID.";
			constexpr char kOperationName[] = "players/helpers.GetIndexFromNetworkID(strNetworkID)";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			if ((CallbackInformation.Length() < kRequiredArgumentCount) || !CallbackInformation[kNetworkIDArgumentIndex]->IsString()) {
				ThrowError(pIsolate, kArgumentError);
				return;
			}

			std::string const strNetworkID = ValueToString(pIsolate, CallbackInformation[kNetworkIDArgumentIndex]);
			if (strNetworkID.empty()) {
				ThrowError(pIsolate, kEmptyNetworkIDError);
				return;
			}

			std::vector<std::string> vecNetworkIDCandidates {};
			AddPlayerSteamIDCandidates(vecNetworkIDCandidates, strNetworkID);

			if (vecNetworkIDCandidates.empty()) {
				CallbackInformation.GetReturnValue().Set(kInvalidEntityIndex);
				return;
			}

			auto* const pPlayerInformationManager = RequirePlayerInformationManager(pIsolate, kOperationName);
			if (!pPlayerInformationManager) {
				return;
			}

			auto* const pGlobalVariables = RequirePlayersGlobals(pIsolate, kOperationName);
			if (!pGlobalVariables) {
				return;
			}

			const std::size_t unPlayerCount = (pGlobalVariables->maxClients > 0) ? static_cast<std::size_t>(pGlobalVariables->maxClients) : 0;
			for (std::size_t unEntityIndex = kFirstPlayerEntityIndex; unEntityIndex <= unPlayerCount; ++unEntityIndex) {
				const int nEntityIndex = static_cast<int>(unEntityIndex);
				auto* const pPlayerEdict = GetEdictFromEntityIndex(nEntityIndex);
				auto* const pPlayerInformation = (pPlayerEdict && !pPlayerEdict->IsFree()) ? pPlayerInformationManager->GetPlayerInfo(pPlayerEdict) : nullptr;
				if (!pPlayerInformation || !pPlayerInformation->IsConnected()) {
					continue;
				}

				if (DoesPlayerNetworkIDMatch(pPlayerInformation, vecNetworkIDCandidates)) {
					CallbackInformation.GetReturnValue().Set(nEntityIndex);
					return;
				}
			}

			CallbackInformation.GetReturnValue().Set(kInvalidEntityIndex);
		} catch (...) {
			ThrowError(CallbackInformation.GetIsolate(), "GetPlayerIndexFromNetworkIDCallback failed with a C++ exception.");
		}

