			constexpr char kCVarTypeError[] = "players/helpers.GetClientCVarValue(Player, strCVarName) expects strCVarName to be a string.";
			constexpr char kEmptyCVarNameError[] = "players/helpers.GetClientCVarValue(Player, strCVarName) expects a non-empty CVar name.";
			constexpr char kOperationName[] = "players/helpers.GetClientCVarValue(Player, strCVarName)";

			auto* const pIsolate = CallbackInformation.GetIsolate();
