		void GetEntityCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) try {
			constexpr int kEntityIndexArgumentIndex = 0;
			constexpr int kRequiredArgumentCount = kEntityIndexArgumentIndex + 1;
			constexpr int kInvalidEntityIndex = -1;
			constexpr char kArgumentError[] = "Entity(nEntityIndex) expects an entity index.";
			constexpr char kTypeError[] = "Entity(nEntityIndex) expects an integer entity index.";
			constexpr char kOperationName[] = "Entity(nEntityIndex)";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			if (CallbackInformation.Length() < kRequiredArgumentCount) {
				ThrowError(pIsolate, kArgumentError);
				return;
			}

			if (!CallbackInformation[kEntityIndexArgumentIndex]->IsInt32()) {
				ThrowError(pIsolate, kTypeError);
				return;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				return;
			}

			int nEntityIndex = kInvalidEntityIndex;
			if (!GetInt32Argument(pIsolate, LocalContext, CallbackInformation[kEntityIndexArgumentIndex], kTypeError, nEntityIndex)) {
				return;
			}

			if (!RequireEntityGlobals(pIsolate, kOperationName)) {
				return;
			}

			auto* const pEntityEdict = GetEdictFromEntityIndex(nEntityIndex);
			if (!pEntityEdict || pEntityEdict->IsFree()) {
				CallbackInformation.GetReturnValue().Set(v8::Null(pIsolate));
				return;
			}

			v8::Local<v8::Object> const LocalEntity = MakeEntityObject(pIsolate, LocalContext, nEntityIndex);
			if (LocalEntity.IsEmpty()) {
				return;
			}

			CallbackInformation.GetReturnValue().Set(LocalEntity);
		} catch (...) {
			ThrowError(CallbackInformation.GetIsolate(), "GetEntityCallback failed with a C++ exception.");
		}

