		void GetEntityKeyValueCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) try {
			constexpr int kEntityArgumentIndex = 0;
			constexpr int kKeyArgumentIndex = 1;
			constexpr int kRequiredArgumentCount = kKeyArgumentIndex + 1;
			constexpr int kMaximumLengthArgumentIndex = kRequiredArgumentCount;
			constexpr int kMaximumLengthArgumentCount = kMaximumLengthArgumentIndex + 1;
			constexpr int kMinimumBufferLength = 1;
			constexpr int kDefaultBufferLength = 256;
			constexpr char kOperationName[] = "entities/factories.GetEntityKeyValue(Entity, strKeyName, nMaximumLength?)";
			constexpr char kUsageMessage[] = "entities/factories.GetEntityKeyValue(Entity, strKeyName, nMaximumLength?) expects an entity and non-empty string key.";
			constexpr char kInvalidEntityMessage[] = "entities/factories.GetEntityKeyValue(Entity, strKeyName, nMaximumLength?) received an invalid entity.";
			constexpr char kEmptyKeyMessage[] = "entities/factories.GetEntityKeyValue(Entity, strKeyName, nMaximumLength?) expects a non-empty key without NUL bytes.";
			constexpr char kMaximumLengthMessage[] = "entities/factories.GetEntityKeyValue(Entity, strKeyName, nMaximumLength?) expects nMaximumLength to be a positive integer.";
			constexpr char kUnterminatedValueMessage[] = "entities/factories.GetEntityKeyValue(Entity, strKeyName, nMaximumLength?) received an unterminated native value.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			if ((CallbackInformation.Length() < kRequiredArgumentCount) || !CallbackInformation[kKeyArgumentIndex]->IsString()) {
				ThrowError(pIsolate, kUsageMessage);
				return;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				return;
			}

			CBaseEntity* pBaseEntity = nullptr;
			if (!ResolveEntityFactoryBaseEntityFromValue(pIsolate, LocalContext, CallbackInformation[kEntityArgumentIndex], pBaseEntity)) {
				return;
			}

			std::string const strKeyName = ValueToString(pIsolate, CallbackInformation[kKeyArgumentIndex]);

			if (!pBaseEntity) {
				ThrowError(pIsolate, kInvalidEntityMessage);
				return;
			}

			if (strKeyName.empty() || (strKeyName.find('\0') != std::string::npos)) {
				ThrowError(pIsolate, kEmptyKeyMessage);
				return;
			}

			int nMaximumLength = kDefaultBufferLength;
			if ((CallbackInformation.Length() >= kMaximumLengthArgumentCount) && !IsValueNullish(CallbackInformation[kMaximumLengthArgumentIndex])) {
				if (!CallbackInformation[kMaximumLengthArgumentIndex]->IsInt32()) {
					ThrowError(pIsolate, kMaximumLengthMessage);
					return;
				}

				if (!GetInt32Argument(pIsolate, LocalContext, CallbackInformation[kMaximumLengthArgumentIndex], kMaximumLengthMessage, nMaximumLength)) {
					return;
				}

				if (nMaximumLength < kMinimumBufferLength) {
					ThrowError(pIsolate, kMaximumLengthMessage);
					return;
				}
			}

			auto* const pServerTools = RequireEntityFactoriesServerTools(pIsolate, kOperationName);
			if (!pServerTools) {
				return;
			}

			std::vector<char> vecValueBuffer = std::vector<char>(static_cast<std::size_t>(nMaximumLength), '\0');
			if (!pServerTools->GetKeyValue(pBaseEntity, strKeyName.c_str(), vecValueBuffer.data(), nMaximumLength)) {
				CallbackInformation.GetReturnValue().Set(v8::Null(pIsolate));
				return;
			}

			auto const itValueTerminator = std::find(vecValueBuffer.cbegin(), vecValueBuffer.cend(), '\0');
			if (itValueTerminator == vecValueBuffer.cend()) {
				ThrowError(pIsolate, kUnterminatedValueMessage);
				return;
			}

			v8::Local<v8::String> const LocalValue = MakeString(pIsolate, vecValueBuffer.data());
			if (LocalValue.IsEmpty()) {
				return;
			}

			CallbackInformation.GetReturnValue().Set(LocalValue);
		} catch (...) {
			ThrowError(CallbackInformation.GetIsolate(), "GetEntityKeyValueCallback failed with a C++ exception.");
		}

