		bool SetEntityFactoryFunction(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalEntityFactoriesObject, char const* const pszName, v8::FunctionCallback const Callback, v8::Local<v8::Value> const LocalRuntimeData) {
			if (!pIsolate || LocalContext.IsEmpty() || LocalEntityFactoriesObject.IsEmpty() || !pszName || !*pszName || !Callback || LocalRuntimeData.IsEmpty()) {
				return false;
			}

			v8::Local<v8::Function> LocalFunction {};
			if (!v8::Function::New(LocalContext, Callback, LocalRuntimeData).ToLocal(&LocalFunction)) {
				return false;
			}

			return SetRecordProperty(pIsolate, LocalContext, LocalEntityFactoriesObject, pszName, LocalFunction);
		}

		template <typename TServerTools>
		bool InstallEntityFactoriesDestroyEntityByHammerIDFunction(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalEntityFactoriesObject, v8::Local<v8::Value> const LocalRuntimeData) {
			if (!pIsolate || LocalContext.IsEmpty() || LocalEntityFactoriesObject.IsEmpty() || LocalRuntimeData.IsEmpty()) {
				return false;
			}

			if constexpr (kEntityFactoriesHasDestroyHammerID<TServerTools>) {
				return SetEntityFactoryFunction(pIsolate, LocalContext, LocalEntityFactoriesObject, "DestroyEntityByHammerID", DestroyEntityByHammerIDCallback<TServerTools>, LocalRuntimeData);

			} else {
				return true;
			}
		}

		bool InstallEntityFactoriesFunctions(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalEntityFactoriesObject, v8::Local<v8::Value> const LocalRuntimeData) {
			if (!pIsolate || LocalContext.IsEmpty() || LocalEntityFactoriesObject.IsEmpty() || LocalRuntimeData.IsEmpty()) {
				return false;
			}

			if (!SetEntityFactoryFunction(pIsolate, LocalContext, LocalEntityFactoriesObject, "CreateEntityByClassName", CreateEntityByClassNameCallback, LocalRuntimeData)) {
				return false;
			}

			if (!SetEntityFactoryFunction(pIsolate, LocalContext, LocalEntityFactoriesObject, "CreateAndSpawnEntityByClassName", CreateAndSpawnEntityByClassNameCallback, LocalRuntimeData)) {
				return false;
			}

			if (!SetEntityFactoryFunction(pIsolate, LocalContext, LocalEntityFactoriesObject, "DispatchEntitySpawn", DispatchEntitySpawnCallback, LocalRuntimeData)) {
				return false;
			}

			if (!SetEntityFactoryFunction(pIsolate, LocalContext, LocalEntityFactoriesObject, "SetEntityKeyValue", SetEntityKeyValueCallback, LocalRuntimeData)) {
				return false;
			}

			if (!SetEntityFactoryFunction(pIsolate, LocalContext, LocalEntityFactoriesObject, "GetEntityKeyValue", GetEntityKeyValueCallback, LocalRuntimeData)) {
				return false;
			}

			if (!SetEntityFactoryFunction(pIsolate, LocalContext, LocalEntityFactoriesObject, "FindEntityByHammerID", FindEntityByHammerIDCallback, LocalRuntimeData)) {
				return false;
			}

			if (!InstallEntityFactoriesDestroyEntityByHammerIDFunction<IServerTools>(pIsolate, LocalContext, LocalEntityFactoriesObject, LocalRuntimeData)) {
				return false;
			}

			return true;
		}
#endif

