		bool EntityDatamapsIsEntityHandleCurrent(CBaseHandle const& EntityHandle, CBaseEntity* const pBaseEntity) {
			if (!EntityHandle.IsValid() || !pBaseEntity) {
				return false;
			}

			auto* const pEntityEdict = GetValidEntityEdictFromIndex(EntityHandle.GetEntryIndex());
			auto* const pServerUnknown = pEntityEdict ? pEntityEdict->GetUnknown() : nullptr;

			return pServerUnknown && (pServerUnknown->GetRefEHandle().ToInt() == EntityHandle.ToInt()) && (pServerUnknown->GetBaseEntity() == pBaseEntity);
		}

		bool EntityDatamapsValidatePropertyEntity(v8::Isolate* const pIsolate, CBaseHandle const& PropertyEntityHandle, CBaseEntity* const pPropertyBaseEntity) {
			constexpr char kEntityResolutionErrorMessage[] = "Unable to resolve entity for datamap property access.";

			if (!EntityDatamapsIsEntityHandleCurrent(PropertyEntityHandle, pPropertyBaseEntity)) {
				ThrowError(pIsolate, kEntityResolutionErrorMessage);
				return false;
			}

			return true;
		}

		void EntityDatamapsSetStringIDProperty(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, v8::Local<v8::Value> const LocalEntityValue, v8::Local<v8::Value> const LocalPropertyValue, v8::Local<v8::Value> const LocalSetValue) {
			try {
				constexpr char kStringValueRequiredErrorMessage[] = "entities/datamaps string-ID property expects a string value.";
				constexpr char kStringAllocationErrorMessage[] = "SetEntityDataMapPropertyString could not allocate the value in the game's string pool.";

				static_assert(std::is_trivially_copyable_v<string_t>);

				auto* const pIsolate = CallbackInformation.GetIsolate();
				if (!pIsolate || LocalEntityValue.IsEmpty() || LocalPropertyValue.IsEmpty() || LocalSetValue.IsEmpty()) {
					return;
				}

				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				if (!LocalSetValue->IsString()) {
					ThrowError(pIsolate, kStringValueRequiredErrorMessage);
					return;
				}

#ifdef SOURCEJS_HAS_BASE_ENTITY
				std::string const strPropertyValue = ValueToString(pIsolate, LocalSetValue);
#endif

				EntityDatamapsFieldInformation FieldInformation {};
				bool bHasFieldInformation = false;
				char* pchPropertyAddress = nullptr;
				CBaseHandle PropertyEntityHandle {};
				CBaseEntity* pPropertyBaseEntity = nullptr;
				if (!EntityDatamapsGetPropertyAddressFromValues(pIsolate, LocalContext, LocalEntityValue, LocalPropertyValue, pchPropertyAddress, FieldInformation, bHasFieldInformation, &PropertyEntityHandle, &pPropertyBaseEntity)) {
					return;
				}

				if (!EntityDatamapsValidatePropertyStorageRange(pIsolate, pchPropertyAddress, sizeof(string_t))) {
					return;
				}

#ifdef SOURCEJS_HAS_BASE_ENTITY
				string_t StringIDValue {};
				if (!AllocateEntityInputString(strPropertyValue, StringIDValue)) {
					ThrowError(pIsolate, kStringAllocationErrorMessage);
					return;
				}

				if (!EntityDatamapsValidatePropertyEntity(pIsolate, PropertyEntityHandle, pPropertyBaseEntity)) {
					return;
				}

				std::memcpy(pchPropertyAddress, &StringIDValue, sizeof(StringIDValue));
				CallbackInformation.GetReturnValue().Set(true);
#else
				ThrowError(pIsolate, kStringAllocationErrorMessage);
				return;
#endif
			} catch (...) {
				constexpr char kNativeOperationErrorMessage[] = "SetEntityDataMapPropertyString failed with a native C++ exception.";

				ThrowError(CallbackInformation.GetIsolate(), kNativeOperationErrorMessage);
			}
		}

		std::size_t EntityDatamapsGetStringBufferCapacity(EntityDatamapsFieldInformation const& FieldInformation, const bool bHasFieldInformation) {
			constexpr std::size_t kDefaultStringBufferCapacity = 256;

			if (bHasFieldInformation && FieldInformation.m_pTypeDescription && (FieldInformation.m_pTypeDescription->fieldSizeInBytes > 0)) {
				return static_cast<std::size_t>(FieldInformation.m_pTypeDescription->fieldSizeInBytes);
			}

			return kDefaultStringBufferCapacity;
		}

		void EntityDatamapsGetStringArrayProperty(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, v8::Local<v8::Value> const LocalEntityValue, v8::Local<v8::Value> const LocalPropertyValue) {
			try {
				constexpr char kStringNotTerminatedErrorMessage[] = "entities/datamaps string-array property has no NUL terminator within its buffer capacity.";
				constexpr char kUnsupportedStringCapacityErrorMessage[] = "entities/datamaps string-array buffer capacity exceeds the V8 string length range.";

				auto* const pIsolate = CallbackInformation.GetIsolate();
				if (!pIsolate || LocalEntityValue.IsEmpty() || LocalPropertyValue.IsEmpty()) {
					return;
				}

				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				EntityDatamapsFieldInformation FieldInformation {};
				bool bHasFieldInformation = false;
				char* pchPropertyAddress = nullptr;
				if (!EntityDatamapsGetPropertyAddressFromValues(pIsolate, LocalContext, LocalEntityValue, LocalPropertyValue, pchPropertyAddress, FieldInformation, bHasFieldInformation)) {
					return;
				}

				const std::size_t unPropertyBufferCapacity = EntityDatamapsGetStringBufferCapacity(FieldInformation, bHasFieldInformation);
				if (unPropertyBufferCapacity > static_cast<std::size_t>(std::numeric_limits<int>::max())) {
					ThrowError(pIsolate, kUnsupportedStringCapacityErrorMessage);
					return;
				}

				if (!EntityDatamapsValidatePropertyStorageRange(pIsolate, pchPropertyAddress, unPropertyBufferCapacity)) {
					return;
				}

				char const* const pszPropertyValue = pchPropertyAddress;
				char const* const pszTerminator = static_cast<char const*>(std::memchr(pszPropertyValue, '\0', unPropertyBufferCapacity));
				if (!pszTerminator) {
					ThrowError(pIsolate, kStringNotTerminatedErrorMessage);
					return;
				}

				const int nStringByteCount = static_cast<int>(pszTerminator - pszPropertyValue);
				v8::Local<v8::String> LocalString {};
				if (!v8::String::NewFromUtf8(pIsolate, pszPropertyValue, v8::NewStringType::kNormal, nStringByteCount).ToLocal(&LocalString)) {
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalString);
			} catch (...) {
				constexpr char kNativeOperationErrorMessage[] = "GetEntityDataMapPropertyStringArray failed with a native C++ exception.";

				ThrowError(CallbackInformation.GetIsolate(), kNativeOperationErrorMessage);
			}
		}

		void EntityDatamapsSetStringArrayProperty(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, v8::Local<v8::Value> const LocalEntityValue, v8::Local<v8::Value> const LocalPropertyValue, v8::Local<v8::Value> const LocalSetValue) {
			try {
				constexpr char kStringValueRequiredErrorMessage[] = "SetEntityDataMapPropertyStringArray(Entity, Property, strValue) expects strValue to be a string.";

				auto* const pIsolate = CallbackInformation.GetIsolate();
				if (!pIsolate || LocalEntityValue.IsEmpty() || LocalPropertyValue.IsEmpty() || LocalSetValue.IsEmpty()) {
					return;
				}

				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				if (!LocalSetValue->IsString()) {
					ThrowError(pIsolate, kStringValueRequiredErrorMessage);
					return;
				}

				std::string const strPropertyValue = ValueToString(pIsolate, LocalSetValue);

				EntityDatamapsFieldInformation FieldInformation {};
				bool bHasFieldInformation = false;
				char* pchPropertyAddress = nullptr;
				if (!EntityDatamapsGetPropertyAddressFromValues(pIsolate, LocalContext, LocalEntityValue, LocalPropertyValue, pchPropertyAddress, FieldInformation, bHasFieldInformation) || !pchPropertyAddress) {
					return;
				}

				const std::size_t unPropertyBufferCapacity = EntityDatamapsGetStringBufferCapacity(FieldInformation, bHasFieldInformation);
				if (!EntityDatamapsValidatePropertyStorageRange(pIsolate, pchPropertyAddress, unPropertyBufferCapacity)) {
					return;
				}

				const std::size_t unTerminatorIndex = unPropertyBufferCapacity - 1;
				char* const pszPropertyBuffer = pchPropertyAddress;
				const std::size_t unMaximumCopyByteCount = std::min(unTerminatorIndex, strPropertyValue.size());
				char const* const pszValueTerminator = static_cast<char const*>(std::memchr(strPropertyValue.data(), '\0', unMaximumCopyByteCount));
				const std::size_t unCopyByteCount = pszValueTerminator ? static_cast<std::size_t>(pszValueTerminator - strPropertyValue.data()) : unMaximumCopyByteCount;
				std::memcpy(pszPropertyBuffer, strPropertyValue.data(), unCopyByteCount);
				std::memset(pszPropertyBuffer + unCopyByteCount, '\0', unPropertyBufferCapacity - unCopyByteCount);
				CallbackInformation.GetReturnValue().Set(true);
			} catch (...) {
				constexpr char kNativeOperationErrorMessage[] = "SetEntityDataMapPropertyStringArray failed with a native C++ exception.";

				ThrowError(CallbackInformation.GetIsolate(), kNativeOperationErrorMessage);
			}
		}

