		void EntityDatamapsSetVectorProperty(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, v8::Local<v8::Value> const LocalEntityValue, v8::Local<v8::Value> const LocalPropertyValue, v8::Local<v8::Value> const LocalSetValue) {
			try {
				constexpr std::size_t kXComponentOffset = 0;
				constexpr std::size_t kYComponentOffset = sizeof(float);
				constexpr std::size_t kZComponentOffset = sizeof(float) * 2;
				constexpr std::size_t kVectorComponentCount = 3;
#ifdef SOURCEJS_HAS_FIELD_VECTOR2D
				constexpr std::size_t kVector2DComponentCount = 2;
#endif

				static_assert(std::is_standard_layout_v<Vector>);
				static_assert(offsetof(Vector, x) == kXComponentOffset);
				static_assert(offsetof(Vector, y) == kYComponentOffset);
				static_assert(offsetof(Vector, z) == kZComponentOffset);
				static_assert(sizeof(Vector) >= (sizeof(float) * kVectorComponentCount));
#ifdef SOURCEJS_HAS_FIELD_VECTOR2D
				static_assert(std::is_standard_layout_v<Vector2D>);
				static_assert(offsetof(Vector2D, x) == kXComponentOffset);
				static_assert(offsetof(Vector2D, y) == kYComponentOffset);
				static_assert(sizeof(Vector2D) >= (sizeof(float) * kVector2DComponentCount));
#endif

				auto* const pIsolate = CallbackInformation.GetIsolate();
				if (!pIsolate || LocalEntityValue.IsEmpty() || LocalPropertyValue.IsEmpty() || LocalSetValue.IsEmpty()) {
					return;
				}

				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				Vector VectorValue {};
				if (!EntityDatamapsGetVectorFromValue(pIsolate, LocalContext, LocalSetValue, VectorValue)) {
					return;
				}

				EntityDatamapsFieldInformation FieldInformation {};
				bool bHasFieldInformation = false;
				char* pchPropertyAddress = nullptr;
				if (!EntityDatamapsGetPropertyAddressFromValues(pIsolate, LocalContext, LocalEntityValue, LocalPropertyValue, pchPropertyAddress, FieldInformation, bHasFieldInformation)) {
					return;
				}

#ifdef SOURCEJS_HAS_FIELD_VECTOR2D
				const bool bHasZComponent = !bHasFieldInformation || !FieldInformation.m_pTypeDescription || (FieldInformation.m_pTypeDescription->fieldType != FIELD_VECTOR2D);
				const std::size_t unVectorByteCount = sizeof(float) * (bHasZComponent ? kVectorComponentCount : kVector2DComponentCount);
#else
				const bool bHasZComponent = true;
				const std::size_t unVectorByteCount = sizeof(float) * kVectorComponentCount;
#endif
				if (!EntityDatamapsValidatePropertyStorageRange(pIsolate, pchPropertyAddress, unVectorByteCount)) {
					return;
				}

				const std::uintptr_t unVectorAddress = reinterpret_cast<std::uintptr_t>(pchPropertyAddress);
				std::memcpy(reinterpret_cast<void*>(unVectorAddress + kXComponentOffset), &VectorValue.x, sizeof(float));
				std::memcpy(reinterpret_cast<void*>(unVectorAddress + kYComponentOffset), &VectorValue.y, sizeof(float));

				if (bHasZComponent) {
					std::memcpy(reinterpret_cast<void*>(unVectorAddress + kZComponentOffset), &VectorValue.z, sizeof(float));
				}

				CallbackInformation.GetReturnValue().Set(true);
			} catch (...) {
				constexpr char kNativeOperationErrorMessage[] = "SetEntityDataMapPropertyVector failed with a native C++ exception.";

				ThrowError(CallbackInformation.GetIsolate(), kNativeOperationErrorMessage);
			}
		}

