		void GetEntityInputFunctionCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			try {
				constexpr int kRequiredArgumentCount = 2;
				constexpr int kEntityArgumentIndex = 0;
				constexpr int kFieldArgumentIndex = 1;
				constexpr int kUnknownFieldIndex = -1;
				constexpr char kUsageErrorMessage[] = "GetEntityInputFunction(Entity, Field) expects Entity and Field.";
				constexpr char kFieldErrorMessage[] = "GetEntityInputFunction(Entity, Field) expects Field to be a string or type description.";
				constexpr char kResolutionErrorMessage[] = "GetEntityInputFunction(Entity, Field) failed to resolve an entity datamap input function.";
				constexpr char kInputFunctionObjectErrorMessage[] = "GetEntityInputFunction(Entity, Field) failed to create the input function object.";
				constexpr char kTypeDescriptionErrorMessage[] = "GetEntityInputFunction(Entity, Field) failed to create the field description.";
				constexpr char kPropertyErrorMessage[] = "GetEntityInputFunction(Entity, Field) failed to populate the input function object.";
				constexpr char kAddressPropertyName[] = "Address";
				constexpr char kEntityPropertyName[] = "Entity";
				constexpr char kDescriptionPropertyName[] = "Description";

				auto* const pIsolate = CallbackInformation.GetIsolate();
				if (!pIsolate) {
					return;
				}

				if (CallbackInformation.Length() < kRequiredArgumentCount) {
					ThrowError(pIsolate, kUsageErrorMessage);
					return;
				}

				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				v8::Local<v8::Value> const LocalEntityValue = CallbackInformation[kEntityArgumentIndex];
				v8::Local<v8::Value> const LocalFieldValue = CallbackInformation[kFieldArgumentIndex];
				CBaseEntity* pTargetBaseEntity = nullptr;
				if (!ResolveEntityDatamapsBaseEntityFromValue(pIsolate, LocalContext, LocalEntityValue, pTargetBaseEntity)) {
					return;
				}

				if (!pTargetBaseEntity) {
					pTargetBaseEntity = GetEntityBaseEntityFromAddressValue(LocalEntityValue);
				}

				CBaseHandle TargetEntityHandle {};
				bool bHasTargetIdentity = false;
				if (pTargetBaseEntity) {
					const int nEntityIndex = GetEntityIndexFromBaseEntity(pTargetBaseEntity);
					auto* const pEntityEdict = GetValidEntityEdictFromIndex(nEntityIndex);
					auto* const pServerUnknown = pEntityEdict ? pEntityEdict->GetUnknown() : nullptr;
					if (pServerUnknown && pServerUnknown->GetRefEHandle().IsValid() && (pServerUnknown->GetBaseEntity() == pTargetBaseEntity)) {
						CBaseHandle const& EntityHandle = pServerUnknown->GetRefEHandle();
						TargetEntityHandle.Init(EntityHandle.GetEntryIndex(), EntityHandle.GetSerialNumber());
						bHasTargetIdentity = true;
					}
				}

				typedescription_t* pInputTypeDescription = nullptr;
				{
					v8::TryCatch FieldResolutionFailure(pIsolate);
					try {
						pInputTypeDescription = EntityDatamapsGetTypeDescriptionFromValue(pIsolate, LocalContext, LocalFieldValue);
						if (FieldResolutionFailure.HasCaught()) {
							FieldResolutionFailure.ReThrow();
							return;
						}
					} catch (...) {
						if (FieldResolutionFailure.HasCaught()) {
							FieldResolutionFailure.ReThrow();
						}

						throw;
					}
				}

				if (pTargetBaseEntity && (!bHasTargetIdentity || !EntityDatamapsIsEntityHandleCurrent(TargetEntityHandle, pTargetBaseEntity))) {
					ThrowError(pIsolate, kResolutionErrorMessage);
					return;
				}

				EntityDatamapsFieldInformation DatamapFieldInformation {};
				if (!pInputTypeDescription && pTargetBaseEntity) {
					auto* const pDatamap = EntityDatamapsGetDatamapFromBaseEntity(pTargetBaseEntity);
					if (!LocalFieldValue->IsString()) {
						ThrowError(pIsolate, kFieldErrorMessage);
						return;
					}

					std::string const strFieldName = ValueToString(pIsolate, LocalFieldValue);
					if (pDatamap && !strFieldName.empty() && EntityDatamapsFindFieldInformation(pDatamap, strFieldName, DatamapFieldInformation)) {
						pInputTypeDescription = DatamapFieldInformation.m_pTypeDescription;
					}
				}

				if (!pTargetBaseEntity || !pInputTypeDescription || !EntityDatamapsIsRecordStorageRangeValid(pInputTypeDescription, sizeof(typedescription_t), alignof(typedescription_t))) {
					ThrowError(pIsolate, kResolutionErrorMessage);
					return;
				}

				if ((pInputTypeDescription->flags & FTYPEDESC_INPUT) == 0) {
					ThrowError(pIsolate, kResolutionErrorMessage);
					return;
				}

				if (!DatamapFieldInformation.m_pTypeDescription) {
					DatamapFieldInformation.m_pTypeDescription = pInputTypeDescription;
					DatamapFieldInformation.m_nFieldIndex = kUnknownFieldIndex;
					DatamapFieldInformation.m_nFieldOffset = EntityDatamapsGetTypeDescriptionOffset(pInputTypeDescription);
					DatamapFieldInformation.m_strFieldName = pInputTypeDescription->fieldName ? pInputTypeDescription->fieldName : "";
					DatamapFieldInformation.m_strFieldPath = DatamapFieldInformation.m_strFieldName;
				}

				v8::Local<v8::Object> const LocalInputFunctionObject = v8::Object::New(pIsolate);
				if (LocalInputFunctionObject.IsEmpty()) {
					ThrowError(pIsolate, kInputFunctionObjectErrorMessage);
					return;
				}

				v8::Local<v8::Object> const LocalTypeDescriptionObject = EntityDatamapsMakeTypeDescriptionObject(pIsolate, LocalContext, DatamapFieldInformation.m_pDatamap, pInputTypeDescription, DatamapFieldInformation.m_nFieldIndex, DatamapFieldInformation.m_nFieldOffset, DatamapFieldInformation.m_strFieldPath);
				if (LocalTypeDescriptionObject.IsEmpty()) {
					ThrowError(pIsolate, kTypeDescriptionErrorMessage);
					return;
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalInputFunctionObject, kAddressPropertyName, EntityDatamapsMakeAddressValue(pIsolate, pInputTypeDescription)) || !SetRecordProperty(pIsolate, LocalContext, LocalInputFunctionObject, kEntityPropertyName, MakeEntityAddressValue(pIsolate, pTargetBaseEntity)) || !SetRecordProperty(pIsolate, LocalContext, LocalInputFunctionObject, kDescriptionPropertyName, LocalTypeDescriptionObject)) {
					ThrowError(pIsolate, kPropertyErrorMessage);
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalInputFunctionObject);
			} catch (...) {
				constexpr char kNativeOperationErrorMessage[] = "GetEntityInputFunction failed with a native C++ exception.";

				ThrowError(CallbackInformation.GetIsolate(), kNativeOperationErrorMessage);
			}
		}

