		template <typename T>
		bool EntityPropertiesGetNumberFromValue(v8::Local<v8::Context> const LocalContext, v8::Local<v8::Value> const LocalValue, T& NumericValueOut) noexcept {
			static_assert(std::is_arithmetic_v<T> && !std::is_same_v<T, bool>, "EntityPropertiesGetNumberFromValue requires a non-boolean arithmetic type");

			if (LocalValue.IsEmpty()) {
				return false;
			}

			if (LocalValue->IsBigInt()) {
				bool bLossless = false;
				if constexpr (std::is_unsigned_v<T>) {
					const std::uint64_t unParsedValue = LocalValue.As<v8::BigInt>()->Uint64Value(&bLossless);
					if (!bLossless || (unParsedValue > static_cast<std::uint64_t>(std::numeric_limits<T>::max()))) {
						return false;
					}

					NumericValueOut = static_cast<T>(unParsedValue);

				} else {
					const std::int64_t nParsedValue = LocalValue.As<v8::BigInt>()->Int64Value(&bLossless);
					if (!bLossless) {
						return false;
					}

					if constexpr (std::is_integral_v<T>) {
						if ((nParsedValue < static_cast<std::int64_t>(std::numeric_limits<T>::lowest())) || (nParsedValue > static_cast<std::int64_t>(std::numeric_limits<T>::max()))) {
							return false;
						}
					}

					NumericValueOut = static_cast<T>(nParsedValue);
				}

				return true;
			}

			if constexpr (std::is_integral_v<T> && (sizeof(T) >= sizeof(std::uint64_t))) {
				return false;

			} else {
				if (!LocalValue->IsNumber()) {
					return false;
				}

				if (LocalContext.IsEmpty()) {
					return false;
				}

				v8::Maybe<double> const MaybeNumber = LocalValue->NumberValue(LocalContext);
				if (MaybeNumber.IsNothing()) {
					return false;
				}

				const double dblNumericValue = MaybeNumber.FromJust();
				if (!std::isfinite(dblNumericValue)) {
					return false;
				}

				if constexpr (std::is_integral_v<T>) {
					if (std::floor(dblNumericValue) != dblNumericValue) {
						return false;
					}

					const double dblExclusiveLimit = std::ldexp(1.0, std::numeric_limits<T>::digits);
					if constexpr (std::is_signed_v<T>) {
						if ((dblNumericValue < -dblExclusiveLimit) || (dblNumericValue >= dblExclusiveLimit)) {
							return false;
						}

					} else {
						if ((dblNumericValue < 0.0) || (dblNumericValue >= dblExclusiveLimit)) {
							return false;
						}
					}

				} else {
					if ((dblNumericValue < static_cast<double>(std::numeric_limits<T>::lowest())) || (dblNumericValue > static_cast<double>(std::numeric_limits<T>::max()))) {
						return false;
					}
				}

				NumericValueOut = static_cast<T>(dblNumericValue);

				return true;
			}
		}

		template <typename T>
		bool EntityPropertiesGetUnsignedNumberFromValue(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Value> const LocalValue, T& unNumberOut) {
			static_assert(std::is_integral_v<T> && std::is_unsigned_v<T> && !std::is_same_v<T, bool>, "EntityPropertiesGetUnsignedNumberFromValue requires an unsigned non-boolean integral type");

			if (!pIsolate || LocalContext.IsEmpty() || LocalValue.IsEmpty()) {
				return false;
			}

			return EntityPropertiesGetNumberFromValue(LocalContext, LocalValue, unNumberOut);
		}

