			constexpr char kIntegerValueRequiredErrorMessage[] = "A valid integer value is required.";
			constexpr char kSignedBigIntValueRequiredErrorMessage[] = "A valid signed BigInt value is required.";
			constexpr char kNativeOperationErrorMessage[] = "entities/props signed property write failed with a native C++ exception.";

