				if (!GetEntityPropertiesPropertyAddressFromValues(pIsolate, LocalContext, LocalEntityValue, LocalPropertyValue, pchResolvedPropertyAddress, ResolvedPropertyInformation, bHasResolvedPropertyInformation) || !pchResolvedPropertyAddress) {
					return;
				}

				char chCharacterValue = '\0';
				if (!ReadEntityPropertiesScalarValue(pchResolvedPropertyAddress, chCharacterValue)) {
					ThrowError(pIsolate, "GetEntityPropertyCharacter requires a valid native field storage range.");
					return;
				}

				const char szCharacterValue[kCharacterBufferLength] { chCharacterValue, '\0' };
