		float* EntityPropertiesGetVectorComponentAddress(v8::Isolate* const pIsolate, v8::Local<v8::Value> const LocalMetadataValue) {
			if (!pIsolate) {
				return nullptr;
			}

			if (LocalMetadataValue.IsEmpty() || !LocalMetadataValue->IsExternal()) {
				ThrowError(pIsolate, "Entity vector component access failed because metadata is invalid.");
				return nullptr;
			}

			void* const pVectorComponentAddress = LocalMetadataValue.As<v8::External>()->Value();
			if (!EntityPropertiesIsRecordStorageRangeValid(pVectorComponentAddress, sizeof(float), alignof(float))) {
				ThrowError(pIsolate, "Entity vector component access failed because the address is null, misaligned, or out of range.");
				return nullptr;
			}

			return static_cast<float*>(pVectorComponentAddress);
		}

