		template <std::size_t unBindingCount>
		bool InstallEntityCollisionConstantBindings(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalDestination, EntityCollisionConstantBinding const (&arrBindings)[unBindingCount]) {
			if (!pIsolate || LocalContext.IsEmpty() || LocalDestination.IsEmpty()) {
				return false;
			}

			for (auto const& BindingInformation : arrBindings) {
				if (!SetRecordProperty(pIsolate, LocalContext, LocalDestination, BindingInformation.m_pszName, v8::Integer::New(pIsolate, BindingInformation.m_nValue))) {
					return false;
				}
			}

			return true;
		}

		void GetEntityCollisionConstantsCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kConstantGroupErrorMessage[] = "Unknown entities/collisions constant group.";
			constexpr char kNativeOperationErrorMessage[] = "GetEntityCollisionConstants failed with a native C++ exception.";

			try {
				auto* const pIsolate = CallbackInformation.GetIsolate();
				if (!pIsolate) {
					return;
				}

				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				v8::Local<v8::Object> const LocalCollisionConstants = v8::Object::New(pIsolate);
				v8::Local<v8::Value> const LocalConstantGroup = CallbackInformation.Data();
				if (LocalCollisionConstants.IsEmpty() || LocalConstantGroup.IsEmpty() || !LocalConstantGroup->IsInt32()) {
					return;
				}

				const EntityCollisionConstantGroup ConstantGroup = static_cast<EntityCollisionConstantGroup>(LocalConstantGroup.As<v8::Int32>()->Value());
				if (ConstantGroup == EntityCollisionConstantGroup::EntityCollisionConstantsCollisionGroup) {
					if (!InstallEntityCollisionConstantBindings(pIsolate, LocalContext, LocalCollisionConstants, kEntityCollisionGroupConstantBindings)) {
						return;
					}

				} else if (ConstantGroup == EntityCollisionConstantGroup::EntityCollisionConstantsSolidType) {
					if (!InstallEntityCollisionConstantBindings(pIsolate, LocalContext, LocalCollisionConstants, kEntitySolidTypeConstantBindings)) {
						return;
					}

				} else if (ConstantGroup == EntityCollisionConstantGroup::EntityCollisionConstantsSolidFlags) {
					if (!InstallEntityCollisionConstantBindings(pIsolate, LocalContext, LocalCollisionConstants, kEntitySolidFlagConstantBindings)) {
						return;
					}

				} else {
					ThrowError(pIsolate, kConstantGroupErrorMessage);
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalCollisionConstants);
			} catch (...) {
				ThrowError(CallbackInformation.GetIsolate(), kNativeOperationErrorMessage);
			}
		}
#endif // SOURCEJS_HAS_CONST_H

		template <std::size_t unNameCount>
		bool FindEntityCollisionPropertyNameValue(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Value> const LocalEntityValue, char const* const (&arrPropertyNames)[unNameCount], v8::Local<v8::Value>& LocalPropertyNameOut) {
			static_assert(unNameCount > 0, "FindEntityCollisionPropertyNameValue requires at least one property name");

			if (!pIsolate || LocalContext.IsEmpty() || LocalEntityValue.IsEmpty()) {
				return false;
			}

			CBaseEntity* pBaseEntity = nullptr;
			ServerClass* pServerClass = nullptr;
			{
				v8::TryCatch EntityResolutionFailure(pIsolate);
				try {
					pServerClass = GetEntityPropertiesServerClassFromEntity(pIsolate, LocalContext, LocalEntityValue, &pBaseEntity);
					if (EntityResolutionFailure.HasCaught()) {
						EntityResolutionFailure.ReThrow();
						return false;
					}
				} catch (...) {
					if (EntityResolutionFailure.HasCaught()) {
						EntityResolutionFailure.ReThrow();
					}

					throw;
				}
			}

			if (!pBaseEntity) {
				ThrowError(pIsolate, "Unable to resolve entity for collision property access.");
				return false;
			}

			if (!EntityPropertiesIsRecordStorageRangeValid(pServerClass, sizeof(ServerClass), alignof(ServerClass)) || !EntityPropertiesIsSendTableStorageValid(pServerClass->m_pTable)) {
				ThrowError(pIsolate, "Unable to resolve entity send table for collision property access.");
				return false;
			}

			auto* const pSendTable = pServerClass->m_pTable;
			EntityPropertiesPropertyInformation ResolvedPropertyInformation {};
			for (std::size_t unPropertyNameIndex = 0; unPropertyNameIndex < unNameCount; ++unPropertyNameIndex) {
				char const* const pszPropertyName = arrPropertyNames[unPropertyNameIndex];
				if (!pszPropertyName) {
					continue;
				}

				if (!FindEntityPropertiesPropertyInformation(pServerClass, pSendTable, pszPropertyName, ResolvedPropertyInformation)) {
					continue;
				}

				v8::Local<v8::String> const LocalPropertyName = MakeString(pIsolate, pszPropertyName);
				if (LocalPropertyName.IsEmpty()) {
					return false;
				}

				LocalPropertyNameOut = LocalPropertyName;
				return true;
			}

			std::string strErrorMessage = "None of the SDK collision properties are available:";
			for (std::size_t unPropertyNameIndex = 0; unPropertyNameIndex < unNameCount; ++unPropertyNameIndex) {
				char const* const pszPropertyName = arrPropertyNames[unPropertyNameIndex];

				strErrorMessage += (unPropertyNameIndex == 0) ? " " : ", ";
				strErrorMessage += pszPropertyName ? pszPropertyName : "";
			}

			strErrorMessage += ".";
			ThrowError(pIsolate, strErrorMessage.c_str());

			return false;
		}

		template <typename TField, std::size_t unNameCount>
		void GetEntityCollisionIntegerProperty(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, char const* const (&arrPropertyNames)[unNameCount]) {
			constexpr int kEntityArgumentIndex = 0;
			constexpr int kRequiredArgumentCount = 1;
			constexpr char kNativeOperationErrorMessage[] = "GetEntityCollisionIntegerProperty failed with a native C++ exception.";

			static_assert(unNameCount > 0, "GetEntityCollisionIntegerProperty requires at least one property name");
			static_assert(std::is_integral_v<TField> && !std::is_same_v<TField, bool>, "Collision scalar fields require a non-boolean integral storage type");

			try {
				auto* const pIsolate = CallbackInformation.GetIsolate();
				if (!pIsolate) {
					return;
				}

				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				if (CallbackInformation.Length() < kRequiredArgumentCount) {
					ThrowError(pIsolate, "A collision property getter expects an entity.");
					return;
				}

				v8::Local<v8::Value> const LocalEntityValue = CallbackInformation[kEntityArgumentIndex];
				if (LocalEntityValue.IsEmpty()) {
					return;
				}

				v8::Local<v8::Value> LocalPropertyNameValue {};
				if (!FindEntityCollisionPropertyNameValue(pIsolate, LocalContext, LocalEntityValue, arrPropertyNames, LocalPropertyNameValue)) {
					return;
				}

				if constexpr (std::is_signed_v<TField>) {
					EntityPropertiesGetSignedProperty<TField>(CallbackInformation, LocalEntityValue, LocalPropertyNameValue);

				} else {
					EntityPropertiesGetUnsignedProperty<TField>(CallbackInformation, LocalEntityValue, LocalPropertyNameValue);
				}
			} catch (...) {
				ThrowError(CallbackInformation.GetIsolate(), kNativeOperationErrorMessage);
			}
		}

