		void SetPlayerActiveWeaponCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kPlayerArgumentIndex = 0;
			constexpr int kWeaponArgumentIndex = 1;
			constexpr int kInvalidEntityIndex = -1;
			constexpr int kRequiredArgumentCount = 2;
			constexpr char kUsageErrorMessage[] = "SetActiveWeapon(Player, Weapon) expects a player and weapon.";
			constexpr char kLivePlayerErrorMessage[] = "SetActiveWeapon(Player, Weapon) expects a live player entity.";
			constexpr char kActiveWeaponPropertyName[] = "m_hActiveWeapon";
			constexpr char kMissingPropertyErrorMessage[] = "SetActiveWeapon(Player, Weapon) requires m_hActiveWeapon.";
			constexpr char kWeaponHandleErrorMessage[] = "SetActiveWeapon(Player, Weapon) expects a valid weapon handle.";
			constexpr char kNativeOperationErrorMessage[] = "SetActiveWeapon failed with a native C++ exception.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				if (CallbackInformation.Length() < kRequiredArgumentCount) {
					ThrowError(pIsolate, kUsageErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalPlayerValue = CallbackInformation[kPlayerArgumentIndex];
				v8::Local<v8::Value> const LocalWeaponValue = CallbackInformation[kWeaponArgumentIndex];
				if (LocalPlayerValue.IsEmpty() || LocalWeaponValue.IsEmpty()) {
					return;
				}

				CBaseEntity* pPlayerBaseEntity = nullptr;
				{
					v8::TryCatch PlayerResolutionFailure(pIsolate);
					try {
						pPlayerBaseEntity = GetBaseEntityFromValue(pIsolate, LocalContext, LocalPlayerValue);
						if (PlayerResolutionFailure.HasCaught()) {
							PlayerResolutionFailure.ReThrow();
							return;
						}
					} catch (...) {
						if (PlayerResolutionFailure.HasCaught()) {
							PlayerResolutionFailure.ReThrow();
						}

						throw;
					}
				}

				if (!pPlayerBaseEntity) {
					ThrowError(pIsolate, kLivePlayerErrorMessage);
					return;
				}

				CBaseHandle const PlayerHandle = GetLiveEntityHandle(pPlayerBaseEntity);
				CBaseHandle ActiveWeaponHandle {};
				bool bHasWeaponHandle = false;
				{
					v8::TryCatch WeaponResolutionFailure(pIsolate);
					try {
						bHasWeaponHandle = GetEntityBaseHandleFromValue(pIsolate, LocalContext, LocalWeaponValue, ActiveWeaponHandle);
						if (WeaponResolutionFailure.HasCaught()) {
							WeaponResolutionFailure.ReThrow();
							return;
						}

						if (!bHasWeaponHandle) {
							const int nWeaponEntityIndex = GetValueIndex(pIsolate, LocalContext, LocalWeaponValue);
							if (WeaponResolutionFailure.HasCaught()) {
								WeaponResolutionFailure.ReThrow();
								return;
							}

							auto* const pWeaponEdict = GetValidEntityEdictFromIndex(nWeaponEntityIndex);
							if (!GetEntityBaseHandleFromEdictAddress(pWeaponEdict, ActiveWeaponHandle)) {
								ThrowError(pIsolate, kWeaponHandleErrorMessage);
								return;
							}
						}
					} catch (...) {
						if (WeaponResolutionFailure.HasCaught()) {
							WeaponResolutionFailure.ReThrow();
						}

						throw;
					}
				}

				int nResolvedPlayerIndex = kInvalidEntityIndex;
				int nResolvedWeaponIndex = kInvalidEntityIndex;
				if (!GetEntityIndexFromBaseHandleValue(PlayerHandle, nResolvedPlayerIndex)) {
					ThrowError(pIsolate, kLivePlayerErrorMessage);
					return;
				}

				if (!GetEntityIndexFromBaseHandleValue(ActiveWeaponHandle, nResolvedWeaponIndex)) {
					ThrowError(pIsolate, kWeaponHandleErrorMessage);
					return;
				}

				pPlayerBaseEntity = GetBaseEntityFromIndex(nResolvedPlayerIndex);
				if (!pPlayerBaseEntity) {
					ThrowError(pIsolate, kLivePlayerErrorMessage);
					return;
				}

				// Resolve storage only after weapon getters and original-entity identity checks.
				char* pchActiveWeaponAddress = nullptr;
				if (!PlayersGetSendPropertyAddress(pPlayerBaseEntity, kActiveWeaponPropertyName, pchActiveWeaponAddress) || !pchActiveWeaponAddress) {
					ThrowError(pIsolate, kMissingPropertyErrorMessage);
					return;
				}

				if (!PlayersWriteEntityHandleStorage(pchActiveWeaponAddress, ActiveWeaponHandle)) {
					return;
				}

				CallbackInformation.GetReturnValue().Set(true);
			} catch (...) {
				ThrowError(pIsolate, kNativeOperationErrorMessage);
			}
		}

		std::string PlayersBuildIndexedPropertyName(std::string const& strPropertyPrefix, const int nPropertyIndex) {
			constexpr int kTwoDigitBoundary = 10;
			constexpr int kThreeDigitBoundary = 100;

			std::ostringstream PropertyNameStream {};

			PropertyNameStream << strPropertyPrefix;

			if (nPropertyIndex < kTwoDigitBoundary) {
				PropertyNameStream << "00";
			} else if (nPropertyIndex < kThreeDigitBoundary) {
				PropertyNameStream << "0";
			}

			PropertyNameStream << nPropertyIndex;

			return PropertyNameStream.str();
		}

		void GetPlayerWeaponIndicesCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kPlayerArgumentIndex = 0;
			constexpr int kPropertyPrefixArgumentIndex = 1;
			constexpr int kMaximumWeaponSlotsArgumentIndex = 2;
			constexpr int kRequiredArgumentCount = 2;
			constexpr int kDefaultMaximumWeaponSlots = 64;
			constexpr int kFirstWeaponSlotIndex = 0;
			constexpr int kInvalidEntityIndex = -1;
			constexpr char kUsageErrorMessage[] = "GetWeaponIndices(Player, strPropertyPrefix, unMaximumWeaponSlots?) expects a player and property prefix.";
			constexpr char kLivePlayerErrorMessage[] = "GetWeaponIndices(Player, strPropertyPrefix, unMaximumWeaponSlots?) expects a live player entity.";
			constexpr char kPropertyPrefixErrorMessage[] = "GetWeaponIndices(Player, strPropertyPrefix, unMaximumWeaponSlots?) requires a non-empty property prefix without null bytes.";
			constexpr char kMaximumWeaponSlotsErrorMessage[] = "GetWeaponIndices(Player, strPropertyPrefix, unMaximumWeaponSlots?) expects a positive integer unMaximumWeaponSlots value.";
			constexpr char kWeaponHandleArrayErrorMessage[] = "GetWeaponIndices(Player, strPropertyPrefix, unMaximumWeaponSlots?) could not resolve the player weapon handle array.";
			constexpr char kNativeOperationErrorMessage[] = "GetWeaponIndices failed with a native C++ exception.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				if (CallbackInformation.Length() < kRequiredArgumentCount) {
					ThrowError(pIsolate, kUsageErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalPlayerValue = CallbackInformation[kPlayerArgumentIndex];
				v8::Local<v8::Value> const LocalPropertyPrefixValue = CallbackInformation[kPropertyPrefixArgumentIndex];
				if (LocalPlayerValue.IsEmpty() || LocalPropertyPrefixValue.IsEmpty()) {
					return;
				}

				CBaseEntity* pPlayerBaseEntity = nullptr;
				{
					v8::TryCatch PlayerResolutionFailure(pIsolate);
					try {
						pPlayerBaseEntity = GetBaseEntityFromValue(pIsolate, LocalContext, LocalPlayerValue);
						if (PlayerResolutionFailure.HasCaught()) {
							PlayerResolutionFailure.ReThrow();
							return;
						}
					} catch (...) {
						if (PlayerResolutionFailure.HasCaught()) {
							PlayerResolutionFailure.ReThrow();
						}

						throw;
					}
				}

				if (!pPlayerBaseEntity) {
					ThrowError(pIsolate, kLivePlayerErrorMessage);
					return;
				}

				CBaseHandle const PlayerHandle = GetLiveEntityHandle(pPlayerBaseEntity);
				v8::Local<v8::String> LocalPropertyPrefixString {};
				if (!LocalPropertyPrefixValue->ToString(LocalContext).ToLocal(&LocalPropertyPrefixString)) {
					return;
				}

				std::string const strPropertyPrefix = ValueToString(pIsolate, LocalPropertyPrefixString);
				if (strPropertyPrefix.empty() || (strPropertyPrefix.find('\0') != std::string::npos)) {
					ThrowError(pIsolate, kPropertyPrefixErrorMessage);
					return;
				}

				int nMaximumWeaponSlots = kDefaultMaximumWeaponSlots;
				if (CallbackInformation.Length() > kMaximumWeaponSlotsArgumentIndex) {
					v8::Local<v8::Value> const LocalMaximumWeaponSlotsValue = CallbackInformation[kMaximumWeaponSlotsArgumentIndex];
					if (LocalMaximumWeaponSlotsValue.IsEmpty()) {
						return;
					}

					if (!IsValueNullish(LocalMaximumWeaponSlotsValue)) {
						if (!LocalMaximumWeaponSlotsValue->IsInt32()) {
							ThrowError(pIsolate, kMaximumWeaponSlotsErrorMessage);
							return;
						}

						if (!GetInt32Argument(pIsolate, LocalContext, LocalMaximumWeaponSlotsValue, kMaximumWeaponSlotsErrorMessage, nMaximumWeaponSlots)) {
							return;
						}

						if (nMaximumWeaponSlots <= 0) {
							ThrowError(pIsolate, kMaximumWeaponSlotsErrorMessage);
							return;
						}
					}
				}

				int nResolvedPlayerIndex = kInvalidEntityIndex;
				if (!GetEntityIndexFromBaseHandleValue(PlayerHandle, nResolvedPlayerIndex)) {
					ThrowError(pIsolate, kLivePlayerErrorMessage);
					return;
				}

				pPlayerBaseEntity = GetBaseEntityFromIndex(nResolvedPlayerIndex);
				if (!pPlayerBaseEntity) {
					ThrowError(pIsolate, kLivePlayerErrorMessage);
					return;
				}

				v8::Local<v8::Array> const LocalWeaponIndicesArray = v8::Array::New(pIsolate);
				if (LocalWeaponIndicesArray.IsEmpty()) {
					return;
				}

				std::uint32_t unWeaponIndexCount = 0;
				bool bResolvedAnyWeaponSlot = false;
				for (int nWeaponSlotIndex = kFirstWeaponSlotIndex; nWeaponSlotIndex < nMaximumWeaponSlots; ++nWeaponSlotIndex) {
					std::string const strPropertyName = PlayersBuildIndexedPropertyName(strPropertyPrefix, nWeaponSlotIndex);
					char* pchWeaponHandleAddress = nullptr;
					if (!PlayersGetSendPropertyAddress(pPlayerBaseEntity, strPropertyName.c_str(), pchWeaponHandleAddress)) {
						if (!bResolvedAnyWeaponSlot) {
							ThrowError(pIsolate, kWeaponHandleArrayErrorMessage);
							return;
						}

						break;
					}

					bResolvedAnyWeaponSlot = true;
					unsigned int unWeaponHandle = 0;
					if (!PlayersReadEntityHandleStorage(pchWeaponHandleAddress, unWeaponHandle)) {
						continue;
					}

					int nWeaponEntityIndex = kInvalidEntityIndex;
					if (!GetEntityIndexFromIntegerHandleValue(unWeaponHandle, nWeaponEntityIndex)) {
						continue;
					}

					v8::Local<v8::Integer> const LocalWeaponIndexValue = v8::Integer::New(pIsolate, nWeaponEntityIndex);
					if (LocalWeaponIndexValue.IsEmpty()) {
						return;
					}

					v8::Maybe<bool> const MaybeCreateResult = LocalWeaponIndicesArray->CreateDataProperty(LocalContext, unWeaponIndexCount, LocalWeaponIndexValue);
					if (MaybeCreateResult.IsNothing() || !MaybeCreateResult.FromJust()) {
						return;
					}

					++unWeaponIndexCount;
				}

				CallbackInformation.GetReturnValue().Set(LocalWeaponIndicesArray);
			} catch (...) {
				ThrowError(pIsolate, kNativeOperationErrorMessage);
			}
		}

		void GetPlayerProjectileIndicesCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kPlayerArgumentIndex = 0;
			constexpr int kProjectileClassNameArgumentIndex = 1;
			constexpr int kRequiredArgumentCount = 2;
			constexpr int kFirstEntityIndex = 0;
			constexpr int kFirstPlayerEntityIndex = 1;
			constexpr int kInvalidEntityIndex = -1;
			constexpr char kUsageErrorMessage[] = "GetProjectileIndices(Player, strClassName) expects a player and projectile class name.";
			constexpr char kOwnerPropertyErrorMessage[] = "GetProjectileIndices(Player, strClassName) requires m_hOwnerEntity on projectile entities.";
			constexpr char kNativeOperationErrorMessage[] = "GetProjectileIndices failed with a native C++ exception.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				if (CallbackInformation.Length() < kRequiredArgumentCount) {
					ThrowError(pIsolate, kUsageErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalPlayerValue = CallbackInformation[kPlayerArgumentIndex];
				v8::Local<v8::Value> const LocalProjectileClassNameValue = CallbackInformation[kProjectileClassNameArgumentIndex];
				if (LocalPlayerValue.IsEmpty() || LocalProjectileClassNameValue.IsEmpty()) {
					return;
				}

				int nPlayerEntityIndex = kInvalidEntityIndex;
				{
					v8::TryCatch PlayerResolutionFailure(pIsolate);
					try {
						nPlayerEntityIndex = GetValueIndex(pIsolate, LocalContext, LocalPlayerValue);
						if (PlayerResolutionFailure.HasCaught()) {
							PlayerResolutionFailure.ReThrow();
							return;
						}
					} catch (...) {
						if (PlayerResolutionFailure.HasCaught()) {
							PlayerResolutionFailure.ReThrow();
						}

						throw;
					}
				}

				v8::Local<v8::String> LocalProjectileClassNameString {};
				if (!LocalProjectileClassNameValue->ToString(LocalContext).ToLocal(&LocalProjectileClassNameString)) {
					return;
				}

				std::string const strProjectileClassName = ValueToString(pIsolate, LocalProjectileClassNameString);
				v8::Local<v8::Array> const LocalProjectileIndicesArray = v8::Array::New(pIsolate);
				if (LocalProjectileIndicesArray.IsEmpty()) {
					return;
				}

				if ((nPlayerEntityIndex < kFirstPlayerEntityIndex) || strProjectileClassName.empty()) {
					CallbackInformation.GetReturnValue().Set(LocalProjectileIndicesArray);
					return;
				}

				auto* const pGlobalVariables = g_Application.GetEngineInterfaces().GetGlobalVariables();
				if (!pGlobalVariables || !g_Application.GetEngineInterfaces().GetEngine()) {
					CallbackInformation.GetReturnValue().Set(LocalProjectileIndicesArray);
					return;
				}

				std::uint32_t unProjectileIndexCount = 0;
				for (int nEntityIndex = kFirstEntityIndex; nEntityIndex < pGlobalVariables->maxEntities; ++nEntityIndex) {
					auto* const pProjectileEdict = GetValidEntityEdictFromIndex(nEntityIndex);
					if (!pProjectileEdict) {
						continue;
					}

					char const* const pszProjectileClassName = pProjectileEdict->GetClassName();
					if (!pszProjectileClassName || (strProjectileClassName != pszProjectileClassName)) {
						continue;
					}

					auto* const pProjectileBaseEntity = GetEntityBaseEntityFromEdictAddress(pProjectileEdict);
					bool bHasOwnerProperty = false;
					int nOwnerEntityIndex = kInvalidEntityIndex;
					const bool bOwnerEntityIndexResolved = PlayersGetOwnerEntityIndexFromEntity(pProjectileBaseEntity, bHasOwnerProperty, nOwnerEntityIndex);
					if (!bHasOwnerProperty) {
						ThrowError(pIsolate, kOwnerPropertyErrorMessage);
						return;
					}

					if (!bOwnerEntityIndexResolved || (nOwnerEntityIndex != nPlayerEntityIndex)) {
						continue;
					}

					v8::Local<v8::Integer> const LocalProjectileIndexValue = v8::Integer::New(pIsolate, nEntityIndex);
					if (LocalProjectileIndexValue.IsEmpty()) {
						return;
					}

					v8::Maybe<bool> const MaybeCreateResult = LocalProjectileIndicesArray->CreateDataProperty(LocalContext, unProjectileIndexCount, LocalProjectileIndexValue);
					if (MaybeCreateResult.IsNothing() || !MaybeCreateResult.FromJust()) {
						return;
					}

					++unProjectileIndexCount;
				}

				CallbackInformation.GetReturnValue().Set(LocalProjectileIndicesArray);
			} catch (...) {
				ThrowError(pIsolate, kNativeOperationErrorMessage);
			}
		}

		bool PlayersGetIntegerSendPropertyAddress(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Value> const LocalPlayerValue, v8::Local<v8::Value> const LocalPropertyValue, char*& pchPropertyAddressOut) {
			constexpr char kLivePlayerErrorMessage[] = "Player integer send-property access requires a live player entity.";
			constexpr char kPropertyNameErrorMessage[] = "Player integer send-property access requires a property name.";
			constexpr char kResolutionErrorMessage[] = "Player integer send-property resolution failed.";

			if (!pIsolate || LocalContext.IsEmpty() || LocalPlayerValue.IsEmpty() || LocalPropertyValue.IsEmpty()) {
				return false;
			}

			CBaseEntity* pPlayerBaseEntity = nullptr;
			{
				v8::TryCatch PlayerResolutionFailure(pIsolate);
				try {
					pPlayerBaseEntity = GetBaseEntityFromValue(pIsolate, LocalContext, LocalPlayerValue);
					if (PlayerResolutionFailure.HasCaught()) {
						PlayerResolutionFailure.ReThrow();
						return false;
					}
				} catch (...) {
					if (PlayerResolutionFailure.HasCaught()) {
						PlayerResolutionFailure.ReThrow();
					}

					throw;
				}
			}

			if (!pPlayerBaseEntity) {
				ThrowError(pIsolate, kLivePlayerErrorMessage);
				return false;
			}

			CBaseHandle const PlayerHandle = GetLiveEntityHandle(pPlayerBaseEntity);
			v8::Local<v8::String> LocalPropertyNameString {};
			if (!LocalPropertyValue->ToString(LocalContext).ToLocal(&LocalPropertyNameString)) {
				return false;
			}

			std::string const strPropertyName = ValueToString(pIsolate, LocalPropertyNameString);
			if (strPropertyName.empty() || (strPropertyName.find('\0') != std::string::npos)) {
				ThrowError(pIsolate, kPropertyNameErrorMessage);
				return false;
			}

			int nResolvedPlayerIndex = -1;
			if (!GetEntityIndexFromBaseHandleValue(PlayerHandle, nResolvedPlayerIndex)) {
				ThrowError(pIsolate, kLivePlayerErrorMessage);
				return false;
			}

			pPlayerBaseEntity = GetBaseEntityFromIndex(nResolvedPlayerIndex);
			if (!pPlayerBaseEntity) {
				ThrowError(pIsolate, kLivePlayerErrorMessage);
				return false;
			}

			char* pchPropertyAddress = nullptr;
			if (!PlayersGetSendPropertyAddress(pPlayerBaseEntity, strPropertyName.c_str(), pchPropertyAddress) || !pchPropertyAddress) {
				ThrowError(pIsolate, kResolutionErrorMessage);
				return false;
			}

			pchPropertyAddressOut = pchPropertyAddress;

			return true;
		}

