		void IsPlayerObserverCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kPlayerArgumentIndex = 0;
			constexpr int kRequiredArgumentCount = 1;
			constexpr int kFirstObserverMode = 1;
			constexpr int kInvalidEntityIndex = -1;
			constexpr char kUsageErrorMessage[] = "IsObserver(Player) expects a player.";
			constexpr char kOperationName[] = "IsObserver(Player)";
			constexpr char kObserverModePropertyName[] = "m_iObserverMode";
			constexpr char kLocalObserverModePropertyName[] = "localdata.m_iObserverMode";
			constexpr char kObserverTargetPropertyName[] = "m_hObserverTarget";
			constexpr char kNativeOperationErrorMessage[] = "IsObserver failed with a native C++ exception.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				if (CallbackInformation.Length() < kRequiredArgumentCount) {
					ThrowError(pIsolate, kUsageErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalPlayerValue = CallbackInformation[kPlayerArgumentIndex];
				if (LocalPlayerValue.IsEmpty()) {
					return;
				}

				int nPlayerEntityIndex = kInvalidEntityIndex;
				{
					v8::TryCatch PlayerResolutionFailure(pIsolate);
					try {
						nPlayerEntityIndex = GetValueIndex(pIsolate, LocalContext, LocalPlayerValue);
						if (PlayerResolutionFailure.HasCaught()) {
							PlayerResolutionFailure.ReThrow();
							return;
						}
					} catch (...) {
						if (PlayerResolutionFailure.HasCaught()) {
							PlayerResolutionFailure.ReThrow();
						}

						throw;
					}
				}

				v8::Local<v8::Integer> const LocalResolvedPlayerValue = v8::Integer::New(pIsolate, nPlayerEntityIndex);
				if (LocalResolvedPlayerValue.IsEmpty()) {
					return;
				}

				std::vector<std::string> const vecObserverModePropertyNames { kObserverModePropertyName, kLocalObserverModePropertyName };
				int nObserverMode = 0;
				if (!PlayersReadNativeIntegerProperty(pIsolate, LocalContext, LocalResolvedPlayerValue, vecObserverModePropertyNames, kOperationName, nObserverMode)) {
					return;
				}

				if (nObserverMode >= kFirstObserverMode) {
					CallbackInformation.GetReturnValue().Set(true);
					return;
				}

				std::vector<std::string> const vecObserverTargetPropertyNames { kObserverTargetPropertyName };
				bool bHasObserverTarget = false;
				if (!PlayersReadNativeHandlePresence(pIsolate, LocalContext, LocalResolvedPlayerValue, vecObserverTargetPropertyNames, kOperationName, bHasObserverTarget)) {
					return;
				}

				CallbackInformation.GetReturnValue().Set(bHasObserverTarget);
			} catch (...) {
				ThrowError(pIsolate, kNativeOperationErrorMessage);
			}
		}

