		v8::Local<v8::Object> MakeEffectsBloodColorObject(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext) {
			constexpr int kDoNotBleedColor = -1;
			constexpr int kRedBloodColor = 0;
			constexpr int kYellowBloodColor = 1;
			constexpr int kGreenBloodColor = 2;
			constexpr int kMechanicalBloodColor = 3;

			if (!pIsolate || LocalContext.IsEmpty()) {
				return {};
			}

			v8::Local<v8::Object> const LocalBloodColorObject = v8::Object::New(pIsolate);
			if (LocalBloodColorObject.IsEmpty()) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalBloodColorObject, "DONT_BLEED", v8::Integer::New(pIsolate, kDoNotBleedColor))) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalBloodColorObject, "RED", v8::Integer::New(pIsolate, kRedBloodColor))) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalBloodColorObject, "YELLOW", v8::Integer::New(pIsolate, kYellowBloodColor))) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalBloodColorObject, "GREEN", v8::Integer::New(pIsolate, kGreenBloodColor))) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalBloodColorObject, "MECH", v8::Integer::New(pIsolate, kMechanicalBloodColor))) {
				return {};
			}

			return LocalBloodColorObject;
		}

		v8::Local<v8::Object> MakeEffectsShatterSurfaceObject(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext) {
			constexpr int kGlassSurface = 0;
			constexpr int kTileSurface = 1;

			if (!pIsolate || LocalContext.IsEmpty()) {
				return {};
			}

			v8::Local<v8::Object> const LocalShatterSurfaceObject = v8::Object::New(pIsolate);
			if (LocalShatterSurfaceObject.IsEmpty()) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalShatterSurfaceObject, "GLASS", v8::Integer::New(pIsolate, kGlassSurface))) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalShatterSurfaceObject, "TILE", v8::Integer::New(pIsolate, kTileSurface))) {
				return {};
			}

			return LocalShatterSurfaceObject;
		}

		bool InstallEffectsConstants(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalEffectsObject) {
			if (!pIsolate || LocalContext.IsEmpty() || LocalEffectsObject.IsEmpty()) {
				return false;
			}

			v8::Local<v8::Object> const LocalBloodColorObject = MakeEffectsBloodColorObject(pIsolate, LocalContext);
			if (LocalBloodColorObject.IsEmpty()) {
				return false;
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalEffectsObject, "BloodColor", LocalBloodColorObject)) {
				return false;
			}

			v8::Local<v8::Object> const LocalShatterSurfaceObject = MakeEffectsShatterSurfaceObject(pIsolate, LocalContext);
			if (LocalShatterSurfaceObject.IsEmpty()) {
				return false;
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalEffectsObject, "ShatterSurface", LocalShatterSurfaceObject)) {
				return false;
			}

			return true;
		}

#if defined(SOURCEJS_HAS_SENDPROPS) && defined(SOURCEJS_HAS_RECIPIENT_FILTER)
		class SourceJSEffectsRecipientFilter : public IRecipientFilter {
		public:
			SourceJSEffectsRecipientFilter(std::vector<int> const& vecRecipients, const bool bReliable);

			bool IsReliable() const noexcept override {
				return m_bReliable;
			}

			bool IsInitMessage() const noexcept override {
				return false;
			}

			int GetRecipientCount() const noexcept override {
				constexpr std::size_t kMaximumRecipientCount = static_cast<std::size_t>(std::numeric_limits<int>::max());

				const std::size_t unRecipientCount = m_vecRecipients.size();
				if (unRecipientCount > kMaximumRecipientCount) {
					return std::numeric_limits<int>::max();
				}

				return static_cast<int>(unRecipientCount);
			}

			int GetRecipientIndex(const int nRecipientSlot) const noexcept override {
				constexpr int kInvalidRecipientIndex = 0;

				if (nRecipientSlot < 0) {
					return kInvalidRecipientIndex;
				}

				const std::size_t unRecipientSlot = static_cast<std::size_t>(nRecipientSlot);
				if (unRecipientSlot >= m_vecRecipients.size()) {
					return kInvalidRecipientIndex;
				}

				return m_vecRecipients[unRecipientSlot];
			}

		private:
			std::vector<int> m_vecRecipients;
			bool m_bReliable;
		};

		SourceJSEffectsRecipientFilter::SourceJSEffectsRecipientFilter(std::vector<int> const& vecRecipients, const bool bReliable) :
			m_vecRecipients(vecRecipients),
			m_bReliable(bReliable)
		{
		}

		bool DoesEffectsStringStartWith(std::string const& strText, std::string const& strPrefix) noexcept {
			return strText.rfind(strPrefix, 0) == 0;
		}

		std::string NormalizeEffectsName(std::string const& strName) {
			std::string strNormalizedName {};
			for (std::size_t unCharacterIndex = 0; unCharacterIndex < strName.size(); ++unCharacterIndex) {
				const unsigned char chCharacter = static_cast<unsigned char>(strName[unCharacterIndex]);
				if (std::isalnum(chCharacter)) {
					strNormalizedName.push_back(static_cast<char>(std::tolower(chCharacter)));
				}
			}

			return strNormalizedName;
		}

		std::string RemoveEffectsNormalizedMemberPrefix(std::string const& strName) {
			constexpr char const* const kMemberScopePrefix = "m_";
			constexpr char const* const kMemberPrefixes[] = {
				"m_vec",
				"m_v",
				"m_fl",
				"m_fn",
				"m_f",
				"m_n",
				"m_i",
				"m_b",
				"m_clr",
				"m_uch",
				"m_ch",
				kMemberScopePrefix,
			};

			// Preserve role capitalization until the native prefix boundary is known.
			for (auto const& pszMemberPrefix : kMemberPrefixes) {
				std::string const strMemberPrefix = pszMemberPrefix;
				const std::size_t unMemberPrefixLength = strMemberPrefix.size();
				if (!DoesEffectsStringStartWith(strName, strMemberPrefix) || (strName.size() <= unMemberPrefixLength)) {
					continue;
				}

				const unsigned char chRoleFirstCharacter = static_cast<unsigned char>(strName[unMemberPrefixLength]);
				if ((strMemberPrefix != kMemberScopePrefix) && !std::isupper(chRoleFirstCharacter) && !std::isdigit(chRoleFirstCharacter) && (chRoleFirstCharacter != '_')) {
					continue;
				}

				return NormalizeEffectsName(strName.substr(unMemberPrefixLength));
			}

			return NormalizeEffectsName(strName);
		}

		std::string GetEffectsLastPathSegment(std::string const& strPath) {
			constexpr char kPathSeparator = '.';

			const std::size_t unSeparatorPosition = strPath.find_last_of(kPathSeparator);
			if (unSeparatorPosition == std::string::npos) {
				return strPath;
			}

			return strPath.substr(unSeparatorPosition + 1);
		}

		std::string GetEffectsPreviousPathSegment(std::string const& strPath) {
			constexpr char kPathSeparator = '.';

			const std::size_t unSeparatorPosition = strPath.find_last_of(kPathSeparator);
			if ((unSeparatorPosition == std::string::npos) || (unSeparatorPosition == 0)) {
				return {};
			}

			std::string const strPathPrefix = strPath.substr(0, unSeparatorPosition);

			return GetEffectsLastPathSegment(strPathPrefix);
		}

		bool DoEffectsNamesMatch(std::string const& strNeedle, std::string const& strCandidate) {
			std::string const strNeedleNormalized = NormalizeEffectsName(strNeedle);
			std::string const strNeedleWithoutMemberPrefix = RemoveEffectsNormalizedMemberPrefix(strNeedle);
			std::string const strCandidateNormalized = NormalizeEffectsName(strCandidate);
			std::string const strCandidateWithoutMemberPrefix = RemoveEffectsNormalizedMemberPrefix(strCandidate);

			if (strNeedleNormalized == strCandidateNormalized) {
				return true;
			}

			if (strNeedleNormalized == strCandidateWithoutMemberPrefix) {
				return true;
			}

			if (strNeedleWithoutMemberPrefix == strCandidateNormalized) {
				return true;
			}

			return strNeedleWithoutMemberPrefix == strCandidateWithoutMemberPrefix;
		}

		std::string GetEffectsShortClassName(std::string const& strClassName) {
			constexpr std::size_t kTemporaryEntityPrefixLength = 3;
			constexpr std::size_t kUnderscoreClassPrefixLength = 2;
			constexpr std::size_t kClassPrefixLength = 1;

			if (DoesEffectsStringStartWith(strClassName, "CTE") && (strClassName.size() > kTemporaryEntityPrefixLength)) {
				return strClassName.substr(kTemporaryEntityPrefixLength);
			}

			if (DoesEffectsStringStartWith(strClassName, "C_") && (strClassName.size() > kUnderscoreClassPrefixLength)) {
				return strClassName.substr(kUnderscoreClassPrefixLength);
			}

			if (DoesEffectsStringStartWith(strClassName, "C") && (strClassName.size() > kClassPrefixLength)) {
				return strClassName.substr(kClassPrefixLength);
			}

			return strClassName;
		}

		bool AreEffectsServerClassStorageRangesValid(ServerClass const* const pServerClass) noexcept {
			if (!EntityPropertiesIsRecordStorageRangeValid(pServerClass, sizeof(ServerClass), alignof(ServerClass))) {
				return false;
			}

			auto const* const pSendTable = pServerClass->m_pTable;
			if (pSendTable && !EntityPropertiesIsRecordStorageRangeValid(pSendTable, sizeof(SendTable), alignof(SendTable))) {
				return false;
			}

			return true;
		}

		bool DoesEffectsServerClassMatch(ServerClass* const pServerClass, std::string const& strRequestedName) {
			constexpr std::size_t kTemporaryTablePrefixLength = 5;

			if (strRequestedName.empty() || !AreEffectsServerClassStorageRangesValid(pServerClass)) {
				return false;
			}

			char const* const pszClassName = pServerClass->GetName();
			char const* const pszTableName = pServerClass->m_pTable ? pServerClass->m_pTable->GetName() : nullptr;
			std::string const strClassName = pszClassName ? pszClassName : "";
			std::string const strTableName = pszTableName ? pszTableName : "";

			if (DoEffectsNamesMatch(strRequestedName, strClassName) || DoEffectsNamesMatch(strRequestedName, GetEffectsShortClassName(strClassName))) {
				return true;
			}

			if (DoEffectsNamesMatch(strRequestedName, strTableName)) {
				return true;
			}

			if (DoesEffectsStringStartWith(strTableName, "DT_TE") && DoEffectsNamesMatch(strRequestedName, strTableName.substr(kTemporaryTablePrefixLength))) {
				return true;
			}

			return false;
		}

		bool IsTemporaryEntityServerClass(ServerClass* const pServerClass) {
			if (!AreEffectsServerClassStorageRangesValid(pServerClass)) {
				return false;
			}

			char const* const pszClassName = pServerClass->GetName();
			char const* const pszTableName = pServerClass->m_pTable ? pServerClass->m_pTable->GetName() : nullptr;
			std::string const strClassName = pszClassName ? pszClassName : "";
			std::string const strTableName = pszTableName ? pszTableName : "";

			return DoesEffectsStringStartWith(strClassName, "CTE") || DoesEffectsStringStartWith(strTableName, "DT_TE") || DoesEffectsStringStartWith(strClassName, "CTutor");
		}

		ServerClass* FindEffectsServerClass(std::string const& strRequestedName) {
			if (strRequestedName.empty()) {
				return nullptr;
			}

			auto* const pServerGameDLL = GetEntityPropertiesServerGameDLL();
			if (!EntityPropertiesIsRecordStorageRangeValid(pServerGameDLL, sizeof(IServerGameDLL), alignof(IServerGameDLL))) {
				return nullptr;
			}

			std::vector<ServerClass*> vecVisitedServerClasses {};
			for (auto* pCurrentServerClass = pServerGameDLL->GetAllServerClasses(); pCurrentServerClass; pCurrentServerClass = pCurrentServerClass->m_pNext) {
				if (!AreEffectsServerClassStorageRangesValid(pCurrentServerClass)) {
					return nullptr;
				}

				for (auto const& pVisitedServerClass : vecVisitedServerClasses) {
					if (pVisitedServerClass == pCurrentServerClass) {
						return nullptr;
					}
				}

				vecVisitedServerClasses.push_back(pCurrentServerClass);

				if (DoesEffectsServerClassMatch(pCurrentServerClass, strRequestedName)) {
					return pCurrentServerClass;
				}
			}

			return nullptr;
		}

		std::size_t GetEffectsSendPropertyTypeSize(SendProp* const pSendProperty, const int nRecursionDepth = 0) noexcept {
			constexpr int kMaximumRecursionDepth = 32;
#ifdef SOURCEJS_HAS_DPT_VECTORXY
			constexpr std::size_t kVectorXYComponentCount = 2;
#endif // SOURCEJS_HAS_DPT_VECTORXY
			constexpr int kDefaultStringLength = 256;

			if ((nRecursionDepth < 0) || (nRecursionDepth > kMaximumRecursionDepth) || !EntityPropertiesIsRecordStorageRangeValid(pSendProperty, sizeof(SendProp), alignof(SendProp))) {
				return 0;
			}

			switch (pSendProperty->GetType()) {
				case DPT_Int:
					return sizeof(int);

				case DPT_Float:
					return sizeof(float);

				case DPT_Vector:
					return sizeof(Vector);

#ifdef SOURCEJS_HAS_DPT_VECTORXY
				case DPT_VectorXY:
					return sizeof(float) * kVectorXYComponentCount;
#endif // SOURCEJS_HAS_DPT_VECTORXY

				case DPT_String:
					return static_cast<std::size_t>((pSendProperty->GetNumElements() > 0) ? pSendProperty->GetNumElements() : kDefaultStringLength);

				case DPT_Array: {
					auto* const pArrayProperty = pSendProperty->GetArrayProp();
					const std::size_t unElementSize = (pSendProperty->GetElementStride() > 0) ? static_cast<std::size_t>(pSendProperty->GetElementStride()) : GetEffectsSendPropertyTypeSize(pArrayProperty, nRecursionDepth + 1);
					const std::size_t unElementCount = (pSendProperty->GetNumElements() > 0) ? static_cast<std::size_t>(pSendProperty->GetNumElements()) : 0;

					if ((unElementSize == 0) || (unElementCount > (std::numeric_limits<std::size_t>::max() / unElementSize))) {
						return 0;
					}

					return unElementSize * unElementCount;
				}

				default:
					return sizeof(std::uintptr_t);
			}
		}

		bool CollectEffectsSendTableSize(SendTable* const pSendTable, const int nBasePropertyOffset, std::size_t& unSendTableSizeInOut, const int nRecursionDepth) noexcept {
			constexpr int kMaximumRecursionDepth = 32;
			constexpr std::int64_t kMinimumPropertyOffset = static_cast<std::int64_t>(std::numeric_limits<int>::min());
			constexpr std::int64_t kMaximumPropertyOffset = static_cast<std::int64_t>(std::numeric_limits<int>::max());

			if ((nRecursionDepth < 0) || (nRecursionDepth > kMaximumRecursionDepth) || !EntityPropertiesIsSendTableStorageValid(pSendTable)) {
				return false;
			}

			const int nPropertyCount = pSendTable->GetNumProps();
			if (nPropertyCount < 0) {
				return false;
			}

			std::size_t unSendTableSize = unSendTableSizeInOut;
			for (int nPropertyIndex = 0; nPropertyIndex < nPropertyCount; ++nPropertyIndex) {
				auto* const pSendProperty = pSendTable->GetProp(nPropertyIndex);
				if (!pSendProperty || pSendProperty->IsExcludeProp()) {
					continue;
				}

				const std::int64_t nWidePropertyOffset = static_cast<std::int64_t>(nBasePropertyOffset) + static_cast<std::int64_t>(pSendProperty->GetOffset());
				if ((nWidePropertyOffset < kMinimumPropertyOffset) || (nWidePropertyOffset > kMaximumPropertyOffset)) {
					return false;
				}

				const int nPropertyOffset = static_cast<int>(nWidePropertyOffset);
				if (pSendProperty->GetType() == DPT_DataTable) {
					if (!CollectEffectsSendTableSize(pSendProperty->GetDataTable(), nPropertyOffset, unSendTableSize, nRecursionDepth + 1)) {
						return false;
					}

					continue;
				}

				const std::size_t unPropertyOffset = static_cast<std::size_t>((nPropertyOffset < 0) ? 0 : nPropertyOffset);
				const std::size_t unPropertySize = GetEffectsSendPropertyTypeSize(pSendProperty);
				if (unPropertySize > (std::numeric_limits<std::size_t>::max() - unPropertyOffset)) {
					return false;
				}

				const std::size_t unPropertyEnd = unPropertyOffset + unPropertySize;
				if (unPropertyEnd > unSendTableSize) {
					unSendTableSize = unPropertyEnd;
				}
			}

			unSendTableSizeInOut = unSendTableSize;

			return true;
		}

		bool ComputeEffectsSenderSize(ServerClass* const pServerClass, std::size_t& unSenderSizeOut) noexcept {
			constexpr std::size_t kInitialSenderAddressCount = 8;
			constexpr std::size_t kInitialSenderSize = sizeof(std::uintptr_t) * kInitialSenderAddressCount;
			constexpr std::size_t kSenderAlignment = sizeof(std::uintptr_t);
			constexpr int kRootPropertyOffset = 0;
			constexpr int kInitialRecursionDepth = 0;

			if (pServerClass && !AreEffectsServerClassStorageRangesValid(pServerClass)) {
				return false;
			}

			std::size_t unSenderSize = kInitialSenderSize;
			if (pServerClass && pServerClass->m_pTable && !CollectEffectsSendTableSize(pServerClass->m_pTable, kRootPropertyOffset, unSenderSize, kInitialRecursionDepth)) {
				return false;
			}

			const std::size_t unAlignmentRemainder = unSenderSize % kSenderAlignment;
			if (unAlignmentRemainder != 0) {
				const std::size_t unAlignmentPadding = kSenderAlignment - unAlignmentRemainder;
				if (unAlignmentPadding > (std::numeric_limits<std::size_t>::max() - unSenderSize)) {
					return false;
				}

				unSenderSize += unAlignmentPadding;
			}

			unSenderSizeOut = unSenderSize;

			return true;
		}

		bool CollectEffectsSendProperties(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Array> const LocalPropertiesArray, std::uint32_t& unWriteIndexInOut, ServerClass* const pServerClass, SendTable* const pSendTable, const int nBasePropertyOffset, std::string const& strBasePropertyPath, const int nRecursionDepth) {
			constexpr int kMaximumRecursionDepth = 32;

			if (!pIsolate || LocalContext.IsEmpty() || LocalPropertiesArray.IsEmpty()) {
				return false;
			}

			if ((nRecursionDepth < 0) || (nRecursionDepth > kMaximumRecursionDepth) || !AreEffectsServerClassStorageRangesValid(pServerClass) || !EntityPropertiesIsSendTableStorageValid(pSendTable)) {
				return false;
			}

			std::uint32_t unWriteIndex = unWriteIndexInOut;
			const int nPropertyCount = pSendTable->GetNumProps();
			for (int nPropertyIndex = 0; nPropertyIndex < nPropertyCount; ++nPropertyIndex) {
				auto* const pSendProperty = pSendTable->GetProp(nPropertyIndex);
				if (!pSendProperty || pSendProperty->IsExcludeProp()) {
					continue;
				}

				char const* const pszPropertyName = pSendProperty->GetName();
				std::string const strPropertyName = pszPropertyName ? pszPropertyName : "";
				std::string const strPropertyPath = strBasePropertyPath.empty() ? strPropertyName : (strBasePropertyPath + "." + strPropertyName);
				const std::int64_t nWidePropertyOffset = static_cast<std::int64_t>(nBasePropertyOffset) + static_cast<std::int64_t>(pSendProperty->GetOffset());
				if ((nWidePropertyOffset < std::numeric_limits<int>::min()) || (nWidePropertyOffset > std::numeric_limits<int>::max())) {
					return false;
				}

				const int nPropertyOffset = static_cast<int>(nWidePropertyOffset);
				if (pSendProperty->GetType() == DPT_DataTable) {
					if (!CollectEffectsSendProperties(pIsolate, LocalContext, LocalPropertiesArray, unWriteIndex, pServerClass, pSendProperty->GetDataTable(), nPropertyOffset, strPropertyPath, nRecursionDepth + 1)) {
						return false;
					}

					continue;
				}

				std::string const strPreviousPathSegment = GetEffectsPreviousPathSegment(strPropertyPath);
				std::string const strAliasSource = strPreviousPathSegment.empty() ? strPropertyName : strPreviousPathSegment;
				std::string const strPropertyAlias = RemoveEffectsNormalizedMemberPrefix(strAliasSource);

				v8::Local<v8::Object> const LocalPropertyObject = MakeEntityPropertiesSendPropertyObject(pIsolate, LocalContext, pServerClass, pSendTable, pSendProperty, nPropertyIndex, nPropertyOffset, strPropertyPath);
				if (LocalPropertyObject.IsEmpty()) {
					return false;
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalPropertyObject, "Alias", MakeString(pIsolate, strPropertyAlias))) {
					return false;
				}

				if (unWriteIndex == std::numeric_limits<std::uint32_t>::max()) {
					return false;
				}

				v8::Maybe<bool> const MaybeSetResult = LocalPropertiesArray->CreateDataProperty(LocalContext, unWriteIndex, LocalPropertyObject);
				if (MaybeSetResult.IsNothing() || !MaybeSetResult.FromJust()) {
					return false;
				}

				++unWriteIndex;
			}

			unWriteIndexInOut = unWriteIndex;

			return true;
		}

		v8::Local<v8::Array> MakeEffectsSendPropertiesArray(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, ServerClass* const pServerClass) {
			constexpr std::uint32_t kInitialWriteIndex = 0;
			constexpr int kRootPropertyOffset = 0;
			constexpr int kInitialRecursionDepth = 0;

			if (!pIsolate || LocalContext.IsEmpty()) {
				return {};
			}

			v8::Local<v8::Array> const LocalPropertiesArray = v8::Array::New(pIsolate);
			if (LocalPropertiesArray.IsEmpty()) {
				return {};
			}

			if (pServerClass && !AreEffectsServerClassStorageRangesValid(pServerClass)) {
				return {};
			}

			std::uint32_t unWriteIndex = kInitialWriteIndex;
			if (pServerClass && pServerClass->m_pTable) {
				if (!CollectEffectsSendProperties(pIsolate, LocalContext, LocalPropertiesArray, unWriteIndex, pServerClass, pServerClass->m_pTable, kRootPropertyOffset, "", kInitialRecursionDepth)) {
					return {};
				}
			}

			return LocalPropertiesArray;
		}

		v8::Local<v8::Object> MakeEffectsTemporaryEntityObject(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, ServerClass* const pServerClass) {
			constexpr std::size_t kMaximumSenderSize = static_cast<std::size_t>(std::numeric_limits<int>::max());

			if (!pIsolate || LocalContext.IsEmpty() || !AreEffectsServerClassStorageRangesValid(pServerClass)) {
				return {};
			}

			char const* const pszClassName = pServerClass->GetName();
			auto* const pSendTable = pServerClass->m_pTable;
			char const* const pszTableName = pSendTable ? pSendTable->GetName() : nullptr;
			std::string const strClassName = pszClassName ? pszClassName : "";
			std::string const strShortClassName = GetEffectsShortClassName(strClassName);
			std::string const strTableName = pszTableName ? pszTableName : "";
			const int nClassIndex = pServerClass->m_ClassID;
			std::size_t unSenderSize = 0;
			if (!ComputeEffectsSenderSize(pServerClass, unSenderSize) || (unSenderSize > kMaximumSenderSize)) {
				return {};
			}

			const int nSenderSize = static_cast<int>(unSenderSize);
			v8::Local<v8::Object> const LocalTemporaryEntityObject = MakeEntityPropertiesReflectionObject(pIsolate, LocalContext, "tempentity", pServerClass);
			if (LocalTemporaryEntityObject.IsEmpty()) {
				return {};
			}

			v8::Local<v8::Object> const LocalServerClassObject = MakeEntityPropertiesServerClassObject(pIsolate, LocalContext, pServerClass);
			v8::Local<v8::Array> const LocalSendPropertiesArray = MakeEffectsSendPropertiesArray(pIsolate, LocalContext, pServerClass);
			if (LocalServerClassObject.IsEmpty() || LocalSendPropertiesArray.IsEmpty()) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalTemporaryEntityObject, "Name", MakeString(pIsolate, strShortClassName))) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalTemporaryEntityObject, "ClassName", MakeString(pIsolate, strClassName))) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalTemporaryEntityObject, "ClassIndex", v8::Integer::New(pIsolate, nClassIndex))) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalTemporaryEntityObject, "TableName", MakeString(pIsolate, strTableName))) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalTemporaryEntityObject, "Size", v8::Integer::New(pIsolate, nSenderSize))) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalTemporaryEntityObject, "ServerClass", LocalServerClassObject)) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalTemporaryEntityObject, "Properties", LocalSendPropertiesArray)) {
				return {};
			}

			return LocalTemporaryEntityObject;
		}

		bool FindEffectsPropertyInformation(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, ServerClass* const pServerClass, std::string const& strRequestedPropertyName, EntityPropertiesPropertyInformation& PropertyInformationOut) {
			if (!pIsolate || LocalContext.IsEmpty() || !pServerClass || strRequestedPropertyName.empty()) {
				return false;
			}

			if (!AreEffectsServerClassStorageRangesValid(pServerClass)) {
				return false;
			}

			auto* const pSendTable = pServerClass->m_pTable;
			if (!pSendTable) {
				return false;
			}

			EntityPropertiesPropertyInformation PropertyInformation {};
			if (FindEntityPropertiesPropertyInformation(pServerClass, pSendTable, strRequestedPropertyName, PropertyInformation)) {
				PropertyInformationOut = PropertyInformation;
				return true;
			}

			v8::HandleScope HandleScope(pIsolate);

			v8::Local<v8::Array> const LocalPropertiesArray = MakeEffectsSendPropertiesArray(pIsolate, LocalContext, pServerClass);
			if (LocalPropertiesArray.IsEmpty()) {
				return false;
			}

			const std::uint32_t unPropertyCount = LocalPropertiesArray->Length();
			for (std::uint32_t unPropertyIndex = 0; unPropertyIndex < unPropertyCount; ++unPropertyIndex) {
				v8::Local<v8::Value> LocalPropertyValue {};
				if (!LocalPropertiesArray->Get(LocalContext, unPropertyIndex).ToLocal(&LocalPropertyValue) || !LocalPropertyValue->IsObject()) {
					return false;
				}

				v8::Local<v8::Object> const LocalPropertyObject = LocalPropertyValue.As<v8::Object>();
				std::string strPropertyPath {};
				std::string strCandidatePropertyName {};
				std::string strPropertyAlias {};
				if (!GetObjectString(pIsolate, LocalContext, LocalPropertyObject, "Path", strPropertyPath)) {
					return false;
				}

				if (!GetObjectString(pIsolate, LocalContext, LocalPropertyObject, "Name", strCandidatePropertyName)) {
					return false;
				}

				if (!GetObjectString(pIsolate, LocalContext, LocalPropertyObject, "Alias", strPropertyAlias)) {
					return false;
				}

				bool bPropertyMatches = DoEffectsNamesMatch(strRequestedPropertyName, strPropertyPath);
				if (!bPropertyMatches) {
					bPropertyMatches = DoEffectsNamesMatch(strRequestedPropertyName, strCandidatePropertyName);
				}

				if (!bPropertyMatches) {
					bPropertyMatches = DoEffectsNamesMatch(strRequestedPropertyName, strPropertyAlias);
				}

				if (!bPropertyMatches) {
					bPropertyMatches = DoEffectsNamesMatch(strRequestedPropertyName, GetEffectsPreviousPathSegment(strPropertyPath));
				}

				if (!bPropertyMatches) {
					continue;
				}

				PropertyInformation = {};
				if (FindEntityPropertiesPropertyInformation(pServerClass, pSendTable, strPropertyPath, PropertyInformation)) {
					PropertyInformationOut = PropertyInformation;
					return true;
				}
			}

			return false;
		}

		bool EffectsRequireVectorFromValue(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Value> const LocalVectorValue, Vector& VectorValueOut) {
			return RequireVectorFromValue(pIsolate, LocalContext, LocalVectorValue, "effects property expects numeric vector components.", VectorValueOut);
		}

		bool EffectsSetVectorComponents(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, char* const pchSenderMemory, const std::size_t unSenderMemoryByteCount, ServerClass* const pServerClass, EntityPropertiesPropertyInformation const& PropertyInformation, v8::Local<v8::Value> const LocalPropertyValue, bool& bHandledOut) {
			constexpr char kPathSeparator = '.';
			constexpr char kVectorComponentErrorMessage[] = "effects vector component property expects numeric vector components.";
			static constexpr char kXComponentName[] = "x";
			static constexpr char kYComponentName[] = "y";
			static constexpr char kZComponentName[] = "z";
			constexpr char const* const kComponentNames[] = { kXComponentName, kYComponentName, kZComponentName };
			constexpr std::size_t kVectorComponentCount = std::size(kComponentNames);

			std::string const& strPropertyPath = PropertyInformation.m_strPropertyPath;
			const std::size_t unSeparatorPosition = strPropertyPath.find_last_of(kPathSeparator);
			if (unSeparatorPosition == std::string::npos) {
				bHandledOut = false;
				return true;
			}

			std::string const strLeafPropertyName = strPropertyPath.substr(unSeparatorPosition + 1);
			if ((strLeafPropertyName != kXComponentName) && (strLeafPropertyName != kYComponentName) && (strLeafPropertyName != kZComponentName)) {
				bHandledOut = false;
				return true;
			}

			if (!pIsolate || LocalContext.IsEmpty() || LocalPropertyValue.IsEmpty()) {
				return false;
			}

			Vector ComponentVector = Vector(0.0f, 0.0f, 0.0f);
			bool bHasComponentVector = false;
			if (!GetVectorFromValue(pIsolate, LocalContext, LocalPropertyValue, kVectorComponentErrorMessage, bHasComponentVector, ComponentVector)) {
				return false;
			}

			if (!bHasComponentVector) {
				bHandledOut = false;
				return true;
			}

			if (!EntityPropertiesIsRecordStorageRangeValid(pchSenderMemory, unSenderMemoryByteCount, alignof(char)) || !AreEffectsServerClassStorageRangesValid(pServerClass) || !pServerClass->m_pTable) {
				return false;
			}

			auto* const pSendTable = pServerClass->m_pTable;
			std::string const strBasePropertyPath = strPropertyPath.substr(0, unSeparatorPosition + 1);
			const float arrComponentValues[kVectorComponentCount] = { ComponentVector.x, ComponentVector.y, ComponentVector.z };
			for (std::size_t unComponentIndex = 0; unComponentIndex < kVectorComponentCount; ++unComponentIndex) {
				EntityPropertiesPropertyInformation ComponentPropertyInformation {};
				if (!FindEntityPropertiesPropertyInformation(pServerClass, pSendTable, strBasePropertyPath + kComponentNames[unComponentIndex], ComponentPropertyInformation)) {
					continue;
				}

				if (ComponentPropertyInformation.m_nPropertyOffset < 0) {
					continue;
				}

				const std::size_t unComponentOffset = static_cast<std::size_t>(ComponentPropertyInformation.m_nPropertyOffset);
				if ((unComponentOffset > unSenderMemoryByteCount) || (sizeof(float) > (unSenderMemoryByteCount - unComponentOffset))) {
					return false;
				}

				if (!WriteEntityPropertiesScalarValue(pchSenderMemory + unComponentOffset, arrComponentValues[unComponentIndex])) {
					return false;
				}
			}

			bHandledOut = true;

			return true;
		}

		bool EffectsSetArrayValue(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, char* const pchArrayAddress, const std::size_t unArrayMemoryByteCount, SendProp* const pSendProperty, v8::Local<v8::Value> const LocalPropertyValue) {
			if (!pIsolate || LocalContext.IsEmpty() || LocalPropertyValue.IsEmpty()) {
				return false;
			}

			if (!pchArrayAddress || !EntityPropertiesIsRecordStorageRangeValid(pSendProperty, sizeof(SendProp), alignof(SendProp)) || (pSendProperty->GetType() != DPT_Array) || !LocalPropertyValue->IsArray()) {
				return false;
			}

			auto* const pArrayElementProperty = pSendProperty->GetArrayProp();
			if (!EntityPropertiesIsRecordStorageRangeValid(pArrayElementProperty, sizeof(SendProp), alignof(SendProp))) {
				return false;
			}

			v8::Local<v8::Array> const LocalInputArray = LocalPropertyValue.As<v8::Array>();
			if (LocalInputArray.IsEmpty()) {
				return false;
			}

			const int nMaximumElementCount = pSendProperty->GetNumElements();
			const int nConfiguredElementStride = pSendProperty->GetElementStride();
			const std::uint32_t unInputElementCount = LocalInputArray->Length();
			const std::uint32_t unMaximumElementCount = static_cast<std::uint32_t>((nMaximumElementCount > 0) ? nMaximumElementCount : 0);
			const std::uint32_t unWriteElementCount = (unInputElementCount < unMaximumElementCount) ? unInputElementCount : unMaximumElementCount;

			if (!unWriteElementCount) {
				return true;
			}

			SendPropType const ArrayElementType = pArrayElementProperty->GetType();
			const std::size_t unElementSize = GetEffectsSendPropertyTypeSize(pArrayElementProperty);
			const std::size_t unElementStride = (nConfiguredElementStride > 0) ? static_cast<std::size_t>(nConfiguredElementStride) : unElementSize;
			if (!unElementStride || !unElementSize || (unElementSize > unElementStride)) {
				return false;
			}

			const std::size_t unMaximumElementIndex = static_cast<std::size_t>(unWriteElementCount - 1);
			if (unMaximumElementIndex > (std::numeric_limits<std::size_t>::max() / unElementStride)) {
				return false;
			}

			const std::size_t unLastElementOffset = unMaximumElementIndex * unElementStride;
			if ((unLastElementOffset > unArrayMemoryByteCount) || (unElementSize > (unArrayMemoryByteCount - unLastElementOffset)) || !EntityPropertiesIsRecordStorageRangeValid(pchArrayAddress, unArrayMemoryByteCount, alignof(char))) {
				return false;
			}

			for (std::uint32_t unElementIndex = 0; unElementIndex < unWriteElementCount; ++unElementIndex) {
				v8::Local<v8::Value> LocalElementValue {};
				if (!LocalInputArray->Get(LocalContext, unElementIndex).ToLocal(&LocalElementValue)) {
					return false;
				}

				char* const pchElementAddress = pchArrayAddress + (unElementStride * static_cast<std::size_t>(unElementIndex));

				switch (ArrayElementType) {
					case DPT_Int: {
						int nElementValue = 0;
						if (!EntityPropertiesGetNumberFromValue(LocalContext, LocalElementValue, nElementValue)) {
							ThrowError(pIsolate, "effects array integer property expects a finite numeric value.");
							return false;
						}

						if (!WriteEntityPropertiesScalarValue(pchElementAddress, nElementValue)) {
							return false;
						}

						break;
					}

					case DPT_Float: {
						float flElementValue = 0.0f;
						if (!GetFloatArgument(pIsolate, LocalContext, LocalElementValue, "effects array float property expects a finite numeric value.", flElementValue)) {
							return false;
						}

						if (!WriteEntityPropertiesScalarValue(pchElementAddress, flElementValue)) {
							return false;
						}

						break;
					}

					case DPT_Vector: {
						Vector ElementVectorValue = Vector(0.0f, 0.0f, 0.0f);
						if (!EffectsRequireVectorFromValue(pIsolate, LocalContext, LocalElementValue, ElementVectorValue)) {
							return false;
						}

						std::memcpy(pchElementAddress, &ElementVectorValue, sizeof(ElementVectorValue));
						break;
					}

					default:
						return false;
				}
			}

			return true;
		}

		bool EffectsSetPropertyValue(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, char* const pchSenderMemory, const std::size_t unSenderMemoryByteCount, ServerClass* const pServerClass, EntityPropertiesPropertyInformation const& PropertyInformation, v8::Local<v8::Value> const LocalPropertyValue) {
#ifdef SOURCEJS_HAS_DPT_VECTORXY
			constexpr std::size_t kVectorXYComponentCount = 2;
			constexpr std::size_t kVectorXYByteCount = sizeof(float) * kVectorXYComponentCount;
#endif // SOURCEJS_HAS_DPT_VECTORXY
			constexpr std::size_t kDefaultStringCapacity = 256;

			if (!pIsolate || LocalContext.IsEmpty() || LocalPropertyValue.IsEmpty()) {
				return false;
			}

			if ((PropertyInformation.m_nPropertyOffset < 0) || !EntityPropertiesIsRecordStorageRangeValid(pchSenderMemory, unSenderMemoryByteCount, alignof(char))) {
				return false;
			}

			const std::size_t unPropertyOffset = static_cast<std::size_t>(PropertyInformation.m_nPropertyOffset);
			if (unPropertyOffset > unSenderMemoryByteCount) {
				return false;
			}

			const std::size_t unPropertyMemoryByteCount = unSenderMemoryByteCount - unPropertyOffset;
			char* const pchPropertyAddress = pchSenderMemory + unPropertyOffset;

			switch (PropertyInformation.m_SendPropertyType) {
				case DPT_Int: {
					if (sizeof(int) > unPropertyMemoryByteCount) {
						return false;
					}

					bool bHandledAsVectorComponent = false;
					if (!EffectsSetVectorComponents(pIsolate, LocalContext, pchSenderMemory, unSenderMemoryByteCount, pServerClass, PropertyInformation, LocalPropertyValue, bHandledAsVectorComponent)) {
						return false;
					}

					if (bHandledAsVectorComponent) {
						return true;
					}

					int nPropertyValue = 0;
					if (!EntityPropertiesGetNumberFromValue(LocalContext, LocalPropertyValue, nPropertyValue)) {
						ThrowError(pIsolate, "effects integer property expects a finite numeric value.");
						return false;
					}

					return WriteEntityPropertiesScalarValue(pchPropertyAddress, nPropertyValue);
				}

				case DPT_Float: {
					if (sizeof(float) > unPropertyMemoryByteCount) {
						return false;
					}

					bool bHandledAsVectorComponent = false;
					if (!EffectsSetVectorComponents(pIsolate, LocalContext, pchSenderMemory, unSenderMemoryByteCount, pServerClass, PropertyInformation, LocalPropertyValue, bHandledAsVectorComponent)) {
						return false;
					}

					if (bHandledAsVectorComponent) {
						return true;
					}

					float flPropertyValue = 0.0f;
					if (!GetFloatArgument(pIsolate, LocalContext, LocalPropertyValue, "effects float property expects a finite numeric value.", flPropertyValue)) {
						return false;
					}

					return WriteEntityPropertiesScalarValue(pchPropertyAddress, flPropertyValue);
				}

				case DPT_Vector: {
					if (sizeof(Vector) > unPropertyMemoryByteCount) {
						return false;
					}

					Vector PropertyVectorValue = Vector(0.0f, 0.0f, 0.0f);
					if (!EffectsRequireVectorFromValue(pIsolate, LocalContext, LocalPropertyValue, PropertyVectorValue)) {
						return false;
					}

					std::memcpy(pchPropertyAddress, &PropertyVectorValue, sizeof(PropertyVectorValue));
					return true;
				}

#ifdef SOURCEJS_HAS_DPT_VECTORXY
				case DPT_VectorXY: {
					if (kVectorXYByteCount > unPropertyMemoryByteCount) {
						return false;
					}

					Vector PropertyVectorValue = Vector(0.0f, 0.0f, 0.0f);
					if (!EffectsRequireVectorFromValue(pIsolate, LocalContext, LocalPropertyValue, PropertyVectorValue)) {
						return false;
					}

					const float arrComponentValues[kVectorXYComponentCount] = { PropertyVectorValue.x, PropertyVectorValue.y };
					std::memcpy(pchPropertyAddress, arrComponentValues, sizeof(arrComponentValues));
					return true;
				}
#endif // SOURCEJS_HAS_DPT_VECTORXY

				case DPT_String: {
					const std::size_t unStringCapacity = (PropertyInformation.m_nElementCount > 0) ? static_cast<std::size_t>(PropertyInformation.m_nElementCount) : kDefaultStringCapacity;
					if (unStringCapacity > unPropertyMemoryByteCount) {
						return false;
					}

					v8::Local<v8::String> LocalPropertyString {};
					if (!LocalPropertyValue->ToString(LocalContext).ToLocal(&LocalPropertyString)) {
						return false;
					}

					v8::String::Utf8Value UTF8PropertyValue(pIsolate, LocalPropertyString);
					char const* const pszPropertyValue = *UTF8PropertyValue;
					if (!pszPropertyValue) {
						return false;
					}

					std::strncpy(pchPropertyAddress, pszPropertyValue, unStringCapacity - 1);
					pchPropertyAddress[unStringCapacity - 1] = '\0';
					return true;
				}

				case DPT_Array:
					return EffectsSetArrayValue(pIsolate, LocalContext, pchPropertyAddress, unPropertyMemoryByteCount, PropertyInformation.m_pProperty, LocalPropertyValue);

				default:
					return false;
			}
		}

		bool ApplyEffectsPropertyValues(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, char* const pchSenderMemory, const std::size_t unSenderMemoryByteCount, ServerClass* const pServerClass, v8::Local<v8::Value> const LocalPropertyValues) {
			constexpr char kPropertyNameErrorMessage[] = "effects.CreateTempEntity() property names must not contain NUL bytes.";
			constexpr char kPropertyValuesErrorMessage[] = "effects.CreateTempEntity() property values must be an object.";
			constexpr char kPropertyNotFoundErrorPrefix[] = "effects.CreateTempEntity() could not find temporary entity property: ";
			constexpr char kPropertySetErrorPrefix[] = "effects.CreateTempEntity() could not set temporary entity property: ";

			if (!pIsolate || LocalContext.IsEmpty() || !EntityPropertiesIsRecordStorageRangeValid(pchSenderMemory, unSenderMemoryByteCount, alignof(char)) || !AreEffectsServerClassStorageRangesValid(pServerClass)) {
				return false;
			}

			if (LocalPropertyValues.IsEmpty() || LocalPropertyValues->IsUndefined() || LocalPropertyValues->IsNull()) {
				return true;
			}

			if (!LocalPropertyValues->IsObject()) {
				ThrowError(pIsolate, kPropertyValuesErrorMessage);
				return false;
			}

			v8::Local<v8::Object> const LocalPropertyValuesObject = LocalPropertyValues.As<v8::Object>();
			if (LocalPropertyValuesObject.IsEmpty()) {
				return false;
			}

			v8::Local<v8::Array> LocalPropertyNamesArray {};
			if (!LocalPropertyValuesObject->GetOwnPropertyNames(LocalContext).ToLocal(&LocalPropertyNamesArray)) {
				return false;
			}

			const std::uint32_t unPropertyCount = LocalPropertyNamesArray->Length();
			for (std::uint32_t unPropertyIndex = 0; unPropertyIndex < unPropertyCount; ++unPropertyIndex) {
				v8::Local<v8::Value> LocalPropertyNameValue {};
				if (!LocalPropertyNamesArray->Get(LocalContext, unPropertyIndex).ToLocal(&LocalPropertyNameValue)) {
					return false;
				}

				v8::Local<v8::String> LocalPropertyNameString {};
				if (!LocalPropertyNameValue->ToString(LocalContext).ToLocal(&LocalPropertyNameString)) {
					return false;
				}

				v8::String::Utf8Value UTF8PropertyName(pIsolate, LocalPropertyNameString);
				char const* const pszPropertyName = *UTF8PropertyName;
				if (!pszPropertyName) {
					return false;
				}

				std::string const strPropertyName = std::string(pszPropertyName, static_cast<std::size_t>(UTF8PropertyName.length()));
				if (strPropertyName.find('\0') != std::string::npos) {
					ThrowError(pIsolate, kPropertyNameErrorMessage);
					return false;
				}

				v8::Local<v8::Value> LocalPropertyValue {};
				if (!LocalPropertyValuesObject->Get(LocalContext, LocalPropertyNameValue).ToLocal(&LocalPropertyValue)) {
					return false;
				}

				v8::TryCatch PropertyFailure(pIsolate);
				try {
					EntityPropertiesPropertyInformation PropertyInformation {};
					if (!FindEffectsPropertyInformation(pIsolate, LocalContext, pServerClass, strPropertyName, PropertyInformation)) {
						if (PropertyFailure.HasCaught()) {
							PropertyFailure.ReThrow();
							return false;
						}

						std::string const strErrorMessage = std::string(kPropertyNotFoundErrorPrefix) + strPropertyName;
						ThrowError(pIsolate, strErrorMessage.c_str());
						PropertyFailure.ReThrow();
						return false;
					}

					if (!EffectsSetPropertyValue(pIsolate, LocalContext, pchSenderMemory, unSenderMemoryByteCount, pServerClass, PropertyInformation, LocalPropertyValue)) {
						if (PropertyFailure.HasCaught()) {
							PropertyFailure.ReThrow();
							return false;
						}

						std::string const strErrorMessage = std::string(kPropertySetErrorPrefix) + strPropertyName;
						ThrowError(pIsolate, strErrorMessage.c_str());
						PropertyFailure.ReThrow();
						return false;
					}
				} catch (...) {
					if (PropertyFailure.HasCaught()) {
						PropertyFailure.ReThrow();
					}

					throw;
				}
			}

			return true;
		}

		void ListEffectsTemporaryEntitiesCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr std::uint32_t kInitialWriteIndex = 0;
			constexpr char kOperationName[] = "effects.ListTempEntities()";
			constexpr char kTemporaryEntityErrorMessage[] = "effects.ListTempEntities() failed to build a temporary-entity descriptor.";
			constexpr char kStorageRangeErrorMessage[] = "effects.ListTempEntities() encountered an invalid native storage range.";
			constexpr char kClassCycleErrorMessage[] = "effects.ListTempEntities() encountered a repeated server-class record.";
			constexpr char kResultLimitErrorMessage[] = "effects.ListTempEntities() exceeded the temporary-entity result limit.";
			constexpr char kNativeExceptionErrorMessage[] = "effects.ListTempEntities() failed with a native C++ exception.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				auto* const pServerGameDLL = RequireServerGameDLL(pIsolate, kOperationName);
				if (!pServerGameDLL) {
					return;
				}

				if (!EntityPropertiesIsRecordStorageRangeValid(pServerGameDLL, sizeof(IServerGameDLL), alignof(IServerGameDLL))) {
					ThrowError(pIsolate, kStorageRangeErrorMessage);
					return;
				}

				v8::Local<v8::Array> const LocalTemporaryEntitiesArray = v8::Array::New(pIsolate);
				if (LocalTemporaryEntitiesArray.IsEmpty()) {
					return;
				}

				std::uint32_t unWriteIndex = kInitialWriteIndex;
				std::vector<ServerClass*> vecVisitedClasses {};
				for (auto* pCurrentServerClass = pServerGameDLL->GetAllServerClasses(); pCurrentServerClass; pCurrentServerClass = pCurrentServerClass->m_pNext) {
					if (!AreEffectsServerClassStorageRangesValid(pCurrentServerClass)) {
						ThrowError(pIsolate, kStorageRangeErrorMessage);
						return;
					}

					for (auto const& pVisitedClass : vecVisitedClasses) {
						if (pVisitedClass == pCurrentServerClass) {
							ThrowError(pIsolate, kClassCycleErrorMessage);
							return;
						}
					}

					vecVisitedClasses.push_back(pCurrentServerClass);

					if (!IsTemporaryEntityServerClass(pCurrentServerClass)) {
						continue;
					}

					v8::Local<v8::Object> const LocalTemporaryEntityObject = MakeEffectsTemporaryEntityObject(pIsolate, LocalContext, pCurrentServerClass);
					if (LocalTemporaryEntityObject.IsEmpty()) {
						ThrowError(pIsolate, kTemporaryEntityErrorMessage);
						return;
					}

					if (unWriteIndex == std::numeric_limits<std::uint32_t>::max()) {
						ThrowError(pIsolate, kResultLimitErrorMessage);
						return;
					}

					v8::Maybe<bool> const MaybeSetResult = LocalTemporaryEntitiesArray->CreateDataProperty(LocalContext, unWriteIndex, LocalTemporaryEntityObject);
					if (MaybeSetResult.IsNothing() || !MaybeSetResult.FromJust()) {
						return;
					}

					++unWriteIndex;
				}

				CallbackInformation.GetReturnValue().Set(LocalTemporaryEntitiesArray);
			} catch (...) {
				ThrowError(pIsolate, kNativeExceptionErrorMessage);
			}
		}

		void GetEffectsTemporaryEntityCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kNameArgumentIndex = 0;
			constexpr int kRequiredArgumentCount = kNameArgumentIndex + 1;
			constexpr char kOperationName[] = "effects.GetTempEntity(strTemporaryEntityName)";
			constexpr char kNameErrorMessage[] = "effects.GetTempEntity(strTemporaryEntityName) requires a temporary entity name string.";
			constexpr char kEmptyNameErrorMessage[] = "effects.GetTempEntity(strTemporaryEntityName) requires a non-empty temporary entity name.";
			constexpr char kTemporaryEntityErrorMessage[] = "effects.GetTempEntity(strTemporaryEntityName) failed to build the temporary-entity descriptor.";
			constexpr char kNativeExceptionErrorMessage[] = "effects.GetTempEntity() failed with a native C++ exception.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				if ((CallbackInformation.Length() < kRequiredArgumentCount) || !CallbackInformation[kNameArgumentIndex]->IsString()) {
					ThrowError(pIsolate, kNameErrorMessage);
					return;
				}

				auto* const pServerGameDLL = RequireServerGameDLL(pIsolate, kOperationName);
				if (!pServerGameDLL) {
					return;
				}

				v8::String::Utf8Value UTF8TemporaryEntityName = v8::String::Utf8Value(pIsolate, CallbackInformation[kNameArgumentIndex]);
				if (!*UTF8TemporaryEntityName) {
					return;
				}

				std::string const strTemporaryEntityName = std::string(*UTF8TemporaryEntityName, static_cast<std::size_t>(UTF8TemporaryEntityName.length()));
				if (strTemporaryEntityName.empty()) {
					ThrowError(pIsolate, kEmptyNameErrorMessage);
					return;
				}

				auto* const pServerClass = FindEffectsServerClass(strTemporaryEntityName);
				if (!pServerClass) {
					CallbackInformation.GetReturnValue().Set(v8::Null(pIsolate));
					return;
				}

				v8::TryCatch MetadataFailure(pIsolate);
				try {
					v8::Local<v8::Object> const LocalTemporaryEntityObject = MakeEffectsTemporaryEntityObject(pIsolate, LocalContext, pServerClass);
					if (LocalTemporaryEntityObject.IsEmpty()) {
						if (MetadataFailure.HasCaught()) {
							MetadataFailure.ReThrow();
							return;
						}

						ThrowError(pIsolate, kTemporaryEntityErrorMessage);
						MetadataFailure.ReThrow();
						return;
					}

					CallbackInformation.GetReturnValue().Set(LocalTemporaryEntityObject);
				} catch (...) {
					if (MetadataFailure.HasCaught()) {
						MetadataFailure.ReThrow();
					}

					throw;
				}
			} catch (...) {
				ThrowError(pIsolate, kNativeExceptionErrorMessage);
			}
		}

		void GetEffectsPropertyCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kTemporaryEntityNameArgumentIndex = 0;
			constexpr int kPropertyNameArgumentIndex = 1;
			constexpr int kRequiredArgumentCount = kPropertyNameArgumentIndex + 1;
			constexpr char kOperationName[] = "effects.GetProperty(strTemporaryEntityName, strPropertyName)";
			constexpr char kNamesErrorMessage[] = "effects.GetProperty(strTemporaryEntityName, strPropertyName) requires temporary entity and property name strings.";
			constexpr char kEmptyNamesErrorMessage[] = "effects.GetProperty(strTemporaryEntityName, strPropertyName) requires non-empty temporary entity and property names.";
			constexpr char kPropertyObjectErrorMessage[] = "effects.GetProperty(strTemporaryEntityName, strPropertyName) failed to build the property descriptor.";
			constexpr char kNativeExceptionErrorMessage[] = "effects.GetProperty() failed with a native C++ exception.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				if ((CallbackInformation.Length() < kRequiredArgumentCount) || !CallbackInformation[kTemporaryEntityNameArgumentIndex]->IsString() || !CallbackInformation[kPropertyNameArgumentIndex]->IsString()) {
					ThrowError(pIsolate, kNamesErrorMessage);
					return;
				}

				auto* const pServerGameDLL = RequireServerGameDLL(pIsolate, kOperationName);
				if (!pServerGameDLL) {
					return;
				}

				v8::String::Utf8Value UTF8TemporaryEntityName = v8::String::Utf8Value(pIsolate, CallbackInformation[kTemporaryEntityNameArgumentIndex]);
				v8::String::Utf8Value UTF8PropertyName = v8::String::Utf8Value(pIsolate, CallbackInformation[kPropertyNameArgumentIndex]);
				if (!*UTF8TemporaryEntityName || !*UTF8PropertyName) {
					return;
				}

				std::string const strTemporaryEntityName = std::string(*UTF8TemporaryEntityName, static_cast<std::size_t>(UTF8TemporaryEntityName.length()));
				std::string const strPropertyName = std::string(*UTF8PropertyName, static_cast<std::size_t>(UTF8PropertyName.length()));
				if (strTemporaryEntityName.empty() || strPropertyName.empty()) {
					ThrowError(pIsolate, kEmptyNamesErrorMessage);
					return;
				}

				auto* const pServerClass = FindEffectsServerClass(strTemporaryEntityName);
				v8::TryCatch PropertyFailure(pIsolate);
				try {
					EntityPropertiesPropertyInformation PropertyInformation {};
					if (!FindEffectsPropertyInformation(pIsolate, LocalContext, pServerClass, strPropertyName, PropertyInformation)) {
						if (PropertyFailure.HasCaught()) {
							PropertyFailure.ReThrow();
							return;
						}

						CallbackInformation.GetReturnValue().Set(v8::Null(pIsolate));
						return;
					}

					v8::Local<v8::Object> const LocalPropertyObject = MakeEntityPropertiesSendPropertyObject(pIsolate, LocalContext, pServerClass, PropertyInformation.m_pSendTable, PropertyInformation.m_pProperty, PropertyInformation.m_nPropertyIndex, PropertyInformation.m_nPropertyOffset, PropertyInformation.m_strPropertyPath);
					if (LocalPropertyObject.IsEmpty()) {
						if (PropertyFailure.HasCaught()) {
							PropertyFailure.ReThrow();
							return;
						}

						ThrowError(pIsolate, kPropertyObjectErrorMessage);
						PropertyFailure.ReThrow();
						return;
					}

					CallbackInformation.GetReturnValue().Set(LocalPropertyObject);
				} catch (...) {
					if (PropertyFailure.HasCaught()) {
						PropertyFailure.ReThrow();
					}

					throw;
				}
			} catch (...) {
				ThrowError(pIsolate, kNativeExceptionErrorMessage);
			}
		}

		void CreateTemporaryEntityCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kNameArgumentIndex = 0;
			constexpr int kPropertyValuesArgumentIndex = 1;
			constexpr int kRecipientsArgumentIndex = 2;
			constexpr int kDelayArgumentIndex = 3;
			constexpr int kReliableArgumentIndex = 4;
			constexpr int kRequiredArgumentCount = kNameArgumentIndex + 1;
			constexpr std::size_t kAddressSize = sizeof(std::uintptr_t);
			constexpr std::size_t kMaximumSenderSize = static_cast<std::size_t>(std::numeric_limits<int>::max());
			constexpr bool kIncludeBots = true;
			constexpr float kDefaultDelay = 0.0f;
			constexpr bool kDefaultReliability = false;
			constexpr char kOperationName[] = "effects.CreateTempEntity(strTemporaryEntityName, PropertyValues?, Recipients?, flDelay?, bReliable?)";
			constexpr char kNameErrorMessage[] = "effects.CreateTempEntity(strTemporaryEntityName, PropertyValues?, Recipients?, flDelay?, bReliable?) requires a temporary entity name string.";
			constexpr char kEmptyNameErrorMessage[] = "effects.CreateTempEntity(strTemporaryEntityName, PropertyValues?, Recipients?, flDelay?, bReliable?) requires a non-empty temporary entity name.";
			constexpr char kTemplateErrorMessage[] = "effects.CreateTempEntity(strTemporaryEntityName, PropertyValues?, Recipients?, flDelay?, bReliable?) could not find the temporary entity template.";
			constexpr char kStorageRangeErrorMessage[] = "effects.CreateTempEntity() encountered an invalid native storage range.";
			constexpr char kTemplateChangedErrorMessage[] = "effects.CreateTempEntity() native template changed while preparing property values or recipients.";
			constexpr char kSendTableErrorMessage[] = "effects.CreateTempEntity(strTemporaryEntityName, PropertyValues?, Recipients?, flDelay?, bReliable?) temporary entity template does not have a send table.";
			constexpr char kSenderSizeErrorMessage[] = "effects.CreateTempEntity(strTemporaryEntityName, PropertyValues?, Recipients?, flDelay?, bReliable?) could not compute a representable temporary entity sender size.";
			constexpr char kDelayErrorMessage[] = "effects.CreateTempEntity(strTemporaryEntityName, PropertyValues?, Recipients?, flDelay?, bReliable?) delay must be finite.";
			constexpr char kReliabilityErrorMessage[] = "effects.CreateTempEntity(strTemporaryEntityName, PropertyValues?, Recipients?, flDelay?, bReliable?) reliability flag must be a boolean.";
			constexpr char kNativeExceptionErrorMessage[] = "effects.CreateTempEntity() failed with a native C++ exception.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				const int nArgumentCount = CallbackInformation.Length();
				if ((nArgumentCount < kRequiredArgumentCount) || !CallbackInformation[kNameArgumentIndex]->IsString()) {
					ThrowError(pIsolate, kNameErrorMessage);
					return;
				}

				v8::String::Utf8Value UTF8TemporaryEntityName = v8::String::Utf8Value(pIsolate, CallbackInformation[kNameArgumentIndex]);
				if (!*UTF8TemporaryEntityName) {
					return;
				}

				std::string const strTemporaryEntityName = std::string(*UTF8TemporaryEntityName, static_cast<std::size_t>(UTF8TemporaryEntityName.length()));
				if (strTemporaryEntityName.empty()) {
					ThrowError(pIsolate, kEmptyNameErrorMessage);
					return;
				}

				auto* const pEngineServer = RequireEngineServer(pIsolate, kOperationName);
				if (!pEngineServer) {
					return;
				}

				auto* const pServerGameDLL = RequireServerGameDLL(pIsolate, kOperationName);
				if (!pServerGameDLL) {
					return;
				}

				auto* const pServerClass = FindEffectsServerClass(strTemporaryEntityName);
				if (!pServerClass) {
					ThrowError(pIsolate, kTemplateErrorMessage);
					return;
				}

				if (!AreEffectsServerClassStorageRangesValid(pServerClass) || !EntityPropertiesIsRecordStorageRangeValid(pEngineServer, sizeof(IVEngineServer), alignof(IVEngineServer))) {
					ThrowError(pIsolate, kStorageRangeErrorMessage);
					return;
				}

				auto* const pSendTable = pServerClass->m_pTable;
				if (!pSendTable) {
					ThrowError(pIsolate, kSendTableErrorMessage);
					return;
				}

				const int nServerClassIndex = pServerClass->m_ClassID;
				std::size_t unSenderSize = 0;
				if (!ComputeEffectsSenderSize(pServerClass, unSenderSize) || !unSenderSize || (unSenderSize > kMaximumSenderSize) || ((unSenderSize % kAddressSize) != 0)) {
					ThrowError(pIsolate, kSenderSizeErrorMessage);
					return;
				}

				const std::size_t unSenderStorageElementCount = unSenderSize / kAddressSize;
				std::vector<std::uintptr_t> vecSenderStorage = std::vector<std::uintptr_t>(unSenderStorageElementCount, 0);
				char* const pchSenderMemory = reinterpret_cast<char*>(vecSenderStorage.data());

				v8::Local<v8::Value> const LocalPropertyValues = (nArgumentCount > kPropertyValuesArgumentIndex) ? CallbackInformation[kPropertyValuesArgumentIndex] : v8::Undefined(pIsolate);
				if (!ApplyEffectsPropertyValues(pIsolate, LocalContext, pchSenderMemory, unSenderSize, pServerClass, LocalPropertyValues)) {
					return;
				}

				std::vector<int> vecRecipients {};
				if ((nArgumentCount > kRecipientsArgumentIndex) && !CallbackInformation[kRecipientsArgumentIndex]->IsUndefined() && !CallbackInformation[kRecipientsArgumentIndex]->IsNull()) {
					if (!CollectRecipientEntityIndicesFromValue(pIsolate, LocalContext, CallbackInformation[kRecipientsArgumentIndex], vecRecipients, kIncludeBots, kOperationName)) {
						return;
					}
				} else if (!CollectPlayerEntityIndices(pIsolate, vecRecipients, kAnyTeamIndex, PlayerFakeClientFilter::ANY, PlayerAliveFilter::ANY, kOperationName)) {
					return;
				}

				float flDelay = kDefaultDelay;
				if ((nArgumentCount > kDelayArgumentIndex) && !IsValueNullish(CallbackInformation[kDelayArgumentIndex]) && !GetFloatArgument(pIsolate, LocalContext, CallbackInformation[kDelayArgumentIndex], kDelayErrorMessage, flDelay)) {
					return;
				}

				bool bReliable = kDefaultReliability;
				if ((nArgumentCount > kReliableArgumentIndex) && !IsValueNullish(CallbackInformation[kReliableArgumentIndex])) {
					if (!CallbackInformation[kReliableArgumentIndex]->IsBoolean()) {
						ThrowError(pIsolate, kReliabilityErrorMessage);
						return;
					}

					bReliable = CallbackInformation[kReliableArgumentIndex]->BooleanValue(pIsolate);
				}

				std::size_t unCurrentSenderSize = 0;
				if (!AreEffectsServerClassStorageRangesValid(pServerClass) || (pServerClass->m_pTable != pSendTable) || (pServerClass->m_ClassID != nServerClassIndex) || !ComputeEffectsSenderSize(pServerClass, unCurrentSenderSize) || (unCurrentSenderSize > unSenderSize)) {
					ThrowError(pIsolate, kTemplateChangedErrorMessage);
					return;
				}

				SourceJSEffectsRecipientFilter RecipientFilter = SourceJSEffectsRecipientFilter(vecRecipients, bReliable);
				pEngineServer->PlaybackTempEntity(RecipientFilter, flDelay, pchSenderMemory, pSendTable, nServerClassIndex);
				CallbackInformation.GetReturnValue().Set(true);
			} catch (...) {
				ThrowError(pIsolate, kNativeExceptionErrorMessage);
			}
		}

		bool InstallEffectsFunctions(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalEffectsObject, v8::Local<v8::Value> const LocalRuntimeData) {
			if (!pIsolate || LocalContext.IsEmpty() || LocalEffectsObject.IsEmpty() || LocalRuntimeData.IsEmpty()) {
				return false;
			}

			if (!SetRecordFunction(pIsolate, LocalContext, LocalEffectsObject, "ListTempEntities", ListEffectsTemporaryEntitiesCallback, LocalRuntimeData)) {
				return false;
			}

			if (!SetRecordFunction(pIsolate, LocalContext, LocalEffectsObject, "GetTempEntity", GetEffectsTemporaryEntityCallback, LocalRuntimeData)) {
				return false;
			}

			if (!SetRecordFunction(pIsolate, LocalContext, LocalEffectsObject, "GetProperty", GetEffectsPropertyCallback, LocalRuntimeData)) {
				return false;
			}

			if (!SetRecordFunction(pIsolate, LocalContext, LocalEffectsObject, "CreateTempEntity", CreateTemporaryEntityCallback, LocalRuntimeData)) {
				return false;
			}

			return true;
		}
#endif // defined(SOURCEJS_HAS_SENDPROPS) && defined(SOURCEJS_HAS_RECIPIENT_FILTER)

		void GetAllInterfaceNamesCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kArrayLimitErrorMessage[] = "interfaces.GetAllInterfaceNames() cannot return more interfaces than a V8 array supports.";
			constexpr char kNativeExceptionErrorMessage[] = "interfaces.GetAllInterfaceNames() failed with a native C++ exception.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				std::vector<std::string> const& vecInterfaceNames = g_Application.GetEngineInterfaces().GetInterfaceNames();
				const std::size_t unInterfaceCount = vecInterfaceNames.size();
				if (unInterfaceCount > static_cast<std::size_t>(std::numeric_limits<int>::max())) {
					ThrowError(pIsolate, kArrayLimitErrorMessage);
					return;
				}

				const int nInterfaceCount = static_cast<int>(unInterfaceCount);
				v8::Local<v8::Array> const LocalInterfaceNamesArray = v8::Array::New(pIsolate, nInterfaceCount);
				if (LocalInterfaceNamesArray.IsEmpty()) {
					return;
				}

				for (std::size_t unInterfaceIndex = 0; unInterfaceIndex < unInterfaceCount; ++unInterfaceIndex) {
					v8::Local<v8::String> const LocalInterfaceName = MakeString(pIsolate, vecInterfaceNames[unInterfaceIndex]);
					if (LocalInterfaceName.IsEmpty()) {
						return;
					}

					v8::Maybe<bool> const MaybeSetResult = LocalInterfaceNamesArray->CreateDataProperty(LocalContext, static_cast<std::uint32_t>(unInterfaceIndex), LocalInterfaceName);
					if (MaybeSetResult.IsNothing() || !MaybeSetResult.FromJust()) {
						return;
					}
				}

				CallbackInformation.GetReturnValue().Set(LocalInterfaceNamesArray);
			} catch (...) {
				ThrowError(pIsolate, kNativeExceptionErrorMessage);
			}
		}

		void GetInterfaceRecordCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kRequiredArgumentCount = 1;
			constexpr int kNameArgumentIndex = 0;
			constexpr bool kInterfaceAvailable = true;
			constexpr char kArgumentErrorMessage[] = "interfaces.GetInterfaceRecord(strInterfaceName) expects a non-empty interface name string.";
			constexpr char kNamePropertyName[] = "Name";
			constexpr char kAvailablePropertyName[] = "Available";
			constexpr char kAddressPropertyName[] = "Address";
			constexpr char kNativeExceptionErrorMessage[] = "interfaces.GetInterfaceRecord() failed with a native C++ exception.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				if (CallbackInformation.Length() < kRequiredArgumentCount) {
					ThrowError(pIsolate, kArgumentErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalInterfaceNameValue = CallbackInformation[kNameArgumentIndex];
				if (LocalInterfaceNameValue.IsEmpty() || !LocalInterfaceNameValue->IsString()) {
					ThrowError(pIsolate, kArgumentErrorMessage);
					return;
				}

				v8::String::Utf8Value UTF8InterfaceName = v8::String::Utf8Value(pIsolate, LocalInterfaceNameValue);
				if (!*UTF8InterfaceName) {
					return;
				}

				std::string const strInterfaceName = std::string(*UTF8InterfaceName, static_cast<std::size_t>(UTF8InterfaceName.length()));
				if (strInterfaceName.empty()) {
					ThrowError(pIsolate, kArgumentErrorMessage);
					return;
				}

				void* const pInterface = g_Application.GetEngineInterfaces().GetInterface(strInterfaceName);
				if (!pInterface) {
					CallbackInformation.GetReturnValue().Set(v8::Null(pIsolate));
					return;
				}

				v8::Local<v8::Object> const LocalInterfaceObject = v8::Object::New(pIsolate);
				if (LocalInterfaceObject.IsEmpty()) {
					return;
				}

				const std::uintptr_t unInterfaceAddress = reinterpret_cast<std::uintptr_t>(pInterface);
				if (!SetRecordProperty(pIsolate, LocalContext, LocalInterfaceObject, kNamePropertyName, MakeString(pIsolate, strInterfaceName))) {
					return;
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalInterfaceObject, kAvailablePropertyName, v8::Boolean::New(pIsolate, kInterfaceAvailable))) {
					return;
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalInterfaceObject, kAddressPropertyName, v8::BigInt::NewFromUnsigned(pIsolate, static_cast<std::uint64_t>(unInterfaceAddress)))) {
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalInterfaceObject);
			} catch (...) {
				ThrowError(pIsolate, kNativeExceptionErrorMessage);
			}
		}

