		enum class MathVectorBinaryOperation : std::int32_t {
			ADD = 0,
			SUBTRACT,
			MULTIPLY,
			DIVIDE
		};

		void CreateRandomVectorCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kUsageErrorMessage[] = "mathlib.CreateRandomVector(flMinimum?, flMaximum?) expects finite numeric bounds.";
			constexpr int kMinimumArgumentIndex = 0;
			constexpr int kMaximumArgumentIndex = 1;
			constexpr float kDefaultMinimum = 0.0f;
			constexpr float kDefaultMaximum = 1.0f;
			constexpr char kNativeExceptionErrorMessage[] = "mathlib.CreateRandomVector() failed with a native C++ exception.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				float flMinimum = kDefaultMinimum;
				float flMaximum = kDefaultMaximum;
				if ((CallbackInformation.Length() > kMinimumArgumentIndex) && !GetFiniteFloatFromValue(pIsolate, LocalContext, CallbackInformation[kMinimumArgumentIndex], kUsageErrorMessage, flMinimum)) {
					return;
				}

				if ((CallbackInformation.Length() > kMaximumArgumentIndex) && !GetFiniteFloatFromValue(pIsolate, LocalContext, CallbackInformation[kMaximumArgumentIndex], kUsageErrorMessage, flMaximum)) {
					return;
				}

				Vector RandomValue = Vector(kDefaultMinimum, kDefaultMinimum, kDefaultMinimum);
				RandomValue.Random(flMinimum, flMaximum);

				v8::Local<v8::Object> const LocalRandomVectorObject = MakeMathVectorObject(pIsolate, LocalContext, RandomValue);
				if (LocalRandomVectorObject.IsEmpty()) {
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalRandomVectorObject);
			} catch (...) {
				ThrowError(pIsolate, kNativeExceptionErrorMessage);
			}
		}

		void IsVectorZeroCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kValueErrorMessage[] = "mathlib.IsVectorZero(VectorValue, flTolerance?) expects a vector-like value.";
			constexpr char kToleranceErrorMessage[] = "mathlib.IsVectorZero(VectorValue, flTolerance?) expects a finite tolerance.";
			constexpr int kValueArgumentIndex = 0;
			constexpr int kToleranceArgumentIndex = 1;
			constexpr float kDefaultTolerance = 0.01f;
			constexpr float kZeroComponent = 0.0f;
			constexpr char kNativeExceptionErrorMessage[] = "mathlib.IsVectorZero() failed with a native C++ exception.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				Vector VectorValue = Vector(kZeroComponent, kZeroComponent, kZeroComponent);
				if (!RequireMathVectorArgument(CallbackInformation, kValueArgumentIndex, kValueErrorMessage, VectorValue)) {
					return;
				}

				float flTolerance = kDefaultTolerance;
				if ((CallbackInformation.Length() > kToleranceArgumentIndex) && !GetFiniteFloatFromValue(pIsolate, LocalContext, CallbackInformation[kToleranceArgumentIndex], kToleranceErrorMessage, flTolerance)) {
					return;
				}

				CallbackInformation.GetReturnValue().Set(VectorValue.IsZero(flTolerance));
			} catch (...) {
				ThrowError(pIsolate, kNativeExceptionErrorMessage);
			}
		}

