		bool GetMatrixValuesFromValue(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Value> const LocalMatrixValue, const std::uint32_t unRowCount, char const* const pszErrorMessage, float* const pflMatrixValuesOut) {
			constexpr std::uint32_t kColumnCount = 4;
			constexpr std::uint32_t kMaximumRowCount = 4;
			constexpr std::size_t kMaximumMatrixElementCount = kMaximumRowCount * kColumnCount;

			if (!pIsolate || !pszErrorMessage || !pflMatrixValuesOut || (unRowCount == 0)) {
				return false;
			}

			if (LocalContext.IsEmpty() || LocalMatrixValue.IsEmpty()) {
				return false;
			}

			if (unRowCount > kMaximumRowCount) {
				return false;
			}

			if (!LocalMatrixValue->IsArray()) {
				ThrowError(pIsolate, pszErrorMessage);
				return false;
			}

			v8::Local<v8::Array> const LocalMatrixArray = LocalMatrixValue.As<v8::Array>();
			if (LocalMatrixArray.IsEmpty()) {
				return false;
			}

			const std::uint32_t unMatrixElementCount = unRowCount * kColumnCount;
			const std::uint32_t unInputElementCount = LocalMatrixArray->Length();

			// Only the 3x4/4x4 wrappers call this leaf; commit bounded storage after validation.
			std::array<float, kMaximumMatrixElementCount> arrStagedMatrixValues {};

			if (unInputElementCount >= unMatrixElementCount) {
				for (std::uint32_t unElementIndex = 0; unElementIndex < unMatrixElementCount; ++unElementIndex) {
					v8::Local<v8::Value> LocalComponentValue {};
					if (!LocalMatrixArray->Get(LocalContext, unElementIndex).ToLocal(&LocalComponentValue)) {
						return false;
					}

					if (!GetFiniteFloatFromValue(pIsolate, LocalContext, LocalComponentValue, pszErrorMessage, arrStagedMatrixValues[unElementIndex])) {
						return false;
					}
				}

				std::copy_n(arrStagedMatrixValues.data(), unMatrixElementCount, pflMatrixValuesOut);
				return true;
			}

			if (unInputElementCount < unRowCount) {
				ThrowError(pIsolate, pszErrorMessage);
				return false;
			}

			for (std::uint32_t unRowIndex = 0; unRowIndex < unRowCount; ++unRowIndex) {
				v8::Local<v8::Value> LocalRowValue {};
				if (!LocalMatrixArray->Get(LocalContext, unRowIndex).ToLocal(&LocalRowValue)) {
					return false;
				}

				if (LocalRowValue.IsEmpty() || !LocalRowValue->IsArray()) {
					ThrowError(pIsolate, pszErrorMessage);
					return false;
				}

				v8::Local<v8::Array> const LocalRowArray = LocalRowValue.As<v8::Array>();
				if (LocalRowArray.IsEmpty() || (LocalRowArray->Length() < kColumnCount)) {
					ThrowError(pIsolate, pszErrorMessage);
					return false;
				}

				for (std::uint32_t unColumnIndex = 0; unColumnIndex < kColumnCount; ++unColumnIndex) {
					v8::Local<v8::Value> LocalComponentValue {};
					const std::uint32_t unElementIndex = unRowIndex * kColumnCount + unColumnIndex;
					if (!LocalRowArray->Get(LocalContext, unColumnIndex).ToLocal(&LocalComponentValue)) {
						return false;
					}

					if (!GetFiniteFloatFromValue(pIsolate, LocalContext, LocalComponentValue, pszErrorMessage, arrStagedMatrixValues[unElementIndex])) {
						return false;
					}
				}
			}

			std::copy_n(arrStagedMatrixValues.data(), unMatrixElementCount, pflMatrixValuesOut);

			return true;
		}

		bool GetMatrix3x4FromValue(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Value> const LocalMatrixValue, char const* const pszErrorMessage, matrix3x4_t& Matrix3x4Out) {
			constexpr std::uint32_t kRowCount = 3;

			if (!pIsolate || LocalContext.IsEmpty() || LocalMatrixValue.IsEmpty() || !pszErrorMessage) {
				return false;
			}

			return GetMatrixValuesFromValue(pIsolate, LocalContext, LocalMatrixValue, kRowCount, pszErrorMessage, Matrix3x4Out.Base());
		}

		bool GetVMatrixFromValue(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Value> const LocalMatrixValue, char const* const pszErrorMessage, VMatrix& VMatrixOut) {
			constexpr std::uint32_t kRowCount = 4;

			if (!pIsolate || LocalContext.IsEmpty() || LocalMatrixValue.IsEmpty() || !pszErrorMessage) {
				return false;
			}

			return GetMatrixValuesFromValue(pIsolate, LocalContext, LocalMatrixValue, kRowCount, pszErrorMessage, VMatrixOut.Base());
		}

		v8::Local<v8::Array> MakeMatrixArray(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, float const* const pflMatrixValues, const std::uint32_t unRowCount) {
			constexpr std::uint32_t kColumnCount = 4;

			if (!pIsolate || !pflMatrixValues || LocalContext.IsEmpty() || (unRowCount == 0)) {
				return {};
			}

			if (unRowCount > (std::numeric_limits<std::uint32_t>::max() / kColumnCount)) {
				return {};
			}

			if (unRowCount > static_cast<std::uint32_t>(std::numeric_limits<int>::max())) {
				return {};
			}

			const int nRowCount = static_cast<int>(unRowCount);
			v8::Local<v8::Array> const LocalMatrixArray = v8::Array::New(pIsolate, nRowCount);
			if (LocalMatrixArray.IsEmpty()) {
				return {};
			}

			for (std::uint32_t unRowIndex = 0; unRowIndex < unRowCount; ++unRowIndex) {
				v8::Local<v8::Array> const LocalRowArray = v8::Array::New(pIsolate, static_cast<int>(kColumnCount));
				if (LocalRowArray.IsEmpty()) {
					return {};
				}

				for (std::uint32_t unColumnIndex = 0; unColumnIndex < kColumnCount; ++unColumnIndex) {
					const std::uint32_t unElementIndex = unRowIndex * kColumnCount + unColumnIndex;
					v8::Local<v8::Number> const LocalComponentValue = v8::Number::New(pIsolate, pflMatrixValues[unElementIndex]);
					if (LocalComponentValue.IsEmpty()) {
						return {};
					}

					v8::Maybe<bool> const MaybeSetResult = LocalRowArray->CreateDataProperty(LocalContext, unColumnIndex, LocalComponentValue);
					if (MaybeSetResult.IsNothing() || !MaybeSetResult.FromJust()) {
						return {};
					}
				}

				v8::Maybe<bool> const MaybeSetResult = LocalMatrixArray->CreateDataProperty(LocalContext, unRowIndex, LocalRowArray);
				if (MaybeSetResult.IsNothing() || !MaybeSetResult.FromJust()) {
					return {};
				}
			}

			return LocalMatrixArray;
		}

