			constexpr int kMaximumFilePosition = std::numeric_limits<int>::max();
			constexpr bool kAllowEmptyPath = false;
			constexpr bool kAllowEmptyMode = false;
			constexpr bool kAllowEmptyPathID = true;
			constexpr char kZeroByte = '\0';
			constexpr char kDefaultMode[] = "rb+";
			constexpr char kReadMode[] = "rb";
			constexpr char kWriteMode[] = "wb";
			constexpr char kPathUsageErrorMessage[] = "filesystem.TruncateSourceFile(hFile, strFilePath, strMode?, strPathID?, nTargetSize?) expects strFilePath to be a non-empty string.";
			constexpr char kModeUsageErrorMessage[] = "filesystem.TruncateSourceFile(hFile, strFilePath, strMode?, strPathID?, nTargetSize?) expects strMode to be a non-empty string or null.";
			constexpr char kPathIDUsageErrorMessage[] = "filesystem.TruncateSourceFile(hFile, strFilePath, strMode?, strPathID?, nTargetSize?) expects strPathID to be a string or null.";
			constexpr char kWritableModeErrorMessage[] = "filesystem.TruncateSourceFile(hFile, strFilePath, strMode?, strPathID?, nTargetSize?) expects strMode to allow writing.";
			constexpr char kTargetSizeUsageErrorMessage[] = "filesystem.TruncateSourceFile(hFile, strFilePath, strMode?, strPathID?, nTargetSize?) expects nTargetSize to be an integer or null.";
			constexpr char kMinimumTargetSizeErrorMessage[] = "filesystem.TruncateSourceFile(hFile, strFilePath, strMode?, strPathID?, nTargetSize?) does not allow nTargetSize below -1.";
			constexpr char kPositionRangeErrorMessage[] = "filesystem.TruncateSourceFile(hFile, strFilePath, strMode?, strPathID?, nTargetSize?) cannot preserve a position outside the supported integer range.";
			constexpr char kReadFileErrorMessage[] = "filesystem.TruncateSourceFile(hFile, strFilePath, strMode?, strPathID?, nTargetSize?) could not read the complete retained file data.";
			constexpr char kReopenForWriteErrorMessage[] = "filesystem.TruncateSourceFile(hFile, strFilePath, strMode?, strPathID?, nTargetSize?) could not reopen the file for truncation.";
			constexpr char kWriteFileErrorMessage[] = "filesystem.TruncateSourceFile(hFile, strFilePath, strMode?, strPathID?, nTargetSize?) could not write the complete truncated file data.";
			constexpr char kReopenAfterTruncationErrorMessage[] = "filesystem.TruncateSourceFile(hFile, strFilePath, strMode?, strPathID?, nTargetSize?) could not reopen the file after truncation.";
			constexpr char kHandlePropertyName[] = "Handle";
			constexpr char kSizePropertyName[] = "Size";
			constexpr char kBytesWrittenPropertyName[] = "BytesWritten";
			constexpr char kNativeExceptionErrorMessage[] = "filesystem.TruncateSourceFile() failed with a native C++ exception.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
