		void FindKeyValuesKeyCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kCreateMissingKeyTypeErrorMessage[] = "keyvalues.FindKey(Handle, strKeyName, bCreateMissingKey?) expects bCreateMissingKey to be a boolean.";
			constexpr char kMissingKeyNameErrorMessage[] = "keyvalues.FindKey(Handle, strKeyName, bCreateMissingKey?) expects a strKeyName.";
			constexpr char kKeyNameTypeErrorMessage[] = "keyvalues.FindKey(Handle, strKeyName, bCreateMissingKey?) expects strKeyName to be a string.";
			constexpr int kKeyNameArgumentIndex = 1;
			constexpr int kCreateMissingKeyArgumentIndex = 2;
			constexpr int kRequiredArgumentCount = 2;
			constexpr char kNativeExceptionErrorMessage[] = "keyvalues.FindKey(Handle, strKeyName, bCreateMissingKey?) failed with a native C++ exception.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				auto* const pKeyValues = RequireKeyValuesAddressArgument(CallbackInformation);
				if (!pKeyValues) {
					return;
				}

				if (CallbackInformation.Length() < kRequiredArgumentCount) {
					ThrowTypeError(pIsolate, kMissingKeyNameErrorMessage);
					return;
				}

				std::string strKeyName {};
				if (!RequireKeyValuesStringFromValue(pIsolate, CallbackInformation[kKeyNameArgumentIndex], kKeyNameTypeErrorMessage, strKeyName)) {
					return;
				}

				const bool bHasCreateMissingKeyArgument = CallbackInformation.Length() > kCreateMissingKeyArgumentIndex;
				bool bCreateMissingKey = false;
				if (bHasCreateMissingKeyArgument && !CallbackInformation[kCreateMissingKeyArgumentIndex]->IsBoolean()) {
					ThrowTypeError(pIsolate, kCreateMissingKeyTypeErrorMessage);
					return;
				}

				if (bHasCreateMissingKeyArgument) {
					bCreateMissingKey = CallbackInformation[kCreateMissingKeyArgumentIndex]->BooleanValue(pIsolate);
				}

				auto* const pChildKeyValues = pKeyValues->FindKey(strKeyName.c_str(), bCreateMissingKey);
				v8::Local<v8::Value> const LocalChildHandleValue = MakeKeyValuesHandleValue(pIsolate, LocalContext, pChildKeyValues, false);
				if (LocalChildHandleValue.IsEmpty()) {
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalChildHandleValue);
			} catch (...) {
				ThrowError(pIsolate, kNativeExceptionErrorMessage);
			}
		}

		bool RequireUnchangedKeyValuesAddress(v8::Isolate* const pIsolate, const int nKeyValuesHandle, KeyValues const* const pKeyValues, char const* const pszErrorMessage) {
			// Another handle's getter may invalidate an already resolved native object.
			std::unordered_map<int, KeyValuesRecord> const& umapKeyValuesRecords = GetKeyValuesRecords();
			auto itRecord = umapKeyValuesRecords.find(nKeyValuesHandle);
			if ((itRecord == umapKeyValuesRecords.end()) || (itRecord->second.m_pKeyValues != pKeyValues)) {
				ThrowError(pIsolate, pszErrorMessage);
				return false;
			}

			return true;
		}

