#undef SOURCEJS_DEFINE_GET_KEYVALUES_CHILD_CALLBACK

		void SetKeyValuesNextKeyCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kDistinctOwnedNextKeyTreeErrorMessage[] = "keyvalues.SetNextKey(Handle, Next) expects Next to be a distinct owned next-key tree or null.";
			constexpr bool kRequireNextKeyValues = true;
			constexpr int kNextKeyHandleArgumentIndex = 1;
			constexpr int kCurrentHandleArgumentIndex = 0;
			constexpr char kInvalidatedCurrentHandleErrorMessage[] = "keyvalues native current handle was invalidated by a handle getter.";
			constexpr char kNativeExceptionErrorMessage[] = "keyvalues.SetNextKey(Handle, Next) failed with a native C++ exception.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				int nCurrentKeyValuesHandle = kInvalidKeyValuesHandle;
				auto* const pKeyValues = RequireKeyValuesAddressArgument(CallbackInformation, kCurrentHandleArgumentIndex, &nCurrentKeyValuesHandle);
				if (!pKeyValues) {
					return;
				}

				const bool bHasNextKeyHandleArgument = (CallbackInformation.Length() > kNextKeyHandleArgumentIndex) && !CallbackInformation[kNextKeyHandleArgumentIndex]->IsNullOrUndefined();
				int nNextKeyValuesHandle = kInvalidKeyValuesHandle;
				KeyValues* pNextKeyValues = nullptr;
				if (bHasNextKeyHandleArgument) {
					pNextKeyValues = GetKeyValuesAddressFromValue(pIsolate, LocalContext, CallbackInformation[kNextKeyHandleArgumentIndex], kRequireNextKeyValues, &nNextKeyValuesHandle);
					if (!pNextKeyValues) {
						return;
					}
				}

				if (!RequireUnchangedKeyValuesAddress(pIsolate, nCurrentKeyValuesHandle, pKeyValues, kInvalidatedCurrentHandleErrorMessage)) {
					return;
				}

				auto* const pPreviousNextKeyValues = pKeyValues->GetNextKey();
				if (pPreviousNextKeyValues == pNextKeyValues) {
					CallbackInformation.GetReturnValue().Set(true);
					return;
				}

				std::unordered_map<int, KeyValuesRecord>& umapKeyValuesRecords = GetKeyValuesRecords();
				if (pNextKeyValues) {
					auto itNextKeyValuesRecord = umapKeyValuesRecords.find(nNextKeyValuesHandle);
					if (itNextKeyValuesRecord == umapKeyValuesRecords.end()) {
						ThrowError(pIsolate, kDistinctOwnedNextKeyTreeErrorMessage);
						return;
					}

					if (!itNextKeyValuesRecord->second.m_bOwnsKeyValues) {
						ThrowError(pIsolate, kDistinctOwnedNextKeyTreeErrorMessage);
						return;
					}

					if (itNextKeyValuesRecord->second.m_pKeyValues != pNextKeyValues) {
						ThrowError(pIsolate, kDistinctOwnedNextKeyTreeErrorMessage);
						return;
					}

					if (pKeyValues == pNextKeyValues) {
						ThrowError(pIsolate, kDistinctOwnedNextKeyTreeErrorMessage);
						return;
					}

					std::vector<KeyValues*> vecNextHierarchy {};
					CollectKeyValuesHierarchy(pNextKeyValues, vecNextHierarchy);
					if (IsKeyValuesAddressCollected(vecNextHierarchy, pKeyValues)) {
						ThrowError(pIsolate, kDistinctOwnedNextKeyTreeErrorMessage);
						return;
					}
				}

				int nPreviousNextKeyValuesOwnerHandle = kInvalidKeyValuesHandle;
				if (pPreviousNextKeyValues) {
					for (auto itKeyValuesRecord = umapKeyValuesRecords.begin(); itKeyValuesRecord != umapKeyValuesRecords.end(); ++itKeyValuesRecord) {
						if (itKeyValuesRecord->second.m_pKeyValues != pPreviousNextKeyValues) {
							continue;
						}

						if ((nPreviousNextKeyValuesOwnerHandle == kInvalidKeyValuesHandle) || (itKeyValuesRecord->first < nPreviousNextKeyValuesOwnerHandle)) {
							nPreviousNextKeyValuesOwnerHandle = itKeyValuesRecord->first;
						}
					}
				}

				// Prepare before linking: allocation failure must preserve the original ownership graph.
				std::vector<KeyValues*> vecPreviousNextHierarchy {};
				if (pPreviousNextKeyValues && (nPreviousNextKeyValuesOwnerHandle == kInvalidKeyValuesHandle)) {
					CollectKeyValuesHierarchy(pPreviousNextKeyValues, vecPreviousNextHierarchy);
				}

				pKeyValues->SetNextKey(pNextKeyValues);

				// The new peer belongs to this tree even if disposal of the detached peer fails.
				if (pNextKeyValues) {
					for (auto itKeyValuesRecord = umapKeyValuesRecords.begin(); itKeyValuesRecord != umapKeyValuesRecords.end(); ++itKeyValuesRecord) {
						if (itKeyValuesRecord->second.m_pKeyValues == pNextKeyValues) {
							itKeyValuesRecord->second.m_bOwnsKeyValues = false;
						}
					}
				}

				if (pPreviousNextKeyValues) {
					if (nPreviousNextKeyValuesOwnerHandle == kInvalidKeyValuesHandle) {
						EraseCollectedKeyValuesRecords(vecPreviousNextHierarchy);
						pPreviousNextKeyValues->deleteThis();
					} else {
						for (auto itKeyValuesRecord = umapKeyValuesRecords.begin(); itKeyValuesRecord != umapKeyValuesRecords.end(); ++itKeyValuesRecord) {
							if (itKeyValuesRecord->second.m_pKeyValues == pPreviousNextKeyValues) {
								itKeyValuesRecord->second.m_bOwnsKeyValues = itKeyValuesRecord->first == nPreviousNextKeyValuesOwnerHandle;
							}
						}
					}
				}

				CallbackInformation.GetReturnValue().Set(true);
			} catch (...) {
				ThrowError(pIsolate, kNativeExceptionErrorMessage);
			}
		}

