		template <typename TKeyValues>
		void GetKeyValuesKeyNamesCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr std::uint32_t kInvalidKeyNameIndex = std::numeric_limits<std::uint32_t>::max();
			constexpr char kKeyNamesLimitErrorMessage[] = "keyvalues.Keys(Handle) exceeds the maximum array length.";
			constexpr char kNativeExceptionErrorMessage[] = "keyvalues.Keys(Handle) failed with a native C++ exception.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				auto* const pKeyValues = static_cast<TKeyValues*>(RequireKeyValuesAddressArgument(CallbackInformation));
				if (!pKeyValues) {
					return;
				}

				v8::Local<v8::Array> const LocalKeyNamesArray = v8::Array::New(pIsolate);
				if (LocalKeyNamesArray.IsEmpty()) {
					return;
				}

				std::uint32_t unKeyNameIndex = 0;
				for (auto* pChildKeyValues = pKeyValues->GetFirstSubKey(); pChildKeyValues; pChildKeyValues = pChildKeyValues->GetNextKey()) {
					if (unKeyNameIndex == kInvalidKeyNameIndex) {
						ThrowError(pIsolate, kKeyNamesLimitErrorMessage);
						return;
					}

					char const* const pszChildKeyName = pChildKeyValues->GetName();
					if (!pszChildKeyName) {
						return;
					}

					v8::Local<v8::String> const LocalChildKeyName = MakeString(pIsolate, pszChildKeyName);
					if (LocalChildKeyName.IsEmpty()) {
						return;
					}

					v8::Maybe<bool> const MaybeCreateResult = LocalKeyNamesArray->CreateDataProperty(LocalContext, unKeyNameIndex, LocalChildKeyName);
					if (MaybeCreateResult.IsNothing() || !MaybeCreateResult.FromJust()) {
						return;
					}

					++unKeyNameIndex;
				}

				CallbackInformation.GetReturnValue().Set(LocalKeyNamesArray);
			} catch (...) {
				ThrowError(pIsolate, kNativeExceptionErrorMessage);
			}
		}

