		// Callers validate a width in [0, 32]; all representation shifts below are unsigned and narrower than 32.
		void WriteBitBufferSignedValue(bf_write& BitBufferWriter, const std::int32_t nValue, const int nBitCount) {
			if (nBitCount == 0) {
				return;
			}

			const int nMagnitudeBitCount = nBitCount - 1;
			const std::uint32_t unSignBit = std::uint32_t(1) << nMagnitudeBitCount;
			const std::uint32_t unMagnitudeMask = unSignBit - 1;
			const std::uint32_t unMagnitude = static_cast<std::uint32_t>(nValue) & unMagnitudeMask;

#if defined(ENGINE_BRANCH_BMS) || defined(ENGINE_BRANCH_CSS) || defined(ENGINE_BRANCH_DODS) || defined(ENGINE_BRANCH_HL2DM) || defined(ENGINE_BRANCH_PVKII) || defined(ENGINE_BRANCH_SDK2013) || defined(ENGINE_BRANCH_TF2)
#ifdef _DEBUG
			const std::int64_t nRepresentableValue = static_cast<std::int64_t>(unMagnitude) - ((nValue < 0) ? static_cast<std::int64_t>(unSignBit) : 0);
			AssertMsg2(nRepresentableValue == nValue, "WriteSBitLong: 0x%08x does not fit in %d bits", nValue, nBitCount);
#endif
			const std::uint32_t unEncodedValue = unMagnitude | ((nValue < 0) ? unSignBit : 0);
			WriteBitBufferUnsignedValue(BitBufferWriter, unEncodedValue, nBitCount);
#elif defined(ENGINE_BRANCH_BGT) || defined(ENGINE_BRANCH_BLADE) || defined(ENGINE_BRANCH_CONTAGION) || defined(ENGINE_BRANCH_CSGO) || defined(ENGINE_BRANCH_DARKM) || defined(ENGINE_BRANCH_DOI) || defined(ENGINE_BRANCH_EPISODE1) || defined(ENGINE_BRANCH_EYE) || defined(ENGINE_BRANCH_GMOD) || defined(ENGINE_BRANCH_INSURGENCY) || defined(ENGINE_BRANCH_L4D) || defined(ENGINE_BRANCH_L4D2) || defined(ENGINE_BRANCH_MCV) || defined(ENGINE_BRANCH_NUCLEARDAWN) || defined(ENGINE_BRANCH_ORANGEBOX) || defined(ENGINE_BRANCH_PORTAL2) || defined(ENGINE_BRANCH_SWARM)
#ifdef _DEBUG
			if (nValue < 0) {
				const std::int64_t nMinimumValue = -static_cast<std::int64_t>(unSignBit);
				Assert(nValue >= nMinimumValue);

			} else if (static_cast<std::uint32_t>(nValue) > unMagnitudeMask) {
				CallErrorHandler(BITBUFERROR_VALUE_OUT_OF_RANGE, BitBufferWriter.GetDebugName());
			}
#endif
			// Preserve the SDK's separate payload/sign failure boundaries without spilling adjacent bits.
			WriteBitBufferUnsignedValue(BitBufferWriter, unMagnitude, nMagnitudeBitCount);
			WriteLegacyBitBufferFlag(BitBufferWriter, nValue < 0);
#else
#error Unsupported engine branch for signed bit-buffer writes.
#endif
		}

		void WriteBitBufferStringCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kNativeExceptionError[] = "bitbuffers.WriteString failed with a native C++ exception.";
			constexpr int kStringValueArgumentIndex = 1;

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				return;
			}

			try {
				std::string strValue {};
				if (CallbackInformation.Length() > kStringValueArgumentIndex) {
					// Convert first: Utf8Value's internal TryCatch would consume the original JavaScript error.
					v8::Local<v8::String> LocalString {};
					if (!CallbackInformation[kStringValueArgumentIndex]->ToString(LocalContext).ToLocal(&LocalString)) {
						return;
					}

					v8::String::Utf8Value UTF8Value = v8::String::Utf8Value(pIsolate, LocalString);
					if (!*UTF8Value) {
						return;
					}

					strValue = *UTF8Value;
				}

				auto WriteString = [&strValue](bf_write& BitBufferWriter) -> void {
					constexpr int kCharacterBitCount = 8;

					// Preserve SDK character/sign boundaries, including the terminating zero after overflow.
					for (auto const& chValue : strValue) {
						WriteBitBufferSignedValue(BitBufferWriter, chValue, kCharacterBitCount);
					}

					WriteBitBufferSignedValue(BitBufferWriter, 0, kCharacterBitCount);
				};
				const bool bWriteSucceeded = ApplyBitBufferWriterOperation(CallbackInformation, WriteString);
				CallbackInformation.GetReturnValue().Set(bWriteSucceeded);
			} catch (...) {
				ThrowError(pIsolate, kNativeExceptionError);
			}
		}

