		void ReadBitBufferVarInt32Callback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kMaximumBitShift = 35;
			constexpr int kPayloadBitCount = 7;
			constexpr int kByteBitCount = 8;
			constexpr std::uint32_t kDataMask = 0x7F;
			constexpr std::uint32_t kContinuationMask = 0x80;
			constexpr std::uint32_t kMaximumValue = std::numeric_limits<std::uint32_t>::max();

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::Local<v8::Object> LocalBitBufferStateObject {};
			BitBuffersState BitBufferState {};
			SDKBitBufferReader BitBufferReader {};
			std::uint32_t unReadValue = 0;
			const bool bReadSucceeded = ApplyBitBufferReaderOperation(CallbackInformation, BitBufferState, LocalBitBufferStateObject, BitBufferReader, [&unReadValue](SDKBitBufferReader& OperationBitBufferReader) {
				int nBitShift = 0;
				while (nBitShift < kMaximumBitShift) {
					const std::uint32_t unEncodedByte = ReadBitBufferUnsignedValue(OperationBitBufferReader, kByteBitCount);
					const std::uint32_t unPayload = unEncodedByte & kDataMask;
					if (unPayload > (kMaximumValue >> nBitShift)) {
						OperationBitBufferReader.SetOverflowFlag();
						return;
					}

					unReadValue |= unPayload << nBitShift;

					if ((unEncodedByte & kContinuationMask) == 0) {
						return;
					}

					nBitShift += kPayloadBitCount;
				}

				OperationBitBufferReader.SetOverflowFlag();
			});
			if (!bReadSucceeded) {
				return;
			}

			v8::Local<v8::Integer> const LocalIntegerValue = v8::Integer::NewFromUnsigned(pIsolate, unReadValue);
			if (LocalIntegerValue.IsEmpty()) {
				return;
			}

			CallbackInformation.GetReturnValue().Set(LocalIntegerValue);
		}

