#if !defined(SOURCEJS_OLD_CONSOLE_API)
		static_assert((COORD_INTEGER_BITS_MP > 0) && (COORD_INTEGER_BITS_MP <= COORD_INTEGER_BITS) && (COORD_FRACTIONAL_BITS_MP_LOWPRECISION > 0) && (COORD_FRACTIONAL_BITS_MP_LOWPRECISION <= COORD_FRACTIONAL_BITS) && ((COORD_INTEGER_BITS + COORD_FRACTIONAL_BITS) < 31), "SDK multiplayer coordinate fields must fit signed 32-bit decoding.");

		float ReadBitBufferMultiplayerCoordinateValue(SDKBitBufferReader& Reader, const bool bIntegral, const bool bLowPrecision) {
#if defined(ENGINE_BRANCH_BMS) || defined(ENGINE_BRANCH_CSS) || defined(ENGINE_BRANCH_DODS) || defined(ENGINE_BRANCH_HL2DM) || defined(ENGINE_BRANCH_PVKII) || defined(ENGINE_BRANCH_SDK2013) || defined(ENGINE_BRANCH_TF2)
			constexpr int kIntegralFlagBitCount = 2;
			constexpr int kFractionalFlagBitCount = 3;
			constexpr std::uint32_t kInBoundsFlag = 0x01;
			constexpr std::uint32_t kHasIntegerFlag = 0x02;
			constexpr std::uint32_t kSignFlag = 0x04;
			constexpr std::uint32_t kIntegralSignBit = 0x01;

			const std::uint32_t unFlags = ReadBitBufferScalarUnsignedValue(Reader, bIntegral ? kIntegralFlagBitCount : kFractionalFlagBitCount);
			const bool bHasInteger = (unFlags & kHasIntegerFlag) != 0;
			const int nIntegerBitCount = (unFlags & kInBoundsFlag) ? COORD_INTEGER_BITS_MP : COORD_INTEGER_BITS;
			if (bIntegral) {
				if (!bHasInteger) {
					return 0.0F;
				}

				// The packed SDK reads sign and integer together, after the two flag bits.
				const std::uint32_t unBits = ReadBitBufferScalarUnsignedValue(Reader, nIntegerBitCount + 1);
				const float flValue = static_cast<float>((unBits >> 1) + 1);
				return (unBits & kIntegralSignBit) ? -flValue : flValue;
			}

			const int nFractionBitCount = bLowPrecision ? COORD_FRACTIONAL_BITS_MP_LOWPRECISION : COORD_FRACTIONAL_BITS;
			const int nPayloadBitCount = nFractionBitCount + (bHasInteger ? nIntegerBitCount : 0);
			std::uint32_t unBits = ReadBitBufferScalarUnsignedValue(Reader, nPayloadBitCount);
			if (bHasInteger) {
				const std::uint32_t unIntegerMask = (std::uint32_t(1) << nIntegerBitCount) - 1;
				const std::uint32_t unInteger = (unBits & unIntegerMask) + 1;
				const std::uint32_t unFraction = unBits >> nIntegerBitCount;
				unBits = (unInteger << nFractionBitCount) | unFraction;
			}

			const float flResolution = bLowPrecision ? static_cast<float>(COORD_RESOLUTION_LOWPRECISION) : static_cast<float>(COORD_RESOLUTION);
			const float flMultiplier = (unFlags & kSignFlag) ? -flResolution : flResolution;

			return static_cast<float>(unBits) * flMultiplier;
#else
			const bool bInBounds = Reader.ReadOneBit() != 0;
			const bool bHasInteger = Reader.ReadOneBit() != 0;
			if (bIntegral && !bHasInteger) {
				return 0.0F;
			}

			const bool bNegative = Reader.ReadOneBit() != 0;
			const int nIntegerBitCount = bInBounds ? COORD_INTEGER_BITS_MP : COORD_INTEGER_BITS;
			const std::uint32_t unInteger = bHasInteger ? (ReadBitBufferScalarUnsignedValue(Reader, nIntegerBitCount) + 1) : 0;
			if (bIntegral) {
				const float flValue = static_cast<float>(unInteger);
				return bNegative ? -flValue : flValue;
			}

			// Legacy SDKs keep the fraction in its own checked payload block.
			const int nFractionBitCount = bLowPrecision ? COORD_FRACTIONAL_BITS_MP_LOWPRECISION : COORD_FRACTIONAL_BITS;
			const std::uint32_t unFraction = ReadBitBufferScalarUnsignedValue(Reader, nFractionBitCount);
			const double dblResolution = bLowPrecision ? COORD_RESOLUTION_LOWPRECISION : COORD_RESOLUTION;
			const float flValue = static_cast<float>(unInteger + (static_cast<float>(unFraction) * dblResolution));

			return bNegative ? -flValue : flValue;
#endif
		}
#endif

		void ReadBitBufferVectorCoordinateValue(SDKBitBufferReader& Reader, Vector& CoordinateVectorOut) {
			CoordinateVectorOut.x = 0.0F;
			CoordinateVectorOut.y = 0.0F;
			CoordinateVectorOut.z = 0.0F;
			const bool bHasX = Reader.ReadOneBit() != 0;
			const bool bHasY = Reader.ReadOneBit() != 0;
			const bool bHasZ = Reader.ReadOneBit() != 0;
			if (bHasX) {
				CoordinateVectorOut.x = ReadBitBufferCoordinateValue(Reader);
			}

			if (bHasY) {
				CoordinateVectorOut.y = ReadBitBufferCoordinateValue(Reader);
			}

			if (bHasZ) {
				CoordinateVectorOut.z = ReadBitBufferCoordinateValue(Reader);
			}
		}

		void ReadBitBufferVectorNormalValue(SDKBitBufferReader& Reader, Vector& NormalVectorOut) {
			const bool bHasX = Reader.ReadOneBit() != 0;
			const bool bHasY = Reader.ReadOneBit() != 0;
			NormalVectorOut.x = bHasX ? ReadBitBufferNormalValue(Reader) : 0.0F;
			NormalVectorOut.y = bHasY ? ReadBitBufferNormalValue(Reader) : 0.0F;
			const bool bNegativeZ = Reader.ReadOneBit() != 0;
			const float flSquaredLength = NormalVectorOut.x * NormalVectorOut.x + NormalVectorOut.y * NormalVectorOut.y;
			NormalVectorOut.z = (flSquaredLength < 1.0F) ? static_cast<float>(::sqrt(1.0F - flSquaredLength)) : 0.0F;

			if (bNegativeZ) {
				NormalVectorOut.z = -NormalVectorOut.z;
			}
		}

		void ReadBitBufferAnglesValue(SDKBitBufferReader& Reader, QAngle& AnglesOut) {
			Vector CoordinateVector = Vector(0.0F, 0.0F, 0.0F);
			ReadBitBufferVectorCoordinateValue(Reader, CoordinateVector);
			AnglesOut.x = CoordinateVector.x;
			AnglesOut.y = CoordinateVector.y;
			AnglesOut.z = CoordinateVector.z;
		}

