			SOURCEJS_SET_TRACE_UNSIGNED(MASK_ALL);
			SOURCEJS_SET_TRACE_UNSIGNED(MASK_SOLID);
			SOURCEJS_SET_TRACE_UNSIGNED(MASK_PLAYERSOLID);
			SOURCEJS_SET_TRACE_UNSIGNED(MASK_NPCSOLID);
