			constexpr char kOriginListPropertyName[] = "Origins";
			constexpr char kSamplePropertyName[] = "Sample";
			constexpr char kEntityPropertyName[] = "Entity";
			constexpr char kChannelPropertyName[] = "Channel";
			constexpr char kVolumePropertyName[] = "Volume";
			constexpr char kAttenuationPropertyName[] = "Attenuation";
			constexpr char kSoundFlagsPropertyName[] = "Flags";
			constexpr char kPitchPropertyName[] = "Pitch";
			constexpr char kUpdatePositionsPropertyName[] = "UpdatePositions";
			constexpr char kSoundTimePropertyName[] = "SoundTime";
			constexpr char kSpeakerEntityIndexPropertyName[] = "SpeakerEntity";
			constexpr char kReliablePropertyName[] = "Reliable";
			constexpr char kChannelErrorMessage[] = "engines/sound.EmitSound() Channel expects an integer.";
			constexpr char kVolumeErrorMessage[] = "engines/sound.EmitSound() Volume expects a finite numeric value.";
			constexpr char kAttenuationErrorMessage[] = "engines/sound.EmitSound() Attenuation expects a finite numeric value.";
			constexpr char kSoundFlagsErrorMessage[] = "engines/sound.EmitSound() Flags expects an integer.";
			constexpr char kPitchErrorMessage[] = "engines/sound.EmitSound() Pitch expects an integer.";
			constexpr char kUpdatePositionsErrorMessage[] = "engines/sound.EmitSound() UpdatePositions expects a boolean.";
			constexpr char kSoundTimeErrorMessage[] = "engines/sound.EmitSound() SoundTime expects a finite numeric value.";
			constexpr char kSpeakerEntityErrorMessage[] = "engines/sound.EmitSound() SpeakerEntity expects an integer.";
			constexpr char kReliableErrorMessage[] = "engines/sound.EmitSound() Reliable expects a boolean.";
			constexpr char kUnavailableErrorMessage[] = "engines/sound.EmitSound() is not available in this Source SDK branch.";
			constexpr char kNativeExceptionErrorMessage[] = "engines/sound.EmitSound() failed with a native C++ exception.";

