			const int nEntityIndex = EntityHandle.GetEntryIndex();
			auto* const pEntityEdict = GetEdictFromEntityIndex(nEntityIndex);
			if (!pEntityEdict || pEntityEdict->IsFree()) {
				return nullptr;
			}

			auto* const pServerUnknown = pEntityEdict->GetUnknown();
			if (!pServerUnknown) {
				return nullptr;
			}

			CBaseHandle const& CurrentEntityHandle = pServerUnknown->GetRefEHandle();
			if (!CurrentEntityHandle.IsValid() || (CurrentEntityHandle.GetEntryIndex() != EntityHandle.GetEntryIndex()) || (CurrentEntityHandle.GetSerialNumber() != EntityHandle.GetSerialNumber())) {
				return nullptr;
			}

			return pServerUnknown->GetCollideable();
