			auto* const pGameClients = static_cast<IServerGameClients*>(g_Application.GetEngineInterfaces().GetInterface(INTERFACEVERSION_SERVERGAMECLIENTS));
			nMaximumClients = ResolveMaximumHumanClients(pGameClients, nMaximumClients);
