		void GetEngineServerInstalledMapsCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) try {
			constexpr char kOperationName[] = "engines/server.GetInstalledMaps()";
			constexpr std::string_view kMapExtension = ".bsp";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			auto* const pEngineServer = RequireEngineServer(pIsolate, kOperationName);
			if (!pEngineServer) {
				return;
			}

			auto* const pFileSystem = g_Application.GetEngineInterfaces().GetFileSystem();
			if (!pFileSystem) {
				ThrowError(pIsolate, "engines/server.GetInstalledMaps() requires the engine filesystem.");
				return;
			}

			std::vector<std::string> vecMaps {};
			{
				struct MapSearch {
					~MapSearch() {
						if (m_hFind != FILESYSTEM_INVALID_FIND_HANDLE) {
							m_FileSystem.FindClose(m_hFind);
						}
					}

					IFileSystem& m_FileSystem;
					FileFindHandle_t m_hFind;
				};

				MapSearch Search { *pFileSystem, FILESYSTEM_INVALID_FIND_HANDLE };

				char const* pszFileName = pFileSystem->FindFirstEx("maps/*.bsp", "GAME", &Search.m_hFind);
				while (pszFileName && (Search.m_hFind != FILESYSTEM_INVALID_FIND_HANDLE)) {
					std::string_view const strvFileName = pszFileName;
					if (!pFileSystem->FindIsDirectory(Search.m_hFind) && (strvFileName.size() > kMapExtension.size()) && (ToLowerASCII(std::string(strvFileName.substr(strvFileName.size() - kMapExtension.size()))) == kMapExtension) && (strvFileName.find_first_of("/\\:") == std::string_view::npos)) {
						std::string strMapName = std::string(strvFileName.substr(0, strvFileName.size() - kMapExtension.size()));
						if (pEngineServer->IsMapValid(strMapName.c_str()) != 0) {
							vecMaps.push_back(std::move(strMapName));
						}
					}

					pszFileName = pFileSystem->FindNext(Search.m_hFind);
				}
			}

			std::sort(vecMaps.begin(), vecMaps.end());
			auto itUniqueEnd = std::unique(vecMaps.begin(), vecMaps.end());
			vecMaps.erase(itUniqueEnd, vecMaps.end());

			v8::Local<v8::Array> const LocalMaps = MakeStringArray(pIsolate, pIsolate->GetCurrentContext(), vecMaps);
			if (!LocalMaps.IsEmpty()) {
				CallbackInformation.GetReturnValue().Set(LocalMaps);
			}
		} catch (...) {
			ThrowError(CallbackInformation.GetIsolate(), "engines/server.GetInstalledMaps() failed with a native C++ exception.");
		}

