		void GetEngineServerPVSForClusterCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kRequiredArgumentCount = 1;
			constexpr int kClusterArgumentIndex = 0;
			constexpr int kMinimumClusterIndex = 0;
			constexpr int kInvalidClusterIndex = -1;
			constexpr int kMaximumPVSByteCount = 1024 * 1024;
			constexpr unsigned char kZeroByte = 0;
			constexpr char kOperationName[] = "engines/server.GetPVSForCluster()";
			constexpr char kClusterArgumentErrorMessage[] = "engines/server.GetPVSForCluster(nClusterIndex) expects an integer cluster index.";
			constexpr char kClusterRangeErrorMessage[] = "engines/server.GetPVSForCluster(nClusterIndex) requires a cluster index inside the loaded BSP.";
			constexpr char kInvalidPVSByteCountErrorMessage[] = "IVEngineServer::GetPVSForCluster returned an invalid PVS size.";
			constexpr char kReportedPVSByteCountErrorMessage[] = "IVEngineServer::GetPVSForCluster did not fit the reported PVS size.";
			constexpr char kRequiredBytesPropertyName[] = "RequiredBytes";
			constexpr char kBytesPropertyName[] = "Bytes";
			constexpr char kNativeExceptionErrorMessage[] = "engines/server.GetPVSForCluster() failed with a native C++ exception.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				auto* const pEngineServer = RequireEngineServer(pIsolate, kOperationName);
				if (!pEngineServer) {
					return;
				}

				const int nArgumentCount = CallbackInformation.Length();
				if (nArgumentCount < kRequiredArgumentCount) {
					ThrowError(pIsolate, kClusterArgumentErrorMessage);
					return;
				}

				int nClusterIndex = kInvalidClusterIndex;
				if (!GetInt32Argument(pIsolate, LocalContext, CallbackInformation[kClusterArgumentIndex], kClusterArgumentErrorMessage, nClusterIndex)) {
					return;
				}

				int nPVSByteCount = 0;
				if (!GetEngineServerPVSByteCount(pIsolate, pEngineServer, nPVSByteCount)) {
					return;
				}

				int nClusterCount = 0;
				if (!GetEngineServerClusterCount(pIsolate, pEngineServer, kOperationName, nClusterCount)) {
					return;
				}

				if ((nClusterIndex < kMinimumClusterIndex) || (nClusterIndex >= nClusterCount)) {
					ThrowError(pIsolate, kClusterRangeErrorMessage);
					return;
				}

				if ((nPVSByteCount <= 0) || (nPVSByteCount > kMaximumPVSByteCount)) {
					ThrowError(pIsolate, kInvalidPVSByteCountErrorMessage);
					return;
				}

				std::vector<unsigned char> vecPVSBytes = std::vector<unsigned char>(static_cast<std::size_t>(nPVSByteCount), kZeroByte);
				int nRequiredPVSByteCount = pEngineServer->GetPVSForCluster(nClusterIndex, nPVSByteCount, vecPVSBytes.data());
				if ((nRequiredPVSByteCount < 0) || (nRequiredPVSByteCount > kMaximumPVSByteCount)) {
					ThrowError(pIsolate, kInvalidPVSByteCountErrorMessage);
					return;
				}

				if (nRequiredPVSByteCount > nPVSByteCount) {
					vecPVSBytes.assign(static_cast<std::size_t>(nRequiredPVSByteCount), kZeroByte);
					nRequiredPVSByteCount = pEngineServer->GetPVSForCluster(nClusterIndex, nRequiredPVSByteCount, vecPVSBytes.data());
					if ((nRequiredPVSByteCount < 0) || (nRequiredPVSByteCount > static_cast<int>(vecPVSBytes.size()))) {
						ThrowError(pIsolate, kReportedPVSByteCountErrorMessage);
						return;
					}
				}

				vecPVSBytes.resize(static_cast<std::size_t>(nRequiredPVSByteCount));

				v8::Local<v8::Object> const LocalPVSResultObject = v8::Object::New(pIsolate);
				if (LocalPVSResultObject.IsEmpty()) {
					return;
				}

				v8::Local<v8::Uint8Array> const LocalPVSBytesArray = MakeEngineByteArrayValue(pIsolate, vecPVSBytes);
				if (LocalPVSBytesArray.IsEmpty()) {
					return;
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalPVSResultObject, kRequiredBytesPropertyName, v8::Integer::New(pIsolate, nRequiredPVSByteCount))) {
					return;
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalPVSResultObject, kBytesPropertyName, LocalPVSBytesArray)) {
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalPVSResultObject);
			} catch (...) {
				ThrowError(pIsolate, kNativeExceptionErrorMessage);
			}
		}

