		template <typename TEngineServer>
		bool ExecuteEngineServerClientCommandKeyValues(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, TEngineServer* const pEngineServer, CBaseHandle const& ClientHandle, v8::Local<v8::Value> const LocalKeyValuesValue) {
			if (!pIsolate || LocalContext.IsEmpty() || !pEngineServer || !ClientHandle.IsValid() || LocalKeyValuesValue.IsEmpty()) {
				return false;
			}

			if constexpr (requires(TEngineServer* const pRequiredEngineServer, edict_t* const pRequiredClientEdict, KeyValues* const pRequiredNativeKeyValues) { pRequiredEngineServer->ClientCommandKeyValues(pRequiredClientEdict, pRequiredNativeKeyValues); }) {
				constexpr char kOperationName[] = "engines/server.ExecuteClientCommandKeyValues()";
				constexpr char kChangedClientErrorMessage[] = "engines/server.ExecuteClientCommandKeyValues() requires the original connected player after KeyValues preparation.";

				auto* const pNativeKeyValues = PrepareKeyValuesOwnershipTransfer(pIsolate, LocalContext, LocalKeyValuesValue);
				if (!pNativeKeyValues) {
					return false;
				}

				// Handle getters may disconnect or replace the original client; no ownership has moved yet.
				int nCurrentClientIndex = 0;
				if (!GetEntityIndexFromBaseHandleValue(ClientHandle, nCurrentClientIndex)) {
					ThrowError(pIsolate, kChangedClientErrorMessage);
					return false;
				}

				edict_t* pClientEdict = nullptr;
				auto* const pCurrentClientPlayerInformation = RequirePlayerInformationFromIndex(pIsolate, nCurrentClientIndex, &pClientEdict, kOperationName);
				if (!pCurrentClientPlayerInformation) {
					return false;
				}

				if (!pCurrentClientPlayerInformation->IsConnected()) {
					ThrowError(pIsolate, kChangedClientErrorMessage);
					return false;
				}

				ReleaseKeyValuesOwnershipToEngine(pNativeKeyValues);
				pEngineServer->ClientCommandKeyValues(pClientEdict, pNativeKeyValues);
				return true;

			} else {
				constexpr char kUnsupportedErrorMessage[] = "IVEngineServer::ClientCommandKeyValues is not declared by the selected Source SDK branch.";

				ThrowError(pIsolate, kUnsupportedErrorMessage);
				return false;
			}
		}

		void ExecuteEngineServerClientCommandKeyValuesCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kNativeExceptionErrorMessage[] = "engines/server.ExecuteClientCommandKeyValues() failed with a native C++ exception.";
			constexpr int kRequiredArgumentCount = 2;
			constexpr int kClientArgumentIndex = 0;
			constexpr int kKeyValuesArgumentIndex = 1;
			constexpr char kOperationName[] = "engines/server.ExecuteClientCommandKeyValues()";
			constexpr char kArgumentsErrorMessage[] = "engines/server.ExecuteClientCommandKeyValues(Client, KeyValues) expects a player or index and a KeyValues object.";
			constexpr char kDisconnectedPlayerErrorMessage[] = "engines/server.ExecuteClientCommandKeyValues(Client, KeyValues) requires a connected player.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				auto* const pEngineServer = RequireEngineServer(pIsolate, kOperationName);
				if (!pEngineServer) {
					return;
				}

				const int nArgumentCount = CallbackInformation.Length();
				if (nArgumentCount < kRequiredArgumentCount) {
					ThrowError(pIsolate, kArgumentsErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalClientValue = CallbackInformation[kClientArgumentIndex];
				v8::Local<v8::Value> const LocalKeyValuesValue = CallbackInformation[kKeyValuesArgumentIndex];
				if (LocalClientValue.IsEmpty() || LocalKeyValuesValue.IsEmpty()) {
					ThrowError(pIsolate, kArgumentsErrorMessage);
					return;
				}

				const int nClientIndex = GetValueIndex(pIsolate, LocalContext, LocalClientValue);
				if (pIsolate->HasPendingException()) {
					return;
				}

				edict_t* pClientEdict = nullptr;
				auto* const pClientPlayerInformation = RequirePlayerInformationFromIndex(pIsolate, nClientIndex, &pClientEdict, kOperationName);
				if (!pClientPlayerInformation) {
					return;
				}

				if (!pClientPlayerInformation->IsConnected()) {
					ThrowError(pIsolate, kDisconnectedPlayerErrorMessage);
					return;
				}

				CBaseHandle ClientHandle {};
				if (!GetEntityBaseHandleFromEdictAddress(pClientEdict, ClientHandle)) {
					ThrowError(pIsolate, kDisconnectedPlayerErrorMessage);
					return;
				}

				if (!ExecuteEngineServerClientCommandKeyValues(pIsolate, LocalContext, pEngineServer, ClientHandle, LocalKeyValuesValue)) {
					return;
				}

				CallbackInformation.GetReturnValue().Set(true);
			} catch (...) {
				ThrowError(pIsolate, kNativeExceptionErrorMessage);
			}
		}

		void* RequireOpaqueAddressFromValue(v8::Isolate* const pIsolate, v8::Local<v8::Value> const LocalAddressValue, char const* const pszErrorMessage) {
			if (!pIsolate || LocalAddressValue.IsEmpty() || !pszErrorMessage) {
				return nullptr;
			}

			std::uintptr_t unAddress = 0;
			if (!GetAddressSizedUnsignedIntegerFromValue(LocalAddressValue, unAddress)) {
				ThrowError(pIsolate, pszErrorMessage);
				return nullptr;
			}

			if (unAddress == 0) {
				ThrowError(pIsolate, pszErrorMessage);
				return nullptr;
			}

			return reinterpret_cast<void*>(unAddress);
		}

