		template <typename TBitVector>
		v8::Local<v8::Array> MakeEngineEntityIndexArrayFromBitVector(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, TBitVector const* const pEntityBitVector) {
			constexpr int kMaximumEntityCount = MAX_EDICTS;

			static_assert(kMaximumEntityCount >= 0, "MAX_EDICTS must not be negative.");
			static_assert(static_cast<std::uint64_t>(kMaximumEntityCount) <= static_cast<std::uint64_t>(std::numeric_limits<std::uint32_t>::max()), "MAX_EDICTS must fit a V8 array index.");

			if (!pIsolate || LocalContext.IsEmpty()) {
				return {};
			}

			// Snapshot native bit storage before constructing the copied index array.
			std::vector<int> vecEntityIndexes {};
			if (pEntityBitVector) {
				for (int nEntityIndex = 0; nEntityIndex < kMaximumEntityCount; ++nEntityIndex) {
					if (pEntityBitVector->IsBitSet(nEntityIndex)) {
						vecEntityIndexes.push_back(nEntityIndex);
					}
				}
			}

			v8::Local<v8::Array> const LocalEntityIndexArray = v8::Array::New(pIsolate);
			if (LocalEntityIndexArray.IsEmpty()) {
				return {};
			}

			std::uint32_t unEntityIndexArrayIndex = 0;
			for (auto const& nEntityIndex : vecEntityIndexes) {
				v8::Local<v8::Integer> const LocalEntityIndexValue = v8::Integer::New(pIsolate, nEntityIndex);
				if (LocalEntityIndexValue.IsEmpty()) {
					return {};
				}

				v8::Maybe<bool> const MaybeSetResult = LocalEntityIndexArray->CreateDataProperty(LocalContext, unEntityIndexArrayIndex, LocalEntityIndexValue);
				if (MaybeSetResult.IsNothing() || !MaybeSetResult.FromJust()) {
					return {};
				}

				++unEntityIndexArrayIndex;
			}

			return LocalEntityIndexArray;
		}

