		v8::Local<v8::Array> MakeEngineIntegerArrayFromBuffer(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, int const* const pnIntegerBuffer, const int nIntegerValueCount) {
			constexpr char kNullIntegerBufferErrorMessage[] = "Could not convert a null integer buffer with a non-zero value count.";

			static_assert(static_cast<std::uint64_t>(std::numeric_limits<int>::max()) <= static_cast<std::uint64_t>(std::numeric_limits<std::uint32_t>::max()), "int values must fit a V8 array index.");

			if (!pIsolate || LocalContext.IsEmpty()) {
				return {};
			}

			const int nNonNegativeIntegerValueCount = std::max(0, nIntegerValueCount);
			if ((nNonNegativeIntegerValueCount > 0) && !pnIntegerBuffer) {
				ThrowError(pIsolate, kNullIntegerBufferErrorMessage);
				return {};
			}

			std::vector<int> vecIntegerValues {};
			if (nNonNegativeIntegerValueCount > 0) {
				vecIntegerValues.assign(pnIntegerBuffer, pnIntegerBuffer + nNonNegativeIntegerValueCount);
			}

			v8::Local<v8::Array> const LocalIntegerArray = v8::Array::New(pIsolate, nNonNegativeIntegerValueCount);
			if (LocalIntegerArray.IsEmpty()) {
				return {};
			}

			for (int nIntegerValueIndex = 0; nIntegerValueIndex < nNonNegativeIntegerValueCount; ++nIntegerValueIndex) {
				v8::Local<v8::Integer> const LocalIntegerValue = v8::Integer::New(pIsolate, vecIntegerValues[nIntegerValueIndex]);
				if (LocalIntegerValue.IsEmpty()) {
					return {};
				}

				v8::Maybe<bool> const MaybeSetResult = LocalIntegerArray->CreateDataProperty(LocalContext, static_cast<std::uint32_t>(nIntegerValueIndex), LocalIntegerValue);
				if (MaybeSetResult.IsNothing() || !MaybeSetResult.FromJust()) {
					return {};
				}
			}

			return LocalIntegerArray;
		}

