				v8::Local<v8::Integer> const LocalByteValue = v8::Integer::NewFromUnsigned(pIsolate, vecByteValues[nByteValueIndex]);
				if (LocalByteValue.IsEmpty()) {
					return {};
				}

				v8::Maybe<bool> const MaybeSetResult = LocalByteArray->CreateDataProperty(LocalContext, static_cast<std::uint32_t>(nByteValueIndex), LocalByteValue);
