		// Track nested result construction on the callback thread, not native partition ownership after return.
		class SpatialPartitionConstructionScope {
		public:
			explicit SpatialPartitionConstructionScope(ISpatialPartition const* const pSpatialPartition) noexcept;
			SpatialPartitionConstructionScope(SpatialPartitionConstructionScope const&) = delete;
			SpatialPartitionConstructionScope(SpatialPartitionConstructionScope&&) = delete;
			~SpatialPartitionConstructionScope() noexcept;

			SpatialPartitionConstructionScope& operator=(SpatialPartitionConstructionScope const&) = delete;
			SpatialPartitionConstructionScope& operator=(SpatialPartitionConstructionScope&&) = delete;

			static bool IsConstructing(ISpatialPartition const* const pSpatialPartition) noexcept;

		private:
			static thread_local SpatialPartitionConstructionScope const* m_pCurrentScope;
			std::uintptr_t m_unAddress;
			SpatialPartitionConstructionScope const* m_pPreviousScope;
		};

		thread_local SpatialPartitionConstructionScope const* SpatialPartitionConstructionScope::m_pCurrentScope = nullptr;

		SpatialPartitionConstructionScope::SpatialPartitionConstructionScope(ISpatialPartition const* const pSpatialPartition) noexcept :
			m_unAddress(reinterpret_cast<std::uintptr_t>(pSpatialPartition))
		{
			m_pPreviousScope = m_pCurrentScope;
			m_pCurrentScope = this;
		}

		SpatialPartitionConstructionScope::~SpatialPartitionConstructionScope() noexcept {
			m_pCurrentScope = m_pPreviousScope;
		}

		bool SpatialPartitionConstructionScope::IsConstructing(ISpatialPartition const* const pSpatialPartition) noexcept {
			if (!pSpatialPartition) {
				return false;
			}

			const std::uintptr_t unSpatialPartitionAddress = reinterpret_cast<std::uintptr_t>(pSpatialPartition);
			for (auto const* pScope = m_pCurrentScope; pScope; pScope = pScope->m_pPreviousScope) {
				if (pScope->m_unAddress == unSpatialPartitionAddress) {
					return true;
				}
			}

			return false;
		}
#endif // defined(SOURCEJS_HAS_SPATIAL_PARTITION)

		void CreateEngineServerSpatialPartitionCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kNativeExceptionErrorMessage[] = "engines/server.CreateSpatialPartition() failed with a native C++ exception.";
			constexpr char kSpatialPartitionCleanupErrorMessage[] = "engines/server.CreateSpatialPartition() failed to return a partition, and destroying the unreturned partition also failed.";
#if defined(SOURCEJS_HAS_SPATIAL_PARTITION)
			constexpr int kRequiredArgumentCount = 2;
			constexpr int kWorldMinimumArgumentIndex = 0;
			constexpr int kWorldMaximumArgumentIndex = 1;
			constexpr char kOperationName[] = "engines/server.CreateSpatialPartition()";
			constexpr char kWorldBoundsArgumentErrorMessage[] = "engines/server.CreateSpatialPartition(WorldMinimum, WorldMaximum) expects two Vector-compatible bounds.";
			constexpr char kSpatialPartitionTypeName[] = "ISpatialPartition";
#else
			constexpr char kUnsupportedErrorMessage[] = "IVEngineServer::CreateSpatialPartition requires ispatialpartition.h in the selected Source SDK branch.";
#endif // defined(SOURCEJS_HAS_SPATIAL_PARTITION)

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			bool bSpatialPartitionCleanupFailed = false;

			try {
#if defined(SOURCEJS_HAS_SPATIAL_PARTITION)
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				auto* const pEngineServer = RequireEngineServer(pIsolate, kOperationName);
				if (!pEngineServer) {
					return;
				}

				const int nArgumentCount = CallbackInformation.Length();
				if (nArgumentCount < kRequiredArgumentCount) {
					ThrowError(pIsolate, kWorldBoundsArgumentErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalWorldMinimumValue = CallbackInformation[kWorldMinimumArgumentIndex];
				v8::Local<v8::Value> const LocalWorldMaximumValue = CallbackInformation[kWorldMaximumArgumentIndex];
				if (LocalWorldMinimumValue.IsEmpty() || LocalWorldMaximumValue.IsEmpty()) {
					ThrowError(pIsolate, kWorldBoundsArgumentErrorMessage);
					return;
				}

				Vector WorldMinimum {};
				Vector WorldMaximum {};
				if (!RequireVectorFromValue(pIsolate, LocalContext, LocalWorldMinimumValue, kWorldBoundsArgumentErrorMessage, WorldMinimum)) {
					return;
				}

				if (!RequireVectorFromValue(pIsolate, LocalContext, LocalWorldMaximumValue, kWorldBoundsArgumentErrorMessage, WorldMaximum)) {
					return;
				}

				bool bIsSpatialPartitionCreationAPIAvailable = false;
				auto* const pSpatialPartition = CreateEngineServerSpatialPartition(pIsolate, pEngineServer, WorldMinimum, WorldMaximum, bIsSpatialPartitionCreationAPIAvailable);
				if (!bIsSpatialPartitionCreationAPIAvailable) {
					return;
				}

				if (!pSpatialPartition) {
					CallbackInformation.GetReturnValue().Set(v8::Null(pIsolate));
					return;
				}

				// Own the SDK allocation until its address wrapper is returned.
				auto ReleaseSpatialPartition = [pEngineServer, &bSpatialPartitionCleanupFailed](ISpatialPartition* const pUnreturnedSpatialPartition) noexcept -> void {
					bSpatialPartitionCleanupFailed = !ReleaseUnreturnedEngineServerSpatialPartition(pEngineServer, pUnreturnedSpatialPartition);
				};

				SpatialPartitionConstructionScope const SpatialPartitionScope(pSpatialPartition);
				std::unique_ptr<ISpatialPartition, decltype(ReleaseSpatialPartition)> pSpatialPartitionOwner(pSpatialPartition, ReleaseSpatialPartition);
				v8::Local<v8::Object> const LocalSpatialPartitionObject = MakeEngineServerAddressObject(pIsolate, LocalContext, kSpatialPartitionTypeName, pSpatialPartition);
				if (LocalSpatialPartitionObject.IsEmpty()) {
					pSpatialPartitionOwner.reset();
					if (bSpatialPartitionCleanupFailed) {
						ThrowError(pIsolate, kSpatialPartitionCleanupErrorMessage);
					}

					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalSpatialPartitionObject);
				pSpatialPartitionOwner.release();
#else
				ThrowError(pIsolate, kUnsupportedErrorMessage);
#endif // defined(SOURCEJS_HAS_SPATIAL_PARTITION)
			} catch (...) {
				ThrowError(pIsolate, bSpatialPartitionCleanupFailed ? kSpatialPartitionCleanupErrorMessage : kNativeExceptionErrorMessage);
			}
		}

		void DestroyEngineServerSpatialPartitionCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kNativeExceptionErrorMessage[] = "engines/server.DestroySpatialPartition() failed with a native C++ exception.";
#if defined(SOURCEJS_HAS_SPATIAL_PARTITION)
			constexpr int kRequiredArgumentCount = 1;
			constexpr int kSpatialPartitionAddressArgumentIndex = 0;
			constexpr char kOperationName[] = "engines/server.DestroySpatialPartition()";
			constexpr char kSpatialPartitionAddressArgumentErrorMessage[] = "engines/server.DestroySpatialPartition(unSpatialPartitionAddress) expects a non-null ISpatialPartition address.";
			constexpr char kSpatialPartitionUnderConstructionErrorMessage[] = "engines/server.DestroySpatialPartition() cannot destroy a partition before CreateSpatialPartition() returns it.";
#else
			constexpr char kUnsupportedErrorMessage[] = "IVEngineServer::DestroySpatialPartition requires ispatialpartition.h in the selected Source SDK branch.";
#endif // defined(SOURCEJS_HAS_SPATIAL_PARTITION)

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
#if defined(SOURCEJS_HAS_SPATIAL_PARTITION)
				auto* const pEngineServer = RequireEngineServer(pIsolate, kOperationName);
				if (!pEngineServer) {
					return;
				}

				const int nArgumentCount = CallbackInformation.Length();
				if (nArgumentCount < kRequiredArgumentCount) {
					ThrowError(pIsolate, kSpatialPartitionAddressArgumentErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalSpatialPartitionAddressValue = CallbackInformation[kSpatialPartitionAddressArgumentIndex];
				if (LocalSpatialPartitionAddressValue.IsEmpty()) {
					ThrowError(pIsolate, kSpatialPartitionAddressArgumentErrorMessage);
					return;
				}

				auto* const pSpatialPartition = static_cast<ISpatialPartition*>(RequireOpaqueAddressFromValue(pIsolate, LocalSpatialPartitionAddressValue, kSpatialPartitionAddressArgumentErrorMessage));
				if (!pSpatialPartition) {
					return;
				}

				if (SpatialPartitionConstructionScope::IsConstructing(pSpatialPartition)) {
					ThrowError(pIsolate, kSpatialPartitionUnderConstructionErrorMessage);
					return;
				}

				if (!DestroyEngineServerSpatialPartition(pIsolate, pEngineServer, pSpatialPartition)) {
					return;
				}

				CallbackInformation.GetReturnValue().Set(true);
#else
				ThrowError(pIsolate, kUnsupportedErrorMessage);
#endif // defined(SOURCEJS_HAS_SPATIAL_PARTITION)
			} catch (...) {
				ThrowError(pIsolate, kNativeExceptionErrorMessage);
			}
		}

