		void DrawEngineServerSpatialPartitionMapToScratchPadCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kNativeExceptionErrorMessage[] = "engines/server.DrawSpatialPartitionMapToScratchPad() failed with a native C++ exception.";
			constexpr int kRequiredArgumentCount = 2;
			constexpr int kScratchPad3DAddressArgumentIndex = 0;
			constexpr int kDrawFlagsArgumentIndex = 1;
			constexpr char kOperationName[] = "engines/server.DrawSpatialPartitionMapToScratchPad()";
			constexpr char kScratchPad3DAddressArgumentErrorMessage[] = "engines/server.DrawSpatialPartitionMapToScratchPad(unScratchPad3DAddress, unDrawFlags) expects a non-null IScratchPad3D address.";
			constexpr char kDrawFlagsArgumentErrorMessage[] = "engines/server.DrawSpatialPartitionMapToScratchPad(unScratchPad3DAddress, unDrawFlags) expects unsigned 32-bit flags.";

			static_assert(sizeof(unsigned long) >= sizeof(std::uint32_t), "unsigned long must represent every uint32_t draw flag value.");

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				auto* const pEngineServer = RequireEngineServer(pIsolate, kOperationName);
				if (!pEngineServer) {
					return;
				}

				const int nArgumentCount = CallbackInformation.Length();
				if (nArgumentCount < kRequiredArgumentCount) {
					ThrowError(pIsolate, (nArgumentCount <= kScratchPad3DAddressArgumentIndex) ? kScratchPad3DAddressArgumentErrorMessage : kDrawFlagsArgumentErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalScratchPad3DAddressValue = CallbackInformation[kScratchPad3DAddressArgumentIndex];
				v8::Local<v8::Value> const LocalDrawFlagsValue = CallbackInformation[kDrawFlagsArgumentIndex];
				if (LocalScratchPad3DAddressValue.IsEmpty()) {
					ThrowError(pIsolate, kScratchPad3DAddressArgumentErrorMessage);
					return;
				}

				if (LocalDrawFlagsValue.IsEmpty()) {
					ThrowError(pIsolate, kDrawFlagsArgumentErrorMessage);
					return;
				}

				auto* const pScratchPad3D = static_cast<IScratchPad3D*>(RequireOpaqueAddressFromValue(pIsolate, LocalScratchPad3DAddressValue, kScratchPad3DAddressArgumentErrorMessage));
				if (!pScratchPad3D) {
					return;
				}

				std::uint32_t unDrawFlags = 0;
				if (!GetUInt32Argument(pIsolate, LocalContext, LocalDrawFlagsValue, kDrawFlagsArgumentErrorMessage, unDrawFlags)) {
					return;
				}

				if (!DrawEngineServerMapToScratchPad(pIsolate, pEngineServer, pScratchPad3D, static_cast<unsigned long>(unDrawFlags))) {
					return;
				}

				CallbackInformation.GetReturnValue().Set(true);
			} catch (...) {
				ThrowError(pIsolate, kNativeExceptionErrorMessage);
			}
		}

