		v8::Local<v8::Object> MakeEngineServerPVSInformationObject(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, PVSInfo_t* const pBorrowedPVSInformation) {
			constexpr std::size_t kMaximumPVSClusterCount = 65536;
			constexpr std::size_t kInlinePVSClusterCount = std::extent_v<decltype(PVSInfo_t::m_pClusters)>;
			constexpr std::size_t kPVSClusterStorageLimit = kInlinePVSClusterCount ? std::min(kMaximumPVSClusterCount, kInlinePVSClusterCount) : kMaximumPVSClusterCount;
			constexpr std::size_t kXComponentIndex = 0;
			constexpr std::size_t kYComponentIndex = 1;
			constexpr std::size_t kZComponentIndex = 2;
			constexpr char kPVSInformationTypeName[] = "PVSInfo_t";
			constexpr char kHeadNodePropertyName[] = "HeadNode";
			constexpr char kClusterCountPropertyName[] = "ClusterCount";
			constexpr char kAreaPropertyName[] = "Area";
			constexpr char kSecondaryAreaPropertyName[] = "SecondaryArea";
			constexpr char kCenterPropertyName[] = "Center";
			constexpr char kClustersPropertyName[] = "Clusters";
			constexpr char kClusterSnapshotAllocationErrorMessage[] = "engines/server PVS information snapshot failed to allocate native cluster storage.";

			static_assert(static_cast<std::uint64_t>(kMaximumPVSClusterCount) <= static_cast<std::uint64_t>(std::numeric_limits<std::uint32_t>::max()), "The PVS cluster limit must fit a V8 array index.");

			if (!pIsolate || LocalContext.IsEmpty()) {
				return {};
			}

			// Construct the result from owned data, independent of the SDK cluster buffer.
			PVSInfo_t PVSInformationSnapshot {};
			std::unique_ptr<std::uint32_t[]> punPVSClusterSnapshot {};
			std::size_t unPVSClusterCount = 0;
			if (pBorrowedPVSInformation) {
				PVSInformationSnapshot.m_nHeadNode = pBorrowedPVSInformation->m_nHeadNode;
				PVSInformationSnapshot.m_nClusterCount = pBorrowedPVSInformation->m_nClusterCount;
				PVSInformationSnapshot.m_nAreaNum = pBorrowedPVSInformation->m_nAreaNum;
				PVSInformationSnapshot.m_nAreaNum2 = pBorrowedPVSInformation->m_nAreaNum2;
				PVSInformationSnapshot.m_vCenter[kXComponentIndex] = pBorrowedPVSInformation->m_vCenter[kXComponentIndex];
				PVSInformationSnapshot.m_vCenter[kYComponentIndex] = pBorrowedPVSInformation->m_vCenter[kYComponentIndex];
				PVSInformationSnapshot.m_vCenter[kZComponentIndex] = pBorrowedPVSInformation->m_vCenter[kZComponentIndex];

				if ((PVSInformationSnapshot.m_nClusterCount > 0) && (kInlinePVSClusterCount || pBorrowedPVSInformation->m_pClusters)) {
					unPVSClusterCount = std::min(static_cast<std::size_t>(PVSInformationSnapshot.m_nClusterCount), kPVSClusterStorageLimit);
					punPVSClusterSnapshot.reset(new (std::nothrow) std::uint32_t[unPVSClusterCount]);
					if (!punPVSClusterSnapshot) {
						ThrowError(pIsolate, kClusterSnapshotAllocationErrorMessage);
						return {};
					}

					for (std::size_t unClusterIndex = 0; unClusterIndex < unPVSClusterCount; ++unClusterIndex) {
						punPVSClusterSnapshot[unClusterIndex] = static_cast<std::uint32_t>(pBorrowedPVSInformation->m_pClusters[unClusterIndex]);
					}
				}
			}

			auto* const pPVSInformation = pBorrowedPVSInformation ? &PVSInformationSnapshot : nullptr;
			v8::Local<v8::Object> const LocalPVSInformationObject = MakeEngineServerAddressObject(pIsolate, LocalContext, kPVSInformationTypeName, pBorrowedPVSInformation);
			if (LocalPVSInformationObject.IsEmpty()) {
				return {};
			}

			if (!pPVSInformation) {
				return LocalPVSInformationObject;
			}

			Vector const Center = Vector(pPVSInformation->m_vCenter[kXComponentIndex], pPVSInformation->m_vCenter[kYComponentIndex], pPVSInformation->m_vCenter[kZComponentIndex]);
			v8::Local<v8::Array> const LocalPVSClusterArray = v8::Array::New(pIsolate);
			if (LocalPVSClusterArray.IsEmpty()) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalPVSInformationObject, kHeadNodePropertyName, v8::Integer::New(pIsolate, pPVSInformation->m_nHeadNode))) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalPVSInformationObject, kClusterCountPropertyName, v8::Integer::New(pIsolate, pPVSInformation->m_nClusterCount))) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalPVSInformationObject, kAreaPropertyName, v8::Integer::New(pIsolate, pPVSInformation->m_nAreaNum))) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalPVSInformationObject, kSecondaryAreaPropertyName, v8::Integer::New(pIsolate, pPVSInformation->m_nAreaNum2))) {
				return {};
			}

			v8::Local<v8::Object> const LocalCenterObject = MakeVectorObject(pIsolate, LocalContext, Center);
			if (LocalCenterObject.IsEmpty()) {
				return {};
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalPVSInformationObject, kCenterPropertyName, LocalCenterObject)) {
				return {};
			}

			for (std::size_t unPVSClusterIndex = 0; unPVSClusterIndex < unPVSClusterCount; ++unPVSClusterIndex) {
				v8::Local<v8::Integer> const LocalPVSClusterValue = v8::Integer::NewFromUnsigned(pIsolate, punPVSClusterSnapshot[unPVSClusterIndex]);
				if (LocalPVSClusterValue.IsEmpty()) {
					return {};
				}

				if (!LocalPVSClusterArray->CreateDataProperty(LocalContext, static_cast<std::uint32_t>(unPVSClusterIndex), LocalPVSClusterValue).FromMaybe(false)) {
					return {};
				}
			}

			if (!SetRecordProperty(pIsolate, LocalContext, LocalPVSInformationObject, kClustersPropertyName, LocalPVSClusterArray)) {
				return {};
			}

			return LocalPVSInformationObject;
		}

