		bool InstallMapLoadTypeConstants(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalTargetObject) {
			constexpr char kNewGamePropertyName[] = "NEW_GAME";
			constexpr char kLoadGamePropertyName[] = "LOAD_GAME";
			constexpr char kTransitionPropertyName[] = "TRANSITION";
			constexpr char kBackgroundPropertyName[] = "BACKGROUND";
			constexpr char kMapLoadTypePropertyName[] = "MapLoadType";
			constexpr char kInstallationErrorMessage[] = "Failed to install MapLoadType constants.";

			if (!pIsolate || LocalContext.IsEmpty() || LocalTargetObject.IsEmpty()) {
				return false;
			}

			v8::TryCatch InstallationFailure(pIsolate);
			try {
				auto const ThrowInstallationFallbackError = [pIsolate, &InstallationFailure, &kInstallationErrorMessage]() {
					if (!InstallationFailure.HasCaught() && !pIsolate->IsExecutionTerminating() && !pIsolate->HasPendingException()) {
						ThrowError(pIsolate, kInstallationErrorMessage);
					}

					if (InstallationFailure.HasCaught()) {
						InstallationFailure.ReThrow();
					}
				};

				v8::Local<v8::Object> const LocalMapLoadTypeObject = v8::Object::New(pIsolate);
				if (LocalMapLoadTypeObject.IsEmpty()) {
					ThrowInstallationFallbackError();
					return false;
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalMapLoadTypeObject, kNewGamePropertyName, v8::Integer::New(pIsolate, MapLoad_NewGame))) {
					ThrowInstallationFallbackError();
					return false;
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalMapLoadTypeObject, kLoadGamePropertyName, v8::Integer::New(pIsolate, MapLoad_LoadGame))) {
					ThrowInstallationFallbackError();
					return false;
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalMapLoadTypeObject, kTransitionPropertyName, v8::Integer::New(pIsolate, MapLoad_Transition))) {
					ThrowInstallationFallbackError();
					return false;
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalMapLoadTypeObject, kBackgroundPropertyName, v8::Integer::New(pIsolate, MapLoad_Background))) {
					ThrowInstallationFallbackError();
					return false;
				}

				if (!SetValue(pIsolate, LocalContext, LocalTargetObject, kMapLoadTypePropertyName, LocalMapLoadTypeObject)) {
					ThrowInstallationFallbackError();
					return false;
				}

				return true;
			} catch (...) {
				if (InstallationFailure.HasCaught()) {
					InstallationFailure.ReThrow();
				}

				throw;
			}
		}

		void GetEngineServerConstantsCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kNativeExceptionErrorMessage[] = "engines/server.GetServerConstants() failed with a native C++ exception.";
			constexpr char kContextErrorMessage[] = "engines/server.GetServerConstants() has no active context.";
			constexpr char kServerConstantsCreationErrorMessage[] = "engines/server.GetServerConstants() could not create the constants object.";
			constexpr char kMapLoadTypePropertyName[] = "MapLoadType";
#if defined(SOURCEJS_HAS_QUERY_CVAR_STATUS)
			constexpr char kQueryCVarSuccessPropertyName[] = "Success";
			constexpr char kQueryCVarNotFoundPropertyName[] = "NotFound";
			constexpr char kQueryCVarInvalidPropertyName[] = "Invalid";
			constexpr char kQueryCVarProtectedPropertyName[] = "Protected";
			constexpr char kQueryCVarStatusPropertyName[] = "QueryCVarStatus";
#endif // defined(SOURCEJS_HAS_QUERY_CVAR_STATUS)

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					ThrowError(pIsolate, kContextErrorMessage);
					return;
				}

				v8::Local<v8::Object> const LocalServerConstantsObject = v8::Object::New(pIsolate);
				if (LocalServerConstantsObject.IsEmpty()) {
					ThrowError(pIsolate, kServerConstantsCreationErrorMessage);
					return;
				}

#if defined(SOURCEJS_HAS_QUERY_CVAR_STATUS)
				v8::Local<v8::Object> const LocalQueryCVarStatusObject = v8::Object::New(pIsolate);
				if (LocalQueryCVarStatusObject.IsEmpty()) {
					ThrowError(pIsolate, kServerConstantsCreationErrorMessage);
					return;
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalQueryCVarStatusObject, kQueryCVarSuccessPropertyName, v8::Integer::New(pIsolate, eQueryCvarValueStatus_ValueIntact))) {
					return;
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalQueryCVarStatusObject, kQueryCVarNotFoundPropertyName, v8::Integer::New(pIsolate, eQueryCvarValueStatus_CvarNotFound))) {
					return;
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalQueryCVarStatusObject, kQueryCVarInvalidPropertyName, v8::Integer::New(pIsolate, eQueryCvarValueStatus_NotACvar))) {
					return;
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalQueryCVarStatusObject, kQueryCVarProtectedPropertyName, v8::Integer::New(pIsolate, eQueryCvarValueStatus_CvarProtected))) {
					return;
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalServerConstantsObject, kQueryCVarStatusPropertyName, LocalQueryCVarStatusObject)) {
					return;
				}
#endif // defined(SOURCEJS_HAS_QUERY_CVAR_STATUS)

				// Keep the installer's arbitrary-target setter contract; this fresh result reserves an own data slot.
				if (!SetRecordProperty(pIsolate, LocalContext, LocalServerConstantsObject, kMapLoadTypePropertyName, v8::Undefined(pIsolate))) {
					return;
				}

				if (!InstallMapLoadTypeConstants(pIsolate, LocalContext, LocalServerConstantsObject)) {
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalServerConstantsObject);
			} catch (...) {
				ThrowError(pIsolate, kNativeExceptionErrorMessage);
			}
		}

