		// The optional index output is committed only after the player edict is validated.
		edict_t* RequireMessagePlayerEdict(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Value> const LocalValue, char const* const pszAPIName, int* const pnPlayerIndexOut = nullptr) {
			constexpr char kInvalidPlayerErrorSuffix[] = " requires a valid player edict.";

			if (!pIsolate || LocalContext.IsEmpty() || LocalValue.IsEmpty() || !pszAPIName) {
				return nullptr;
			}

			int nPlayerIndex = 0;
			{
				v8::TryCatch PlayerIndexFailure(pIsolate);
				try {
					nPlayerIndex = GetValueIndex(pIsolate, LocalContext, LocalValue);
					if (PlayerIndexFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						PlayerIndexFailure.ReThrow();
						return nullptr;
					}
				} catch (...) {
					if (PlayerIndexFailure.HasCaught()) {
						PlayerIndexFailure.ReThrow();
					}

					throw;
				}
			}

			auto* const pPlayerEdict = (nPlayerIndex > 0) ? GetEdictFromEntityIndex(nPlayerIndex) : nullptr;
			if ((nPlayerIndex <= 0) || !pPlayerEdict || pPlayerEdict->IsFree()) {
				std::string const strErrorMessage = std::string(pszAPIName) + kInvalidPlayerErrorSuffix;
				ThrowError(pIsolate, strErrorMessage.c_str());
				return nullptr;
			}

			if (pnPlayerIndexOut) {
				*pnPlayerIndexOut = nPlayerIndex;
			}

			return pPlayerEdict;
		}

		void SendMessagesClientConsoleMessageCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kNativeExceptionErrorMessage[] = "messages.SendClientConsoleMessage() failed with a native C++ exception.";
			constexpr int kPlayerOrIndexArgumentIndex = 0;
			constexpr int kMessageArgumentIndex = 1;
			constexpr int kRequiredArgumentCount = kMessageArgumentIndex + 1;
			constexpr char kAPIName[] = "messages.SendClientConsoleMessage()";
			constexpr char kArgumentCountErrorMessage[] = "messages.SendClientConsoleMessage(PlayerOrIndex, strMessage) requires a player index or Index-bearing object and message.";
			constexpr char kMessageTypeErrorMessage[] = "messages.SendClientConsoleMessage(PlayerOrIndex, strMessage) requires a string strMessage.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				auto* const pEngineServer = RequireEngineServer(pIsolate, kAPIName);
				if (!pEngineServer) {
					return;
				}

				if (CallbackInformation.Length() < kRequiredArgumentCount) {
					ThrowError(pIsolate, kArgumentCountErrorMessage);
					return;
				}

				auto* const pPlayerEdict = RequireMessagePlayerEdict(pIsolate, LocalContext, CallbackInformation[kPlayerOrIndexArgumentIndex], kAPIName);
				if (!pPlayerEdict) {
					return;
				}

				v8::Local<v8::Value> const LocalMessageValue = CallbackInformation[kMessageArgumentIndex];
				if (LocalMessageValue.IsEmpty() || !LocalMessageValue->IsString()) {
					ThrowError(pIsolate, kMessageTypeErrorMessage);
					return;
				}

				std::string const strMessage = ValueToString(pIsolate, LocalMessageValue);
				pEngineServer->ClientPrintf(pPlayerEdict, strMessage.c_str());

				CallbackInformation.GetReturnValue().Set(true);
			} catch (...) {
				ThrowError(pIsolate, kNativeExceptionErrorMessage);
			}
		}

		void SendMessagesClientCommandCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kNativeExceptionErrorMessage[] = "messages.SendClientCommand() failed with a native C++ exception.";
			constexpr int kPlayerOrIndexArgumentIndex = 0;
			constexpr int kCommandLineArgumentIndex = 1;
			constexpr int kRequiredArgumentCount = kCommandLineArgumentIndex + 1;
			constexpr char kAPIName[] = "messages.SendClientCommand()";
			constexpr char kArgumentCountErrorMessage[] = "messages.SendClientCommand(PlayerOrIndex, strCommandLine) requires a player index or Index-bearing object and command line.";
			constexpr char kCommandLineTypeErrorMessage[] = "messages.SendClientCommand(PlayerOrIndex, strCommandLine) requires a string strCommandLine.";
			constexpr char kEmptyCommandLineErrorMessage[] = "messages.SendClientCommand(PlayerOrIndex, strCommandLine) requires a non-empty strCommandLine.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				auto* const pEngineServer = RequireEngineServer(pIsolate, kAPIName);
				if (!pEngineServer) {
					return;
				}

				if (CallbackInformation.Length() < kRequiredArgumentCount) {
					ThrowError(pIsolate, kArgumentCountErrorMessage);
					return;
				}

				auto* const pPlayerEdict = RequireMessagePlayerEdict(pIsolate, LocalContext, CallbackInformation[kPlayerOrIndexArgumentIndex], kAPIName);
				if (!pPlayerEdict) {
					return;
				}

				v8::Local<v8::Value> const LocalCommandLineValue = CallbackInformation[kCommandLineArgumentIndex];
				if (LocalCommandLineValue.IsEmpty() || !LocalCommandLineValue->IsString()) {
					ThrowError(pIsolate, kCommandLineTypeErrorMessage);
					return;
				}

				std::string const strCommandLine = ValueToString(pIsolate, LocalCommandLineValue);
				if (strCommandLine.empty()) {
					ThrowError(pIsolate, kEmptyCommandLineErrorMessage);
					return;
				}

				pEngineServer->ClientCommand(pPlayerEdict, "%s", strCommandLine.c_str());

				CallbackInformation.GetReturnValue().Set(true);
			} catch (...) {
				ThrowError(pIsolate, kNativeExceptionErrorMessage);
			}
		}

