		template <typename TEngineServer>
		bf_write* BeginUserMessage(TEngineServer* const pEngineServer, IRecipientFilter* const pRecipientFilter, const int nUserMessageType, char const* const pszUserMessageName) {
			if (!pEngineServer || !pRecipientFilter || (nUserMessageType < 0)) {
				return nullptr;
			}

			if constexpr (UserMessageBeginHasName<TEngineServer>()) {
				if (!pszUserMessageName || !pszUserMessageName[0]) {
					return nullptr;
				}

				return pEngineServer->UserMessageBegin(pRecipientFilter, nUserMessageType, pszUserMessageName);
			} else {
				return pEngineServer->UserMessageBegin(pRecipientFilter, nUserMessageType);
			}
		}

		bool WriteUserMessageBits(bf_write* const pBitBuffer, const std::uint32_t unBitValue, const int nBitCount) {
			constexpr int kMaximumUnsignedIntegerBitCount = 32;

			if (!pBitBuffer || (nBitCount < 0) || (nBitCount > kMaximumUnsignedIntegerBitCount) || (pBitBuffer->GetNumBitsLeft() < nBitCount)) {
				return false;
			}

			// SDK writers can touch storage even for zero bits; keep this a true no-op.
			if (nBitCount == 0) {
				return !pBitBuffer->IsOverflowed();
			}

			const std::uint32_t unMaskedBitValue = (nBitCount == kMaximumUnsignedIntegerBitCount) ? unBitValue : (unBitValue & ((std::uint32_t(1) << nBitCount) - 1));
			pBitBuffer->WriteUBitLong(unMaskedBitValue, nBitCount, false);

			return !pBitBuffer->IsOverflowed();
		}

		bool WriteUserMessageByte(bf_write* const pBitBuffer, const int nByteValue) {
			constexpr int kByteBitCount = 8;

			return WriteUserMessageBits(pBitBuffer, static_cast<std::uint32_t>(static_cast<unsigned char>(nByteValue)), kByteBitCount);
		}

		bool WriteUserMessageShort(bf_write* const pBitBuffer, const int nShortValue) {
			constexpr int kShortBitCount = 16;

			return WriteUserMessageBits(pBitBuffer, static_cast<std::uint32_t>(static_cast<std::uint16_t>(nShortValue)), kShortBitCount);
		}

		bool WriteUserMessageLong(bf_write* const pBitBuffer, const std::int32_t nLongValue) {
			constexpr int kLongBitCount = 32;

			return WriteUserMessageBits(pBitBuffer, static_cast<std::uint32_t>(nLongValue), kLongBitCount);
		}

		bool WriteUserMessageFloat(bf_write* const pBitBuffer, const float flFloatValue) {
			constexpr int kFloatBitCount = 32;

			static_assert(sizeof(float) == sizeof(std::uint32_t), "User-message floats require a 32-bit representation.");
			static_assert(std::numeric_limits<float>::is_iec559, "User-message floats require the SDK's IEEE-754 representation.");

			std::uint32_t unFloatBits = 0;
			std::memcpy(&unFloatBits, &flFloatValue, sizeof(unFloatBits));

			return WriteUserMessageBits(pBitBuffer, unFloatBits, kFloatBitCount);
		}

		bool WriteUserMessageString(bf_write* const pBitBuffer, std::string const& strStringValue) {
			if (!pBitBuffer) {
				return false;
			}

			for (std::size_t unCharacterIndex = 0; unCharacterIndex < strStringValue.size(); ++unCharacterIndex) {
				if (!WriteUserMessageByte(pBitBuffer, static_cast<unsigned char>(strStringValue[unCharacterIndex]))) {
					return false;
				}
			}

			return WriteUserMessageByte(pBitBuffer, 0);
		}

		bool WriteUserMessageField(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, bf_write* const pBitBuffer, v8::Local<v8::Value> const LocalFieldDescriptorValue) {
			constexpr int kUnsignedIntegerBitCount = 32;
			constexpr int kBooleanBitCount = 1;
			constexpr int kMinimumFieldBitCount = 0;
			constexpr int kMaximumFieldBitCount = 32;
			constexpr char kFieldTypeErrorMessage[] = "messages.SendUserMessage() field requires a string type.";

			if (!pIsolate || LocalContext.IsEmpty() || !pBitBuffer) {
				return false;
			}

			if (LocalFieldDescriptorValue.IsEmpty() || !LocalFieldDescriptorValue->IsObject()) {
				ThrowError(pIsolate, "messages.SendUserMessage() fields must contain field objects.");
				return false;
			}

			v8::Local<v8::Object> const LocalFieldDescriptor = LocalFieldDescriptorValue.As<v8::Object>();
			v8::Local<v8::Value> LocalFieldTypeValue {};
			if (!GetMessagesObjectValue(pIsolate, LocalContext, LocalFieldDescriptor, "Type", kFieldTypeErrorMessage, LocalFieldTypeValue)) {
				return false;
			}

			if (!LocalFieldTypeValue->IsString()) {
				ThrowError(pIsolate, kFieldTypeErrorMessage);
				return false;
			}

			std::string const strFieldType = ValueToString(pIsolate, LocalFieldTypeValue);
			v8::Local<v8::Value> LocalFieldValue {};
			if (!GetMessagesObjectValue(pIsolate, LocalContext, LocalFieldDescriptor, "Value", "messages.SendUserMessage() field requires a value.", LocalFieldValue)) {
				return false;
			}

			if (strFieldType == "byte") {
				int nByteValue = 0;
				if (!GetMessagesIntegerFromValue(pIsolate, LocalContext, LocalFieldValue, "messages.SendUserMessage() byte field expects an integer value.", nByteValue)) {
					return false;
				}

				return WriteUserMessageByte(pBitBuffer, nByteValue);
			}

			if (strFieldType == "short") {
				int nShortValue = 0;
				if (!GetMessagesIntegerFromValue(pIsolate, LocalContext, LocalFieldValue, "messages.SendUserMessage() short field expects an integer value.", nShortValue)) {
					return false;
				}

				return WriteUserMessageShort(pBitBuffer, nShortValue);
			}

			if (strFieldType == "int") {
				int nIntegerValue = 0;
				if (!GetMessagesIntegerFromValue(pIsolate, LocalContext, LocalFieldValue, "messages.SendUserMessage() int field expects an integer value.", nIntegerValue)) {
					return false;
				}

				return WriteUserMessageLong(pBitBuffer, nIntegerValue);
			}

			if (strFieldType == "uint") {
				std::uint32_t unUnsignedIntegerValue = 0;
				if (!GetMessagesUnsignedIntegerFromValue(pIsolate, LocalContext, LocalFieldValue, "messages.SendUserMessage() uint field expects an unsigned integer value.", unUnsignedIntegerValue)) {
					return false;
				}

				return WriteUserMessageBits(pBitBuffer, unUnsignedIntegerValue, kUnsignedIntegerBitCount);
			}

			if (strFieldType == "float") {
				float flFloatValue = 0.0F;
				if (!GetMessagesFloatFromValue(pIsolate, LocalContext, LocalFieldValue, "messages.SendUserMessage() float field expects a finite numeric value.", flFloatValue)) {
					return false;
				}

				return WriteUserMessageFloat(pBitBuffer, flFloatValue);
			}

			if (strFieldType == "string") {
				if (!LocalFieldValue->IsString()) {
					ThrowError(pIsolate, "messages.SendUserMessage() string field expects a string value.");
					return false;
				}

				std::string const strStringValue = ValueToString(pIsolate, LocalFieldValue);
				return WriteUserMessageString(pBitBuffer, strStringValue);
			}

			if (strFieldType == "bool") {
				if (!LocalFieldValue->IsBoolean()) {
					ThrowError(pIsolate, "messages.SendUserMessage() bool field expects a boolean value.");
					return false;
				}

				const std::uint32_t unBooleanValue = LocalFieldValue->BooleanValue(pIsolate) ? 1 : 0;
				return WriteUserMessageBits(pBitBuffer, unBooleanValue, kBooleanBitCount);
			}

			if (strFieldType == "bits") {
				v8::Local<v8::Value> LocalFieldBitCountValue {};
				if (!GetMessagesObjectValue(pIsolate, LocalContext, LocalFieldDescriptor, "Bits", "messages.SendUserMessage() bits field expects a bit count.", LocalFieldBitCountValue)) {
					return false;
				}

				int nFieldBitCount = 0;
				if (!GetMessagesIntegerFromValue(pIsolate, LocalContext, LocalFieldBitCountValue, "messages.SendUserMessage() bits field expects an integer bit count.", nFieldBitCount)) {
					return false;
				}

				if ((nFieldBitCount < kMinimumFieldBitCount) || (nFieldBitCount > kMaximumFieldBitCount)) {
					ThrowError(pIsolate, "messages.SendUserMessage() bits field expects bit count between 0 and 32.");
					return false;
				}

				std::uint32_t unFieldBitValue = 0;
				if (!GetMessagesUnsignedIntegerFromValue(pIsolate, LocalContext, LocalFieldValue, "messages.SendUserMessage() bits field expects an unsigned integer value.", unFieldBitValue)) {
					return false;
				}

				return WriteUserMessageBits(pBitBuffer, unFieldBitValue, nFieldBitCount);
			}

			ThrowError(pIsolate, "messages.SendUserMessage() field has an unsupported type.");

			return false;
		}

		bool WriteUserMessageFields(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, bf_write* const pBitBuffer, v8::Local<v8::Array> const LocalUserMessageFields) {
			if (!pIsolate || LocalContext.IsEmpty() || !pBitBuffer || LocalUserMessageFields.IsEmpty()) {
				return false;
			}

			const std::uint32_t unUserMessageFieldCount = LocalUserMessageFields->Length();
			for (std::uint32_t unUserMessageFieldIndex = 0; unUserMessageFieldIndex < unUserMessageFieldCount; ++unUserMessageFieldIndex) {
				v8::Local<v8::Value> LocalFieldDescriptorValue {};
				if (!LocalUserMessageFields->Get(LocalContext, unUserMessageFieldIndex).ToLocal(&LocalFieldDescriptorValue)) {
					return false;
				}

				if (!WriteUserMessageField(pIsolate, LocalContext, pBitBuffer, LocalFieldDescriptorValue)) {
					return false;
				}
			}

			return true;
		}
#endif

