		// Attempts to end a successfully begun bitbuffer message once, including during unwinding.
		class SourceJSUserMessageScope {
		public:
			explicit SourceJSUserMessageScope(IVEngineServer* const pEngineServer) noexcept;
			SourceJSUserMessageScope(SourceJSUserMessageScope const&) = delete;
			SourceJSUserMessageScope(SourceJSUserMessageScope&&) = delete;
			~SourceJSUserMessageScope() noexcept;

		public:
			SourceJSUserMessageScope& operator=(SourceJSUserMessageScope const&) = delete;
			SourceJSUserMessageScope& operator=(SourceJSUserMessageScope&&) = delete;
			void EndUserMessage();

		private:
			IVEngineServer* m_pEngineServer;
		};

		SourceJSUserMessageScope::SourceJSUserMessageScope(IVEngineServer* const pEngineServer) noexcept :
			m_pEngineServer(pEngineServer)
		{
		}

		SourceJSUserMessageScope::~SourceJSUserMessageScope() noexcept {
			try {
				EndUserMessage();
			} catch (...) {
				// Unwinding cleanup must not replace the original callback exception.
			}
		}

		void SourceJSUserMessageScope::EndUserMessage() {
			if (!m_pEngineServer) {
				return;
			}

			auto* const pEngineServer = m_pEngineServer;
			m_pEngineServer = nullptr;
			pEngineServer->MessageEnd();
		}
