		bool ReadMessagesOptionalChatArgument(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, const int nChatArgumentIndex, char const* const pszAPIName, bool& bChatOut) {
			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate || !pszAPIName || (nChatArgumentIndex < 0)) {
				return false;
			}

			if (CallbackInformation.Length() <= nChatArgumentIndex) {
				bChatOut = true;
				return true;
			}

			v8::Local<v8::Value> const LocalChatArgumentValue = CallbackInformation[nChatArgumentIndex];
			if (!LocalChatArgumentValue.IsEmpty() && LocalChatArgumentValue->IsNullOrUndefined()) {
				bChatOut = true;
				return true;
			}

			if (LocalChatArgumentValue.IsEmpty() || !LocalChatArgumentValue->IsBoolean()) {
				std::string const strChatArgumentErrorMessage = std::string(pszAPIName) + " bChatEnabled must be a boolean.";
				ThrowError(pIsolate, strChatArgumentErrorMessage.c_str());
				return false;
			}

			bChatOut = LocalChatArgumentValue->BooleanValue(pIsolate);

			return true;
		}

		void SendMessagesSayTextMessageCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kNativeExceptionErrorMessage[] = "messages.SendSayTextMessage() failed with a native C++ exception.";
			constexpr int kPlayerIndexArgumentIndex = 0;
			constexpr int kMessageTextArgumentIndex = 1;
			constexpr int kSenderIndexArgumentIndex = 2;
			constexpr int kChatArgumentIndex = 3;
			constexpr int kMinimumSayTextArgumentCount = kMessageTextArgumentIndex + 1;
			constexpr int kDefaultSenderIndex = 0;
			constexpr char kSendSayTextMessageAPIName[] = "messages.SendSayTextMessage()";
			constexpr char kSendSayTextMessageArgumentsErrorMessage[] = "messages.SendSayTextMessage(PlayerOrIndex, strMessageText, SenderOrIndex?, bChatEnabled?) requires a player index and message.";
			constexpr char kSayTextUserMessageName[] = "SayText";
			constexpr char kBeginSayTextErrorMessage[] = "messages.SendSayTextMessage() failed to begin SayText.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				auto* const pEngineServer = RequireEngineServer(pIsolate, kSendSayTextMessageAPIName);
				if (!pEngineServer) {
					return;
				}

				if (CallbackInformation.Length() < kMinimumSayTextArgumentCount) {
					ThrowError(pIsolate, kSendSayTextMessageArgumentsErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalPlayerIndexValue = CallbackInformation[kPlayerIndexArgumentIndex];
				v8::Local<v8::Value> const LocalMessageTextValue = CallbackInformation[kMessageTextArgumentIndex];
				if (LocalPlayerIndexValue.IsEmpty() || LocalMessageTextValue.IsEmpty() || !LocalMessageTextValue->IsString()) {
					ThrowError(pIsolate, kSendSayTextMessageArgumentsErrorMessage);
					return;
				}

				int nPlayerIndex = 0;
				if (!RequireMessagePlayerEdict(pIsolate, LocalContext, LocalPlayerIndexValue, kSendSayTextMessageAPIName, &nPlayerIndex)) {
					return;
				}

				const int nUserMessageType = RequireUserMessageType(pIsolate, kSendSayTextMessageAPIName, kSayTextUserMessageName);
				if (nUserMessageType < 0) {
					return;
				}

				std::string strMessageText = ValueToString(pIsolate, LocalMessageTextValue);
				int nSenderIndex = kDefaultSenderIndex;

				if (CallbackInformation.Length() > kSenderIndexArgumentIndex) {
					v8::Local<v8::Value> const LocalSenderIndexValue = CallbackInformation[kSenderIndexArgumentIndex];
					if (LocalSenderIndexValue.IsEmpty()) {
						ThrowError(pIsolate, kSendSayTextMessageArgumentsErrorMessage);
						return;
					}

					v8::TryCatch SenderIndexFailure(pIsolate);
					try {
						nSenderIndex = GetValueIndex(pIsolate, LocalContext, LocalSenderIndexValue);
						if (SenderIndexFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
							SenderIndexFailure.ReThrow();
							return;
						}
					} catch (...) {
						if (SenderIndexFailure.HasCaught()) {
							SenderIndexFailure.ReThrow();
						}

						throw;
					}
				}

				bool bChat = true;
				if (!ReadMessagesOptionalChatArgument(CallbackInformation, kChatArgumentIndex, kSendSayTextMessageAPIName, bChat)) {
					return;
				}

				if (bChat && (strMessageText.find('\n') == std::string::npos)) {
					strMessageText += "\x01\n";
				}

				std::vector<int> vecRecipientEntityIndices = { nPlayerIndex };
				SourceJSUserMessageRecipientFilter UserMessageRecipientFilter = SourceJSUserMessageRecipientFilter(vecRecipientEntityIndices, true);
				auto* const pBitBuffer = BeginUserMessage(pEngineServer, &UserMessageRecipientFilter, nUserMessageType, kSayTextUserMessageName);
				if (!pBitBuffer) {
					ThrowError(pIsolate, kBeginSayTextErrorMessage);
					return;
				}

				SourceJSUserMessageScope UserMessageScope(pEngineServer);
				const int nSerializedSenderIndex = (nSenderIndex > 0) ? nSenderIndex : 0;
				const int nSerializedChatValue = bChat ? 1 : 0;
				bool bSayTextWriteSucceeded = WriteUserMessageByte(pBitBuffer, nSerializedSenderIndex);

				if (bSayTextWriteSucceeded) {
					bSayTextWriteSucceeded = WriteUserMessageString(pBitBuffer, strMessageText);
				}

				if (bSayTextWriteSucceeded) {
					bSayTextWriteSucceeded = WriteUserMessageByte(pBitBuffer, nSerializedChatValue);
				}

				UserMessageScope.EndUserMessage();

				CallbackInformation.GetReturnValue().Set(bSayTextWriteSucceeded);
			} catch (...) {
				if (!pIsolate->IsExecutionTerminating() && !pIsolate->HasPendingException()) {
					ThrowError(pIsolate, kNativeExceptionErrorMessage);
				}
			}
		}

