		std::string StripMessagesSayText2ColorCodes(std::string const& strMessage) {
			constexpr unsigned char kFirstColorCode = 0x01;
			constexpr unsigned char kLastColorCode = 0x10;

			std::string strMessageWithoutColorCodes {};
			strMessageWithoutColorCodes.reserve(strMessage.size());

			for (std::size_t unIndex = 0; unIndex < strMessage.size(); ++unIndex) {
				const unsigned char unColorCode = static_cast<unsigned char>(strMessage[unIndex]);
				if ((unColorCode >= kFirstColorCode) && (unColorCode <= kLastColorCode)) {
					continue;
				}

				strMessageWithoutColorCodes.push_back(strMessage[unIndex]);
			}

			return strMessageWithoutColorCodes;
		}

