		bool GetMessagesColorComponentFromValue(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Value> const LocalColorComponentValue, char const* const pszColorComponentTypeErrorMessage, int& nColorComponentOut) {
			constexpr int kMinimumColorComponent = 0;
			constexpr int kMaximumColorComponent = 255;
			constexpr char kColorComponentRangeErrorMessage[] = "messages.CreateDialog() Color components must be between 0 and 255.";

			if (!pIsolate || LocalContext.IsEmpty() || LocalColorComponentValue.IsEmpty() || !pszColorComponentTypeErrorMessage) {
				return false;
			}

			int nColorComponent = 0;
			if (!GetMessagesIntegerFromValue(pIsolate, LocalContext, LocalColorComponentValue, pszColorComponentTypeErrorMessage, nColorComponent)) {
				return false;
			}

			if ((nColorComponent < kMinimumColorComponent) || (nColorComponent > kMaximumColorComponent)) {
				ThrowError(pIsolate, kColorComponentRangeErrorMessage);
				return false;
			}

			nColorComponentOut = nColorComponent;

			return true;
		}

		bool GetMessagesColorArrayComponent(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Array> const LocalColorArray, const std::uint32_t unColorComponentIndex, const bool bIsColorComponentRequired, const int nDefaultColorComponentValue, int& nColorComponentOut) {
			constexpr char kRequiredColorComponentsErrorMessage[] = "messages.CreateDialog() Color expects red, green, and blue integer components.";
			constexpr char kIntegerColorComponentErrorMessage[] = "messages.CreateDialog() Color expects integer components.";

			if (!pIsolate || LocalContext.IsEmpty() || LocalColorArray.IsEmpty()) {
				return false;
			}

			v8::Local<v8::Value> LocalColorComponentValue {};
			{
				v8::TryCatch ColorComponentFailure(pIsolate);
				try {
					const bool bHasColorComponent = LocalColorArray->Get(LocalContext, unColorComponentIndex).ToLocal(&LocalColorComponentValue);
					if (!bHasColorComponent || ColorComponentFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						if (bIsColorComponentRequired && !ColorComponentFailure.HasCaught() && !pIsolate->IsExecutionTerminating() && !pIsolate->HasPendingException()) {
							ThrowError(pIsolate, kRequiredColorComponentsErrorMessage);
						}

						ColorComponentFailure.ReThrow();
						return false;
					}
				} catch (...) {
					if (ColorComponentFailure.HasCaught()) {
						ColorComponentFailure.ReThrow();
					}

					throw;
				}
			}

			if (IsValueNullish(LocalColorComponentValue)) {
				if (!bIsColorComponentRequired) {
					nColorComponentOut = nDefaultColorComponentValue;
					return true;
				}

				ThrowError(pIsolate, kRequiredColorComponentsErrorMessage);
				return false;
			}

			return GetMessagesColorComponentFromValue(pIsolate, LocalContext, LocalColorComponentValue, kIntegerColorComponentErrorMessage, nColorComponentOut);
		}

		bool GetMessagesColorObjectComponent(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalColorObject, char const* const pszColorComponentPropertyName, const bool bIsColorComponentRequired, const int nDefaultColorComponentValue, int& nColorComponentOut) {
			constexpr char kRequiredColorComponentsErrorMessage[] = "messages.CreateDialog() Color expects red, green, and blue integer components.";
			constexpr char kIntegerColorComponentErrorMessage[] = "messages.CreateDialog() Color expects integer components.";

			if (!pIsolate || LocalContext.IsEmpty() || LocalColorObject.IsEmpty() || !pszColorComponentPropertyName) {
				return false;
			}

			v8::Local<v8::String> const LocalColorComponentPropertyName = MakeString(pIsolate, pszColorComponentPropertyName);
			if (LocalColorComponentPropertyName.IsEmpty()) {
				return false;
			}

			v8::Local<v8::Value> LocalColorComponentValue {};
			{
				v8::TryCatch ColorComponentFailure(pIsolate);
				try {
					const bool bHasColorComponent = LocalColorObject->Get(LocalContext, LocalColorComponentPropertyName).ToLocal(&LocalColorComponentValue);
					if (!bHasColorComponent || ColorComponentFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						if (bIsColorComponentRequired && !ColorComponentFailure.HasCaught() && !pIsolate->IsExecutionTerminating() && !pIsolate->HasPendingException()) {
							ThrowError(pIsolate, kRequiredColorComponentsErrorMessage);
						}

						ColorComponentFailure.ReThrow();
						return false;
					}
				} catch (...) {
					if (ColorComponentFailure.HasCaught()) {
						ColorComponentFailure.ReThrow();
					}

					throw;
				}
			}

			if (IsValueNullish(LocalColorComponentValue)) {
				if (!bIsColorComponentRequired) {
					nColorComponentOut = nDefaultColorComponentValue;
					return true;
				}

				ThrowError(pIsolate, kRequiredColorComponentsErrorMessage);
				return false;
			}

			return GetMessagesColorComponentFromValue(pIsolate, LocalContext, LocalColorComponentValue, kIntegerColorComponentErrorMessage, nColorComponentOut);
		}

		bool GetMessagesColorStringFromValue(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Value> const LocalColorValue, std::string& strColorStringOut) {
			constexpr std::uint32_t kRedColorComponentIndex = 0;
			constexpr std::uint32_t kGreenColorComponentIndex = 1;
			constexpr std::uint32_t kBlueColorComponentIndex = 2;
			constexpr std::uint32_t kAlphaColorComponentIndex = 3;
			constexpr int kMinimumColorComponent = 0;
			constexpr int kMaximumColorComponent = 255;
			constexpr char kRedColorComponentPropertyName[] = "Red";
			constexpr char kGreenColorComponentPropertyName[] = "Green";
			constexpr char kBlueColorComponentPropertyName[] = "Blue";
			constexpr char kAlphaColorComponentPropertyName[] = "Alpha";
			constexpr char kColorTypeErrorMessage[] = "messages.CreateDialog() Color expects an array or object.";

			if (!pIsolate || LocalContext.IsEmpty() || LocalColorValue.IsEmpty()) {
				return false;
			}

			int nRedColorComponent = kMinimumColorComponent;
			int nGreenColorComponent = kMinimumColorComponent;
			int nBlueColorComponent = kMinimumColorComponent;
			int nAlphaColorComponent = kMaximumColorComponent;

			if (LocalColorValue->IsArray()) {
				v8::Local<v8::Array> const LocalColorArray = LocalColorValue.As<v8::Array>();
				if (LocalColorArray.IsEmpty()) {
					return false;
				}

				if (!GetMessagesColorArrayComponent(pIsolate, LocalContext, LocalColorArray, kRedColorComponentIndex, true, kMinimumColorComponent, nRedColorComponent)) {
					return false;
				}

				if (!GetMessagesColorArrayComponent(pIsolate, LocalContext, LocalColorArray, kGreenColorComponentIndex, true, kMinimumColorComponent, nGreenColorComponent)) {
					return false;
				}

				if (!GetMessagesColorArrayComponent(pIsolate, LocalContext, LocalColorArray, kBlueColorComponentIndex, true, kMinimumColorComponent, nBlueColorComponent)) {
					return false;
				}

				if (!GetMessagesColorArrayComponent(pIsolate, LocalContext, LocalColorArray, kAlphaColorComponentIndex, false, kMaximumColorComponent, nAlphaColorComponent)) {
					return false;
				}

			} else if (LocalColorValue->IsObject()) {
				v8::Local<v8::Object> const LocalColorObject = LocalColorValue.As<v8::Object>();
				if (LocalColorObject.IsEmpty()) {
					return false;
				}

				if (!GetMessagesColorObjectComponent(pIsolate, LocalContext, LocalColorObject, kRedColorComponentPropertyName, true, kMinimumColorComponent, nRedColorComponent)) {
					return false;
				}

				if (!GetMessagesColorObjectComponent(pIsolate, LocalContext, LocalColorObject, kGreenColorComponentPropertyName, true, kMinimumColorComponent, nGreenColorComponent)) {
					return false;
				}

				if (!GetMessagesColorObjectComponent(pIsolate, LocalContext, LocalColorObject, kBlueColorComponentPropertyName, true, kMinimumColorComponent, nBlueColorComponent)) {
					return false;
				}

				if (!GetMessagesColorObjectComponent(pIsolate, LocalContext, LocalColorObject, kAlphaColorComponentPropertyName, false, kMaximumColorComponent, nAlphaColorComponent)) {
					return false;
				}

			} else {
				ThrowError(pIsolate, kColorTypeErrorMessage);
				return false;
			}

			std::ostringstream ColorStringStream {};

			ColorStringStream << nRedColorComponent << ' ' << nGreenColorComponent << ' ' << nBlueColorComponent << ' ' << nAlphaColorComponent;

			strColorStringOut = ColorStringStream.str();

			return true;
		}

		bool IsValidMessagesKeyValuesFieldName(std::string const& strFieldName) {
			return !strFieldName.empty() && (strFieldName.find('\0') == std::string::npos) && (strFieldName.find('/') == std::string::npos);
		}

		bool SetMessagesKeyValuesFromObject(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, KeyValues* const pKeyValues, v8::Local<v8::Object> const LocalFieldsObject, const std::size_t unNestedDepth = 0) {
			constexpr std::size_t kMaximumNestedDepth = 32;
			constexpr char kDialogFieldDepthErrorMessage[] = "messages.CreateDialog() nested fields exceed the maximum object depth of 32.";
			constexpr char kReadDialogFieldValueErrorMessage[] = "messages.CreateDialog() failed to read a field value.";
			constexpr char kEnumerateDialogFieldsErrorMessage[] = "messages.CreateDialog() failed to enumerate fields.";
			constexpr char kReadDialogFieldNameErrorMessage[] = "messages.CreateDialog() failed to read a field name.";
			constexpr char kInvalidDialogFieldNameErrorMessage[] = "messages.CreateDialog() field names must be non-empty and must not contain NUL or KeyValues path separators.";
			constexpr char kDialogColorFieldName[] = "Color";
			constexpr char kDialogIntegerFieldValueErrorMessage[] = "messages.CreateDialog() integer fields require integer values.";
			constexpr char kDialogNumericFieldValueErrorMessage[] = "messages.CreateDialog() numeric fields require finite numeric values.";
			constexpr bool kCreateNestedDialogField = true;
			constexpr char kCreateNestedDialogFieldErrorMessage[] = "messages.CreateDialog() failed to create a nested field.";
			constexpr char kUnsupportedDialogFieldValueErrorMessage[] = "messages.CreateDialog() fields must be strings, finite numbers, booleans, colors, or nested objects.";

			if (!pIsolate || LocalContext.IsEmpty() || !pKeyValues || LocalFieldsObject.IsEmpty()) {
				return false;
			}

			if (unNestedDepth > kMaximumNestedDepth) {
				ThrowError(pIsolate, kDialogFieldDepthErrorMessage);
				return false;
			}

			v8::Local<v8::Array> LocalFieldPropertyNames {};
			{
				v8::TryCatch FieldEnumerationFailure(pIsolate);
				try {
					if (!LocalFieldsObject->GetOwnPropertyNames(LocalContext).ToLocal(&LocalFieldPropertyNames) || FieldEnumerationFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						if (!FieldEnumerationFailure.HasCaught() && !pIsolate->IsExecutionTerminating() && !pIsolate->HasPendingException()) {
							ThrowError(pIsolate, kEnumerateDialogFieldsErrorMessage);
						}

						FieldEnumerationFailure.ReThrow();
						return false;
					}
				} catch (...) {
					if (FieldEnumerationFailure.HasCaught()) {
						FieldEnumerationFailure.ReThrow();
					}

					throw;
				}
			}

			if (LocalFieldPropertyNames.IsEmpty()) {
				return false;
			}

			const std::uint32_t unFieldPropertyCount = LocalFieldPropertyNames->Length();
			for (std::uint32_t unFieldPropertyIndex = 0; unFieldPropertyIndex < unFieldPropertyCount; ++unFieldPropertyIndex) {
				v8::Local<v8::Value> LocalFieldPropertyNameValue {};
				{
					v8::TryCatch FieldNameFailure(pIsolate);
					try {
						if (!LocalFieldPropertyNames->Get(LocalContext, unFieldPropertyIndex).ToLocal(&LocalFieldPropertyNameValue) || FieldNameFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
							if (!FieldNameFailure.HasCaught() && !pIsolate->IsExecutionTerminating() && !pIsolate->HasPendingException()) {
								ThrowError(pIsolate, kReadDialogFieldNameErrorMessage);
							}

							FieldNameFailure.ReThrow();
							return false;
						}
					} catch (...) {
						if (FieldNameFailure.HasCaught()) {
							FieldNameFailure.ReThrow();
						}

						throw;
					}
				}

				if (LocalFieldPropertyNameValue.IsEmpty()) {
					return false;
				}

				std::string const strFieldName = ValueToString(pIsolate, LocalFieldPropertyNameValue);
				v8::Local<v8::Value> LocalFieldValue {};
				{
					v8::TryCatch FieldValueFailure(pIsolate);
					try {
						const bool bHasFieldValue = LocalFieldsObject->Get(LocalContext, LocalFieldPropertyNameValue).ToLocal(&LocalFieldValue);
						if (!bHasFieldValue || FieldValueFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
							if (!FieldValueFailure.HasCaught() && !pIsolate->IsExecutionTerminating() && !pIsolate->HasPendingException()) {
								ThrowError(pIsolate, kReadDialogFieldValueErrorMessage);
							}

							FieldValueFailure.ReThrow();
							return false;
						}
					} catch (...) {
						if (FieldValueFailure.HasCaught()) {
							FieldValueFailure.ReThrow();
						}

						throw;
					}
				}

				if (IsValueNullish(LocalFieldValue)) {
					continue;
				}

				if (!IsValidMessagesKeyValuesFieldName(strFieldName)) {
					ThrowError(pIsolate, kInvalidDialogFieldNameErrorMessage);
					return false;
				}

				if (strFieldName == kDialogColorFieldName) {
					std::string strDialogColorString {};
					if (!GetMessagesColorStringFromValue(pIsolate, LocalContext, LocalFieldValue, strDialogColorString)) {
						return false;
					}

					pKeyValues->SetString(strFieldName.c_str(), strDialogColorString.c_str());
					continue;
				}

				if (LocalFieldValue->IsBoolean()) {
					const int nDialogBooleanFieldValue = LocalFieldValue->BooleanValue(pIsolate) ? 1 : 0;
					pKeyValues->SetInt(strFieldName.c_str(), nDialogBooleanFieldValue);
					continue;
				}

				if (LocalFieldValue->IsInt32()) {
					int nDialogIntegerFieldValue = 0;
					if (!GetMessagesIntegerFromValue(pIsolate, LocalContext, LocalFieldValue, kDialogIntegerFieldValueErrorMessage, nDialogIntegerFieldValue)) {
						return false;
					}

					pKeyValues->SetInt(strFieldName.c_str(), nDialogIntegerFieldValue);
					continue;
				}

				if (LocalFieldValue->IsNumber()) {
					double dblDialogNumericFieldValue = 0.0;
					if (!GetMessagesNumberFromValue(pIsolate, LocalContext, LocalFieldValue, kDialogNumericFieldValueErrorMessage, dblDialogNumericFieldValue)) {
						return false;
					}

					std::ostringstream DialogNumericFieldValueStream {};

					DialogNumericFieldValueStream << dblDialogNumericFieldValue;

					std::string const strDialogNumericFieldValue = DialogNumericFieldValueStream.str();
					pKeyValues->SetString(strFieldName.c_str(), strDialogNumericFieldValue.c_str());
					continue;
				}

				if (LocalFieldValue->IsObject() && !LocalFieldValue->IsArray()) {
					v8::Local<v8::Object> const LocalNestedDialogFieldsObject = LocalFieldValue.As<v8::Object>();
					if (LocalNestedDialogFieldsObject.IsEmpty()) {
						return false;
					}

					auto* const pNestedDialogKeyValues = pKeyValues->FindKey(strFieldName.c_str(), kCreateNestedDialogField);
					if (!pNestedDialogKeyValues) {
						ThrowError(pIsolate, kCreateNestedDialogFieldErrorMessage);
						return false;
					}

					if (!SetMessagesKeyValuesFromObject(pIsolate, LocalContext, pNestedDialogKeyValues, LocalNestedDialogFieldsObject, unNestedDepth + 1)) {
						return false;
					}

					continue;
				}

				if (!LocalFieldValue->IsString()) {
					ThrowError(pIsolate, kUnsupportedDialogFieldValueErrorMessage);
					return false;
				}

				std::string const strDialogFieldValue = ValueToString(pIsolate, LocalFieldValue);
				pKeyValues->SetString(strFieldName.c_str(), strDialogFieldValue.c_str());
			}

			return true;
		}

		// Retain client identity, not a borrowed edict, while JavaScript inputs are read.
		struct MessagesRecipientIdentity {
			int m_nPlayerIndex;
			int m_nPlayerUserID;
		};

		constexpr int kInvalidMessagesPlayerUserID = -1;

		bool CaptureMessagesRecipientIdentity(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Value> const LocalPlayerValue, char const* const pszAPIName, MessagesRecipientIdentity& RecipientIdentityOut) {
			constexpr char kConnectedPlayerErrorSuffix[] = " requires a connected player.";

			if (!pIsolate || LocalContext.IsEmpty() || LocalPlayerValue.IsEmpty() || !pszAPIName) {
				return false;
			}

			int nPlayerIndex = 0;
			auto* const pPlayerEdict = RequireMessagePlayerEdict(pIsolate, LocalContext, LocalPlayerValue, pszAPIName, &nPlayerIndex);
			if (!pPlayerEdict) {
				return false;
			}

			auto* const pEngineServer = RequireEngineServer(pIsolate, pszAPIName);
			if (!pEngineServer) {
				return false;
			}

			const int nPlayerUserID = pEngineServer->GetPlayerUserId(pPlayerEdict);
			if (nPlayerUserID == kInvalidMessagesPlayerUserID) {
				std::string const strErrorMessage = std::string(pszAPIName) + kConnectedPlayerErrorSuffix;
				ThrowError(pIsolate, strErrorMessage.c_str());
				return false;
			}

			RecipientIdentityOut.m_nPlayerIndex = nPlayerIndex;
			RecipientIdentityOut.m_nPlayerUserID = nPlayerUserID;

			return true;
		}

		edict_t* RequireMessagesRecipientEdict(v8::Isolate* const pIsolate, MessagesRecipientIdentity const& RecipientIdentity, char const* const pszAPIName) {
			constexpr char kChangedRecipientErrorSuffix[] = " recipient is no longer the same connected player.";

			if (!pIsolate || !pszAPIName || (RecipientIdentity.m_nPlayerIndex <= 0) || (RecipientIdentity.m_nPlayerUserID == kInvalidMessagesPlayerUserID)) {
				return nullptr;
			}

			auto* const pEngineServer = RequireEngineServer(pIsolate, pszAPIName);
			if (!pEngineServer) {
				return nullptr;
			}

			// Resolve again only after the final getter/coercion; never touch the old edict.
			auto* const pPlayerEdict = GetEdictFromEntityIndex(RecipientIdentity.m_nPlayerIndex);
			if (!pPlayerEdict || pPlayerEdict->IsFree() || (pEngineServer->GetPlayerUserId(pPlayerEdict) != RecipientIdentity.m_nPlayerUserID)) {
				std::string const strErrorMessage = std::string(pszAPIName) + kChangedRecipientErrorSuffix;
				ThrowError(pIsolate, strErrorMessage.c_str());
				return nullptr;
			}

			return pPlayerEdict;
		}

		void CreateMessagesDialogCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kNativeExceptionErrorMessage[] = "messages.CreateDialog() failed with a native C++ exception.";
			constexpr int kDialogPlayerArgumentIndex = 0;
			constexpr int kDialogTypeArgumentIndex = 1;
			constexpr int kDialogFieldsArgumentIndex = 2;
			constexpr int kDialogNameArgumentIndex = 3;
			constexpr int kMinimumCreateDialogArgumentCount = kDialogFieldsArgumentIndex + 1;
			constexpr char kDefaultDialogName[] = "menu";
			constexpr char kCreateDialogAPIName[] = "messages.CreateDialog()";
			constexpr char kCreateDialogArgumentsErrorMessage[] = "messages.CreateDialog(PlayerOrIndex, nDialogType, DialogFields, strDialogName?) requires a player index, dialog type, and DialogFields object.";
			constexpr char kDialogFieldsErrorMessage[] = "messages.CreateDialog(PlayerOrIndex, nDialogType, DialogFields, strDialogName?) expects DialogFields to be an object.";
			constexpr char kDialogTypeErrorMessage[] = "messages.CreateDialog(PlayerOrIndex, nDialogType, DialogFields, strDialogName?) expects nDialogType to be an integer.";
			constexpr char kDialogTypeRangeErrorMessage[] = "messages.CreateDialog(PlayerOrIndex, nDialogType, DialogFields, strDialogName?) received a dialog type not declared by the selected Source SDK branch.";
			constexpr char kDialogNameErrorMessage[] = "messages.CreateDialog(PlayerOrIndex, nDialogType, DialogFields, strDialogName?) expects strDialogName to be a string.";
#if defined(SOURCEJS_OLD_CONSOLE_API)
			constexpr int kLastDialogType = DIALOG_ENTRY;
#else
			constexpr int kLastDialogType = DIALOG_ASKCONNECT;
#endif

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				auto* const pDialogServerPluginHelpers = RequireServerPluginHelpers(pIsolate, kCreateDialogAPIName);
				if (!pDialogServerPluginHelpers) {
					return;
				}

				if (CallbackInformation.Length() < kMinimumCreateDialogArgumentCount) {
					ThrowError(pIsolate, kCreateDialogArgumentsErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalDialogPlayerValue = CallbackInformation[kDialogPlayerArgumentIndex];
				v8::Local<v8::Value> const LocalDialogTypeValue = CallbackInformation[kDialogTypeArgumentIndex];
				v8::Local<v8::Value> const LocalDialogFieldsValue = CallbackInformation[kDialogFieldsArgumentIndex];
				if (LocalDialogPlayerValue.IsEmpty() || LocalDialogTypeValue.IsEmpty()) {
					ThrowError(pIsolate, kCreateDialogArgumentsErrorMessage);
					return;
				}

				if (LocalDialogFieldsValue.IsEmpty() || !LocalDialogFieldsValue->IsObject() || LocalDialogFieldsValue->IsArray()) {
					ThrowError(pIsolate, kDialogFieldsErrorMessage);
					return;
				}

				MessagesRecipientIdentity DialogRecipientIdentity {};
				if (!CaptureMessagesRecipientIdentity(pIsolate, LocalContext, LocalDialogPlayerValue, kCreateDialogAPIName, DialogRecipientIdentity)) {
					return;
				}

				int nDialogType = 0;
				if (!GetMessagesIntegerFromValue(pIsolate, LocalContext, LocalDialogTypeValue, kDialogTypeErrorMessage, nDialogType)) {
					return;
				}

				if ((nDialogType < DIALOG_MSG) || (nDialogType > kLastDialogType)) {
					ThrowError(pIsolate, kDialogTypeRangeErrorMessage);
					return;
				}

				if (!RequireKeyValuesSystem(pIsolate, kCreateDialogAPIName)) {
					return;
				}

				std::string strDialogName = kDefaultDialogName;
				if (CallbackInformation.Length() > kDialogNameArgumentIndex) {
					v8::Local<v8::Value> const LocalDialogNameValue = CallbackInformation[kDialogNameArgumentIndex];
					if (LocalDialogNameValue.IsEmpty()) {
						ThrowError(pIsolate, kDialogNameErrorMessage);
						return;
					}

					const bool bHasDialogName = !LocalDialogNameValue->IsNullOrUndefined();
					if (bHasDialogName && !LocalDialogNameValue->IsString()) {
						ThrowError(pIsolate, kDialogNameErrorMessage);
						return;
					}

					if (bHasDialogName) {
						strDialogName = ValueToString(pIsolate, LocalDialogNameValue);
					}
				}

				if (strDialogName.empty()) {
					strDialogName = kDefaultDialogName;
				}

				v8::Local<v8::Object> const LocalDialogFieldsObject = LocalDialogFieldsValue.As<v8::Object>();
				if (LocalDialogFieldsObject.IsEmpty()) {
					return;
				}

				SourceJSKeyValuesOwner pDialogKeyValues(new KeyValues(strDialogName.c_str()));
				if (!pDialogKeyValues) {
					return;
				}

				if (!SetMessagesKeyValuesFromObject(pIsolate, LocalContext, pDialogKeyValues.get(), LocalDialogFieldsObject)) {
					return;
				}

				auto* const pDialogPlayerEdict = RequireMessagesRecipientEdict(pIsolate, DialogRecipientIdentity, kCreateDialogAPIName);
				if (!pDialogPlayerEdict) {
					return;
				}

				pDialogServerPluginHelpers->CreateMessage(pDialogPlayerEdict, static_cast<DIALOG_TYPE>(nDialogType), pDialogKeyValues.get(), &g_SourceJSPlugin);

				pDialogKeyValues.reset();

				CallbackInformation.GetReturnValue().Set(true);
			} catch (...) {
				if (!pIsolate->IsExecutionTerminating() && !pIsolate->HasPendingException()) {
					ThrowError(pIsolate, kNativeExceptionErrorMessage);
				}
			}
		}

		void ShowMenusTextCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kNativeExceptionErrorMessage[] = "menus.ShowText() failed with a native C++ exception.";
			constexpr int kMenuPlayerArgumentIndex = 0;
			constexpr int kMenuTitleArgumentIndex = 1;
			constexpr int kMenuMessageArgumentIndex = 2;
			constexpr int kMenuDisplayTimeArgumentIndex = 3;
			constexpr int kMinimumShowTextArgumentCount = kMenuMessageArgumentIndex + 1;
			constexpr int kDefaultMenuDisplayTime = 10;
			constexpr int kMenuLevel = 1;
			constexpr char kMenuKeyValuesName[] = "menu";
			constexpr char kMenuTitleFieldName[] = "title";
			constexpr char kMenuMessageFieldName[] = "msg";
			constexpr char kMenuLevelFieldName[] = "level";
			constexpr char kMenuDisplayTimeFieldName[] = "time";
			constexpr char kShowTextAPIName[] = "menus.ShowText()";
			constexpr char kShowTextArgumentsErrorMessage[] = "menus.ShowText(PlayerOrIndex, strMenuTitle, strMenuMessage, nMenuDisplayTime?) requires a player index, title, and message.";
			constexpr char kMenuDisplayTimeErrorMessage[] = "menus.ShowText(PlayerOrIndex, strMenuTitle, strMenuMessage, nMenuDisplayTime?) expects nMenuDisplayTime to be an integer.";
			constexpr char kMenuDisplayTimeRangeErrorMessage[] = "menus.ShowText(PlayerOrIndex, strMenuTitle, strMenuMessage, nMenuDisplayTime?) expects nMenuDisplayTime to be non-negative.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				auto* const pMenuServerPluginHelpers = RequireServerPluginHelpers(pIsolate, kShowTextAPIName);
				if (!pMenuServerPluginHelpers) {
					return;
				}

				if (CallbackInformation.Length() < kMinimumShowTextArgumentCount) {
					ThrowError(pIsolate, kShowTextArgumentsErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalMenuPlayerValue = CallbackInformation[kMenuPlayerArgumentIndex];
				v8::Local<v8::Value> const LocalMenuTitleValue = CallbackInformation[kMenuTitleArgumentIndex];
				v8::Local<v8::Value> const LocalMenuMessageValue = CallbackInformation[kMenuMessageArgumentIndex];
				if (LocalMenuPlayerValue.IsEmpty() || LocalMenuTitleValue.IsEmpty() || LocalMenuMessageValue.IsEmpty() || !LocalMenuTitleValue->IsString() || !LocalMenuMessageValue->IsString()) {
					ThrowError(pIsolate, kShowTextArgumentsErrorMessage);
					return;
				}

				MessagesRecipientIdentity MenuRecipientIdentity {};
				if (!CaptureMessagesRecipientIdentity(pIsolate, LocalContext, LocalMenuPlayerValue, kShowTextAPIName, MenuRecipientIdentity)) {
					return;
				}

				std::string const strMenuTitle = ValueToString(pIsolate, LocalMenuTitleValue);
				std::string const strMenuMessage = ValueToString(pIsolate, LocalMenuMessageValue);
				int nMenuDisplayTime = kDefaultMenuDisplayTime;
				if (CallbackInformation.Length() > kMenuDisplayTimeArgumentIndex) {
					v8::Local<v8::Value> const LocalMenuDisplayTimeValue = CallbackInformation[kMenuDisplayTimeArgumentIndex];
					if (LocalMenuDisplayTimeValue.IsEmpty()) {
						ThrowError(pIsolate, kMenuDisplayTimeErrorMessage);
						return;
					}

					if (!GetMessagesIntegerFromValue(pIsolate, LocalContext, LocalMenuDisplayTimeValue, kMenuDisplayTimeErrorMessage, nMenuDisplayTime)) {
						return;
					}
				}

				if (nMenuDisplayTime < 0) {
					ThrowError(pIsolate, kMenuDisplayTimeRangeErrorMessage);
					return;
				}

				if (!RequireKeyValuesSystem(pIsolate, kShowTextAPIName)) {
					return;
				}

				SourceJSKeyValuesOwner pMenuKeyValues(new KeyValues(kMenuKeyValuesName));
				if (!pMenuKeyValues) {
					return;
				}

				pMenuKeyValues->SetString(kMenuTitleFieldName, strMenuTitle.c_str());
				pMenuKeyValues->SetString(kMenuMessageFieldName, strMenuMessage.c_str());
				pMenuKeyValues->SetInt(kMenuLevelFieldName, kMenuLevel);
				pMenuKeyValues->SetInt(kMenuDisplayTimeFieldName, nMenuDisplayTime);

				auto* const pMenuPlayerEdict = RequireMessagesRecipientEdict(pIsolate, MenuRecipientIdentity, kShowTextAPIName);
				if (!pMenuPlayerEdict) {
					return;
				}

				pMenuServerPluginHelpers->CreateMessage(pMenuPlayerEdict, DIALOG_TEXT, pMenuKeyValues.get(), &g_SourceJSPlugin);

				pMenuKeyValues.reset();

				CallbackInformation.GetReturnValue().Set(true);
			} catch (...) {
				if (!pIsolate->IsExecutionTerminating() && !pIsolate->HasPendingException()) {
					ThrowError(pIsolate, kNativeExceptionErrorMessage);
				}
			}
		}

		void HideMenusTextCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kNativeExceptionErrorMessage[] = "menus.HideText() failed with a native C++ exception.";
			constexpr int kMenuPlayerArgumentIndex = 0;
			constexpr int kMinimumHideTextArgumentCount = kMenuPlayerArgumentIndex + 1;
			constexpr int kMenuLevel = 1;
			constexpr int kHiddenMenuDisplayTime = 0;
			constexpr char kMenuKeyValuesName[] = "menu";
			constexpr char kMenuTitleFieldName[] = "title";
			constexpr char kMenuMessageFieldName[] = "msg";
			constexpr char kMenuLevelFieldName[] = "level";
			constexpr char kMenuDisplayTimeFieldName[] = "time";
			constexpr char kEmptyMenuText[] = "";
			constexpr char kHideTextAPIName[] = "menus.HideText()";
			constexpr char kHideTextArgumentsErrorMessage[] = "menus.HideText(PlayerOrIndex) requires a player index.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				auto* const pMenuServerPluginHelpers = RequireServerPluginHelpers(pIsolate, kHideTextAPIName);
				if (!pMenuServerPluginHelpers) {
					return;
				}

				if (CallbackInformation.Length() < kMinimumHideTextArgumentCount) {
					ThrowError(pIsolate, kHideTextArgumentsErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalMenuPlayerValue = CallbackInformation[kMenuPlayerArgumentIndex];
				if (LocalMenuPlayerValue.IsEmpty()) {
					ThrowError(pIsolate, kHideTextArgumentsErrorMessage);
					return;
				}

				MessagesRecipientIdentity MenuRecipientIdentity {};
				if (!CaptureMessagesRecipientIdentity(pIsolate, LocalContext, LocalMenuPlayerValue, kHideTextAPIName, MenuRecipientIdentity)) {
					return;
				}

				if (!RequireKeyValuesSystem(pIsolate, kHideTextAPIName)) {
					return;
				}

				SourceJSKeyValuesOwner pMenuKeyValues(new KeyValues(kMenuKeyValuesName));
				if (!pMenuKeyValues) {
					return;
				}

				pMenuKeyValues->SetString(kMenuTitleFieldName, kEmptyMenuText);
				pMenuKeyValues->SetString(kMenuMessageFieldName, kEmptyMenuText);
				pMenuKeyValues->SetInt(kMenuLevelFieldName, kMenuLevel);
				pMenuKeyValues->SetInt(kMenuDisplayTimeFieldName, kHiddenMenuDisplayTime);

				auto* const pMenuPlayerEdict = RequireMessagesRecipientEdict(pIsolate, MenuRecipientIdentity, kHideTextAPIName);
				if (!pMenuPlayerEdict) {
					return;
				}

				pMenuServerPluginHelpers->CreateMessage(pMenuPlayerEdict, DIALOG_TEXT, pMenuKeyValues.get(), &g_SourceJSPlugin);

				pMenuKeyValues.reset();

				CallbackInformation.GetReturnValue().Set(true);
			} catch (...) {
				if (!pIsolate->IsExecutionTerminating() && !pIsolate->HasPendingException()) {
					ThrowError(pIsolate, kNativeExceptionErrorMessage);
				}
			}
		}

