		bool IsSteamBMSBranch() noexcept {
			constexpr char kBMSBranchName[] = "bms";

			return std::strcmp(SOURCEJS_SDK_BRANCH, kBMSBranchName) == 0;
		}

		bool IsSteamL4D2Branch() noexcept {
			constexpr char kL4D2BranchName[] = "l4d2";

			return std::strcmp(SOURCEJS_SDK_BRANCH, kL4D2BranchName) == 0;
		}

		bool IsSteamConsoleUserAccountType(const int nAccountType) noexcept {
			constexpr int kBMSConsoleUserAccountType = 9;

			return IsSteamBMSBranch() && (nAccountType == kBMSConsoleUserAccountType);
		}

		bool IsSteamAnonymousUserAccountType(const int nAccountType) noexcept {
			constexpr int kAnonymousUserAccountType = 10;

			return nAccountType == kAnonymousUserAccountType;
		}

		bool IsSteamKnownAccountType(const int nAccountType) noexcept {
			constexpr int kMinimumStandardAccountType = 0;
			constexpr int kMaximumStandardAccountType = 8;
			constexpr int kL4D2ConsoleUserAccountType = 9;

			if ((nAccountType >= kMinimumStandardAccountType) && (nAccountType <= kMaximumStandardAccountType)) {
				return true;
			}

			if (IsSteamL4D2Branch() && (nAccountType == kL4D2ConsoleUserAccountType)) {
				return true;
			}

			if (IsSteamConsoleUserAccountType(nAccountType)) {
				return true;
			}

			return IsSteamAnonymousUserAccountType(nAccountType);
		}

