		bool GetSteamUInt32FromValue(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Value> const LocalIntegerValue, char const* const pszErrorMessage, std::uint32_t& unIntegerValueOut) {
			constexpr std::uint64_t kMaximumUInt32Value = static_cast<std::uint64_t>(std::numeric_limits<std::uint32_t>::max());
			constexpr int kAutomaticIntegerBase = 0;

			if (!pIsolate || LocalContext.IsEmpty() || !pszErrorMessage) {
				return false;
			}

			if (IsValueNullish(LocalIntegerValue)) {
				ThrowError(pIsolate, pszErrorMessage);
				return false;
			}

			if (LocalIntegerValue->IsBigInt()) {
				std::uint64_t unSteamUInt64Value = 0;
				if (!GetUInt64ValueFromValue(pIsolate, LocalContext, LocalIntegerValue, unSteamUInt64Value) || (unSteamUInt64Value > kMaximumUInt32Value)) {
					ThrowError(pIsolate, pszErrorMessage);
					return false;
				}

				unIntegerValueOut = static_cast<std::uint32_t>(unSteamUInt64Value);
				return true;
			}

			if (LocalIntegerValue->IsNumber()) {
				double dblSteamUInt32NumberValue = 0.0;
				{
					v8::TryCatch NumberFailure(pIsolate);
					try {
						v8::Maybe<double> const MaybeSteamUInt32NumberValue = LocalIntegerValue->NumberValue(LocalContext);
						if (MaybeSteamUInt32NumberValue.IsNothing() || NumberFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
							if (!NumberFailure.HasCaught() && !pIsolate->IsExecutionTerminating() && !pIsolate->HasPendingException()) {
								ThrowError(pIsolate, pszErrorMessage);
							}

							NumberFailure.ReThrow();
							return false;
						}

						dblSteamUInt32NumberValue = MaybeSteamUInt32NumberValue.FromJust();
					} catch (...) {
						if (NumberFailure.HasCaught()) {
							NumberFailure.ReThrow();
						}

						throw;
					}
				}

				if (!std::isfinite(dblSteamUInt32NumberValue) || (dblSteamUInt32NumberValue < 0.0) || (std::floor(dblSteamUInt32NumberValue) != dblSteamUInt32NumberValue) || (dblSteamUInt32NumberValue > static_cast<double>(kMaximumUInt32Value))) {
					ThrowError(pIsolate, pszErrorMessage);
					return false;
				}

				unIntegerValueOut = static_cast<std::uint32_t>(dblSteamUInt32NumberValue);
				return true;
			}

			if (LocalIntegerValue->IsString()) {
				std::string const strSteamUInt32Value = ValueToString(pIsolate, LocalIntegerValue);
				if (strSteamUInt32Value.empty() || (strSteamUInt32Value.find('-') != std::string::npos)) {
					ThrowError(pIsolate, pszErrorMessage);
					return false;
				}

				char* pszSteamUInt32ParseEnd = nullptr;

				errno = 0;
				const unsigned long long unParsedSteamUInt32Value = std::strtoull(strSteamUInt32Value.c_str(), &pszSteamUInt32ParseEnd, kAutomaticIntegerBase);
				const int nSteamUInt32ParseError = errno;
				char const* const pszSteamUInt32ValueEnd = strSteamUInt32Value.c_str() + strSteamUInt32Value.size();
				if ((pszSteamUInt32ParseEnd == strSteamUInt32Value.c_str()) || (pszSteamUInt32ParseEnd != pszSteamUInt32ValueEnd) || (nSteamUInt32ParseError == ERANGE) || (unParsedSteamUInt32Value > static_cast<unsigned long long>(kMaximumUInt32Value))) {
					ThrowError(pIsolate, pszErrorMessage);
					return false;
				}

				unIntegerValueOut = static_cast<std::uint32_t>(unParsedSteamUInt32Value);
				return true;
			}

			ThrowError(pIsolate, pszErrorMessage);

			return false;
		}

