		v8::Local<v8::Object> MakeSteamIDFieldsObject(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, CSteamID const& SteamIDBorrowed) {
			constexpr char kAccountIDPropertyName[] = "AccountID";
			constexpr char kAccountInstancePropertyName[] = "AccountInstance";
			constexpr char kAccountTypePropertyName[] = "AccountType";
			constexpr char kUniversePropertyName[] = "Universe";
			constexpr char kStaticAccountKeyPropertyName[] = "StaticAccountKey";
			constexpr char kSteamIDValuePropertyName[] = "Value";
			constexpr char kValidPropertyName[] = "Valid";

			if (!pIsolate || LocalContext.IsEmpty()) {
				return {};
			}

			// Snapshot borrowed SDK storage before allocating the JavaScript result.
			CSteamID const SteamID = SteamIDBorrowed;

			v8::TryCatch InstallationFailure(pIsolate);
			try {
				v8::Local<v8::Object> const LocalSteamIDFieldsObject = v8::Object::New(pIsolate);
				if (LocalSteamIDFieldsObject.IsEmpty()) {
					RethrowV8InstallationFailure(pIsolate, InstallationFailure, nullptr);
					return {};
				}

				v8::Local<v8::Number> const LocalSteamAccountIDValue = v8::Number::New(pIsolate, static_cast<double>(SteamID.GetAccountID()));
				if (LocalSteamAccountIDValue.IsEmpty() || !SetRecordProperty(pIsolate, LocalContext, LocalSteamIDFieldsObject, kAccountIDPropertyName, LocalSteamAccountIDValue)) {
					RethrowV8InstallationFailure(pIsolate, InstallationFailure, nullptr);
					return {};
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalSteamIDFieldsObject, kAccountInstancePropertyName, v8::Integer::New(pIsolate, static_cast<int>(SteamID.GetUnAccountInstance())))) {
					RethrowV8InstallationFailure(pIsolate, InstallationFailure, nullptr);
					return {};
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalSteamIDFieldsObject, kAccountTypePropertyName, v8::Integer::New(pIsolate, static_cast<int>(SteamID.GetEAccountType())))) {
					RethrowV8InstallationFailure(pIsolate, InstallationFailure, nullptr);
					return {};
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalSteamIDFieldsObject, kUniversePropertyName, v8::Integer::New(pIsolate, static_cast<int>(SteamID.GetEUniverse())))) {
					RethrowV8InstallationFailure(pIsolate, InstallationFailure, nullptr);
					return {};
				}

				v8::Local<v8::BigInt> const LocalSteamStaticAccountKeyValue = MakeSteamUInt64(pIsolate, GetSteamStaticAccountKey(SteamID));
				if (LocalSteamStaticAccountKeyValue.IsEmpty() || !SetRecordProperty(pIsolate, LocalContext, LocalSteamIDFieldsObject, kStaticAccountKeyPropertyName, LocalSteamStaticAccountKeyValue)) {
					RethrowV8InstallationFailure(pIsolate, InstallationFailure, nullptr);
					return {};
				}

				v8::Local<v8::BigInt> const LocalSteamIDValue = MakeSteamUInt64(pIsolate, SteamIDToUInt64(SteamID));
				if (LocalSteamIDValue.IsEmpty() || !SetRecordProperty(pIsolate, LocalContext, LocalSteamIDFieldsObject, kSteamIDValuePropertyName, LocalSteamIDValue)) {
					RethrowV8InstallationFailure(pIsolate, InstallationFailure, nullptr);
					return {};
				}

				if (!SetRecordProperty(pIsolate, LocalContext, LocalSteamIDFieldsObject, kValidPropertyName, v8::Boolean::New(pIsolate, SteamID.IsValid()))) {
					RethrowV8InstallationFailure(pIsolate, InstallationFailure, nullptr);
					return {};
				}

				return LocalSteamIDFieldsObject;
			} catch (...) {
				if (InstallationFailure.HasCaught()) {
					InstallationFailure.ReThrow();
				}

				throw;
			}
		}
#endif

