		void GetEngineServerClientSteamIDCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kNativeExceptionErrorMessage[] = "engines/server.GetClientSteamID() failed with a native C++ exception.";
#if SOURCEJS_HAS_STEAMCLIENTPUBLIC
			constexpr int kClientSteamIDPlayerArgumentIndex = 0;
			constexpr int kClientSteamIDValidatedOnlyArgumentIndex = 1;
			constexpr int kMinimumGetClientSteamIDArgumentCount = kClientSteamIDPlayerArgumentIndex + 1;
			constexpr char kGetClientSteamIDAPIName[] = "engines/server.GetClientSteamID()";
			constexpr char kGetClientSteamIDArgumentsErrorMessage[] = "engines/server.GetClientSteamID(PlayerOrIndex, bValidatedOnly?) expects a player index and an optional validated-only boolean.";
			constexpr char kClientSteamIDPlayerErrorMessage[] = "engines/server.GetClientSteamID(PlayerOrIndex, bValidatedOnly?) requires a valid player index.";
#else
			constexpr char kGetClientSteamIDSupportErrorMessage[] = "engines/server.GetClientSteamID(PlayerOrIndex, bValidatedOnly?) requires steam/steamclientpublic.h in the selected Source SDK branch.";
#endif

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			try {
#if SOURCEJS_HAS_STEAMCLIENTPUBLIC
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				auto* const pEngineServer = RequireEngineServer(pIsolate, kGetClientSteamIDAPIName);
				if (!pEngineServer) {
					return;
				}

				if (CallbackInformation.Length() < kMinimumGetClientSteamIDArgumentCount) {
					ThrowError(pIsolate, kGetClientSteamIDArgumentsErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalClientSteamIDPlayerValue = CallbackInformation[kClientSteamIDPlayerArgumentIndex];
				if (LocalClientSteamIDPlayerValue.IsEmpty()) {
					ThrowError(pIsolate, kGetClientSteamIDArgumentsErrorMessage);
					return;
				}

				bool bIsClientSteamIDValidatedOnly = false;
				if (CallbackInformation.Length() > kClientSteamIDValidatedOnlyArgumentIndex) {
					v8::Local<v8::Value> const LocalClientSteamIDValidatedOnlyValue = CallbackInformation[kClientSteamIDValidatedOnlyArgumentIndex];
					if (LocalClientSteamIDValidatedOnlyValue.IsEmpty()) {
						ThrowError(pIsolate, kGetClientSteamIDArgumentsErrorMessage);
						return;
					}

					const bool bIsValidatedOnlyProvided = !IsValueNullish(LocalClientSteamIDValidatedOnlyValue);
					if (bIsValidatedOnlyProvided && !LocalClientSteamIDValidatedOnlyValue->IsBoolean()) {
						ThrowError(pIsolate, kGetClientSteamIDArgumentsErrorMessage);
						return;
					}

					if (bIsValidatedOnlyProvided) {
						bIsClientSteamIDValidatedOnly = LocalClientSteamIDValidatedOnlyValue->BooleanValue(pIsolate);
					}
				}

				int nClientSteamIDPlayerIndex = -1;
				{
					v8::TryCatch ClientIndexFailure(pIsolate);
					try {
						const int nReadClientSteamIDPlayerIndex = GetValueIndex(pIsolate, LocalContext, LocalClientSteamIDPlayerValue);
						if (ClientIndexFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
							ClientIndexFailure.ReThrow();
							return;
						}

						nClientSteamIDPlayerIndex = nReadClientSteamIDPlayerIndex;
					} catch (...) {
						if (ClientIndexFailure.HasCaught()) {
							ClientIndexFailure.ReThrow();
						}

						throw;
					}
				}

				auto* const pClientSteamIDPlayerEdict = GetEdictFromEntityIndex(nClientSteamIDPlayerIndex);
				auto* const pPlayerGlobalVariables = RequirePlayersGlobals(pIsolate, kGetClientSteamIDAPIName);
				if (!pPlayerGlobalVariables) {
					return;
				}

				if ((nClientSteamIDPlayerIndex <= 0) || (nClientSteamIDPlayerIndex > pPlayerGlobalVariables->maxClients) || !pClientSteamIDPlayerEdict || pClientSteamIDPlayerEdict->IsFree()) {
					ThrowError(pIsolate, kClientSteamIDPlayerErrorMessage);
					return;
				}

				bool bClientSteamIDMethodAvailable = false;
				auto const* const pClientSteamID = GetEngineServerClientSteamIDDirect(pIsolate, pEngineServer, pClientSteamIDPlayerEdict, bIsClientSteamIDValidatedOnly, bClientSteamIDMethodAvailable);
				if (!bClientSteamIDMethodAvailable) {
					return;
				}

				if (!pClientSteamID) {
					CallbackInformation.GetReturnValue().Set(v8::Null(pIsolate));
					return;
				}

				v8::Local<v8::Object> const LocalClientSteamIDFieldsObject = MakeSteamIDFieldsObject(pIsolate, LocalContext, *pClientSteamID);
				if (LocalClientSteamIDFieldsObject.IsEmpty()) {
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalClientSteamIDFieldsObject);
#else
				ThrowError(pIsolate, kGetClientSteamIDSupportErrorMessage);
#endif
			} catch (...) {
				if (!pIsolate->IsExecutionTerminating() && !pIsolate->HasPendingException()) {
					ThrowError(pIsolate, kNativeExceptionErrorMessage);
				}
			}
		}

