		// Internal package control: wait for one existing continuation, not a new SOCI operation.
		void WaitForAuthenticationSQLRequestCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kCallbackArgumentIndex = 0;
			constexpr int kRequiredArgumentCount = 1;
			constexpr char kInvalidArgumentsErrorMessage[] = "auth/backends/sql.WaitForRequest(Callback) expects one callback function.";
			constexpr char kRequestFailureErrorMessage[] = "auth/backends/sql.WaitForRequest failed.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch RequestFailure(pIsolate);
			try {
				if ((CallbackInformation.Length() != kRequiredArgumentCount) || !CallbackInformation[kCallbackArgumentIndex]->IsFunction()) {
					RethrowV8InstallationFailure(pIsolate, RequestFailure, kInvalidArgumentsErrorMessage);
					return;
				}

				auto* const pRuntime = GetRuntimeFromCallbackInformation(CallbackInformation);
				if (!pRuntime || RequestFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, RequestFailure, kRequestFailureErrorMessage);
					return;
				}

				v8::Local<v8::Function> const LocalCallbackFunction = CallbackInformation[kCallbackArgumentIndex].As<v8::Function>();
				const bool bDelivered = pRuntime->WaitForAsyncRequest(LocalCallbackFunction);
				if (RequestFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, RequestFailure, kRequestFailureErrorMessage);
					return;
				}

				CallbackInformation.GetReturnValue().Set(bDelivered);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, RequestFailure, kRequestFailureErrorMessage);
			}
		}

