		bool RequireWeaponsStringArgument(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, const int nArgumentIndex, char const* const pszErrorMessage, std::string& strArgumentValueOut) {
			constexpr int kFirstArgumentIndex = 0;
			constexpr char kWeaponsArgumentReadErrorMessage[] = "Weapons: failed to read string argument.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate || !pszErrorMessage || (nArgumentIndex < kFirstArgumentIndex)) {
				return false;
			}

			v8::TryCatch WeaponsArgumentReadFailure(pIsolate);
			try {
				if (CallbackInformation.Length() <= nArgumentIndex) {
					RethrowV8InstallationFailure(pIsolate, WeaponsArgumentReadFailure, pszErrorMessage);
					return false;
				}

				v8::Local<v8::Value> const LocalStringArgument = CallbackInformation[nArgumentIndex];
				if (LocalStringArgument.IsEmpty() || !LocalStringArgument->IsString()) {
					RethrowV8InstallationFailure(pIsolate, WeaponsArgumentReadFailure, pszErrorMessage);
					return false;
				}

				std::string const strArgumentValue = ValueToString(pIsolate, LocalStringArgument);
				if (WeaponsArgumentReadFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, WeaponsArgumentReadFailure, nullptr);
					return false;
				}

				if (strArgumentValue.empty()) {
					RethrowV8InstallationFailure(pIsolate, WeaponsArgumentReadFailure, pszErrorMessage);
					return false;
				}

				strArgumentValueOut = strArgumentValue;

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, WeaponsArgumentReadFailure, kWeaponsArgumentReadErrorMessage);
				return false;
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, WeaponsArgumentReadFailure, kWeaponsArgumentReadErrorMessage);
				return false;
			}
		}

		bool RequireWeaponsIndexArgument(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, const int nArgumentIndex, char const* const pszErrorMessage, int& nWeaponIndexOut) {
			constexpr int kFirstArgumentIndex = 0;
			constexpr int kFirstWeaponIndex = 0;
			constexpr char kWeaponsArgumentReadErrorMessage[] = "Weapons: failed to read index argument.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate || !pszErrorMessage || (nArgumentIndex < kFirstArgumentIndex)) {
				return false;
			}

			v8::TryCatch WeaponsArgumentReadFailure(pIsolate);
			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty() || (CallbackInformation.Length() <= nArgumentIndex)) {
					RethrowV8InstallationFailure(pIsolate, WeaponsArgumentReadFailure, pszErrorMessage);
					return false;
				}

				v8::Local<v8::Value> const LocalWeaponReferenceArgument = CallbackInformation[nArgumentIndex];
				if (LocalWeaponReferenceArgument.IsEmpty()) {
					RethrowV8InstallationFailure(pIsolate, WeaponsArgumentReadFailure, pszErrorMessage);
					return false;
				}

				const int nWeaponIndex = GetValueIndex(pIsolate, LocalContext, LocalWeaponReferenceArgument);
				if (WeaponsArgumentReadFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, WeaponsArgumentReadFailure, nullptr);
					return false;
				}

				if (nWeaponIndex < kFirstWeaponIndex) {
					RethrowV8InstallationFailure(pIsolate, WeaponsArgumentReadFailure, pszErrorMessage);
					return false;
				}

				nWeaponIndexOut = nWeaponIndex;

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, WeaponsArgumentReadFailure, kWeaponsArgumentReadErrorMessage);
				return false;
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, WeaponsArgumentReadFailure, kWeaponsArgumentReadErrorMessage);
				return false;
			}
		}

