		bool GetWeaponClassName(edict_t* const pWeaponEdict, std::string& strClassNameOut) {
			if (!pWeaponEdict || pWeaponEdict->IsFree()) {
				return false;
			}

			char const* const pszClassName = pWeaponEdict->GetClassName();
			if (!pszClassName) {
				return false;
			}

			std::string const strClassName = pszClassName;
			if (!IsWeaponClassName(strClassName)) {
				return false;
			}

			strClassNameOut = strClassName;

			return true;
		}

		bool IsWeaponEdict(edict_t* const pWeaponEdict) {
			if (!pWeaponEdict || pWeaponEdict->IsFree()) {
				return false;
			}

			char const* const pszClassName = pWeaponEdict->GetClassName();

			return pszClassName && IsWeaponClassName(pszClassName);
		}

		bool CollectWeaponIndexes(v8::Isolate* const pIsolate, std::vector<int>& vecWeaponIndexesOut, std::string const& strClassNameFilter, char const* const pszOperationName) {
			constexpr int kFirstEntityIndex = 0;

			if (!pIsolate || !pszOperationName) {
				return false;
			}

			auto* const pGlobalVariables = RequirePlayersGlobals(pIsolate, pszOperationName);
			if (!pGlobalVariables) {
				return false;
			}

			const int nEntityCount = pGlobalVariables->maxEntities;
			std::vector<int> vecWeaponIndexes {};
			for (int nEntityIndex = kFirstEntityIndex; nEntityIndex < nEntityCount; ++nEntityIndex) {
				auto* const pEntityEdict = GetEdictFromEntityIndex(nEntityIndex);
				std::string strEntityClassName {};
				if (!GetWeaponClassName(pEntityEdict, strEntityClassName)) {
					continue;
				}

				if (!strClassNameFilter.empty() && (strEntityClassName != strClassNameFilter)) {
					continue;
				}

				vecWeaponIndexes.push_back(nEntityIndex);
			}

			vecWeaponIndexesOut = std::move(vecWeaponIndexes);

			return true;
		}

		v8::Local<v8::Array> MakeWeaponArrayFromIndexes(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, std::vector<int> const& vecWeaponIndexes) {
			constexpr std::size_t kMaximumWeaponArraySize = static_cast<std::size_t>(std::numeric_limits<std::uint32_t>::max());
			constexpr char kWeaponsArrayConstructionErrorMessage[] = "Weapons: failed to construct weapon array.";

			if (!pIsolate || LocalContext.IsEmpty() || (vecWeaponIndexes.size() > kMaximumWeaponArraySize)) {
				return {};
			}

			v8::TryCatch WeaponsArrayConstructionFailure(pIsolate);
			try {
				v8::Local<v8::Array> const LocalWeaponArray = v8::Array::New(pIsolate);
				if (LocalWeaponArray.IsEmpty()) {
					RethrowV8InstallationFailure(pIsolate, WeaponsArrayConstructionFailure, kWeaponsArrayConstructionErrorMessage);
					return {};
				}

				std::uint32_t unOutputIndex = 0;
				for (auto const& nWeaponIndex : vecWeaponIndexes) {
					auto* const pWeaponEdict = GetEdictFromEntityIndex(nWeaponIndex);
					if (!IsWeaponEdict(pWeaponEdict)) {
						continue;
					}

					v8::Local<v8::Object> const LocalWeaponObject = MakeWeaponObject(pIsolate, LocalContext, nWeaponIndex);
					if (LocalWeaponObject.IsEmpty()) {
						RethrowV8InstallationFailure(pIsolate, WeaponsArrayConstructionFailure, kWeaponsArrayConstructionErrorMessage);
						return {};
					}

					v8::Maybe<bool> const MaybeSetResult = LocalWeaponArray->CreateDataProperty(LocalContext, unOutputIndex, LocalWeaponObject);
					if (MaybeSetResult.IsNothing() || !MaybeSetResult.FromJust()) {
						RethrowV8InstallationFailure(pIsolate, WeaponsArrayConstructionFailure, kWeaponsArrayConstructionErrorMessage);
						return {};
					}

					++unOutputIndex;
				}

				return LocalWeaponArray;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, WeaponsArrayConstructionFailure, kWeaponsArrayConstructionErrorMessage);
				return {};
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, WeaponsArrayConstructionFailure, kWeaponsArrayConstructionErrorMessage);
				return {};
			}
		}

		v8::Local<v8::Array> MakeWeaponNameArray(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, CGlobalVars* const pGlobalVariables, const bool bUseShortNames) {
			constexpr int kFirstEntityIndex = 0;
			constexpr char kWeaponsArrayConstructionErrorMessage[] = "Weapons: failed to construct weapon-name array.";

			if (!pIsolate || LocalContext.IsEmpty()) {
				return {};
			}

			v8::TryCatch WeaponsArrayConstructionFailure(pIsolate);
			try {
				v8::Local<v8::Array> const LocalWeaponNamesArray = v8::Array::New(pIsolate);
				if (LocalWeaponNamesArray.IsEmpty()) {
					RethrowV8InstallationFailure(pIsolate, WeaponsArrayConstructionFailure, kWeaponsArrayConstructionErrorMessage);
					return {};
				}

				if (!pGlobalVariables) {
					return LocalWeaponNamesArray;
				}

				std::vector<std::string> vecWeaponNames {};
				const int nEntityCount = pGlobalVariables->maxEntities;
				for (int nEntityIndex = kFirstEntityIndex; nEntityIndex < nEntityCount; ++nEntityIndex) {
					auto* const pEntityEdict = GetEdictFromEntityIndex(nEntityIndex);
					std::string strWeaponClassName {};
					if (!GetWeaponClassName(pEntityEdict, strWeaponClassName)) {
						continue;
					}

					std::string const strWeaponName = bUseShortNames ? GetWeaponNameFromClassName(strWeaponClassName) : strWeaponClassName;
					if (strWeaponName.empty() || ContainsString(vecWeaponNames, strWeaponName)) {
						continue;
					}

					vecWeaponNames.push_back(strWeaponName);
				}

				std::uint32_t unOutputIndex = 0;
				for (auto const& strWeaponName : vecWeaponNames) {
					v8::Local<v8::String> const LocalWeaponName = MakeString(pIsolate, strWeaponName);
					if (LocalWeaponName.IsEmpty()) {
						RethrowV8InstallationFailure(pIsolate, WeaponsArrayConstructionFailure, kWeaponsArrayConstructionErrorMessage);
						return {};
					}

					v8::Maybe<bool> const MaybeSetResult = LocalWeaponNamesArray->CreateDataProperty(LocalContext, unOutputIndex, LocalWeaponName);
					if (MaybeSetResult.IsNothing() || !MaybeSetResult.FromJust()) {
						RethrowV8InstallationFailure(pIsolate, WeaponsArrayConstructionFailure, kWeaponsArrayConstructionErrorMessage);
						return {};
					}

					++unOutputIndex;
				}

				return LocalWeaponNamesArray;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, WeaponsArrayConstructionFailure, kWeaponsArrayConstructionErrorMessage);
				return {};
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, WeaponsArrayConstructionFailure, kWeaponsArrayConstructionErrorMessage);
				return {};
			}
		}

