		void GetWeaponCountCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr std::size_t kMaximumWeaponCount = static_cast<std::size_t>(std::numeric_limits<int>::max());
			constexpr char kWeaponsCallbackErrorMessage[] = "Weapons.GetCount failed.";
			constexpr char kWeaponCountRangeErrorMessage[] = "Weapons.GetCount() result exceeds the supported integer range.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch WeaponsOperationFailure(pIsolate);
			try {
				std::string const strWeaponClassNameFilter {};
				std::vector<int> vecWeaponIndexes {};
				if (!CollectWeaponIndexes(pIsolate, vecWeaponIndexes, strWeaponClassNameFilter, "Weapons.GetCount()")) {
					RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, kWeaponsCallbackErrorMessage);
					return;
				}

				const std::size_t unWeaponCount = vecWeaponIndexes.size();
				if (unWeaponCount > kMaximumWeaponCount) {
					ThrowError(pIsolate, kWeaponCountRangeErrorMessage);
					RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, kWeaponsCallbackErrorMessage);
					return;
				}

				const int nWeaponCount = static_cast<int>(unWeaponCount);
				CallbackInformation.GetReturnValue().Set(nWeaponCount);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, kWeaponsCallbackErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, kWeaponsCallbackErrorMessage);
			}
		}

		void RemoveWeaponCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kWeaponsCallbackErrorMessage[] = "Weapons.Remove failed.";
			constexpr int kWeaponReferenceArgumentIndex = 0;
			constexpr int kRequiredWeaponReferenceArgumentCount = kWeaponReferenceArgumentIndex + 1;
			constexpr char kRemoveWeaponOperationName[] = "Weapons.Remove()";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch WeaponsOperationFailure(pIsolate);
			try {
				if (CallbackInformation.Length() < kRequiredWeaponReferenceArgumentCount) {
					ThrowError(pIsolate, "Weapons.Remove(WeaponReference) expects a non-negative weapon index or indexed object.");
					RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, kWeaponsCallbackErrorMessage);
					return;
				}

				if (!RequireEntityGlobals(pIsolate, kRemoveWeaponOperationName)) {
					RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, kWeaponsCallbackErrorMessage);
					return;
				}

				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, nullptr);
					return;
				}

				const int nWeaponIndex = GetValueIndex(pIsolate, LocalContext, CallbackInformation[kWeaponReferenceArgumentIndex]);
				if (WeaponsOperationFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, nullptr);
					return;
				}

				auto* const pWeaponEdict = GetEdictFromEntityIndex(nWeaponIndex);
				if (!IsWeaponEdict(pWeaponEdict)) {
					CallbackInformation.GetReturnValue().Set(false);
					RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, nullptr);
					return;
				}

				const bool bWeaponRemoved = RemoveEntityByIndex(pIsolate, nWeaponIndex, kRemoveWeaponOperationName);
				if (WeaponsOperationFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, nullptr);
					return;
				}

				CallbackInformation.GetReturnValue().Set(bWeaponRemoved);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, kWeaponsCallbackErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, kWeaponsCallbackErrorMessage);
			}
		}

