		void GetWeaponsDictionaryEntriesCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kWeaponsCallbackErrorMessage[] = "Weapons/Dictionary.GetEntries failed.";
			constexpr int kWeaponDictionaryEntryLength = 2;
			constexpr std::uint32_t kWeaponIndexElementIndex = 0;
			constexpr std::uint32_t kWeaponObjectElementIndex = 1;
			constexpr char kGetWeaponsDictionaryEntriesOperationName[] = "Weapons/Dictionary.GetEntries()";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch WeaponsOperationFailure(pIsolate);
			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, nullptr);
					return;
				}

				std::string const strWeaponClassNameFilter {};
				std::vector<int> vecWeaponIndexes {};
				if (!CollectWeaponIndexes(pIsolate, vecWeaponIndexes, strWeaponClassNameFilter, kGetWeaponsDictionaryEntriesOperationName)) {
					RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, kWeaponsCallbackErrorMessage);
					return;
				}

				v8::Local<v8::Array> const LocalWeaponEntriesArray = v8::Array::New(pIsolate);
				if (LocalWeaponEntriesArray.IsEmpty()) {
					RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, kWeaponsCallbackErrorMessage);
					return;
				}

				std::uint32_t unWeaponEntryIndex = 0;
				for (auto const& nWeaponIndex : vecWeaponIndexes) {
					auto* const pWeaponEdict = GetEdictFromEntityIndex(nWeaponIndex);
					std::string strWeaponClassName {};
					if (!GetWeaponClassName(pWeaponEdict, strWeaponClassName)) {
						continue;
					}

					v8::Local<v8::Array> const LocalWeaponEntryArray = v8::Array::New(pIsolate, kWeaponDictionaryEntryLength);
					if (LocalWeaponEntryArray.IsEmpty()) {
						RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, kWeaponsCallbackErrorMessage);
						return;
					}

					v8::Local<v8::Integer> const LocalWeaponIndex = v8::Integer::New(pIsolate, nWeaponIndex);
					if (LocalWeaponIndex.IsEmpty()) {
						RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, kWeaponsCallbackErrorMessage);
						return;
					}

					v8::Local<v8::Object> const LocalWeaponObject = MakeWeaponObject(pIsolate, LocalContext, nWeaponIndex);
					if (LocalWeaponObject.IsEmpty()) {
						RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, kWeaponsCallbackErrorMessage);
						return;
					}

					v8::Maybe<bool> const MaybeSetIndexResult = LocalWeaponEntryArray->CreateDataProperty(LocalContext, kWeaponIndexElementIndex, LocalWeaponIndex);
					if (MaybeSetIndexResult.IsNothing() || !MaybeSetIndexResult.FromJust()) {
						RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, kWeaponsCallbackErrorMessage);
						return;
					}

					v8::Maybe<bool> const MaybeSetObjectResult = LocalWeaponEntryArray->CreateDataProperty(LocalContext, kWeaponObjectElementIndex, LocalWeaponObject);
					if (MaybeSetObjectResult.IsNothing() || !MaybeSetObjectResult.FromJust()) {
						RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, kWeaponsCallbackErrorMessage);
						return;
					}

					v8::Maybe<bool> const MaybeSetEntryResult = LocalWeaponEntriesArray->CreateDataProperty(LocalContext, unWeaponEntryIndex, LocalWeaponEntryArray);
					if (MaybeSetEntryResult.IsNothing() || !MaybeSetEntryResult.FromJust()) {
						RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, kWeaponsCallbackErrorMessage);
						return;
					}

					++unWeaponEntryIndex;
				}

				CallbackInformation.GetReturnValue().Set(LocalWeaponEntriesArray);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, kWeaponsCallbackErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, WeaponsOperationFailure, kWeaponsCallbackErrorMessage);
			}
		}

