		INetChannel* GetNetChannelFromPlayerIndex(const int nPlayerIndex, IVEngineServer* const pEngineServer) {
			constexpr int kFirstPlayerIndex = 1;

			if (nPlayerIndex < kFirstPlayerIndex) {
				return nullptr;
			}

#if defined(SOURCEJS_HAS_ISERVER)
			auto* const pClient = GetPlayerClientFromIndex(nPlayerIndex);
			auto* const pClientNetChannel = pClient ? pClient->GetNetChannel() : nullptr;
			if (pClientNetChannel) {
				return pClientNetChannel;
			}
#endif

			if (!pEngineServer) {
				return nullptr;
			}

			auto* const pNetChannelInformation = pEngineServer->GetPlayerNetInfo(nPlayerIndex);
			if (!pNetChannelInformation) {
				return nullptr;
			}

			return static_cast<INetChannel*>(pNetChannelInformation);
		}

