		constexpr char kNetChannelBitBufferCapacityErrorMessage[] = "netchannel bit buffer exceeds the selected Source SDK aligned byte capacity.";

		bool PrepareNetChannelBitBufferStorage(std::vector<char> const& vecBytes, std::vector<std::uint32_t>& vecWordsOut, int& nStorageByteCountOut) {
			constexpr std::size_t kBitsPerByte = 8;
			constexpr std::size_t kWordByteCount = sizeof(std::uint32_t);
			constexpr std::size_t kRequiredWordByteCount = 4;
			constexpr std::size_t kMinimumAllocationWordCount = 1;
			constexpr std::size_t kMaximumWordCount = static_cast<std::size_t>(std::numeric_limits<int>::max()) / (kBitsPerByte * kWordByteCount);
			constexpr std::size_t kMaximumStorageByteCount = kMaximumWordCount * kWordByteCount;

			static_assert(kWordByteCount == kRequiredWordByteCount);
			static_assert(std::is_same_v<std::uint32_t, uint32>);

			if (vecBytes.size() > kMaximumStorageByteCount) {
				return false;
			}

			// SDK writers require aligned whole words; explicit bit counts keep padding outside the logical payload.
			const std::size_t unWordCount = (vecBytes.size() + (kWordByteCount - 1)) / kWordByteCount;
			const std::size_t unAllocationWordCount = std::max(unWordCount, kMinimumAllocationWordCount);
			std::vector<std::uint32_t> vecWords(unAllocationWordCount);
			if (!vecBytes.empty()) {
				std::memcpy(vecWords.data(), vecBytes.data(), vecBytes.size());
			}

			vecWordsOut = std::move(vecWords);
			nStorageByteCountOut = static_cast<int>(unWordCount * kWordByteCount);

			return true;
		}

