		void SendNetChannelDataCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kNetChannelCallbackErrorMessage[] = "netchannel.SendData failed.";
			constexpr int kRequiredNetChannelDataArgumentCount = 2;
			constexpr int kDataArgumentIndex = 1;
			constexpr int kReliableArgumentIndex = 2;
			constexpr int kUnknownBitCount = -1;
			constexpr bool kDefaultReliable = true;
			constexpr char kWrittenBitCountPropertyName[] = "WrittenBitCount";
			constexpr char kSendNetChannelDataOperationName[] = "netchannel.SendData(unChannelAddress, Data, bReliable?)";
			constexpr char kInvalidNetChannelDataErrorMessage[] = "netchannel.SendData(unChannelAddress, Data, bReliable?) expects a bit buffer or byte payload.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch NetChannelOperationFailure(pIsolate);
			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					RethrowV8InstallationFailure(pIsolate, NetChannelOperationFailure, nullptr);
					return;
				}

				auto* const pNetChannel = RequireNetChannelFromFirstArgument(pIsolate, CallbackInformation, kSendNetChannelDataOperationName);
				if (!pNetChannel) {
					RethrowV8InstallationFailure(pIsolate, NetChannelOperationFailure, kNetChannelCallbackErrorMessage);
					return;
				}

				if (CallbackInformation.Length() < kRequiredNetChannelDataArgumentCount) {
					ThrowError(pIsolate, kInvalidNetChannelDataErrorMessage);
					RethrowV8InstallationFailure(pIsolate, NetChannelOperationFailure, kNetChannelCallbackErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalDataValue = CallbackInformation[kDataArgumentIndex];
				std::vector<char> vecDataBytes {};
				int nBitCount = kUnknownBitCount;
				if (!GetNetChannelBufferBytes(pIsolate, LocalContext, LocalDataValue, vecDataBytes, nBitCount, kUnknownBitCount, kWrittenBitCountPropertyName)) {
					if (NetChannelOperationFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, NetChannelOperationFailure, kNetChannelCallbackErrorMessage);
						return;
					}

					ThrowError(pIsolate, kInvalidNetChannelDataErrorMessage);
					RethrowV8InstallationFailure(pIsolate, NetChannelOperationFailure, kNetChannelCallbackErrorMessage);
					return;
				}

				std::vector<std::uint32_t> vecBufferWords {};
				int nStorageByteCount = 0;
				if (!PrepareNetChannelBitBufferStorage(vecDataBytes, vecBufferWords, nStorageByteCount)) {
					ThrowError(pIsolate, kNetChannelBitBufferCapacityErrorMessage);
					RethrowV8InstallationFailure(pIsolate, NetChannelOperationFailure, kNetChannelCallbackErrorMessage);
					return;
				}

				bf_write BitWriteBuffer {};
				BitWriteBuffer.StartWriting(vecBufferWords.data(), nStorageByteCount, nBitCount, nBitCount);

				bool bReliable = kDefaultReliable;
				if (!GetOptionalNetChannelBooleanArgument(pIsolate, CallbackInformation, kReliableArgumentIndex, kDefaultReliable, kSendNetChannelDataOperationName, bReliable)) {
					RethrowV8InstallationFailure(pIsolate, NetChannelOperationFailure, kNetChannelCallbackErrorMessage);
					return;
				}

				const bool bDataSent = pNetChannel->SendData(BitWriteBuffer, bReliable);
				CallbackInformation.GetReturnValue().Set(bDataSent);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, NetChannelOperationFailure, kNetChannelCallbackErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, NetChannelOperationFailure, kNetChannelCallbackErrorMessage);
			}
		}

