		bool NormalizeMemoryDataTypeName(std::string const& strDataTypeName, std::string& strNormalizedDataTypeNameOut) {
			constexpr char const* kSupportedDataTypeNames[] = {
				"void",
				"bool",
				"char",
				"uchar",
				"short",
				"ushort",
				"int",
				"uint",
				"long",
				"ulong",
				"longlong",
				"ulonglong",
				"float",
				"double",
				"address",
				"string",
				"stringaddress",
				"stringarray",
			};

			for (auto const& pszSupportedDataTypeName : kSupportedDataTypeNames) {
				if (strDataTypeName == pszSupportedDataTypeName) {
					strNormalizedDataTypeNameOut = pszSupportedDataTypeName;
					return true;
				}
			}

			return false;
		}

		v8::Local<v8::BigInt> MakeMemoryAddressValue(v8::Isolate* const pIsolate, const std::uintptr_t unAddress) {
			constexpr char kMemoryAddressConstructionErrorMessage[] = "memory address construction failed.";

			if (!pIsolate) {
				return {};
			}

			v8::TryCatch MemoryAddressConstructionFailure(pIsolate);
			try {
				v8::Local<v8::BigInt> const LocalAddress = v8::BigInt::NewFromUnsigned(pIsolate, static_cast<std::uint64_t>(unAddress));
				if (LocalAddress.IsEmpty()) {
					RethrowV8InstallationFailure(pIsolate, MemoryAddressConstructionFailure, kMemoryAddressConstructionErrorMessage);
					return {};
				}

				return LocalAddress;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, MemoryAddressConstructionFailure, kMemoryAddressConstructionErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, MemoryAddressConstructionFailure, kMemoryAddressConstructionErrorMessage);
			}

			return {};
		}

		bool RequireMemoryUnsignedIntegerFromValue(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Value> const LocalUnsignedIntegerValue, char const* const pszArgumentErrorMessage, std::uintptr_t& unUnsignedIntegerOut) {
			if (!pIsolate || LocalContext.IsEmpty() || !pszArgumentErrorMessage) {
				return false;
			}

			v8::TryCatch MemoryIntegerConversionFailure(pIsolate);
			try {
				if (LocalUnsignedIntegerValue.IsEmpty() || LocalUnsignedIntegerValue->IsUndefined() || LocalUnsignedIntegerValue->IsNull()) {
					ThrowError(pIsolate, pszArgumentErrorMessage);
					RethrowV8InstallationFailure(pIsolate, MemoryIntegerConversionFailure, pszArgumentErrorMessage);
					return false;
				}

				std::uint64_t unParsedValue = 0;
				if (LocalUnsignedIntegerValue->IsBigInt()) {
					v8::Local<v8::BigInt> const LocalBigInteger = LocalUnsignedIntegerValue.As<v8::BigInt>();
					if (LocalBigInteger.IsEmpty()) {
						ThrowError(pIsolate, pszArgumentErrorMessage);
						RethrowV8InstallationFailure(pIsolate, MemoryIntegerConversionFailure, pszArgumentErrorMessage);
						return false;
					}

					bool bConversionLossless = false;
					unParsedValue = LocalBigInteger->Uint64Value(&bConversionLossless);
					if (!bConversionLossless) {
						ThrowError(pIsolate, pszArgumentErrorMessage);
						RethrowV8InstallationFailure(pIsolate, MemoryIntegerConversionFailure, pszArgumentErrorMessage);
						return false;
					}

				} else if (LocalUnsignedIntegerValue->IsNumber()) {
					v8::Maybe<double> const MaybeNumericValue = LocalUnsignedIntegerValue->NumberValue(LocalContext);
					if (MaybeNumericValue.IsNothing()) {
						RethrowV8InstallationFailure(pIsolate, MemoryIntegerConversionFailure, pszArgumentErrorMessage);
						return false;
					}

					const double dblNumericValue = MaybeNumericValue.FromJust();
					if (!std::isfinite(dblNumericValue) || (dblNumericValue < 0.0) || (std::floor(dblNumericValue) != dblNumericValue) || (dblNumericValue > kMaximumSafeNumberInteger)) {
						ThrowError(pIsolate, pszArgumentErrorMessage);
						RethrowV8InstallationFailure(pIsolate, MemoryIntegerConversionFailure, pszArgumentErrorMessage);
						return false;
					}

					unParsedValue = static_cast<std::uint64_t>(dblNumericValue);

				} else {
					ThrowError(pIsolate, pszArgumentErrorMessage);
					RethrowV8InstallationFailure(pIsolate, MemoryIntegerConversionFailure, pszArgumentErrorMessage);
					return false;
				}

				if (unParsedValue > static_cast<std::uint64_t>(std::numeric_limits<std::uintptr_t>::max())) {
					ThrowError(pIsolate, pszArgumentErrorMessage);
					RethrowV8InstallationFailure(pIsolate, MemoryIntegerConversionFailure, pszArgumentErrorMessage);
					return false;
				}

				unUnsignedIntegerOut = static_cast<std::uintptr_t>(unParsedValue);

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, MemoryIntegerConversionFailure, pszArgumentErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, MemoryIntegerConversionFailure, pszArgumentErrorMessage);
			}

			return false;
		}

