		void AllocateMemoryCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kMemoryCallbackErrorMessage[] = "memory.Allocate failed.";
			constexpr int kSizeArgumentIndex = 0;
			constexpr int kRequiredArgumentCount = 1;
			constexpr std::size_t kAllocationElementCount = 1;
			constexpr bool kRequirePositiveSize = true;
			constexpr char kSizeArgumentErrorMessage[] = "memory.Allocate(unByteSize) expects a positive byte size.";
			constexpr char kAllocationErrorMessage[] = "memory.Allocate(unByteSize) could not allocate the requested bytes.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch MemoryOperationFailure(pIsolate);
			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					RethrowV8InstallationFailure(pIsolate, MemoryOperationFailure, nullptr);
					return;
				}

				if (CallbackInformation.Length() < kRequiredArgumentCount) {
					ThrowError(pIsolate, kSizeArgumentErrorMessage);
					RethrowV8InstallationFailure(pIsolate, MemoryOperationFailure, kMemoryCallbackErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalSizeValue = CallbackInformation[kSizeArgumentIndex];
				if (LocalSizeValue.IsEmpty()) {
					RethrowV8InstallationFailure(pIsolate, MemoryOperationFailure, kMemoryCallbackErrorMessage);
					return;
				}

				std::size_t unByteSize = 0;
				if (!RequireMemorySizeFromValue(pIsolate, LocalContext, LocalSizeValue, kSizeArgumentErrorMessage, unByteSize, kRequirePositiveSize)) {
					RethrowV8InstallationFailure(pIsolate, MemoryOperationFailure, kMemoryCallbackErrorMessage);
					return;
				}

				std::unique_ptr<void, void(*)(void*)> pAllocatedMemory(std::calloc(kAllocationElementCount, unByteSize), std::free);
				if (!pAllocatedMemory) {
					ThrowError(pIsolate, kAllocationErrorMessage);
					RethrowV8InstallationFailure(pIsolate, MemoryOperationFailure, kMemoryCallbackErrorMessage);
					return;
				}

				const std::uintptr_t unAllocatedAddress = reinterpret_cast<std::uintptr_t>(pAllocatedMemory.get());
				v8::Local<v8::BigInt> const LocalAddressValue = MakeMemoryAddressValue(pIsolate, unAllocatedAddress);
				if (LocalAddressValue.IsEmpty()) {
					RethrowV8InstallationFailure(pIsolate, MemoryOperationFailure, kMemoryCallbackErrorMessage);
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalAddressValue);
				pAllocatedMemory.release();
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, MemoryOperationFailure, kMemoryCallbackErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, MemoryOperationFailure, kMemoryCallbackErrorMessage);
			}
		}

