		bool ApplyMemoryAddressOffset(v8::Isolate* const pIsolate, const std::uintptr_t unBaseAddress, const std::int64_t nByteOffset, const bool bSubtractOffset, char const* const pszArithmeticErrorMessage, std::uintptr_t& unAddressOut) {
			constexpr std::uint64_t kMaximumAddress = static_cast<std::uint64_t>(std::numeric_limits<std::uintptr_t>::max());

			static_assert(std::numeric_limits<std::uintptr_t>::max() <= std::numeric_limits<std::uint64_t>::max(), "std::uintptr_t must fit in std::uint64_t");

			if (!pIsolate || !pszArithmeticErrorMessage) {
				return false;
			}

			v8::TryCatch MemoryArgumentReadFailure(pIsolate);
			try {
				const std::uint64_t unOffsetMagnitude = (nByteOffset < 0x0) ? (static_cast<std::uint64_t>(-(nByteOffset + 1)) + 1) : static_cast<std::uint64_t>(nByteOffset);
				const bool bDecreaseAddress = bSubtractOffset ? nByteOffset >= 0x0 : nByteOffset < 0x0;
				if (bDecreaseAddress) {
					if (unOffsetMagnitude > static_cast<std::uint64_t>(unBaseAddress)) {
						ThrowError(pIsolate, pszArithmeticErrorMessage);
						RethrowV8InstallationFailure(pIsolate, MemoryArgumentReadFailure, pszArithmeticErrorMessage);
						return false;
					}

					unAddressOut = unBaseAddress - static_cast<std::uintptr_t>(unOffsetMagnitude);
					return true;
				}

				if ((unOffsetMagnitude > kMaximumAddress) || (static_cast<std::uint64_t>(unBaseAddress) > (kMaximumAddress - unOffsetMagnitude))) {
					ThrowError(pIsolate, pszArithmeticErrorMessage);
					RethrowV8InstallationFailure(pIsolate, MemoryArgumentReadFailure, pszArithmeticErrorMessage);
					return false;
				}

				unAddressOut = unBaseAddress + static_cast<std::uintptr_t>(unOffsetMagnitude);

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, MemoryArgumentReadFailure, pszArithmeticErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, MemoryArgumentReadFailure, pszArithmeticErrorMessage);
			}

			return false;
		}

