			constexpr char kShortDataErrorMessage[] = "memory/helpers.Write(unBaseAddress, strDataTypeName, Data, nByteOffset?) short data expects an integer between -32768 and 32767.";
			constexpr char kUnsignedShortDataErrorMessage[] = "memory/helpers.Write(unBaseAddress, strDataTypeName, Data, nByteOffset?) ushort data expects an integer between 0 and 65535.";
			constexpr char kIntDataErrorMessage[] = "memory/helpers.Write(unBaseAddress, strDataTypeName, Data, nByteOffset?) int data expects an integer value.";
			constexpr char kUnsignedIntDataErrorMessage[] = "memory/helpers.Write(unBaseAddress, strDataTypeName, Data, nByteOffset?) uint data expects an unsigned integer value.";
			constexpr char kLongDataErrorMessage[] = "memory/helpers.Write(unBaseAddress, strDataTypeName, Data, nByteOffset?) long data expects a BigInt when long is 64-bit, otherwise an integer Number.";
			constexpr char kLongRangeErrorMessage[] = "memory/helpers.Write(unBaseAddress, strDataTypeName, Data, nByteOffset?) long data is out of range.";
			constexpr char kUnsignedLongDataErrorMessage[] = "memory/helpers.Write(unBaseAddress, strDataTypeName, Data, nByteOffset?) ulong data expects a BigInt when unsigned long is 64-bit, otherwise an unsigned integer Number.";
			constexpr char kUnsignedLongRangeErrorMessage[] = "memory/helpers.Write(unBaseAddress, strDataTypeName, Data, nByteOffset?) ulong data is out of range.";
			constexpr char kLongLongDataErrorMessage[] = "memory/helpers.Write(unBaseAddress, strDataTypeName, Data, nByteOffset?) longlong data expects a BigInt value.";
			constexpr char kUnsignedLongLongDataErrorMessage[] = "memory/helpers.Write(unBaseAddress, strDataTypeName, Data, nByteOffset?) ulonglong data expects a BigInt value.";
			constexpr char kFloatDataErrorMessage[] = "memory/helpers.Write(unBaseAddress, strDataTypeName, Data, nByteOffset?) float data expects a finite numeric value.";
			constexpr char kFloatRangeErrorMessage[] = "memory/helpers.Write(unBaseAddress, strDataTypeName, Data, nByteOffset?) float data is out of range.";
			constexpr char kDoubleDataErrorMessage[] = "memory/helpers.Write(unBaseAddress, strDataTypeName, Data, nByteOffset?) double data expects a finite numeric value.";
			constexpr char kAddressDataErrorMessage[] = "memory/helpers.Write(unBaseAddress, strDataTypeName, Data, nByteOffset?) address data expects a non-negative BigInt address.";
			constexpr char kMemoryRangeErrorMessage[] = "memory/helpers.Write(unBaseAddress, strDataTypeName, Data, nByteOffset?) range is too large.";
			constexpr char kUnsupportedTypeErrorMessage[] = "memory/helpers.Write(unBaseAddress, strDataTypeName, Data, nByteOffset?) received an unsupported data type.";
			constexpr char kMemoryCallbackErrorMessage[] = "memory/helpers.Write() failed to process the native memory operation.";

			static_assert((std::numeric_limits<char>::min() == kMinimumCharValue) && (std::numeric_limits<char>::max() == kMaximumCharValue), "char must be a signed 8-bit type");
			static_assert(std::numeric_limits<unsigned char>::max() == kMaximumUnsignedCharValue, "unsigned char must be an 8-bit type");
			static_assert((std::numeric_limits<short>::min() == kMinimumShortValue) && (std::numeric_limits<short>::max() == kMaximumShortValue), "short must be a signed 16-bit type");

			auto* const pIsolate = CallbackInformation.GetIsolate();
