		void GetAllGameDataFilesCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char const* const kNamePropertyName = "Name";
			constexpr char const* const kPathPropertyName = "Path";
			constexpr char const* const kJSONExtension = ".json";
			constexpr char const* const kINIExtension = ".ini";
			constexpr char const* const kTextExtension = ".txt";
			constexpr std::uint32_t kMaximumArrayIndex = std::numeric_limits<std::uint32_t>::max() - 1;
			constexpr char kGameDataFilesErrorMessage[] = "memory/manager.GetAllGameDataFiles() failed to enumerate GameData files.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				return;
			}

			v8::TryCatch MemoryGameDataFilesFailure(pIsolate);
			try {
				auto const* const pRuntime = GetRuntimeFromCallbackInformation(CallbackInformation);
				std::filesystem::path const PathAddonGameData = GetMemoryManagerAddonGameDataPath(pRuntime);
				std::array<std::filesystem::path, 2> const arrGameDataRoots = { GetSourceModGameDataRoot(PathAddonGameData), PathAddonGameData };
				v8::Local<v8::Array> const LocalGameDataFilesArray = v8::Array::New(pIsolate);
				if (LocalGameDataFilesArray.IsEmpty()) {
					RethrowV8InstallationFailure(pIsolate, MemoryGameDataFilesFailure, kGameDataFilesErrorMessage);
					return;
				}

				auto const DefineField = [pIsolate, LocalContext](v8::Local<v8::Object> const LocalFileObject, char const* const pszName, std::string const& strValue) -> bool {
					v8::Local<v8::String> const LocalName = MakeString(pIsolate, pszName);
					v8::Local<v8::String> const LocalValue = MakeString(pIsolate, strValue);
					if (LocalName.IsEmpty() || LocalValue.IsEmpty()) {
						return false;
					}

					return LocalFileObject->CreateDataProperty(LocalContext, LocalName, LocalValue).FromMaybe(false);
				};

				std::uint32_t unWriteIndex = 0;
				std::unordered_set<std::string> usetRelativeFileNames {};
				for (auto const& PathGameDataRoot : arrGameDataRoots) {
					std::error_code ErrorCode {};
					if (!std::filesystem::is_directory(PathGameDataRoot, ErrorCode)) {
						continue;
					}

					auto itGameDataFile = std::filesystem::recursive_directory_iterator(PathGameDataRoot, std::filesystem::directory_options::skip_permission_denied, ErrorCode);
					auto const itDirectoryEnd = std::filesystem::recursive_directory_iterator {};
					while (!ErrorCode && (itGameDataFile != itDirectoryEnd)) {
						if ((PathGameDataRoot == PathAddonGameData) && (itGameDataFile.depth() == 0) && IsSourceModGameDataStorageDirectory(itGameDataFile->path())) {
							itGameDataFile.disable_recursion_pending();
							itGameDataFile.increment(ErrorCode);
							continue;
						}

						const bool bIsRegularFile = itGameDataFile->is_regular_file(ErrorCode);
						if (ErrorCode) {
							break;
						}

						if (bIsRegularFile) {
							std::filesystem::path const PathGameDataFile = itGameDataFile->path();
							std::string const strExtension = ConvertMemoryManagerStringToLowercase(PathGameDataFile.extension().string());
							const bool bSupportedExtension = (strExtension == kJSONExtension) || (strExtension == kINIExtension) || (strExtension == kTextExtension);
							if (bSupportedExtension) {
								std::filesystem::path PathRelativeGameDataFile = std::filesystem::relative(PathGameDataFile, PathGameDataRoot, ErrorCode);
								if (ErrorCode) {
									break;
								}

								if (!usetRelativeFileNames.emplace(PathRelativeGameDataFile.generic_string()).second) {
									itGameDataFile.increment(ErrorCode);
									continue;
								}

								PathRelativeGameDataFile.replace_extension();

								v8::Local<v8::Object> const LocalGameDataFileObject = v8::Object::New(pIsolate);
								if (LocalGameDataFileObject.IsEmpty()) {
									RethrowV8InstallationFailure(pIsolate, MemoryGameDataFilesFailure, kGameDataFilesErrorMessage);
									return;
								}

								std::string const strRelativeGameDataFileName = PathRelativeGameDataFile.generic_string();
								std::string const strNormalizedGameDataFilePath = PathGameDataFile.lexically_normal().string();
								if (!DefineField(LocalGameDataFileObject, kNamePropertyName, strRelativeGameDataFileName)) {
									RethrowV8InstallationFailure(pIsolate, MemoryGameDataFilesFailure, kGameDataFilesErrorMessage);
									return;
								}

								if (!DefineField(LocalGameDataFileObject, kPathPropertyName, strNormalizedGameDataFilePath)) {
									RethrowV8InstallationFailure(pIsolate, MemoryGameDataFilesFailure, kGameDataFilesErrorMessage);
									return;
								}

								const bool bFileSet = LocalGameDataFilesArray->CreateDataProperty(LocalContext, unWriteIndex, LocalGameDataFileObject).FromMaybe(false);
								if (!bFileSet) {
									RethrowV8InstallationFailure(pIsolate, MemoryGameDataFilesFailure, kGameDataFilesErrorMessage);
									return;
								}

								if (unWriteIndex == kMaximumArrayIndex) {
									CallbackInformation.GetReturnValue().Set(LocalGameDataFilesArray);
									return;
								}

								++unWriteIndex;
							}
						}

						itGameDataFile.increment(ErrorCode);
					}
				}

				CallbackInformation.GetReturnValue().Set(LocalGameDataFilesArray);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, MemoryGameDataFilesFailure, kGameDataFilesErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, MemoryGameDataFilesFailure, kGameDataFilesErrorMessage);
			}
		}

		void LoadGameDataFileCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kFileArgumentIndex = 0;
			constexpr char const* const kArgumentErrorMessage = "memory/manager.LoadGameDataFile(strGameDataFileName) expects a non-empty game data file name.";
			constexpr bool kAllowEmptyFileName = false;
			constexpr char const* const kPathPropertyName = "Path";
			constexpr char kGameDataLoadErrorMessage[] = "memory/manager.LoadGameDataFile() failed to load GameData.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				return;
			}

			v8::TryCatch MemoryGameDataLoadFailure(pIsolate);
			try {
				std::string strGameDataFileName {};
				if (!RequireMemoryManagerStringArgument(CallbackInformation, kFileArgumentIndex, kArgumentErrorMessage, kAllowEmptyFileName, strGameDataFileName)) {
					RethrowV8InstallationFailure(pIsolate, MemoryGameDataLoadFailure, nullptr);
					return;
				}

				auto const* const pRuntime = GetRuntimeFromCallbackInformation(CallbackInformation);
				std::filesystem::path PathGameDataFile {};
				v8::Local<v8::Value> const LocalGameDataValue = LoadMemoryManagerGameDataFileValue(pIsolate, LocalContext, pRuntime, strGameDataFileName, &PathGameDataFile);
				if (LocalGameDataValue.IsEmpty()) {
					RethrowV8InstallationFailure(pIsolate, MemoryGameDataLoadFailure, kGameDataLoadErrorMessage);
					return;
				}

				if (!LocalGameDataValue->IsObject()) {
					CallbackInformation.GetReturnValue().Set(LocalGameDataValue);
					return;
				}

				v8::Local<v8::Object> const LocalGameDataObject = LocalGameDataValue.As<v8::Object>();
				std::string const strGameDataFilePath = PathGameDataFile.string();
				v8::Local<v8::String> const LocalPathPropertyName = MakeString(pIsolate, kPathPropertyName);
				v8::Local<v8::String> const LocalPathPropertyValue = MakeString(pIsolate, strGameDataFilePath);
				if (LocalPathPropertyName.IsEmpty() || LocalPathPropertyValue.IsEmpty() || !LocalGameDataObject->CreateDataProperty(LocalContext, LocalPathPropertyName, LocalPathPropertyValue).FromMaybe(false)) {
					RethrowV8InstallationFailure(pIsolate, MemoryGameDataLoadFailure, kGameDataLoadErrorMessage);
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalGameDataValue);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, MemoryGameDataLoadFailure, kGameDataLoadErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, MemoryGameDataLoadFailure, kGameDataLoadErrorMessage);
			}
		}

		void GetGameDataValueCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kFileArgumentIndex = 0;
			constexpr int kPathArgumentIndex = 1;
			constexpr char const* const kFileArgumentErrorMessage = "memory/manager.GetGameDataValue(strGameDataFileName, strPropertyPath?) expects a non-empty game data file name.";
			constexpr char const* const kPathArgumentErrorMessage = "memory/manager.GetGameDataValue(strGameDataFileName, strPropertyPath?) expects path to be a string.";
			constexpr bool kAllowEmptyFileName = false;
			constexpr bool kAllowEmptyPath = true;
			constexpr char kGameDataValueErrorMessage[] = "memory/manager.GetGameDataValue() failed to read a GameData value.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				return;
			}

			v8::TryCatch MemoryGameDataValueFailure(pIsolate);
			try {
				std::string strGameDataFileName {};
				if (!RequireMemoryManagerStringArgument(CallbackInformation, kFileArgumentIndex, kFileArgumentErrorMessage, kAllowEmptyFileName, strGameDataFileName)) {
					RethrowV8InstallationFailure(pIsolate, MemoryGameDataValueFailure, nullptr);
					return;
				}

				auto const* const pRuntime = GetRuntimeFromCallbackInformation(CallbackInformation);
				v8::Local<v8::Value> const LocalGameDataValue = LoadMemoryManagerGameDataFileValue(pIsolate, LocalContext, pRuntime, strGameDataFileName, nullptr);
				if (LocalGameDataValue.IsEmpty()) {
					RethrowV8InstallationFailure(pIsolate, MemoryGameDataValueFailure, kGameDataValueErrorMessage);
					return;
				}

				if (CallbackInformation.Length() <= kPathArgumentIndex) {
					CallbackInformation.GetReturnValue().Set(LocalGameDataValue);
					return;
				}

				v8::Local<v8::Value> const LocalPathArgumentValue = CallbackInformation[kPathArgumentIndex];
				if (LocalPathArgumentValue.IsEmpty() || LocalPathArgumentValue->IsNull() || LocalPathArgumentValue->IsUndefined()) {
					CallbackInformation.GetReturnValue().Set(LocalGameDataValue);
					return;
				}

				std::string strPropertyPath {};
				if (!RequireMemoryManagerStringArgument(CallbackInformation, kPathArgumentIndex, kPathArgumentErrorMessage, kAllowEmptyPath, strPropertyPath)) {
					RethrowV8InstallationFailure(pIsolate, MemoryGameDataValueFailure, nullptr);
					return;
				}

				v8::Local<v8::Value> LocalPropertyValue {};
				if (!GetMemoryManagerValueByPath(pIsolate, LocalContext, LocalGameDataValue, strPropertyPath, LocalPropertyValue)) {
					if (MemoryGameDataValueFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, MemoryGameDataValueFailure, nullptr);
						return;
					}

					CallbackInformation.GetReturnValue().Set(v8::Null(pIsolate));
					return;
				}

				v8::Local<v8::Value> const LocalSelectedPropertyValue = SelectMemoryManagerValue(pIsolate, LocalContext, LocalPropertyValue);
				if (LocalSelectedPropertyValue.IsEmpty()) {
					RethrowV8InstallationFailure(pIsolate, MemoryGameDataValueFailure, kGameDataValueErrorMessage);
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalSelectedPropertyValue);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, MemoryGameDataValueFailure, kGameDataValueErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, MemoryGameDataValueFailure, kGameDataValueErrorMessage);
			}
		}

