		void GetGameDataOffsetCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kFileArgumentIndex = 0;
			constexpr int kNameArgumentIndex = 1;
			constexpr char const* const kFileArgumentErrorMessage = "memory/manager.GetGameDataOffset(strGameDataFileName, strOffsetName) expects a non-empty game data file name.";
			constexpr char const* const kNameArgumentErrorMessage = "memory/manager.GetGameDataOffset(strGameDataFileName, strOffsetName) expects a non-empty offset name.";
			constexpr char const* const kResolvedOffsetErrorMessage = "memory/manager.GetGameDataOffset(strGameDataFileName, strOffsetName) resolved offset must be an integer.";
			constexpr bool kAllowEmptyArgument = false;
			constexpr char const* const kOffsetsSectionName = "Offsets";
			constexpr char kGameDataOffsetErrorMessage[] = "memory/manager.GetGameDataOffset() failed to read a GameData offset.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
			if (LocalContext.IsEmpty()) {
				return;
			}

			v8::TryCatch MemoryGameDataOffsetFailure(pIsolate);
			try {
				std::string strGameDataFileName {};
				std::string strOffsetName {};
				if (!RequireMemoryManagerStringArgument(CallbackInformation, kFileArgumentIndex, kFileArgumentErrorMessage, kAllowEmptyArgument, strGameDataFileName)) {
					RethrowV8InstallationFailure(pIsolate, MemoryGameDataOffsetFailure, nullptr);
					return;
				}

				if (!RequireMemoryManagerStringArgument(CallbackInformation, kNameArgumentIndex, kNameArgumentErrorMessage, kAllowEmptyArgument, strOffsetName)) {
					RethrowV8InstallationFailure(pIsolate, MemoryGameDataOffsetFailure, nullptr);
					return;
				}

				auto const* const pRuntime = GetRuntimeFromCallbackInformation(CallbackInformation);
				v8::Local<v8::Value> LocalOffsetRecordValue {};
				if (!GetMemoryManagerNamedData(pIsolate, LocalContext, pRuntime, strGameDataFileName, kOffsetsSectionName, strOffsetName, LocalOffsetRecordValue)) {
					if (MemoryGameDataOffsetFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, MemoryGameDataOffsetFailure, nullptr);
						return;
					}

					CallbackInformation.GetReturnValue().Set(v8::Null(pIsolate));
					return;
				}

				int nOffsetValue = 0x0;
				const MemoryManagerIntegerResult IntegerResult = GetMemoryManagerSelectedInteger(pIsolate, LocalContext, LocalOffsetRecordValue, kResolvedOffsetErrorMessage, nOffsetValue);
				if (IntegerResult == MemoryManagerIntegerResult::Error) {
					RethrowV8InstallationFailure(pIsolate, MemoryGameDataOffsetFailure, nullptr);
					return;
				}

				if (IntegerResult == MemoryManagerIntegerResult::Missing) {
					CallbackInformation.GetReturnValue().Set(v8::Null(pIsolate));
					return;
				}

				CallbackInformation.GetReturnValue().Set(nOffsetValue);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, MemoryGameDataOffsetFailure, kGameDataOffsetErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, MemoryGameDataOffsetFailure, kGameDataOffsetErrorMessage);
			}
		}

