				if (CallbackInformation.Length() <= kIdentifierArgumentIndex) {
					ThrowError(pIsolate, kIdentifierArgumentErrorMessage);
					RethrowV8InstallationFailure(pIsolate, MemoryBinaryIdentifierFailure, nullptr);
					return;
				}

				v8::Local<v8::Value> const LocalIdentifierValue = CallbackInformation[kIdentifierArgumentIndex];
