				v8::Local<v8::Value> const LocalStringTableValue = CallbackInformation[kStringTableValueArgumentIndex];
				if (LocalStringTableNameValue.IsEmpty() || LocalStringTableValue.IsEmpty() || !LocalStringTableNameValue->IsString() || !LocalStringTableValue->IsString()) {
					RethrowV8InstallationFailure(pIsolate, StringTableFailure, kRequiredArgumentsErrorMessage);
					return;
				}

				std::string strStringTableName {};
				if (!ReadStringTableCString(pIsolate, LocalStringTableNameValue, StringTableFailure, strStringTableName)) {
					RethrowV8InstallationFailure(pIsolate, StringTableFailure, kStringTableStringReadErrorMessage);
					return;
				}

				if (strStringTableName.empty()) {
					RethrowV8InstallationFailure(pIsolate, StringTableFailure, kEmptyStringTableNameErrorMessage);
					return;
				}

				std::string strStringTableValue {};
				if (!ReadStringTableCString(pIsolate, LocalStringTableValue, StringTableFailure, strStringTableValue)) {
					RethrowV8InstallationFailure(pIsolate, StringTableFailure, kStringTableStringReadErrorMessage);
					return;
				}

				auto* const pStringTableContainer = RequireNetworkStringTableContainer(pIsolate, kOperationName);
