		bool ReadStringUserDataTarget(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, v8::TryCatch& StringTableFailure, char const* const pszOperationName, INetworkStringTable*& pStringTableOut, int& nStringIndexOut) {
			constexpr char kInvalidTargetErrorMessage[] = "String table user data requires a non-empty table name without embedded NUL and an int32 string index.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			std::string strTableName {};
			if ((CallbackInformation.Length() < 2) || !CallbackInformation[0]->IsString() || !CallbackInformation[1]->IsInt32() || !ReadStringTableCString(pIsolate, CallbackInformation[0], StringTableFailure, strTableName) || strTableName.empty()) {
				RethrowV8InstallationFailure(pIsolate, StringTableFailure, kInvalidTargetErrorMessage);
				return false;
			}

			auto* const pStringTableContainer = RequireNetworkStringTableContainer(pIsolate, pszOperationName);
			if (!pStringTableContainer || StringTableFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
				RethrowV8InstallationFailure(pIsolate, StringTableFailure, nullptr);
				return false;
			}

			auto* const pStringTable = pStringTableContainer->FindTable(strTableName.c_str());
			const int nStringIndex = CallbackInformation[1].As<v8::Int32>()->Value();
			pStringTableOut = (pStringTable && (nStringIndex >= 0) && (nStringIndex < pStringTable->GetNumStrings())) ? pStringTable : nullptr;
			nStringIndexOut = nStringIndex;

			return true;
		}

		void GetStringUserDataCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kOperationName[] = "stringtables.GetStringUserData(strTableName, nStringIndex)";
			constexpr char kFailureMessage[] = "stringtables.GetStringUserData() could not copy the entry data.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			v8::TryCatch StringTableFailure(pIsolate);
			try {
				INetworkStringTable* pStringTable = nullptr;
				int nStringIndex = 0;
				if (!ReadStringUserDataTarget(CallbackInformation, StringTableFailure, kOperationName, pStringTable, nStringIndex)) {
					return;
				}

				int nByteCount = 0;
				void const* const pData = pStringTable ? pStringTable->GetStringUserData(nStringIndex, &nByteCount) : nullptr;
				if (!pData || (nByteCount <= 0)) {
					CallbackInformation.GetReturnValue().SetNull();
					return;
				}

				unsigned char const* const pchBytes = static_cast<unsigned char const*>(pData);
				std::vector<unsigned char> const vecBytes(pchBytes, pchBytes + nByteCount);
				v8::Local<v8::Uint8Array> const LocalBytes = MakeEngineByteArrayValue(pIsolate, vecBytes);
				if (LocalBytes.IsEmpty()) {
					RethrowV8InstallationFailure(pIsolate, StringTableFailure, kFailureMessage);
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalBytes);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StringTableFailure, kFailureMessage);
			}
		}

		void SetStringUserDataCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char kOperationName[] = "stringtables.SetStringUserData(strTableName, nStringIndex, arrBytes)";
			constexpr char kInvalidDataMessage[] = "stringtables.SetStringUserData() expects a non-shared, attached Uint8Array.";
			constexpr char kFailureMessage[] = "stringtables.SetStringUserData() could not replace the entry data.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			v8::TryCatch StringTableFailure(pIsolate);
			try {
				if ((CallbackInformation.Length() < 3) || !CallbackInformation[2]->IsUint8Array()) {
					RethrowV8InstallationFailure(pIsolate, StringTableFailure, kInvalidDataMessage);
					return;
				}

				v8::Local<v8::Uint8Array> const LocalBytes = CallbackInformation[2].As<v8::Uint8Array>();
				v8::Local<v8::ArrayBuffer> const LocalBuffer = LocalBytes->Buffer();
				if (LocalBuffer.IsEmpty() || LocalBuffer->IsSharedArrayBuffer() || LocalBuffer->WasDetached()) {
					RethrowV8InstallationFailure(pIsolate, StringTableFailure, kInvalidDataMessage);
					return;
				}

				INetworkStringTable* pStringTable = nullptr;
				int nStringIndex = 0;
				if (!ReadStringUserDataTarget(CallbackInformation, StringTableFailure, kOperationName, pStringTable, nStringIndex)) {
					return;
				}

				int nByteCount = 0;
				void const* const pData = pStringTable ? pStringTable->GetStringUserData(nStringIndex, &nByteCount) : nullptr;
				// The public SDK does not expose the table's fixed-size user-data schema.
				if (!pData || (nByteCount <= 0) || (LocalBytes->ByteLength() != static_cast<std::size_t>(nByteCount))) {
					CallbackInformation.GetReturnValue().Set(false);
					return;
				}

				const std::size_t unByteCount = static_cast<std::size_t>(nByteCount);
				std::vector<unsigned char> vecBytes(unByteCount);
				if (LocalBytes->CopyContents(vecBytes.data(), unByteCount) != unByteCount) {
					RethrowV8InstallationFailure(pIsolate, StringTableFailure, kFailureMessage);
					return;
				}

				pStringTable->SetStringUserData(nStringIndex, nByteCount, vecBytes.data());
				if (StringTableFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StringTableFailure, nullptr);
					return;
				}

				CallbackInformation.GetReturnValue().Set(true);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StringTableFailure, kFailureMessage);
			}
		}

		INetworkStringTable* GetStringTablesDownloadablesTable() {
			constexpr char const* const kDownloadablesStringTableName = "downloadables";

			auto* const pStringTableContainer = g_Application.GetEngineInterfaces().GetNetworkStringTableContainer();
			if (!pStringTableContainer) {
				return nullptr;
			}

			return pStringTableContainer->FindTable(kDownloadablesStringTableName);
		}

		INetworkStringTable* RequireStringTablesDownloadablesTable(v8::Isolate* const pIsolate, char const* const pszAPIName) {
			constexpr char const* const kFailureErrorMessage = "stringtables could not acquire the downloadables table.";

			if (!pIsolate || !pszAPIName) {
				return nullptr;
			}

			v8::TryCatch StringTableFailure(pIsolate);
			try {
				if (!RequireNetworkStringTableContainer(pIsolate, pszAPIName) || StringTableFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StringTableFailure, kFailureErrorMessage);
					return nullptr;
				}

				auto* const pDownloadablesStringTable = GetStringTablesDownloadablesTable();
				if (!pDownloadablesStringTable) {
					std::string const strMissingDownloadablesStringTableErrorMessage = std::string(pszAPIName) + " requires the downloadables string table.";
					RethrowV8InstallationFailure(pIsolate, StringTableFailure, strMissingDownloadablesStringTableErrorMessage.c_str());
					return nullptr;
				}

				return pDownloadablesStringTable;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StringTableFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StringTableFailure, kFailureErrorMessage);
			}

			return nullptr;
		}

		bool DoesStringTablesVectorContainValue(std::vector<std::string> const& vecStringTableValues, std::string const& strCandidateStringTableValue) noexcept {
			for (auto const& strStringTableValue : vecStringTableValues) {
				if (strStringTableValue == strCandidateStringTableValue) {
					return true;
				}
			}

			return false;
		}

		void AppendStringTablesUniqueStringValue(std::vector<std::string>& vecStringTableValuesInOut, std::string const& strCandidateStringTableValue) {
			if (strCandidateStringTableValue.empty()) {
				return;
			}

			if (DoesStringTablesVectorContainValue(vecStringTableValuesInOut, strCandidateStringTableValue)) {
				return;
			}

			vecStringTableValuesInOut.push_back(strCandidateStringTableValue);
		}

		bool RemoveStringTablesStringValue(std::vector<std::string>& vecStringTableValuesInOut, std::string const& strStringTableValueToRemove) {
			for (auto itStringTableValue = vecStringTableValuesInOut.begin(); itStringTableValue != vecStringTableValuesInOut.end(); ++itStringTableValue) {
				if (*itStringTableValue == strStringTableValueToRemove) {
					vecStringTableValuesInOut.erase(itStringTableValue);
					return true;
				}
			}

			return false;
		}

		std::string NormalizeStringTablesDownloadPath(V8Runtime const* const pRuntime, std::string const& strDownloadPath) {
			constexpr std::size_t kDownloadPathStartOffset = 0x0;
			constexpr char const* const kCurrentDirectoryPrefix = "./";
			constexpr std::size_t kCurrentDirectoryPrefixLength = 2;
			constexpr char kWindowsPathSeparatorCharacter = '\\';
			constexpr char kGenericPathSeparatorCharacter = '/';
			constexpr char kDownloadPathTerminatorCharacter = '\0';

			if (strDownloadPath.find(kDownloadPathTerminatorCharacter) != std::string::npos) {
				return {};
			}

			std::string strNormalizedDownloadPath = TrimStringWhitespace(strDownloadPath);
			for (auto& chDownloadPathCharacter : strNormalizedDownloadPath) {
				if (chDownloadPathCharacter == kWindowsPathSeparatorCharacter) {
					chDownloadPathCharacter = kGenericPathSeparatorCharacter;
				}
			}

			auto const* const pRuntimePaths = pRuntime ? pRuntime->GetRuntimePaths() : nullptr;
			if (pRuntimePaths) {
				std::filesystem::path const PathGameRoot = pRuntimePaths->GetGameRootPath().lexically_normal();
				std::filesystem::path const PathDownloadInput = std::u8string(strNormalizedDownloadPath.begin(), strNormalizedDownloadPath.end());
				if (PathDownloadInput.is_absolute()) {
					std::error_code RelativePathErrorCode {};
					std::filesystem::path const PathRelativeDownload = std::filesystem::relative(PathDownloadInput.lexically_normal(), PathGameRoot, RelativePathErrorCode);
					if (!RelativePathErrorCode) {
						std::u8string const strRelativeDownloadPathUTF8 = PathRelativeDownload.generic_u8string();
						strNormalizedDownloadPath = std::string(strRelativeDownloadPathUTF8.begin(), strRelativeDownloadPathUTF8.end());
					}
				}
			}

			while (strNormalizedDownloadPath.rfind(kCurrentDirectoryPrefix, kDownloadPathStartOffset) == kDownloadPathStartOffset) {
				strNormalizedDownloadPath = strNormalizedDownloadPath.substr(kCurrentDirectoryPrefixLength);
			}

			while (!strNormalizedDownloadPath.empty() && (strNormalizedDownloadPath[kDownloadPathStartOffset] == kGenericPathSeparatorCharacter)) {
				strNormalizedDownloadPath.erase(strNormalizedDownloadPath.begin());
			}

			return strNormalizedDownloadPath;
		}

		int FindStringTablesDownloadableIndex(std::string const& strDownloadableFilePath) {
			constexpr int kInvalidDownloadableStringIndex = -1;

			auto* const pDownloadablesStringTable = GetStringTablesDownloadablesTable();
			if (!pDownloadablesStringTable || strDownloadableFilePath.empty() || (strDownloadableFilePath.find('\0') != std::string::npos)) {
				return kInvalidDownloadableStringIndex;
			}

			const int nDownloadableStringIndex = pDownloadablesStringTable->FindStringIndex(strDownloadableFilePath.c_str());
			if (nDownloadableStringIndex == INVALID_STRING_INDEX) {
				return kInvalidDownloadableStringIndex;
			}

			return nDownloadableStringIndex;
		}

		int AddStringTablesDownloadable(std::string const& strDownloadableFilePath, const bool bTrackDownloadableFilePath) {
			constexpr int kInvalidDownloadableStringIndex = -1;
			constexpr int kFirstValidDownloadableStringIndex = 0;
#if !defined(SOURCEJS_OLD_CONSOLE_API)
			constexpr bool kIsServerSide = true;
#endif

			auto* const pDownloadablesStringTable = GetStringTablesDownloadablesTable();
			if (!pDownloadablesStringTable || strDownloadableFilePath.empty() || (strDownloadableFilePath.find('\0') != std::string::npos)) {
				return kInvalidDownloadableStringIndex;
			}

			int nDownloadableStringIndex = pDownloadablesStringTable->FindStringIndex(strDownloadableFilePath.c_str());
			if (nDownloadableStringIndex == INVALID_STRING_INDEX) {
#if defined(SOURCEJS_OLD_CONSOLE_API)
				nDownloadableStringIndex = pDownloadablesStringTable->AddString(strDownloadableFilePath.c_str());
#else
				nDownloadableStringIndex = pDownloadablesStringTable->AddString(kIsServerSide, strDownloadableFilePath.c_str());
#endif
			}

			if (bTrackDownloadableFilePath && (nDownloadableStringIndex >= kFirstValidDownloadableStringIndex)) {
				AppendStringTablesUniqueStringValue(g_vecDownloadableFilePaths, strDownloadableFilePath);
			}

			return nDownloadableStringIndex;
		}

		v8::Local<v8::Array> MakeStringTablesStringArray(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, std::vector<std::string> const& vecStringTableValues) {
			constexpr std::size_t kMaximumStringTableValueArrayLength = static_cast<std::size_t>(std::numeric_limits<std::uint32_t>::max());
			constexpr char const* const kFailureErrorMessage = "stringtables could not create a string-array result.";

			if (!pIsolate || LocalContext.IsEmpty() || (vecStringTableValues.size() > kMaximumStringTableValueArrayLength)) {
				return {};
			}

			v8::TryCatch StringTableFailure(pIsolate);
			try {
				v8::Local<v8::Array> const LocalStringTableValueArray = v8::Array::New(pIsolate);
				if (LocalStringTableValueArray.IsEmpty() || StringTableFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StringTableFailure, kFailureErrorMessage);
					return {};
				}

				for (std::size_t unStringTableValueIndex = 0; unStringTableValueIndex < vecStringTableValues.size(); ++unStringTableValueIndex) {
					v8::Local<v8::String> const LocalStringTableValueString = MakeString(pIsolate, vecStringTableValues[unStringTableValueIndex]);
					if (LocalStringTableValueString.IsEmpty() || StringTableFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, StringTableFailure, kFailureErrorMessage);
						return {};
					}

					const bool bStringTableValueSet = LocalStringTableValueArray->CreateDataProperty(LocalContext, static_cast<std::uint32_t>(unStringTableValueIndex), LocalStringTableValueString).FromMaybe(false);
					if (!bStringTableValueSet || StringTableFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, StringTableFailure, kFailureErrorMessage);
						return {};
					}
				}

				return LocalStringTableValueArray;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StringTableFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StringTableFailure, kFailureErrorMessage);
			}

			return {};
		}

