		void SetGameRulesColorPropertyCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kMinimumArgumentCount = 2;
			constexpr int kColorPropertyValueArgumentIndex = 1;
			constexpr char const* const kColorPropertyArgumentsErrorMessage = "SetPropertyColor(strGameRulesPropertyName, ColorValue) expects a property name and value.";
			constexpr char const* const kFailureErrorMessage = "engines/gamerules could not write the color property.";

			static_assert(alignof(Color) == alignof(unsigned char), "Game rules color writes require byte-aligned SDK colors.");

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch GameRulesFailure(pIsolate);
			try {
				if (CallbackInformation.Length() < kMinimumArgumentCount) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kColorPropertyArgumentsErrorMessage);
					return;
				}

				char* const pchColorPropertyAddress = GetGameRulesPropertyAddress(CallbackInformation);
				if (!pchColorPropertyAddress || GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
					return;
				}

				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				v8::Local<v8::Value> const LocalColorPropertyValue = CallbackInformation[kColorPropertyValueArgumentIndex];
				if (LocalColorPropertyValue.IsEmpty()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kColorPropertyArgumentsErrorMessage);
					return;
				}

				Color ColorPropertyValue = Color(0x0, 0x0, 0x0, 0x0);
				if (!GetGameRulesColorFromValue(pIsolate, LocalContext, LocalColorPropertyValue, ColorPropertyValue) || GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
					return;
				}

				const std::uintptr_t unColorPropertyAddress = reinterpret_cast<std::uintptr_t>(pchColorPropertyAddress);
				if (!IsMemoryAddressRangeRepresentable(unColorPropertyAddress, sizeof(Color))) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
					return;
				}

				// The engine owns byte-aligned Color storage; avoid the SDK's int-based copy operation.
				auto* const pColorPropertyValue = reinterpret_cast<Color*>(pchColorPropertyAddress);
				pColorPropertyValue->SetColor(ColorPropertyValue.r(), ColorPropertyValue.g(), ColorPropertyValue.b(), ColorPropertyValue.a());

				CallbackInformation.GetReturnValue().Set(true);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
			}
		}

		bool GetGameRulesObjectFloatComponent(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalSourceObject, char const* const pszComponentName, char const* const pszErrorMessage, float& flComponentOut) {
			constexpr char const* const kFailureErrorMessage = "engines/gamerules could not read the object float component.";

			if (!pIsolate) {
				return false;
			}

			v8::TryCatch GameRulesFailure(pIsolate);
			try {
				if (LocalContext.IsEmpty() || LocalSourceObject.IsEmpty() || !pszComponentName || !*pszComponentName || !pszErrorMessage || !*pszErrorMessage) {
					return false;
				}

				v8::Local<v8::String> const LocalComponentName = MakeString(pIsolate, pszComponentName);
				if (LocalComponentName.IsEmpty() || GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
					return false;
				}

				v8::Local<v8::Value> LocalComponentValue {};
				if (!LocalSourceObject->Get(LocalContext, LocalComponentName).ToLocal(&LocalComponentValue) || GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, pszErrorMessage);
					return false;
				}

				if (LocalComponentValue.IsEmpty() || !LocalComponentValue->IsNumber()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, pszErrorMessage);
					return false;
				}

				float flComponent = 0.0F;
				if (!GetFloatArgument(pIsolate, LocalContext, LocalComponentValue, pszErrorMessage, flComponent) || GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, pszErrorMessage);
					return false;
				}

				flComponentOut = flComponent;

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
			}

			return false;
		}

