		void SetGameRulesQuaternionPropertyCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kMinimumArgumentCount = 2;
			constexpr int kQuaternionPropertyValueArgumentIndex = 1;
			constexpr char const* const kQuaternionXPropertyName = "X";
			constexpr char const* const kQuaternionYPropertyName = "Y";
			constexpr char const* const kQuaternionZPropertyName = "Z";
			constexpr char const* const kQuaternionWPropertyName = "W";
			constexpr char const* const kQuaternionPropertyArgumentsErrorMessage = "SetPropertyQuaternion(strGameRulesPropertyName, QuaternionValue) expects a property name and value object.";
			constexpr char const* const kQuaternionComponentsErrorMessage = "SetPropertyQuaternion(strGameRulesPropertyName, QuaternionValue) expects numeric components.";
			constexpr char const* const kMisalignedQuaternionPropertyAddressErrorMessage = "Game rules quaternion property address is not aligned.";
			constexpr char const* const kFailureErrorMessage = "engines/gamerules could not write the quaternion property.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch GameRulesFailure(pIsolate);
			try {
				if (CallbackInformation.Length() < kMinimumArgumentCount) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kQuaternionPropertyArgumentsErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalQuaternionPropertyValue = CallbackInformation[kQuaternionPropertyValueArgumentIndex];
				if (LocalQuaternionPropertyValue.IsEmpty() || !LocalQuaternionPropertyValue->IsObject()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kQuaternionPropertyArgumentsErrorMessage);
					return;
				}

				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				char* const pchQuaternionPropertyAddress = GetGameRulesPropertyAddress(CallbackInformation);
				if (!pchQuaternionPropertyAddress || GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
					return;
				}

				v8::Local<v8::Object> const LocalQuaternionObject = LocalQuaternionPropertyValue.As<v8::Object>();
				float flQuaternionXComponent = 0.0F;
				float flQuaternionYComponent = 0.0F;
				float flQuaternionZComponent = 0.0F;
				float flQuaternionWComponent = 0.0F;
				if (!GetGameRulesObjectFloatComponent(pIsolate, LocalContext, LocalQuaternionObject, kQuaternionXPropertyName, kQuaternionComponentsErrorMessage, flQuaternionXComponent) || GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kQuaternionComponentsErrorMessage);
					return;
				}

				if (!GetGameRulesObjectFloatComponent(pIsolate, LocalContext, LocalQuaternionObject, kQuaternionYPropertyName, kQuaternionComponentsErrorMessage, flQuaternionYComponent) || GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kQuaternionComponentsErrorMessage);
					return;
				}

				if (!GetGameRulesObjectFloatComponent(pIsolate, LocalContext, LocalQuaternionObject, kQuaternionZPropertyName, kQuaternionComponentsErrorMessage, flQuaternionZComponent) || GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kQuaternionComponentsErrorMessage);
					return;
				}

				if (!GetGameRulesObjectFloatComponent(pIsolate, LocalContext, LocalQuaternionObject, kQuaternionWPropertyName, kQuaternionComponentsErrorMessage, flQuaternionWComponent) || GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kQuaternionComponentsErrorMessage);
					return;
				}

				Quaternion const QuaternionPropertyValue = Quaternion(flQuaternionXComponent, flQuaternionYComponent, flQuaternionZComponent, flQuaternionWComponent);
				const std::uintptr_t unQuaternionPropertyAddress = reinterpret_cast<std::uintptr_t>(pchQuaternionPropertyAddress);
				if ((unQuaternionPropertyAddress % alignof(Quaternion)) != 0) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kMisalignedQuaternionPropertyAddressErrorMessage);
					return;
				}

				if (!IsMemoryAddressRangeRepresentable(unQuaternionPropertyAddress, sizeof(Quaternion))) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
					return;
				}

				// The engine owns live Quaternion storage with the full writable extent.
				auto* const pQuaternionPropertyValue = reinterpret_cast<Quaternion*>(pchQuaternionPropertyAddress);
				*pQuaternionPropertyValue = QuaternionPropertyValue;

				CallbackInformation.GetReturnValue().Set(true);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
			}
		}

		void GetGameRulesEdictPropertyCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kInvalidEdictEntityIndex = -1;
			constexpr char const* const kFailureErrorMessage = "engines/gamerules could not read the Edict property.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch GameRulesFailure(pIsolate);
			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				char* const pchEdictPropertyAddress = GetGameRulesPropertyAddress(CallbackInformation);
				if (!pchEdictPropertyAddress || GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
					return;
				}

				const std::uintptr_t unEdictPropertyAddress = reinterpret_cast<std::uintptr_t>(pchEdictPropertyAddress);
				if (!IsMemoryAddressRangeRepresentable(unEdictPropertyAddress, sizeof(edict_t*))) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
					return;
				}

				edict_t* pEdictPropertyValue = nullptr;
				// The engine send-table property contract owns the address-sized source extent; memcpy avoids alignment and aliasing assumptions.
				std::memcpy(&pEdictPropertyValue, pchEdictPropertyAddress, sizeof(pEdictPropertyValue));

				int nEdictEntityIndex = kInvalidEdictEntityIndex;
				const bool bEdictEntityResolved = GetEntityIndexFromEdictAddress(pEdictPropertyValue, nEdictEntityIndex);
				if (GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
					return;
				}

				if (!bEdictEntityResolved) {
					CallbackInformation.GetReturnValue().Set(v8::Null(pIsolate));
					return;
				}

				v8::Local<v8::Object> const LocalEdictEntityObject = MakeEntityObject(pIsolate, LocalContext, nEdictEntityIndex);
				if (LocalEdictEntityObject.IsEmpty() || GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalEdictEntityObject);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
			}
		}

		void SetGameRulesEdictPropertyCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kMinimumArgumentCount = 2;
			constexpr int kEdictPropertyValueArgumentIndex = 1;
			constexpr char const* const kEdictPropertyArgumentsErrorMessage = "SetPropertyEdict(strGameRulesPropertyName, EntityValue) expects a property name and entity.";
			constexpr char const* const kEdictPropertyEntityValueErrorMessage = "SetPropertyEdict(strGameRulesPropertyName, EntityValue) expects an entity index, entity object, or null.";
			constexpr char const* const kFailureErrorMessage = "engines/gamerules could not write the Edict property.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch GameRulesFailure(pIsolate);
			try {
				if (CallbackInformation.Length() < kMinimumArgumentCount) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kEdictPropertyArgumentsErrorMessage);
					return;
				}

				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				v8::Local<v8::Value> const LocalEdictPropertyValue = CallbackInformation[kEdictPropertyValueArgumentIndex];
				if (LocalEdictPropertyValue.IsEmpty()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kEdictPropertyArgumentsErrorMessage);
					return;
				}

				char* const pchEdictPropertyAddress = GetGameRulesPropertyAddress(CallbackInformation);
				if (!pchEdictPropertyAddress || GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
					return;
				}

				edict_t* pEdictPropertyValue = nullptr;
				if (!LocalEdictPropertyValue->IsNull()) {
					const int nEdictEntityIndex = GetValueIndex(pIsolate, LocalContext, LocalEdictPropertyValue);
					if (GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
						return;
					}

					if (nEdictEntityIndex < 0) {
						RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kEdictPropertyEntityValueErrorMessage);
						return;
					}

					pEdictPropertyValue = GetEdictFromEntityIndex(nEdictEntityIndex);
					if (GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
						return;
					}
				}

				const std::uintptr_t unEdictPropertyAddress = reinterpret_cast<std::uintptr_t>(pchEdictPropertyAddress);
				if (!IsMemoryAddressRangeRepresentable(unEdictPropertyAddress, sizeof(edict_t*))) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
					return;
				}

				// The engine send-table property contract owns the address-sized destination extent; memcpy avoids alignment and aliasing assumptions.
				std::memcpy(pchEdictPropertyAddress, &pEdictPropertyValue, sizeof(pEdictPropertyValue));

				CallbackInformation.GetReturnValue().Set(true);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
			}
		}

