		void ListEngineGameRulesPropertiesCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr int kRootGameRulesPropertyOffset = 0x0;
			constexpr std::size_t kInitialGameRulesPropertyRecursionDepth = 0;
			constexpr char const* const kRootGameRulesPropertyPath = "";
			constexpr char const* const kGameRulesSendTableErrorMessage = "ListProperties() could not find the game rules send table.";
			constexpr char const* const kFailureErrorMessage = "engines/gamerules could not list the properties.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch GameRulesFailure(pIsolate);
			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				auto* const pGameRulesSendTable = GetGameRulesSendTable();
				if (!pGameRulesSendTable || GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kGameRulesSendTableErrorMessage);
					return;
				}

				v8::Local<v8::Array> const LocalGameRulesPropertyInformationArray = v8::Array::New(pIsolate);
				if (LocalGameRulesPropertyInformationArray.IsEmpty() || GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
					return;
				}

				std::uint32_t unGameRulesPropertyWriteIndex = 0;
				if (!CollectGameRulesPropertyInformationObjects(pIsolate, LocalContext, LocalGameRulesPropertyInformationArray, unGameRulesPropertyWriteIndex, pGameRulesSendTable, kRootGameRulesPropertyOffset, kRootGameRulesPropertyPath, kInitialGameRulesPropertyRecursionDepth) || GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalGameRulesPropertyInformationArray);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
			}
		}

		bool InstallGameRulesFunction(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalGameRulesObject, char const* const pszFunctionName, v8::FunctionCallback const Callback, v8::Local<v8::Value> const LocalRuntimeData) {
			constexpr char const* const kFailureErrorMessage = "engines/gamerules could not install the function.";

			if (!pIsolate) {
				return false;
			}

			v8::TryCatch GameRulesFailure(pIsolate);
			try {
				if (LocalContext.IsEmpty() || LocalGameRulesObject.IsEmpty() || !pszFunctionName || !*pszFunctionName || !Callback || LocalRuntimeData.IsEmpty()) {
					return false;
				}

				v8::Local<v8::Function> LocalFunction {};
				if (!v8::Function::New(LocalContext, Callback, LocalRuntimeData).ToLocal(&LocalFunction) || GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
					return false;
				}

				v8::Local<v8::String> const LocalFunctionName = MakeString(pIsolate, pszFunctionName);
				if (LocalFunctionName.IsEmpty() || GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
					return false;
				}

				const bool bFunctionDefined = LocalGameRulesObject->CreateDataProperty(LocalContext, LocalFunctionName, LocalFunction).FromMaybe(false);
				if (!bFunctionDefined || GameRulesFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
					return false;
				}

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, GameRulesFailure, kFailureErrorMessage);
			}

			return false;
		}

