		v8::Local<v8::Object> MakeStudioModelObject(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, const MDLHandle_t hModelHandle) {
			constexpr char const* const kFailureErrorMessage = "studio could not create the model object.";
			constexpr char const* const kModelHandlePropertyName = "Handle";
			constexpr char const* const kModelIsValidFunctionName = "IsValid";
			constexpr char const* const kModelGetNameFunctionName = "GetName";
#if !defined(SOURCEJS_OLD_CONSOLE_API)
			constexpr char const* const kModelGetReferenceCountFunctionName = "GetReferenceCount";
#endif // !defined(SOURCEJS_OLD_CONSOLE_API)

			static_assert(static_cast<std::uint64_t>(std::numeric_limits<MDLHandle_t>::max()) <= static_cast<std::uint64_t>(std::numeric_limits<int>::max()), "Studio model handles must fit in V8 integer values.");

			if (!pIsolate) {
				return {};
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				if (LocalContext.IsEmpty()) {
					return {};
				}

				v8::Local<v8::Object> const LocalModelObject = v8::Object::New(pIsolate);
				if (LocalModelObject.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return {};
				}

				v8::Local<v8::Value> const LocalModelMethodData = v8::Undefined(pIsolate);
				if (LocalModelMethodData.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return {};
				}

				auto const DefineValue = [pIsolate, LocalContext, LocalModelObject, &StudioFailure](char const* const pszName, v8::Local<v8::Value> const LocalValue) -> bool {
					if (LocalValue.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
						return false;
					}

					v8::Local<v8::String> const LocalName = MakeString(pIsolate, pszName);
					if (LocalName.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
						return false;
					}

					const bool bValueDefined = LocalModelObject->CreateDataProperty(LocalContext, LocalName, LocalValue).FromMaybe(false);
					if (!bValueDefined || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
						return false;
					}

					return true;
				};

				auto const DefineFunction = [pIsolate, LocalContext, LocalModelMethodData, &DefineValue, &StudioFailure](char const* const pszName, v8::FunctionCallback const Callback) -> bool {
					v8::Local<v8::Function> LocalFunction {};
					if (!v8::Function::New(LocalContext, Callback, LocalModelMethodData).ToLocal(&LocalFunction) || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
						return false;
					}

					return DefineValue(pszName, LocalFunction);
				};

				if (!DefineValue(kModelHandlePropertyName, v8::Integer::New(pIsolate, static_cast<int>(hModelHandle))) || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return {};
				}

				if (!DefineFunction(kModelIsValidFunctionName, IsStudioModelValidCallback) || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return {};
				}

				if (!DefineFunction(kModelGetNameFunctionName, GetStudioModelNameCallback) || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return {};
				}
#if !defined(SOURCEJS_OLD_CONSOLE_API)
				if (!DefineFunction(kModelGetReferenceCountFunctionName, GetStudioModelReferenceCountCallback) || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return {};
				}
#endif // !defined(SOURCEJS_OLD_CONSOLE_API)

				return LocalModelObject;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}

			return {};
		}

		v8::Local<v8::BigInt> MakeStudioAddressValue(v8::Isolate* const pIsolate, void const* const pStudioAddress) {
			constexpr char const* const kFailureErrorMessage = "studio could not create the native address.";

			if (!pIsolate) {
				return {};
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				const std::uintptr_t unStudioAddress = reinterpret_cast<std::uintptr_t>(pStudioAddress);
				v8::Local<v8::BigInt> const LocalStudioAddress = v8::BigInt::NewFromUnsigned(pIsolate, static_cast<std::uint64_t>(unStudioAddress));
				if (LocalStudioAddress.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return {};
				}

				return LocalStudioAddress;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}

			return {};
		}

		bool InstallStudioAddress(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalTargetObject, void const* const pStudioAddress) {
			constexpr char const* const kFailureErrorMessage = "studio could not install the native address.";
			constexpr char const* const kStudioAddressPropertyName = "Address";

			if (!pIsolate) {
				return false;
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				if (LocalContext.IsEmpty() || LocalTargetObject.IsEmpty()) {
					return false;
				}

				v8::Local<v8::BigInt> const LocalStudioAddress = MakeStudioAddressValue(pIsolate, pStudioAddress);
				if (LocalStudioAddress.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return false;
				}

				v8::Local<v8::String> const LocalAddressPropertyName = MakeString(pIsolate, kStudioAddressPropertyName);
				if (LocalAddressPropertyName.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return false;
				}

				const bool bAddressDefined = LocalTargetObject->CreateDataProperty(LocalContext, LocalAddressPropertyName, LocalStudioAddress).FromMaybe(false);
				if (!bAddressDefined || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return false;
				}

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}

			return false;
		}

		float* GetStudioFloatPropertyAddress(v8::Isolate* const pIsolate, v8::Local<v8::Value> const LocalFloatPropertyMetadataValue) {
			constexpr char const* const kFailureErrorMessage = "studio could not resolve the float property address.";
			constexpr char const* const kInvalidStudioFloatPropertyMetadataErrorMessage = "Studio float property metadata is invalid.";
			constexpr char const* const kNullStudioFloatPropertyAddressErrorMessage = "Studio float property address is null.";
			constexpr char const* const kMisalignedStudioFloatPropertyAddressErrorMessage = "Studio float property address is misaligned.";

			if (!pIsolate) {
				return nullptr;
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				if (LocalFloatPropertyMetadataValue.IsEmpty() || !LocalFloatPropertyMetadataValue->IsExternal()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kInvalidStudioFloatPropertyMetadataErrorMessage);
					return nullptr;
				}

				v8::Local<v8::External> const LocalFloatPropertyMetadata = LocalFloatPropertyMetadataValue.As<v8::External>();
				float* const pflFloatPropertyValue = static_cast<float*>(LocalFloatPropertyMetadata->Value());
				if (!pflFloatPropertyValue) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kNullStudioFloatPropertyAddressErrorMessage);
					return nullptr;
				}

				const std::uintptr_t unFloatPropertyAddress = reinterpret_cast<std::uintptr_t>(pflFloatPropertyValue);
				if ((unFloatPropertyAddress % alignof(float)) != 0) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kMisalignedStudioFloatPropertyAddressErrorMessage);
					return nullptr;
				}

				if (!IsMemoryAddressRangeRepresentable(unFloatPropertyAddress, sizeof(float))) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return nullptr;
				}

				return pflFloatPropertyValue;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}

			return nullptr;
		}

		void GetStudioFloatPropertyCallback(v8::Local<v8::Name>, v8::PropertyCallbackInfo<v8::Value> const& PropertyInformation) {
			constexpr char const* const kFailureErrorMessage = "studio could not read the float property.";

			auto* const pIsolate = PropertyInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				float const* const pflFloatPropertyValue = GetStudioFloatPropertyAddress(pIsolate, PropertyInformation.Data());
				if (!pflFloatPropertyValue || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				float flPropertyValue = 0.0F;
				if (!ReadMemoryScalarFromAddress(reinterpret_cast<std::uintptr_t>(pflFloatPropertyValue), flPropertyValue)) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				PropertyInformation.GetReturnValue().Set(flPropertyValue);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}
		}

		void SetStudioFloatPropertyCallback(v8::Local<v8::Name>, v8::Local<v8::Value> const LocalFloatPropertyValue, v8::PropertyCallbackInfo<void> const& PropertyInformation) {
			constexpr char const* const kFailureErrorMessage = "studio could not write the float property.";
			constexpr double kMinimumFloatPropertyValue = static_cast<double>(std::numeric_limits<float>::lowest());
			constexpr double kMaximumFloatPropertyValue = static_cast<double>(std::numeric_limits<float>::max());
			constexpr char const* const kStudioFloatNumericValueErrorMessage = "Studio float properties require numeric values.";
			constexpr char const* const kStudioFloatConversionErrorMessage = "Studio float property conversion failed.";
			constexpr char const* const kStudioFloatRangeErrorMessage = "Studio float properties require finite values within the float range.";

			auto* const pIsolate = PropertyInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				if (LocalFloatPropertyValue.IsEmpty() || !LocalFloatPropertyValue->IsNumber()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kStudioFloatNumericValueErrorMessage);
					return;
				}

				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				float* const pflFloatPropertyValue = GetStudioFloatPropertyAddress(pIsolate, PropertyInformation.Data());
				if (!pflFloatPropertyValue || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				v8::Maybe<double> const MaybeFloatPropertyNumberValue = LocalFloatPropertyValue->NumberValue(LocalContext);
				if (MaybeFloatPropertyNumberValue.IsNothing() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kStudioFloatConversionErrorMessage);
					return;
				}

				const double dblFloatPropertyValue = MaybeFloatPropertyNumberValue.FromJust();
				if (!std::isfinite(dblFloatPropertyValue) || (dblFloatPropertyValue < kMinimumFloatPropertyValue) || (dblFloatPropertyValue > kMaximumFloatPropertyValue)) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kStudioFloatRangeErrorMessage);
					return;
				}

				const float flPropertyValue = static_cast<float>(dblFloatPropertyValue);
				WriteMemoryScalarToAddress(reinterpret_cast<std::uintptr_t>(pflFloatPropertyValue), flPropertyValue);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}
		}

		bool InstallStudioFloatProperty(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalTargetObject, char const* const pszPropertyName, float* const pflFloatPropertyValue) {
			constexpr char const* const kFailureErrorMessage = "studio could not install the float property.";
			constexpr char const* const kNullStudioFloatPropertyAddressErrorMessage = "Studio float property address is null.";
			constexpr char const* const kMisalignedStudioFloatPropertyAddressErrorMessage = "Studio float property address is misaligned.";

			if (!pIsolate) {
				return false;
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				if (LocalContext.IsEmpty() || LocalTargetObject.IsEmpty() || !pszPropertyName || !*pszPropertyName) {
					return false;
				}

				if (!pflFloatPropertyValue) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kNullStudioFloatPropertyAddressErrorMessage);
					return false;
				}

				const std::uintptr_t unFloatPropertyAddress = reinterpret_cast<std::uintptr_t>(pflFloatPropertyValue);
				if ((unFloatPropertyAddress % alignof(float)) != 0) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kMisalignedStudioFloatPropertyAddressErrorMessage);
					return false;
				}

				if (!IsMemoryAddressRangeRepresentable(unFloatPropertyAddress, sizeof(float))) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return false;
				}

				v8::Local<v8::String> const LocalPropertyName = MakeString(pIsolate, pszPropertyName);
				if (LocalPropertyName.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return false;
				}

				v8::Local<v8::External> const LocalFloatPropertyMetadata = v8::External::New(pIsolate, pflFloatPropertyValue);
				if (LocalFloatPropertyMetadata.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return false;
				}

				const bool bPropertyInstalled = LocalTargetObject->SetNativeDataProperty(LocalContext, LocalPropertyName, GetStudioFloatPropertyCallback, SetStudioFloatPropertyCallback, LocalFloatPropertyMetadata).FromMaybe(false);
				if (!bPropertyInstalled || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return false;
				}

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}

			return false;
		}

