		void SetStudioIntegerPropertyCallback(v8::Local<v8::Name>, v8::Local<v8::Value> const LocalIntegerPropertyValue, v8::PropertyCallbackInfo<void> const& PropertyInformation) {
			constexpr char const* const kFailureErrorMessage = "studio could not write the integer property.";
			constexpr char const* const kStudioIntegerPropertyValueErrorMessage = "Studio integer properties require signed 32-bit integer values.";
			constexpr char const* const kStudioIntegerConversionErrorMessage = "Studio integer property conversion failed.";

			auto* const pIsolate = PropertyInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				if (LocalIntegerPropertyValue.IsEmpty() || !LocalIntegerPropertyValue->IsInt32()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kStudioIntegerPropertyValueErrorMessage);
					return;
				}

				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				int* const pnIntegerPropertyValue = GetStudioIntegerPropertyAddress(pIsolate, PropertyInformation.Data());
				if (!pnIntegerPropertyValue || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				v8::Maybe<std::int32_t> const MaybeIntegerPropertyValue = LocalIntegerPropertyValue->Int32Value(LocalContext);
				if (MaybeIntegerPropertyValue.IsNothing() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kStudioIntegerConversionErrorMessage);
					return;
				}

				const int nIntegerPropertyValue = static_cast<int>(MaybeIntegerPropertyValue.FromJust());
				WriteMemoryScalarToAddress(reinterpret_cast<std::uintptr_t>(pnIntegerPropertyValue), nIntegerPropertyValue);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}
		}

		bool InstallStudioIntegerProperty(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalTargetObject, char const* const pszPropertyName, int* const pnIntegerPropertyValue) {
			constexpr char const* const kFailureErrorMessage = "studio could not install the integer property.";
			constexpr char const* const kNullStudioIntegerPropertyAddressErrorMessage = "Studio integer property address is null.";
			constexpr char const* const kMisalignedStudioIntegerPropertyAddressErrorMessage = "Studio integer property address is misaligned.";

			if (!pIsolate) {
				return false;
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				if (LocalContext.IsEmpty() || LocalTargetObject.IsEmpty() || !pszPropertyName || !*pszPropertyName) {
					return false;
				}

				if (!pnIntegerPropertyValue) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kNullStudioIntegerPropertyAddressErrorMessage);
					return false;
				}

				const std::uintptr_t unIntegerPropertyAddress = reinterpret_cast<std::uintptr_t>(pnIntegerPropertyValue);
				if ((unIntegerPropertyAddress % alignof(int)) != 0) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kMisalignedStudioIntegerPropertyAddressErrorMessage);
					return false;
				}

				if (!IsMemoryAddressRangeRepresentable(unIntegerPropertyAddress, sizeof(int))) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return false;
				}

				v8::Local<v8::String> const LocalPropertyName = MakeString(pIsolate, pszPropertyName);
				if (LocalPropertyName.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return false;
				}

				v8::Local<v8::External> const LocalIntegerPropertyMetadata = v8::External::New(pIsolate, pnIntegerPropertyValue);
				if (LocalIntegerPropertyMetadata.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return false;
				}

				const bool bPropertyInstalled = LocalTargetObject->SetNativeDataProperty(LocalContext, LocalPropertyName, GetStudioIntegerPropertyCallback, SetStudioIntegerPropertyCallback, LocalIntegerPropertyMetadata).FromMaybe(false);
				if (!bPropertyInstalled || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return false;
				}

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}

			return false;
		}

		char const* GetStudioCStringPropertyAddress(v8::Isolate* const pIsolate, v8::Local<v8::Value> const LocalStringPropertyMetadataValue) {
			constexpr char const* const kFailureErrorMessage = "studio could not resolve the string property address.";
			constexpr char const* const kInvalidStudioStringPropertyMetadataErrorMessage = "Studio string property metadata is invalid.";

			if (!pIsolate) {
				return nullptr;
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				if (LocalStringPropertyMetadataValue.IsEmpty() || !LocalStringPropertyMetadataValue->IsExternal()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kInvalidStudioStringPropertyMetadataErrorMessage);
					return nullptr;
				}

				v8::Local<v8::External> const LocalStringPropertyMetadata = LocalStringPropertyMetadataValue.As<v8::External>();
				char const* const pszStringPropertyValue = static_cast<char const*>(LocalStringPropertyMetadata->Value());

				return pszStringPropertyValue;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}

			return nullptr;
		}

		void GetStudioCStringPropertyCallback(v8::Local<v8::Name>, v8::PropertyCallbackInfo<v8::Value> const& PropertyInformation) {
			constexpr char const* const kFailureErrorMessage = "studio could not read the string property.";

			auto* const pIsolate = PropertyInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				char const* const pszStringPropertyValue = GetStudioCStringPropertyAddress(pIsolate, PropertyInformation.Data());
				if (StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				if (!pszStringPropertyValue) {
					PropertyInformation.GetReturnValue().Set(v8::Null(pIsolate));
					return;
				}

				v8::Local<v8::String> const LocalStringPropertyValue = MakeString(pIsolate, pszStringPropertyValue);
				if (LocalStringPropertyValue.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				PropertyInformation.GetReturnValue().Set(LocalStringPropertyValue);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}
		}

		bool InstallStudioCStringProperty(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalTargetObject, char const* const pszPropertyName, char const* const pszStringPropertyValue) {
			constexpr char const* const kFailureErrorMessage = "studio could not install the string property.";

			if (!pIsolate) {
				return false;
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				if (LocalContext.IsEmpty() || LocalTargetObject.IsEmpty() || !pszPropertyName || !*pszPropertyName) {
					return false;
				}

				v8::Local<v8::String> const LocalPropertyName = MakeString(pIsolate, pszPropertyName);
				if (LocalPropertyName.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return false;
				}

				// V8 External stores opaque metadata as void*, while the installed getter never mutates the borrowed SDK string.
				void* const pStringPropertyMetadata = const_cast<char*>(pszStringPropertyValue);
				v8::Local<v8::External> const LocalStringPropertyMetadata = v8::External::New(pIsolate, pStringPropertyMetadata);
				if (LocalStringPropertyMetadata.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return false;
				}

				const bool bPropertyInstalled = LocalTargetObject->SetNativeDataProperty(LocalContext, LocalPropertyName, GetStudioCStringPropertyCallback, nullptr, LocalStringPropertyMetadata).FromMaybe(false);
				if (!bPropertyInstalled || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return false;
				}

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}

			return false;
		}

