		v8::Local<v8::Array> MakeStudioIntegerArray(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, int* const pnIntegerValues, const int nElementCount) {
			constexpr char const* const kFailureErrorMessage = "studio could not create the integer array view.";
			constexpr char const* const kInvalidIntegerArrayArgumentsErrorMessage = "Studio integer array requires a valid address and non-negative element count.";

			if (!pIsolate) {
				return {};
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				if (LocalContext.IsEmpty()) {
					return {};
				}

				if (!pnIntegerValues || (nElementCount < 0)) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kInvalidIntegerArrayArgumentsErrorMessage);
					return {};
				}

				const std::size_t unElementCount = static_cast<std::size_t>(nElementCount);
				if (unElementCount > (std::numeric_limits<std::size_t>::max() / sizeof(int))) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return {};
				}

				if (unElementCount != 0) {
					const std::uintptr_t unIntegerArrayAddress = reinterpret_cast<std::uintptr_t>(pnIntegerValues);
					const std::size_t unIntegerArrayByteCount = unElementCount * sizeof(int);
					if (((unIntegerArrayAddress % alignof(int)) != 0) || !IsMemoryAddressRangeRepresentable(unIntegerArrayAddress, unIntegerArrayByteCount)) {
						RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
						return {};
					}
				}

				v8::Local<v8::Array> const LocalIntegerArray = v8::Array::New(pIsolate, nElementCount);
				if (LocalIntegerArray.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return {};
				}

				if (!InstallStudioAddress(pIsolate, LocalContext, LocalIntegerArray, pnIntegerValues) || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return {};
				}

				for (std::size_t unIndex = 0; unIndex < unElementCount; ++unIndex) {
					std::string const strElementIndex = std::to_string(unIndex);
					if (!InstallStudioIntegerProperty(pIsolate, LocalContext, LocalIntegerArray, strElementIndex.c_str(), &pnIntegerValues[unIndex]) || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
						return {};
					}
				}

				return LocalIntegerArray;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}

			return {};
		}

