		v8::Local<v8::Array> MakeStudioMatrix3x4Array(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, matrix3x4_t* const pMatrix3x4Value) {
			constexpr char const* const kFailureErrorMessage = "studio could not create the matrix3x4 view.";
			constexpr std::size_t kMatrixRowCount = 3;
			constexpr std::size_t kMatrixColumnCount = 4;
			constexpr char const* const kNullMatrix3x4AddressErrorMessage = "Studio matrix3x4 address is null.";

			static_assert(std::extent_v<decltype(matrix3x4_t::m_flMatVal), 0> == kMatrixRowCount, "unexpected matrix3x4 row count");
			static_assert(std::extent_v<decltype(matrix3x4_t::m_flMatVal), 1> == kMatrixColumnCount, "unexpected matrix3x4 column count");
			static_assert(kMatrixRowCount <= static_cast<std::size_t>(std::numeric_limits<int>::max()), "matrix3x4 row count exceeds the V8 array length range");
			static_assert(kMatrixColumnCount <= static_cast<std::size_t>(std::numeric_limits<int>::max()), "matrix3x4 column count exceeds the V8 array length range");

			if (!pIsolate) {
				return {};
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				if (LocalContext.IsEmpty()) {
					return {};
				}

				if (!pMatrix3x4Value) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kNullMatrix3x4AddressErrorMessage);
					return {};
				}

				const std::uintptr_t unStorageAddress = reinterpret_cast<std::uintptr_t>(pMatrix3x4Value);
				if (((unStorageAddress % alignof(matrix3x4_t)) != 0) || !IsMemoryAddressRangeRepresentable(unStorageAddress, sizeof(matrix3x4_t))) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return {};
				}

				v8::Local<v8::Array> const LocalMatrixRows = v8::Array::New(pIsolate, static_cast<int>(kMatrixRowCount));
				if (LocalMatrixRows.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return {};
				}

				if (!InstallStudioAddress(pIsolate, LocalContext, LocalMatrixRows, pMatrix3x4Value) || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return {};
				}

				for (std::size_t unRowIndex = 0; unRowIndex < kMatrixRowCount; ++unRowIndex) {
					v8::Local<v8::Array> const LocalMatrixRow = v8::Array::New(pIsolate, static_cast<int>(kMatrixColumnCount));
					if (LocalMatrixRow.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
						return {};
					}

					for (std::size_t unColumnIndex = 0; unColumnIndex < kMatrixColumnCount; ++unColumnIndex) {
						std::string const strColumnPropertyName = std::to_string(unColumnIndex);
						if (!InstallStudioFloatProperty(pIsolate, LocalContext, LocalMatrixRow, strColumnPropertyName.c_str(), &(*pMatrix3x4Value)[static_cast<int>(unRowIndex)][unColumnIndex]) || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
							RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
							return {};
						}
					}

					if (!LocalMatrixRows->CreateDataProperty(LocalContext, static_cast<std::uint32_t>(unRowIndex), LocalMatrixRow).FromMaybe(false) || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
						return {};
					}
				}

				return LocalMatrixRows;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}

			return {};
		}

		bool GetStudioAddressFromValue(v8::Local<v8::Value> const LocalAddressValue, std::uintptr_t& unAddressOut) {
			constexpr char const* const kFailureErrorMessage = "studio could not convert the native address.";

			if (LocalAddressValue.IsEmpty() || !LocalAddressValue->IsBigInt()) {
				return false;
			}

			auto* const pIsolate = v8::Isolate::GetCurrent();
			if (!pIsolate) {
				return false;
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				bool bLossless = false;
				const std::uint64_t unAddressValue = LocalAddressValue.As<v8::BigInt>()->Uint64Value(&bLossless);
				if (StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return false;
				}

				if (!bLossless || (unAddressValue > std::numeric_limits<std::uintptr_t>::max())) {
					return false;
				}

				unAddressOut = static_cast<std::uintptr_t>(unAddressValue);

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}

			return false;
		}

		bool GetStudioAddressFromObject(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalSourceObject, std::uintptr_t& unAddressOut) {
			constexpr char const* const kFailureErrorMessage = "studio could not read the native address.";
			constexpr char const* const kAddressPropertyName = "Address";

			if (!pIsolate) {
				return false;
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				if (LocalContext.IsEmpty() || LocalSourceObject.IsEmpty()) {
					return false;
				}

				v8::Local<v8::String> const LocalAddressPropertyName = MakeString(pIsolate, kAddressPropertyName);
				if (LocalAddressPropertyName.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return false;
				}

				v8::Local<v8::Value> LocalAddressValue {};
				if (!LocalSourceObject->Get(LocalContext, LocalAddressPropertyName).ToLocal(&LocalAddressValue) || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return false;
				}

				std::uintptr_t unAddress = 0x0;
				const bool bAddressConverted = GetStudioAddressFromValue(LocalAddressValue, unAddress);
				if (StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return false;
				}

				if (!bAddressConverted) {
					return false;
				}

				unAddressOut = unAddress;

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}

			return false;
		}

		studiohdr_t* GetStudioHeaderFromObject(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalStudioHeaderObject) {
			constexpr char const* const kFailureErrorMessage = "studio could not resolve the header address.";

			if (!pIsolate) {
				return nullptr;
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				if (LocalContext.IsEmpty() || LocalStudioHeaderObject.IsEmpty()) {
					return nullptr;
				}

				std::uintptr_t unStudioHeaderAddress = 0x0;
				const bool bAddressResolved = GetStudioAddressFromObject(pIsolate, LocalContext, LocalStudioHeaderObject, unStudioHeaderAddress);
				if (StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return nullptr;
				}

				if (!bAddressResolved) {
					return nullptr;
				}

				if (!unStudioHeaderAddress) {
					return nullptr;
				}

				if ((unStudioHeaderAddress % alignof(studiohdr_t)) != 0) {
					return nullptr;
				}

				if (!IsMemoryAddressRangeRepresentable(unStudioHeaderAddress, sizeof(studiohdr_t))) {
					return nullptr;
				}

				return reinterpret_cast<studiohdr_t*>(unStudioHeaderAddress);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}

			return nullptr;
		}

