		bool GetStudioCollectionOperationFromCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, StudioCollectionOperation& CollectionOperationOut) {
			constexpr char const* const kFailureErrorMessage = "studio could not read the collection operation.";
			constexpr char const* const kInvalidStudioCollectionOperationErrorMessage = "Studio collection operation is invalid.";
			constexpr char const* const kStudioCollectionOperationRangeErrorMessage = "Studio collection operation is outside the supported range.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return false;
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				v8::Local<v8::Value> const LocalStudioCollectionOperationData = CallbackInformation.Data();
				if (LocalStudioCollectionOperationData.IsEmpty() || !LocalStudioCollectionOperationData->IsInt32()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kInvalidStudioCollectionOperationErrorMessage);
					return false;
				}

				v8::Local<v8::Int32> const LocalStudioCollectionOperationValue = LocalStudioCollectionOperationData.As<v8::Int32>();
				const int nStudioCollectionOperationValue = LocalStudioCollectionOperationValue->Value();
				if ((nStudioCollectionOperationValue < static_cast<int>(StudioCollectionOperation::Bones)) || (nStudioCollectionOperationValue > static_cast<int>(StudioCollectionOperation::Attachments))) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kStudioCollectionOperationRangeErrorMessage);
					return false;
				}

				CollectionOperationOut = static_cast<StudioCollectionOperation>(nStudioCollectionOperationValue);

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}

			return false;
		}

