		void GetStudioHitboxSetHitboxCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char const* const kFailureErrorMessage = "studio could not get the hitbox from the hitbox set.";
			constexpr int kHitboxIndexArgumentIndex = 0;
			constexpr int kDefaultHitboxIndex = 0;
			constexpr char const* const kGetHitboxOperationName = "HitboxSet.GetHitbox(nHitboxIndex)";
			constexpr char const* const kHitboxIndexErrorMessage = "HitboxSet.GetHitbox(nHitboxIndex) expects a non-negative integer index.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				auto* const pStudioHitboxSet = RequireStudioHitboxSetFromThis(CallbackInformation, kGetHitboxOperationName);
				if (!pStudioHitboxSet || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				int nHitboxIndex = 0;
				if (!GetStudioIndexArgument(CallbackInformation, kHitboxIndexArgumentIndex, false, kDefaultHitboxIndex, kHitboxIndexErrorMessage, nHitboxIndex) || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				auto* const pStudioHitbox = (nHitboxIndex < pStudioHitboxSet->numhitboxes) ? pStudioHitboxSet->pHitbox(nHitboxIndex) : nullptr;
				if (!pStudioHitbox) {
					CallbackInformation.GetReturnValue().Set(v8::Null(pIsolate));
					return;
				}

				v8::Local<v8::Object> const LocalHitboxObject = MakeStudioHitboxObject(pIsolate, LocalContext, pStudioHitbox);
				if (LocalHitboxObject.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalHitboxObject);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}
		}

		void GetStudioHitboxSetHitboxesCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char const* const kFailureErrorMessage = "studio could not enumerate the hitbox set.";
			constexpr char const* const kHitboxesOperationName = "HitboxSet.Hitboxes()";
			constexpr char const* const kNegativeHitboxSetHitboxCountErrorMessage = "HitboxSet hitbox count is negative.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				auto* const pStudioHitboxSet = RequireStudioHitboxSetFromThis(CallbackInformation, kHitboxesOperationName);
				if (!pStudioHitboxSet || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				const int nHitboxCount = pStudioHitboxSet->numhitboxes;
				if (nHitboxCount < 0) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kNegativeHitboxSetHitboxCountErrorMessage);
					return;
				}

				const std::size_t unHitboxCount = static_cast<std::size_t>(nHitboxCount);
				if (unHitboxCount > (std::numeric_limits<std::size_t>::max() / sizeof(mstudiobbox_t))) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				if (unHitboxCount > 0) {
					auto* const pFirstStudioHitbox = pStudioHitboxSet->pHitbox(0);
					const std::uintptr_t unHitboxStorageAddress = reinterpret_cast<std::uintptr_t>(pFirstStudioHitbox);
					const std::size_t unHitboxStorageByteCount = unHitboxCount * sizeof(mstudiobbox_t);
					if (((unHitboxStorageAddress % alignof(mstudiobbox_t)) != 0) || !IsMemoryAddressRangeRepresentable(unHitboxStorageAddress, unHitboxStorageByteCount)) {
						RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
						return;
					}
				}

				v8::Local<v8::Array> const LocalHitboxArray = v8::Array::New(pIsolate, nHitboxCount);
				if (LocalHitboxArray.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				for (int nHitboxIndex = 0; nHitboxIndex < nHitboxCount; ++nHitboxIndex) {
					auto* const pStudioHitbox = pStudioHitboxSet->pHitbox(nHitboxIndex);
					v8::Local<v8::Object> const LocalHitboxObject = MakeStudioHitboxObject(pIsolate, LocalContext, pStudioHitbox);
					if (LocalHitboxObject.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
						return;
					}

					const bool bHitboxInstalled = LocalHitboxArray->CreateDataProperty(LocalContext, static_cast<std::uint32_t>(nHitboxIndex), LocalHitboxObject).FromMaybe(false);
					if (!bHitboxInstalled || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
						return;
					}
				}

				CallbackInformation.GetReturnValue().Set(LocalHitboxArray);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}
		}

