		void GetStudioSequenceModelHeaderCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char const* const kFailureErrorMessage = "studio could not resolve the sequence model header.";
			constexpr char const* const kGetModelHeaderOperationName = "Sequence.GetModelHeader()";
			constexpr char const* const kStudioHeaderResolutionErrorMessage = "Sequence.GetModelHeader() cannot resolve the SDK model header.";

			auto* const pCallbackIsolate = CallbackInformation.GetIsolate();
			if (!pCallbackIsolate) {
				return;
			}

			v8::TryCatch StudioFailure(pCallbackIsolate);
			try {
				v8::Local<v8::Context> const LocalCallbackContext = pCallbackIsolate->GetCurrentContext();
				if (LocalCallbackContext.IsEmpty()) {
					return;
				}

				auto* const pCallbackStudioSequence = RequireStudioSequenceFromThis(CallbackInformation, kGetModelHeaderOperationName);
				if (!pCallbackStudioSequence || StudioFailure.HasCaught() || pCallbackIsolate->IsExecutionTerminating() || pCallbackIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pCallbackIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				const std::uintptr_t unCallbackStudioSequenceAddress = reinterpret_cast<std::uintptr_t>(pCallbackStudioSequence);
				if (!IsMemoryAddressRangeRepresentable(unCallbackStudioSequenceAddress, sizeof(mstudioseqdesc_t))) {
					RethrowV8InstallationFailure(pCallbackIsolate, StudioFailure, kStudioHeaderResolutionErrorMessage);
					return;
				}

				std::uintptr_t unCallbackStudioHeaderAddress = 0x0;
				if (!ApplyMemoryAddressOffset(pCallbackIsolate, unCallbackStudioSequenceAddress, static_cast<std::int64_t>(pCallbackStudioSequence->baseptr), false, kStudioHeaderResolutionErrorMessage, unCallbackStudioHeaderAddress) || StudioFailure.HasCaught() || pCallbackIsolate->IsExecutionTerminating() || pCallbackIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pCallbackIsolate, StudioFailure, kStudioHeaderResolutionErrorMessage);
					return;
				}

				auto* const pCallbackStudioHeader = reinterpret_cast<studiohdr_t*>(unCallbackStudioHeaderAddress);
				v8::Local<v8::Object> const LocalStudioHeaderObject = MakeStudioHeaderObject(pCallbackIsolate, LocalCallbackContext, pCallbackStudioHeader);
				if (LocalStudioHeaderObject.IsEmpty() || StudioFailure.HasCaught() || pCallbackIsolate->IsExecutionTerminating() || pCallbackIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pCallbackIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalStudioHeaderObject);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pCallbackIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pCallbackIsolate, StudioFailure, kFailureErrorMessage);
			}
		}

