		// A failed lookup publication must release the reference acquired by IMDLCache::FindMDL.
		class StudioModelReferenceOwner {
		public:
			StudioModelReferenceOwner(IMDLCache* const pStudioModelCache, const MDLHandle_t hModelHandle) noexcept;
			~StudioModelReferenceOwner() noexcept;

			StudioModelReferenceOwner(StudioModelReferenceOwner const&) = delete;
			StudioModelReferenceOwner& operator=(StudioModelReferenceOwner const&) = delete;
			StudioModelReferenceOwner(StudioModelReferenceOwner&&) = delete;
			StudioModelReferenceOwner& operator=(StudioModelReferenceOwner&&) = delete;

			void ReleaseOwnership() noexcept;

		private:
			IMDLCache* m_pStudioModelCache;
			MDLHandle_t m_hModelHandle;
		};

		StudioModelReferenceOwner::StudioModelReferenceOwner(IMDLCache* const pStudioModelCache, const MDLHandle_t hModelHandle) noexcept :
			m_pStudioModelCache(pStudioModelCache),
			m_hModelHandle(hModelHandle)
		{
		}

		StudioModelReferenceOwner::~StudioModelReferenceOwner() noexcept {
			constexpr char const* const kReleaseFailureErrorMessage = "studio/cache lookup-reference cleanup failed Handle=%u.";

			if (!m_pStudioModelCache || (m_hModelHandle == MDLHANDLE_INVALID)) {
				return;
			}

			try {
				m_pStudioModelCache->Release(m_hModelHandle);
			} catch (std::exception const&) {
				LogError(kReleaseFailureErrorMessage, static_cast<unsigned int>(m_hModelHandle));
			} catch (...) {
				LogError(kReleaseFailureErrorMessage, static_cast<unsigned int>(m_hModelHandle));
			}
		}

		void StudioModelReferenceOwner::ReleaseOwnership() noexcept {
			m_hModelHandle = MDLHANDLE_INVALID;
			m_pStudioModelCache = nullptr;
		}

		void FindStudioModelCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char const* const kFailureErrorMessage = "studio/cache.FindModel(strModelPath) failed.";
			constexpr int kModelPathArgumentIndex = 0;
			constexpr int kRequiredArgumentCount = 1;
			constexpr char const* const kFindModelOperationName = "studio/cache.FindModel(strModelPath)";
			constexpr char const* const kModelPathTypeErrorMessage = "studio/cache.FindModel(strModelPath) expects a model path.";
			constexpr char const* const kEmptyModelPathErrorMessage = "studio/cache.FindModel(strModelPath) expects a non-empty model path.";
			constexpr char const* const kEmbeddedNullModelPathErrorMessage = "studio/cache model paths must not contain embedded NUL bytes.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				if (CallbackInformation.Length() < kRequiredArgumentCount) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kModelPathTypeErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalModelPathValue = CallbackInformation[kModelPathArgumentIndex];
				if (LocalModelPathValue.IsEmpty() || !LocalModelPathValue->IsString() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kModelPathTypeErrorMessage);
					return;
				}

				std::string const strModelPath = ValueToString(pIsolate, LocalModelPathValue);
				if (StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				if (strModelPath.empty()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kEmptyModelPathErrorMessage);
					return;
				}

				if (strModelPath.find('\0') != std::string::npos) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kEmbeddedNullModelPathErrorMessage);
					return;
				}

				auto* const pStudioModelCache = RequireStudioModelCache(pIsolate, kFindModelOperationName);
				if (!pStudioModelCache || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				const MDLHandle_t hModelHandle = pStudioModelCache->FindMDL(strModelPath.c_str());
				StudioModelReferenceOwner ReferenceOwner = StudioModelReferenceOwner(pStudioModelCache, hModelHandle);
				if (StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				v8::Local<v8::Object> const LocalStudioModelObject = MakeStudioModelObject(pIsolate, LocalContext, hModelHandle);
				if (LocalStudioModelObject.IsEmpty() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalStudioModelObject);
				ReferenceOwner.ReleaseOwnership();
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}
		}

		void FindStudioModelHandleCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char const* const kFailureErrorMessage = "studio/cache.FindModelHandle(strModelPath) failed.";
			constexpr int kModelPathArgumentIndex = 0;
			constexpr int kRequiredArgumentCount = 1;
			constexpr char const* const kFindModelHandleOperationName = "studio/cache.FindModelHandle(strModelPath)";
			constexpr char const* const kModelPathTypeErrorMessage = "studio/cache.FindModelHandle(strModelPath) expects a model path.";
			constexpr char const* const kEmptyModelPathErrorMessage = "studio/cache.FindModelHandle(strModelPath) expects a non-empty model path.";
			constexpr char const* const kEmbeddedNullModelPathErrorMessage = "studio/cache model paths must not contain embedded NUL bytes.";

			static_assert(static_cast<std::uint64_t>(std::numeric_limits<MDLHandle_t>::max()) <= static_cast<std::uint64_t>(std::numeric_limits<int>::max()), "Studio model handles must fit in V8 integer values.");

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				if (CallbackInformation.Length() < kRequiredArgumentCount) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kModelPathTypeErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalModelPathValue = CallbackInformation[kModelPathArgumentIndex];
				if (LocalModelPathValue.IsEmpty() || !LocalModelPathValue->IsString() || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kModelPathTypeErrorMessage);
					return;
				}

				std::string const strModelPath = ValueToString(pIsolate, LocalModelPathValue);
				if (StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				if (strModelPath.empty()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kEmptyModelPathErrorMessage);
					return;
				}

				if (strModelPath.find('\0') != std::string::npos) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kEmbeddedNullModelPathErrorMessage);
					return;
				}

				auto* const pStudioModelCache = RequireStudioModelCache(pIsolate, kFindModelHandleOperationName);
				if (!pStudioModelCache || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				const MDLHandle_t hModelHandle = pStudioModelCache->FindMDL(strModelPath.c_str());
				StudioModelReferenceOwner ReferenceOwner = StudioModelReferenceOwner(pStudioModelCache, hModelHandle);
				if (StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				CallbackInformation.GetReturnValue().Set(static_cast<int>(hModelHandle));
				ReferenceOwner.ReleaseOwnership();
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}
		}

		void AddStudioReferenceCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char const* const kFailureErrorMessage = "studio/cache.AddReference(hModelHandle) failed.";
			constexpr int kModelHandleArgumentIndex = 0;
			constexpr int kRequiredArgumentCount = 1;
			constexpr char const* const kAddReferenceOperationName = "studio/cache.AddReference(hModelHandle)";
			constexpr char const* const kModelHandleTypeErrorMessage = "studio/cache.AddReference(hModelHandle) expects a model handle.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch StudioFailure(pIsolate);
			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return;
				}

				if (CallbackInformation.Length() < kRequiredArgumentCount) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kModelHandleTypeErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalModelHandleValue = CallbackInformation[kModelHandleArgumentIndex];
				MDLHandle_t hModelHandle = MDLHANDLE_INVALID;
				if (!GetStudioModelHandleFromValue(LocalContext, LocalModelHandleValue, hModelHandle) || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kModelHandleTypeErrorMessage);
					return;
				}

				if (!RequireStudioModelHandle(pIsolate, kAddReferenceOperationName, hModelHandle) || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				auto* const pStudioModelCache = RequireStudioModelCache(pIsolate, kAddReferenceOperationName);
				if (!pStudioModelCache || StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				const int nReferenceCount = pStudioModelCache->AddRef(hModelHandle);
				if (StudioFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
					return;
				}

				CallbackInformation.GetReturnValue().Set(nReferenceCount);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, StudioFailure, kFailureErrorMessage);
			}
		}

