		void GetPhysicsGravityCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char const* const kFailureErrorMessage = "physics.Gravity() failed.";
			constexpr char const* const kGravityConVarName = "sv_gravity";
			constexpr char const* const kMissingGravityConVarErrorMessage = "sv_gravity is not available.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch PhysicsFailure(pIsolate);
			try {
				auto* const pCVarInterface = RequireCVarInterface(pIsolate);
				if (!pCVarInterface || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				auto* const pGravityConVar = pCVarInterface->FindVar(kGravityConVarName);
				if (!pGravityConVar || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kMissingGravityConVarErrorMessage);
					return;
				}

				const float flGravity = pGravityConVar->GetFloat();
				if (PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				CallbackInformation.GetReturnValue().Set(flGravity);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
			}
		}

