		IPhysicsEnvironment* GetPhysicsEnvironmentFromValue(v8::Local<v8::Value> const LocalPhysicsEnvironmentValue) noexcept {
			std::uintptr_t unPhysicsEnvironmentAddress = 0x0;
			if (!GetAddressSizedUnsignedIntegerFromValue(LocalPhysicsEnvironmentValue, unPhysicsEnvironmentAddress)) {
				return nullptr;
			}

			if ((unPhysicsEnvironmentAddress == 0x0) || ((unPhysicsEnvironmentAddress % alignof(IPhysicsEnvironment)) != 0)) {
				return nullptr;
			}

			return reinterpret_cast<IPhysicsEnvironment*>(unPhysicsEnvironmentAddress);
		}

		IPhysicsEnvironment* GetPhysicsEnvironmentFromThis(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char const* const kFailureErrorMessage = "physics environment receiver resolution failed.";
			constexpr char const* const kPhysicsEnvironmentAddressPropertyName = "Address";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return nullptr;
			}

			v8::TryCatch PhysicsFailure(pIsolate);
			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty()) {
					return nullptr;
				}

				v8::Local<v8::Object> const LocalPhysicsEnvironmentObject = CallbackInformation.This();
				if (LocalPhysicsEnvironmentObject.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return nullptr;
				}

				v8::Local<v8::String> const LocalPhysicsEnvironmentAddressPropertyName = MakeString(pIsolate, kPhysicsEnvironmentAddressPropertyName);
				if (LocalPhysicsEnvironmentAddressPropertyName.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return nullptr;
				}

				v8::Local<v8::Value> LocalPhysicsEnvironmentAddressValue {};
				const bool bHasPhysicsEnvironmentAddressValue = LocalPhysicsEnvironmentObject->Get(LocalContext, LocalPhysicsEnvironmentAddressPropertyName).ToLocal(&LocalPhysicsEnvironmentAddressValue);
				if (!bHasPhysicsEnvironmentAddressValue || LocalPhysicsEnvironmentAddressValue.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return nullptr;
				}

				auto* const pPhysicsEnvironment = GetPhysicsEnvironmentFromValue(LocalPhysicsEnvironmentAddressValue);
				if (PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return nullptr;
				}

				return pPhysicsEnvironment;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
			}

			return nullptr;
		}

