		template <typename TOperation>
		bool GetPhysicsOperationFromCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, TOperation& OperationOut) {
			constexpr char const* const kFailureErrorMessage = "physics binding operation lookup failed.";
			constexpr char const* const kInvalidOperationErrorMessage = "Physics binding operation is invalid.";

			static_assert(std::is_enum_v<TOperation>, "Physics binding operations require an enum type.");
			static_assert(std::is_same_v<std::underlying_type_t<TOperation>, int>, "Physics binding operation enums must use int storage.");

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return false;
			}

			v8::TryCatch PhysicsFailure(pIsolate);
			try {
				v8::Local<v8::Value> const LocalOperationMetadata = CallbackInformation.Data();
				if (LocalOperationMetadata.IsEmpty() || !LocalOperationMetadata->IsInt32() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kInvalidOperationErrorMessage);
					return false;
				}

				const int nOperationValue = LocalOperationMetadata.As<v8::Int32>()->Value();
				if (PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return false;
				}

				OperationOut = static_cast<TOperation>(nOperationValue);

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
			}

			return false;
		}

