		void SetPhysicsObjectBooleanStateCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char const* const kFailureErrorMessage = "physics boolean state update failed.";
			constexpr int kPhysicsObjectBooleanSetterEnabledArgumentIndex = 0;
			constexpr bool kDefaultPhysicsObjectBooleanSetterEnabled = true;
			constexpr char const* const kUnknownPhysicsObjectBooleanSetterOperationErrorMessage = "Unknown physics object boolean setter operation.";
			constexpr char const* const kPhysicsObjectBooleanSetterArgumentErrorMessages[] = {
				"PhysicsObject.EnableCollisions(bPhysicsObjectBooleanSetterEnabled?) expects a boolean value.",
				"PhysicsObject.EnableGravity(bPhysicsObjectBooleanSetterEnabled?) expects a boolean value.",
				"PhysicsObject.EnableDrag(bPhysicsObjectBooleanSetterEnabled?) expects a boolean value.",
				"PhysicsObject.EnableMotion(bPhysicsObjectBooleanSetterEnabled?) expects a boolean value.",
				"PhysicsObject.SetAsleep(bPhysicsObjectBooleanSetterEnabled?) expects a boolean value."
			};
			constexpr std::size_t kPhysicsObjectBooleanSetterArgumentErrorMessageCount = sizeof(kPhysicsObjectBooleanSetterArgumentErrorMessages) / sizeof(kPhysicsObjectBooleanSetterArgumentErrorMessages[0]);

			static_assert(kPhysicsObjectBooleanSetterArgumentErrorMessageCount == (static_cast<std::size_t>(PhysicsObjectBooleanSetterOperation::PhysicsObjectSetAsleep) + 1), "Physics object boolean setter diagnostics must match the operation enum.");

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch PhysicsFailure(pIsolate);
			try {
				auto* const pPhysicsObject = RequirePhysicsObjectFromThis(CallbackInformation);
				if (!pPhysicsObject || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				PhysicsObjectBooleanSetterOperation BooleanSetterOperation = PhysicsObjectBooleanSetterOperation::PhysicsObjectSetCollisions;
				if (!GetPhysicsOperationFromCallback(CallbackInformation, BooleanSetterOperation) || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				if ((BooleanSetterOperation < PhysicsObjectBooleanSetterOperation::PhysicsObjectSetCollisions) || (BooleanSetterOperation > PhysicsObjectBooleanSetterOperation::PhysicsObjectSetAsleep)) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kUnknownPhysicsObjectBooleanSetterOperationErrorMessage);
					return;
				}

				const std::size_t unPhysicsObjectBooleanSetterOperationIndex = static_cast<std::size_t>(BooleanSetterOperation);
				char const* const pszPhysicsObjectBooleanSetterArgumentErrorMessage = kPhysicsObjectBooleanSetterArgumentErrorMessages[unPhysicsObjectBooleanSetterOperationIndex];
				bool bPhysicsObjectBooleanSetterEnabled = kDefaultPhysicsObjectBooleanSetterEnabled;
				if (((CallbackInformation.Length() > kPhysicsObjectBooleanSetterEnabledArgumentIndex) && !GetPhysicsBooleanFromValue(pIsolate, CallbackInformation[kPhysicsObjectBooleanSetterEnabledArgumentIndex], pszPhysicsObjectBooleanSetterArgumentErrorMessage, bPhysicsObjectBooleanSetterEnabled)) || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				switch (BooleanSetterOperation) {
					case PhysicsObjectBooleanSetterOperation::PhysicsObjectSetCollisions:
						pPhysicsObject->EnableCollisions(bPhysicsObjectBooleanSetterEnabled);
						break;

					case PhysicsObjectBooleanSetterOperation::PhysicsObjectSetGravity:
						pPhysicsObject->EnableGravity(bPhysicsObjectBooleanSetterEnabled);
						break;

					case PhysicsObjectBooleanSetterOperation::PhysicsObjectSetDrag:
						pPhysicsObject->EnableDrag(bPhysicsObjectBooleanSetterEnabled);
						break;

					case PhysicsObjectBooleanSetterOperation::PhysicsObjectSetMotion:
						pPhysicsObject->EnableMotion(bPhysicsObjectBooleanSetterEnabled);
						break;

					case PhysicsObjectBooleanSetterOperation::PhysicsObjectSetAsleep:
						if (bPhysicsObjectBooleanSetterEnabled) {
							pPhysicsObject->Sleep();
						} else {
							pPhysicsObject->Wake();
						}

						break;
				}

				if (PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				CallbackInformation.GetReturnValue().Set(true);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
			}
		}

