		bool ParsePhysicsVelocityArguments(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, Vector& LinearVelocityValueOut, AngularImpulse& AngularVelocityValueOut, Vector const*& pLinearVelocityOut, AngularImpulse const*& pAngularVelocityOut) {
			constexpr char const* const kFailureErrorMessage = "physics velocity argument parsing failed.";
			constexpr int kPhysicsLinearVelocityArgumentIndex = 0;
			constexpr int kPhysicsAngularVelocityArgumentIndex = 1;
			constexpr char const* const kPhysicsLinearVelocityVectorPropertyName = "LinearVelocity";
			constexpr char const* const kPhysicsAngularVelocityVectorPropertyName = "AngularVelocity";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return false;
			}

			v8::TryCatch PhysicsFailure(pIsolate);
			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, nullptr);
					return false;
				}

				Vector LinearVelocityValue = Vector(0, 0, 0);
				AngularImpulse AngularVelocityValue = AngularImpulse(0, 0, 0);
				bool bHasLinearVelocity = false;
				bool bHasAngularVelocity = false;

				auto ParsePrimaryPhysicsVelocityArgument = [pIsolate, LocalContext, kPhysicsLinearVelocityVectorPropertyName, kPhysicsAngularVelocityVectorPropertyName, &LinearVelocityValue, &AngularVelocityValue, &bHasLinearVelocity, &bHasAngularVelocity, &PhysicsFailure](v8::Local<v8::Value> const LocalPhysicsLinearVelocityArgument) -> bool {
					if (LocalPhysicsLinearVelocityArgument.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, PhysicsFailure, nullptr);
						return false;
					}

					if (!LocalPhysicsLinearVelocityArgument->IsObject()) {
						if (!GetPhysicsVectorFromValue(pIsolate, LocalContext, LocalPhysicsLinearVelocityArgument, LinearVelocityValue) || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
							RethrowV8InstallationFailure(pIsolate, PhysicsFailure, nullptr);
							return false;
						}

						bHasLinearVelocity = true;
						return true;
					}

					v8::Local<v8::Object> const LocalPhysicsVelocityOptionsObject = LocalPhysicsLinearVelocityArgument.As<v8::Object>();
					if (LocalPhysicsVelocityOptionsObject.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, PhysicsFailure, nullptr);
						return false;
					}

					v8::Local<v8::Value> const LocalPhysicsNamedLinearVelocityValue = GetTraceObjectPropertyValue(pIsolate, LocalContext, LocalPhysicsVelocityOptionsObject, kPhysicsLinearVelocityVectorPropertyName);
					if (LocalPhysicsNamedLinearVelocityValue.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, PhysicsFailure, nullptr);
						return false;
					}

					v8::Local<v8::Value> const LocalPhysicsNamedAngularVelocityValue = GetTraceObjectPropertyValue(pIsolate, LocalContext, LocalPhysicsVelocityOptionsObject, kPhysicsAngularVelocityVectorPropertyName);
					if (LocalPhysicsNamedAngularVelocityValue.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, PhysicsFailure, nullptr);
						return false;
					}

					const bool bHasNamedPhysicsLinearVelocity = !IsValueNullish(LocalPhysicsNamedLinearVelocityValue);
					const bool bHasNamedPhysicsAngularVelocity = !IsValueNullish(LocalPhysicsNamedAngularVelocityValue);
					if (!bHasNamedPhysicsLinearVelocity && !bHasNamedPhysicsAngularVelocity) {
						if (!GetPhysicsVectorFromValue(pIsolate, LocalContext, LocalPhysicsLinearVelocityArgument, LinearVelocityValue) || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
							RethrowV8InstallationFailure(pIsolate, PhysicsFailure, nullptr);
							return false;
						}

						bHasLinearVelocity = true;
						return true;
					}

					if (bHasNamedPhysicsLinearVelocity) {
						if (!GetPhysicsVectorFromValue(pIsolate, LocalContext, LocalPhysicsNamedLinearVelocityValue, LinearVelocityValue) || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
							RethrowV8InstallationFailure(pIsolate, PhysicsFailure, nullptr);
							return false;
						}

						bHasLinearVelocity = true;
					}

					if (bHasNamedPhysicsAngularVelocity) {
						if (!GetPhysicsVectorFromValue(pIsolate, LocalContext, LocalPhysicsNamedAngularVelocityValue, AngularVelocityValue) || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
							RethrowV8InstallationFailure(pIsolate, PhysicsFailure, nullptr);
							return false;
						}

						bHasAngularVelocity = true;
					}

					return true;
				};

				if (CallbackInformation.Length() > kPhysicsLinearVelocityArgumentIndex) {
					v8::Local<v8::Value> const LocalPhysicsLinearVelocityArgument = CallbackInformation[kPhysicsLinearVelocityArgumentIndex];
					if (LocalPhysicsLinearVelocityArgument.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, PhysicsFailure, nullptr);
						return false;
					}

					if ((!IsValueNullish(LocalPhysicsLinearVelocityArgument) && !ParsePrimaryPhysicsVelocityArgument(LocalPhysicsLinearVelocityArgument)) || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, PhysicsFailure, nullptr);
						return false;
					}
				}

				if (CallbackInformation.Length() > kPhysicsAngularVelocityArgumentIndex) {
					v8::Local<v8::Value> const LocalPhysicsAngularVelocityArgument = CallbackInformation[kPhysicsAngularVelocityArgumentIndex];
					if (LocalPhysicsAngularVelocityArgument.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, PhysicsFailure, nullptr);
						return false;
					}

					if (!IsValueNullish(LocalPhysicsAngularVelocityArgument)) {
						if (!GetPhysicsVectorFromValue(pIsolate, LocalContext, LocalPhysicsAngularVelocityArgument, AngularVelocityValue) || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
							RethrowV8InstallationFailure(pIsolate, PhysicsFailure, nullptr);
							return false;
						}

						bHasAngularVelocity = true;
					}
				}

				if (!bHasLinearVelocity && !bHasAngularVelocity) {
					return false;
				}

				if (PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, nullptr);
					return false;
				}

				if (bHasLinearVelocity) {
					LinearVelocityValueOut = LinearVelocityValue;
					pLinearVelocityOut = &LinearVelocityValueOut;
				} else {
					pLinearVelocityOut = nullptr;
				}

				if (bHasAngularVelocity) {
					AngularVelocityValueOut = AngularVelocityValue;
					pAngularVelocityOut = &AngularVelocityValueOut;
				} else {
					pAngularVelocityOut = nullptr;
				}

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
			}

			return false;
		}

