		void TransformPhysicsObjectVectorCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char const* const kFailureErrorMessage = "physics vector transformation failed.";
			constexpr int kPhysicsObjectVectorTransformArgumentIndex = 0;
			constexpr int kPhysicsObjectVectorTransformRequiredArgumentCount = 1;
			constexpr char const* const kPhysicsObjectVectorTransformUnknownOperationErrorMessage = "Unknown PhysicsObject vector transform operation.";
			constexpr char const* const kPhysicsObjectVectorTransformArgumentErrorMessages[] = {
				"PhysicsObject.LocalToWorld(PhysicsObjectVectorTransformInput) expects a vector.",
				"PhysicsObject.WorldToLocal(PhysicsObjectVectorTransformInput) expects a vector.",
				"PhysicsObject.LocalToWorldVector(PhysicsObjectVectorTransformInput) expects a vector.",
				"PhysicsObject.WorldToLocalVector(PhysicsObjectVectorTransformInput) expects a vector."
			};
			constexpr std::size_t kPhysicsObjectVectorTransformArgumentErrorMessageCount = sizeof(kPhysicsObjectVectorTransformArgumentErrorMessages) / sizeof(kPhysicsObjectVectorTransformArgumentErrorMessages[0]);

			static_assert(kPhysicsObjectVectorTransformArgumentErrorMessageCount == (static_cast<std::size_t>(PhysicsObjectVectorTransformOperation::PhysicsObjectVectorTransformWorldToLocalVector) + 1), "Physics object vector transform diagnostics must match the operation enum.");

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch PhysicsFailure(pIsolate);
			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				auto* const pPhysicsObject = RequirePhysicsObjectFromThis(CallbackInformation);
				if (!pPhysicsObject || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				PhysicsObjectVectorTransformOperation VectorTransformOperation = PhysicsObjectVectorTransformOperation::PhysicsObjectVectorTransformLocalToWorld;
				if (!GetPhysicsOperationFromCallback(CallbackInformation, VectorTransformOperation) || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				if ((VectorTransformOperation < PhysicsObjectVectorTransformOperation::PhysicsObjectVectorTransformLocalToWorld) || (VectorTransformOperation > PhysicsObjectVectorTransformOperation::PhysicsObjectVectorTransformWorldToLocalVector)) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kPhysicsObjectVectorTransformUnknownOperationErrorMessage);
					return;
				}

				const std::size_t unPhysicsObjectVectorTransformOperationIndex = static_cast<std::size_t>(VectorTransformOperation);
				char const* const pszPhysicsObjectVectorTransformArgumentErrorMessage = kPhysicsObjectVectorTransformArgumentErrorMessages[unPhysicsObjectVectorTransformOperationIndex];
				if (CallbackInformation.Length() < kPhysicsObjectVectorTransformRequiredArgumentCount) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, pszPhysicsObjectVectorTransformArgumentErrorMessage);
					return;
				}

				v8::Local<v8::Value> const LocalPhysicsObjectVectorTransformArgument = CallbackInformation[kPhysicsObjectVectorTransformArgumentIndex];
				if (LocalPhysicsObjectVectorTransformArgument.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, pszPhysicsObjectVectorTransformArgumentErrorMessage);
					return;
				}

				Vector PhysicsObjectVectorTransformInput = Vector(0, 0, 0);
				Vector PhysicsObjectVectorTransformOutput = Vector(0, 0, 0);
				if (!GetPhysicsVectorFromValue(pIsolate, LocalContext, LocalPhysicsObjectVectorTransformArgument, PhysicsObjectVectorTransformInput) || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, pszPhysicsObjectVectorTransformArgumentErrorMessage);
					return;
				}

				switch (VectorTransformOperation) {
					case PhysicsObjectVectorTransformOperation::PhysicsObjectVectorTransformLocalToWorld:
						pPhysicsObject->LocalToWorld(&PhysicsObjectVectorTransformOutput, PhysicsObjectVectorTransformInput);
						break;

					case PhysicsObjectVectorTransformOperation::PhysicsObjectVectorTransformWorldToLocal:
						pPhysicsObject->WorldToLocal(&PhysicsObjectVectorTransformOutput, PhysicsObjectVectorTransformInput);
						break;

					case PhysicsObjectVectorTransformOperation::PhysicsObjectVectorTransformLocalToWorldVector:
						pPhysicsObject->LocalToWorldVector(&PhysicsObjectVectorTransformOutput, PhysicsObjectVectorTransformInput);
						break;

					case PhysicsObjectVectorTransformOperation::PhysicsObjectVectorTransformWorldToLocalVector:
						pPhysicsObject->WorldToLocalVector(&PhysicsObjectVectorTransformOutput, PhysicsObjectVectorTransformInput);
						break;

					default:
						RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kPhysicsObjectVectorTransformUnknownOperationErrorMessage);
						return;
				}

				if (PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				v8::Local<v8::Object> const LocalPhysicsObjectVectorTransformResultObject = MakePhysicsVectorObject(pIsolate, LocalContext, PhysicsObjectVectorTransformOutput);
				if (LocalPhysicsObjectVectorTransformResultObject.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalPhysicsObjectVectorTransformResultObject);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
			}
		}

