		void GetPhysicsObjectContactPointCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char const* const kFailureErrorMessage = "physics contact point query failed.";
			constexpr char const* const kPhysicsObjectContactPointHitPropertyName = "Hit";
			constexpr char const* const kPhysicsObjectContactPointVectorPropertyName = "Point";
			constexpr char const* const kPhysicsObjectContactPointObjectPropertyName = "Object";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch PhysicsFailure(pIsolate);
			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				auto* const pPhysicsObject = RequirePhysicsObjectFromThis(CallbackInformation);
				if (!pPhysicsObject || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				Vector PhysicsObjectContactPoint = Vector(0, 0, 0);
				IPhysicsObject* pContactPhysicsObject = nullptr;
				const bool bPhysicsObjectContactPointHit = pPhysicsObject->GetContactPoint(&PhysicsObjectContactPoint, &pContactPhysicsObject);
				if (PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				v8::Local<v8::Object> const LocalPhysicsObjectContactPointResultObject = v8::Object::New(pIsolate);
				if (LocalPhysicsObjectContactPointResultObject.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				if (!InstallPhysicsValue(pIsolate, LocalContext, LocalPhysicsObjectContactPointResultObject, kPhysicsObjectContactPointHitPropertyName, v8::Boolean::New(pIsolate, bPhysicsObjectContactPointHit)) || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				v8::Local<v8::Object> const LocalPhysicsObjectContactPointVectorObject = MakePhysicsVectorObject(pIsolate, LocalContext, PhysicsObjectContactPoint);
				if (LocalPhysicsObjectContactPointVectorObject.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				if (!InstallPhysicsValue(pIsolate, LocalContext, LocalPhysicsObjectContactPointResultObject, kPhysicsObjectContactPointVectorPropertyName, LocalPhysicsObjectContactPointVectorObject) || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				auto MakePhysicsObjectContactObjectValue = [pIsolate, LocalContext, bPhysicsObjectContactPointHit, pContactPhysicsObject, &PhysicsFailure]() -> v8::Local<v8::Value> {
					if (!bPhysicsObjectContactPointHit || !pContactPhysicsObject) {
						return v8::Null(pIsolate);
					}

					v8::Local<v8::Object> const LocalPhysicsObjectContactObject = MakePhysicsObject(pIsolate, LocalContext, pContactPhysicsObject);
					if (LocalPhysicsObjectContactObject.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
						return {};
					}

					return LocalPhysicsObjectContactObject.As<v8::Value>();
				};

				v8::Local<v8::Value> const LocalPhysicsObjectContactObjectValue = MakePhysicsObjectContactObjectValue();
				if (LocalPhysicsObjectContactObjectValue.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				if (!InstallPhysicsValue(pIsolate, LocalContext, LocalPhysicsObjectContactPointResultObject, kPhysicsObjectContactPointObjectPropertyName, LocalPhysicsObjectContactObjectValue) || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				CallbackInformation.GetReturnValue().Set(LocalPhysicsObjectContactPointResultObject);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
			}
		}

