		void GetPhysicsEnvironmentActiveObjectsCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char const* const kFailureErrorMessage = "physics environment active object enumeration failed.";
			constexpr char const* const kPhysicsEnvironmentNegativeActiveObjectCountErrorMessage = "PhysicsEnvironment.ActiveObjects() received a negative object count from the SDK.";
			constexpr char const* const kPhysicsEnvironmentNullActivePhysicsObjectErrorMessage = "PhysicsEnvironment.ActiveObjects() received a null physics object from the SDK.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch PhysicsFailure(pIsolate);
			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				auto* const pPhysicsEnvironment = RequirePhysicsEnvironmentFromThis(CallbackInformation);
				if (!pPhysicsEnvironment || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				const int nActivePhysicsObjectCount = pPhysicsEnvironment->GetActiveObjectCount();
				if (PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				if (nActivePhysicsObjectCount < 0) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kPhysicsEnvironmentNegativeActiveObjectCountErrorMessage);
					return;
				}

				std::vector<IPhysicsObject*> vecActivePhysicsObjects = std::vector<IPhysicsObject*>(static_cast<std::size_t>(nActivePhysicsObjectCount), nullptr);
				if (nActivePhysicsObjectCount > 0) {
					pPhysicsEnvironment->GetActiveObjects(vecActivePhysicsObjects.data());
					if (PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
						return;
					}
				}

				v8::Local<v8::Array> const LocalActivePhysicsObjectArray = v8::Array::New(pIsolate, nActivePhysicsObjectCount);
				if (LocalActivePhysicsObjectArray.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
					return;
				}

				for (int nActivePhysicsObjectIndex = 0; nActivePhysicsObjectIndex < nActivePhysicsObjectCount; ++nActivePhysicsObjectIndex) {
					auto* const pActivePhysicsObject = vecActivePhysicsObjects[static_cast<std::size_t>(nActivePhysicsObjectIndex)];
					if (!pActivePhysicsObject || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kPhysicsEnvironmentNullActivePhysicsObjectErrorMessage);
						return;
					}

					v8::Local<v8::Object> const LocalActivePhysicsObject = MakePhysicsObject(pIsolate, LocalContext, pActivePhysicsObject);
					if (LocalActivePhysicsObject.IsEmpty() || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
						return;
					}

					const std::uint32_t unActivePhysicsObjectIndex = static_cast<std::uint32_t>(nActivePhysicsObjectIndex);
					v8::Maybe<bool> const MaybeCreationResult = LocalActivePhysicsObjectArray->CreateDataProperty(LocalContext, unActivePhysicsObjectIndex, LocalActivePhysicsObject);
					if (!MaybeCreationResult.FromMaybe(false) || PhysicsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
						return;
					}
				}

				CallbackInformation.GetReturnValue().Set(LocalActivePhysicsObjectArray);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, PhysicsFailure, kFailureErrorMessage);
			}
		}

