		bool ParseExtensionStringArgument(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, char const* const pszInvalidExtensionValueErrorMessage, std::string& strExtensionValueOut) {
			constexpr char const* const kFailureErrorMessage = "extensions string argument parsing failed.";
			constexpr int kExtensionValueArgumentIndex = 0;
			constexpr int kExtensionStringRequiredArgumentCount = 1;

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate || !pszInvalidExtensionValueErrorMessage || !*pszInvalidExtensionValueErrorMessage) {
				return false;
			}

			v8::TryCatch ManagerFailure(pIsolate);
			try {
				if (ManagerFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
					return false;
				}

				if (CallbackInformation.Length() < kExtensionStringRequiredArgumentCount) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, pszInvalidExtensionValueErrorMessage);
					return false;
				}

				v8::Local<v8::Value> const LocalExtensionValue = CallbackInformation[kExtensionValueArgumentIndex];
				if (LocalExtensionValue.IsEmpty() || ManagerFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, pszInvalidExtensionValueErrorMessage);
					return false;
				}

				if (!LocalExtensionValue->IsString()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, pszInvalidExtensionValueErrorMessage);
					return false;
				}

				std::string strExtensionValue = ValueToString(pIsolate, LocalExtensionValue);
				if (ManagerFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
					return false;
				}

				if (strExtensionValue.empty()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, pszInvalidExtensionValueErrorMessage);
					return false;
				}

				strExtensionValueOut = std::move(strExtensionValue);

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
			}

			return false;
		}

		void ListExtensionsCallback(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation) {
			constexpr char const* const kFailureErrorMessage = "extensions list query failed.";
			constexpr char const* const kExtensionListExcessiveLineCountErrorMessage = "extensions.List() received too many extension lines.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch ManagerFailure(pIsolate);
			try {
				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty() || ManagerFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
					return;
				}

				std::vector<std::string> const vecExtensionLines = g_Application.GetExtensionManager().List();
				if (ManagerFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
					return;
				}

				const std::size_t unExtensionLineCount = vecExtensionLines.size();
				if (unExtensionLineCount > static_cast<std::size_t>(std::numeric_limits<int>::max())) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, kExtensionListExcessiveLineCountErrorMessage);
					return;
				}

				const int nExtensionLineCount = static_cast<int>(unExtensionLineCount);
				v8::Local<v8::Array> const LocalExtensionLinesArray = v8::Array::New(pIsolate, nExtensionLineCount);
				if (LocalExtensionLinesArray.IsEmpty() || ManagerFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
					return;
				}

				for (std::size_t unExtensionLineIndex = 0; unExtensionLineIndex < unExtensionLineCount; ++unExtensionLineIndex) {
					v8::Local<v8::String> const LocalExtensionLine = MakeString(pIsolate, vecExtensionLines[unExtensionLineIndex]);
					if (LocalExtensionLine.IsEmpty() || ManagerFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
						return;
					}

					const std::uint32_t unExtensionLineArrayIndex = static_cast<std::uint32_t>(unExtensionLineIndex);
					v8::Maybe<bool> const MaybeCreationResult = LocalExtensionLinesArray->CreateDataProperty(LocalContext, unExtensionLineArrayIndex, LocalExtensionLine);
					if (!MaybeCreationResult.FromMaybe(false) || ManagerFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
						return;
					}
				}

				CallbackInformation.GetReturnValue().Set(LocalExtensionLinesArray);
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
			}
		}

