		int AllocateExternalHandle() {
			static std::uintmax_t s_unNextExternalHandle = 1;
			if (s_unNextExternalHandle > static_cast<std::uintmax_t>(std::numeric_limits<int>::max())) {
				throw std::overflow_error("External handle space exhausted.");
			}

			const int nExternalHandle = static_cast<int>(s_unNextExternalHandle);
			++s_unNextExternalHandle;

			return nExternalHandle;
		}

		bool RequireExternalPluginName(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, std::string& strPluginNameOut) {
			constexpr char const* const kFailureErrorMessage = "External resource runtime lookup failed.";
			constexpr char const* const kExternalPluginNameMissingRuntimeContextErrorMessage = "External resource access requires a SourceJS runtime context.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate) {
				return false;
			}

			v8::TryCatch ManagerFailure(pIsolate);
			try {
				if (ManagerFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
					return false;
				}

				auto* const pRuntime = GetRuntimeFromCallbackInformation(CallbackInformation);
				if (ManagerFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
					return false;
				}

				if (!pRuntime) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, kExternalPluginNameMissingRuntimeContextErrorMessage);
					return false;
				}

				std::string strPluginName {};
				if (!pRuntime->GetCurrentPluginName(pIsolate, strPluginName) || ManagerFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, kExternalPluginNameMissingRuntimeContextErrorMessage);
					return false;
				}

				strPluginNameOut = std::move(strPluginName);

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
			}

			return false;
		}

		bool ParseExternalHandleFromValue(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Value> const LocalExternalHandleValue, int& nExternalHandleOut) {
			constexpr char const* const kFailureErrorMessage = "External resource handle parsing failed.";
			constexpr char const* const kExternalHandlePropertyName = "Handle";

			if (!pIsolate || LocalContext.IsEmpty() || LocalExternalHandleValue.IsEmpty()) {
				return false;
			}

			v8::TryCatch ManagerFailure(pIsolate);
			try {
				if (ManagerFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
					return false;
				}

				int nExternalHandle = 0;
				const bool bIntegerParsed = GetIntegerFromValue(LocalContext, LocalExternalHandleValue, nExternalHandle);
				if (ManagerFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
					return false;
				}

				if (bIntegerParsed) {
					if (nExternalHandle <= 0) {
						return false;
					}

					nExternalHandleOut = nExternalHandle;

					return true;
				}

				if (!LocalExternalHandleValue->IsObject()) {
					return false;
				}

				v8::Local<v8::Object> const LocalExternalHandleObject = LocalExternalHandleValue.As<v8::Object>();
				if (LocalExternalHandleObject.IsEmpty()) {
					return false;
				}

				const bool bObjectIntegerParsed = GetObjectInteger(pIsolate, LocalContext, LocalExternalHandleObject, kExternalHandlePropertyName, nExternalHandle);
				if (ManagerFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
					return false;
				}

				if (!bObjectIntegerParsed || (nExternalHandle <= 0)) {
					return false;
				}

				nExternalHandleOut = nExternalHandle;

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
			}

			return false;
		}

		bool ParseRequiredExternalStringArgument(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, const int nExternalStringArgumentIndex, char const* const pszInvalidExternalStringValueErrorMessage, const bool bAllowEmptyExternalString, std::string& strExternalStringOut) {
			constexpr char const* const kFailureErrorMessage = "External resource string argument parsing failed.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate || !pszInvalidExternalStringValueErrorMessage || !*pszInvalidExternalStringValueErrorMessage) {
				return false;
			}

			v8::TryCatch ManagerFailure(pIsolate);
			try {
				if (ManagerFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
					return false;
				}

				if (nExternalStringArgumentIndex < 0) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, pszInvalidExternalStringValueErrorMessage);
					return false;
				}

				if (nExternalStringArgumentIndex >= CallbackInformation.Length()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, pszInvalidExternalStringValueErrorMessage);
					return false;
				}

				v8::Local<v8::Value> const LocalExternalStringValue = CallbackInformation[nExternalStringArgumentIndex];
				if (LocalExternalStringValue.IsEmpty() || ManagerFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, pszInvalidExternalStringValueErrorMessage);
					return false;
				}

				if (LocalExternalStringValue->IsNullOrUndefined()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, pszInvalidExternalStringValueErrorMessage);
					return false;
				}

				if (!LocalExternalStringValue->IsString()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, pszInvalidExternalStringValueErrorMessage);
					return false;
				}

				std::string strExternalString = ValueToString(pIsolate, LocalExternalStringValue);
				if (ManagerFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
					return false;
				}

				if (!bAllowEmptyExternalString && strExternalString.empty()) {
					RethrowV8InstallationFailure(pIsolate, ManagerFailure, pszInvalidExternalStringValueErrorMessage);
					return false;
				}

				strExternalStringOut = std::move(strExternalString);

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, ManagerFailure, kFailureErrorMessage);
			}

			return false;
		}

		bool ParseExternalStringFromValue(v8::Isolate* const pIsolate, v8::Local<v8::Value> const LocalExternalStringValue, char const* const pszInvalidExternalStringValueErrorMessage, const bool bAllowEmptyExternalString, std::string& strExternalStringOut) {
			constexpr char const* const kFailureErrorMessage = "External resource string value parsing failed.";

			if (!pIsolate || !pszInvalidExternalStringValueErrorMessage || !*pszInvalidExternalStringValueErrorMessage) {
				return false;
			}

			v8::TryCatch ExternalFailure(pIsolate);
			try {
				if (ExternalFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ExternalFailure, kFailureErrorMessage);
					return false;
				}

				if (LocalExternalStringValue.IsEmpty() || ExternalFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ExternalFailure, pszInvalidExternalStringValueErrorMessage);
					return false;
				}

				if (IsValueNullish(LocalExternalStringValue)) {
					RethrowV8InstallationFailure(pIsolate, ExternalFailure, pszInvalidExternalStringValueErrorMessage);
					return false;
				}

				if (!LocalExternalStringValue->IsString()) {
					RethrowV8InstallationFailure(pIsolate, ExternalFailure, pszInvalidExternalStringValueErrorMessage);
					return false;
				}

				std::string strExternalString = ValueToString(pIsolate, LocalExternalStringValue);
				if (ExternalFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ExternalFailure, kFailureErrorMessage);
					return false;
				}

				if (!bAllowEmptyExternalString && strExternalString.empty()) {
					RethrowV8InstallationFailure(pIsolate, ExternalFailure, pszInvalidExternalStringValueErrorMessage);
					return false;
				}

				strExternalStringOut = std::move(strExternalString);

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, ExternalFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, ExternalFailure, kFailureErrorMessage);
			}

			return false;
		}

		bool ParseOptionalExternalStringArgument(v8::FunctionCallbackInfo<v8::Value> const& CallbackInformation, const int nExternalStringArgumentIndex, char const* const pszInvalidExternalStringValueErrorMessage, const bool bAllowEmptyExternalString, std::string& strExternalStringOut) {
			constexpr char const* const kFailureErrorMessage = "External resource optional string argument parsing failed.";

			auto* const pIsolate = CallbackInformation.GetIsolate();
			if (!pIsolate || !pszInvalidExternalStringValueErrorMessage || !*pszInvalidExternalStringValueErrorMessage) {
				return false;
			}

			v8::TryCatch ExternalFailure(pIsolate);
			try {
				if (ExternalFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ExternalFailure, kFailureErrorMessage);
					return false;
				}

				if (nExternalStringArgumentIndex < 0) {
					RethrowV8InstallationFailure(pIsolate, ExternalFailure, pszInvalidExternalStringValueErrorMessage);
					return false;
				}

				if (nExternalStringArgumentIndex >= CallbackInformation.Length()) {
					strExternalStringOut.clear();
					return true;
				}

				v8::Local<v8::Value> const LocalExternalStringArgumentValue = CallbackInformation[nExternalStringArgumentIndex];
				if (LocalExternalStringArgumentValue.IsEmpty() || ExternalFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ExternalFailure, pszInvalidExternalStringValueErrorMessage);
					return false;
				}

				if (IsValueNullish(LocalExternalStringArgumentValue)) {
					strExternalStringOut.clear();
					return true;
				}

				std::string strExternalString {};
				const bool bStringParsed = ParseExternalStringFromValue(pIsolate, LocalExternalStringArgumentValue, pszInvalidExternalStringValueErrorMessage, bAllowEmptyExternalString, strExternalString);
				if (ExternalFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ExternalFailure, kFailureErrorMessage);
					return false;
				}

				if (!bStringParsed) {
					return false;
				}

				strExternalStringOut = std::move(strExternalString);

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, ExternalFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, ExternalFailure, kFailureErrorMessage);
			}

			return false;
		}

