		bool ParseExternalInt32FromValue(v8::Isolate* const pIsolate, v8::Local<v8::Value> const LocalExternalInt32Value, char const* const pszInvalidExternalInt32ValueErrorMessage, int& nExternalInt32Out) {
			constexpr char const* const kFailureErrorMessage = "External resource signed integer parsing failed.";

			if (!pIsolate || !pszInvalidExternalInt32ValueErrorMessage || !*pszInvalidExternalInt32ValueErrorMessage) {
				return false;
			}

			v8::TryCatch ExternalFailure(pIsolate);
			try {
				if (ExternalFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ExternalFailure, kFailureErrorMessage);
					return false;
				}

				if (LocalExternalInt32Value.IsEmpty() || ExternalFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ExternalFailure, pszInvalidExternalInt32ValueErrorMessage);
					return false;
				}

				if (IsValueNullish(LocalExternalInt32Value)) {
					RethrowV8InstallationFailure(pIsolate, ExternalFailure, pszInvalidExternalInt32ValueErrorMessage);
					return false;
				}

				if (!LocalExternalInt32Value->IsNumber()) {
					RethrowV8InstallationFailure(pIsolate, ExternalFailure, pszInvalidExternalInt32ValueErrorMessage);
					return false;
				}

				v8::Local<v8::Number> const LocalExternalInt32Number = LocalExternalInt32Value.As<v8::Number>();
				if (LocalExternalInt32Number.IsEmpty() || ExternalFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ExternalFailure, pszInvalidExternalInt32ValueErrorMessage);
					return false;
				}

				const double dblExternalInt32Value = LocalExternalInt32Number->Value();
				if (!std::isfinite(dblExternalInt32Value) || (std::floor(dblExternalInt32Value) != dblExternalInt32Value) || (dblExternalInt32Value < static_cast<double>(std::numeric_limits<int>::min())) || (dblExternalInt32Value > static_cast<double>(std::numeric_limits<int>::max())) || ExternalFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ExternalFailure, pszInvalidExternalInt32ValueErrorMessage);
					return false;
				}

				nExternalInt32Out = static_cast<int>(dblExternalInt32Value);

				return true;
			} catch (std::exception const&) {
				RethrowV8InstallationFailure(pIsolate, ExternalFailure, kFailureErrorMessage);
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, ExternalFailure, kFailureErrorMessage);
			}

			return false;
		}

