		void ExecuteRedisCommandCallback(v8::FunctionCallbackInfo<v8::Value> const& RedisCommandCallbackInformation) {
			constexpr int kRedisCommandRequiredArgumentCount = 3;
			constexpr char const* const kRedisCommandCallbackErrorMessage = "redis.command(nRedisClientHandle, strRedisCommand, ...strRedisCommandArguments, Options, Callback) expects options and a callback.";
			constexpr char const* const kRedisCommandBlockingOptionErrorMessage = "redis.command Blocking option must be a boolean.";
			constexpr char const* const kRedisCommandRequestFailureErrorMessage = "redis.command request failed.";
			constexpr char const* const kInvalidRedisCommandReplyErrorMessage = "redis.command returned an invalid reply value.";
			constexpr char const* const kUnknownRedisCommandFailureErrorMessage = "redis.command failed because of an unknown native exception.";

			auto* const pIsolate = RedisCommandCallbackInformation.GetIsolate();
			if (!pIsolate) {
				return;
			}

			v8::TryCatch RedisFailure(pIsolate);
			try {
				if (RedisFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, RedisFailure, kUnknownRedisCommandFailureErrorMessage);
					return;
				}

				const int nRedisCommandOptionalArgumentCount = RedisCommandCallbackInformation.Length() - (kRedisCommandRequiredArgumentCount + 1);
				RedisRequestExecutionMode ExecutionMode {};
				if (!ParseRedisRequestExecutionMode(RedisCommandCallbackInformation, pIsolate, kRedisCommandRequiredArgumentCount, kRedisCommandCallbackErrorMessage, kRedisCommandBlockingOptionErrorMessage, ExecutionMode, nRedisCommandOptionalArgumentCount) || RedisFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, RedisFailure, kRedisCommandCallbackErrorMessage);
					return;
				}

				std::shared_ptr<sw::redis::Redis> const pRedisClient = AcquireRedisClientFromCallbackInformation(RedisCommandCallbackInformation);
				if (!pRedisClient || RedisFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, RedisFailure, kRedisCommandRequestFailureErrorMessage);
					return;
				}

				const int nCommandArgumentEndExclusive = RedisCommandCallbackInformation.Length() - 2;
				std::vector<std::string> vecRedisCommandParts {};
				if (!ParseRedisCommandArguments(RedisCommandCallbackInformation, nCommandArgumentEndExclusive, vecRedisCommandParts) || RedisFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, RedisFailure, kRedisCommandRequestFailureErrorMessage);
					return;
				}

				auto Operation = [pRedisClient, vecRedisCommandParts = std::move(vecRedisCommandParts)]() -> std::shared_ptr<redisReply> {
					sw::redis::ReplyUPtr RedisCommandReply = pRedisClient->command(vecRedisCommandParts.begin(), vecRedisCommandParts.end());
					std::shared_ptr<redisReply> pRedisCommandReply = std::move(RedisCommandReply);

					return pRedisCommandReply;
				};

				auto ConvertResult = [](v8::Isolate* const pResultIsolate, v8::Local<v8::Context> const LocalResultContext, std::shared_ptr<redisReply> const& pRedisCommandReply) -> v8::MaybeLocal<v8::Value> {
					if (!pResultIsolate || LocalResultContext.IsEmpty()) {
						return {};
					}

					v8::TryCatch RedisResultFailure(pResultIsolate);
					try {
						if (!pRedisCommandReply || RedisResultFailure.HasCaught() || pResultIsolate->IsExecutionTerminating() || pResultIsolate->HasPendingException()) {
							RethrowV8InstallationFailure(pResultIsolate, RedisResultFailure, kInvalidRedisCommandReplyErrorMessage);
							return {};
						}

						v8::Local<v8::Value> const LocalRedisCommandReply = MakeRedisReplyValue(pResultIsolate, LocalResultContext, pRedisCommandReply.get());
						if (LocalRedisCommandReply.IsEmpty() || RedisResultFailure.HasCaught() || pResultIsolate->IsExecutionTerminating() || pResultIsolate->HasPendingException()) {
							RethrowV8InstallationFailure(pResultIsolate, RedisResultFailure, kInvalidRedisCommandReplyErrorMessage);
							return {};
						}

						return LocalRedisCommandReply;
					} catch (std::exception const&) {
						RethrowV8InstallationFailure(pResultIsolate, RedisResultFailure, kInvalidRedisCommandReplyErrorMessage);
					} catch (...) {
						RethrowV8InstallationFailure(pResultIsolate, RedisResultFailure, kInvalidRedisCommandReplyErrorMessage);
					}

					return {};
				};

				v8::Local<v8::Context> const LocalContext = pIsolate->GetCurrentContext();
				if (LocalContext.IsEmpty() || RedisFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, RedisFailure, kRedisCommandRequestFailureErrorMessage);
					return;
				}

				auto* const pRuntime = GetRuntimeFromCallbackInformation(RedisCommandCallbackInformation);
				if (!pRuntime || RedisFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, RedisFailure, kRedisCommandRequestFailureErrorMessage);
					return;
				}

				if (!RunRedisRequest<std::shared_ptr<redisReply>>(pRuntime, pIsolate, LocalContext, ExecutionMode, kRedisCommandRequestFailureErrorMessage, kInvalidRedisCommandReplyErrorMessage, std::move(Operation), ConvertResult) || RedisFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, RedisFailure, kRedisCommandRequestFailureErrorMessage);
					return;
				}
			} catch (std::exception const& Exception) {
				RethrowV8InstallationFailure(pIsolate, RedisFailure, Exception.what());
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, RedisFailure, kUnknownRedisCommandFailureErrorMessage);
			}
		}

		v8::MaybeLocal<v8::Value> MakeRedisOptionalStringValue(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, sw::redis::OptionalString const& OptionalRedisStringValue) {
			if (!pIsolate || LocalContext.IsEmpty()) {
				return {};
			}

			if (!OptionalRedisStringValue) {
				return v8::Null(pIsolate);
			}

			return MakeString(pIsolate, OptionalRedisStringValue.value());
		}

