		bool ParseOptionalExternalStringMapProperty(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalExternalStringMapPropertyContext, v8::Local<v8::Object> const LocalExternalStringMapPropertyOwnerObject, char const* const pszExternalStringMapPropertyName, char const* const pszExternalStringMapContainerErrorMessage, char const* const pszExternalStringMapEntryErrorMessage, std::map<std::string, std::string>& mapExternalStringValuesOut) {
			constexpr bool kAllowEmptyExternalStringMapKeys = true;
			constexpr char const* const kUnknownExternalStringMapPropertyFailureErrorMessage = "Reading an external string-map property failed because of an unknown native exception.";

			if (!pIsolate || LocalExternalStringMapPropertyContext.IsEmpty() || LocalExternalStringMapPropertyOwnerObject.IsEmpty() || !pszExternalStringMapPropertyName || !pszExternalStringMapContainerErrorMessage || !pszExternalStringMapEntryErrorMessage) {
				return false;
			}

			v8::TryCatch ExternalStringMapFailure(pIsolate);
			try {
				if (ExternalStringMapFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ExternalStringMapFailure, kUnknownExternalStringMapPropertyFailureErrorMessage);
					return false;
				}

				v8::Local<v8::String> const LocalExternalStringMapPropertyName = MakeString(pIsolate, pszExternalStringMapPropertyName);
				if (LocalExternalStringMapPropertyName.IsEmpty() || ExternalStringMapFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ExternalStringMapFailure, pszExternalStringMapContainerErrorMessage);
					return false;
				}

				v8::Local<v8::Value> LocalExternalStringMapPropertyValue {};
				if (!LocalExternalStringMapPropertyOwnerObject->Get(LocalExternalStringMapPropertyContext, LocalExternalStringMapPropertyName).ToLocal(&LocalExternalStringMapPropertyValue) || LocalExternalStringMapPropertyValue.IsEmpty() || ExternalStringMapFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ExternalStringMapFailure, pszExternalStringMapContainerErrorMessage);
					return false;
				}

				if (IsValueNullish(LocalExternalStringMapPropertyValue)) {
					return true;
				}

				if (!ParseExternalStringMapFromValue(pIsolate, LocalExternalStringMapPropertyContext, LocalExternalStringMapPropertyValue, pszExternalStringMapContainerErrorMessage, pszExternalStringMapEntryErrorMessage, kAllowEmptyExternalStringMapKeys, mapExternalStringValuesOut) || ExternalStringMapFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, ExternalStringMapFailure, pszExternalStringMapEntryErrorMessage);
					return false;
				}

				return true;
			} catch (std::exception const& Exception) {
				RethrowV8InstallationFailure(pIsolate, ExternalStringMapFailure, Exception.what());
				return false;
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, ExternalStringMapFailure, kUnknownExternalStringMapPropertyFailureErrorMessage);
				return false;
			}
		}

