		bool InstallPathConstants(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalPathConstantsContext, v8::Local<v8::Object> const LocalPathModuleObject, RuntimePaths const& RuntimePathsInformation) {
			constexpr char const* const kPathConstantsFailureErrorMessage = "Could not install runtime path constants.";

			if (!pIsolate || LocalPathConstantsContext.IsEmpty() || LocalPathModuleObject.IsEmpty()) {
				return false;
			}

			v8::TryCatch PathConstantsFailure(pIsolate);
			try {
				if (PathConstantsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
					RethrowV8InstallationFailure(pIsolate, PathConstantsFailure, kPathConstantsFailureErrorMessage);
					return false;
				}

				std::filesystem::path const PathGameRoot = RuntimePathsInformation.GetGameRootPath();
				std::filesystem::path const PathAddonRoot = RuntimePathsInformation.GetAddonRootPath();
				std::filesystem::path const PathPackageRoot = RuntimePathsInformation.GetPackageRootPath();
				std::filesystem::path const PathDataRoot = RuntimePathsInformation.GetDataPath();
				std::filesystem::path const PathConfigurationRoot = PathGameRoot / "cfg" / "sourcejs";
				std::filesystem::path const PathLogRoot = PathGameRoot / "logs" / "sourcejs";
				std::filesystem::path const PathDocumentationRoot = PathAddonRoot / "docs";
				std::filesystem::path const PathResourceRoot = PathGameRoot / "resource" / "sourcejs";
				std::filesystem::path const PathAuthenticationConfigurationRoot = PathConfigurationRoot / "auth";
				std::filesystem::path const PathUpdateRoot = PathAddonRoot / "update";

				auto InstallPathConstant = [pIsolate, LocalPathConstantsContext, LocalPathModuleObject, &PathConstantsFailure](char const* const pszPropertyName, std::filesystem::path const& PathValue) -> bool {
					v8::Local<v8::String> const LocalPathValue = MakeString(pIsolate, EncodePathAsUTF8(PathValue));
					if (LocalPathValue.IsEmpty() || PathConstantsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, PathConstantsFailure, kPathConstantsFailureErrorMessage);
						return false;
					}

					v8::Local<v8::String> const LocalPropertyName = MakeString(pIsolate, pszPropertyName);
					if (LocalPropertyName.IsEmpty() || PathConstantsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, PathConstantsFailure, kPathConstantsFailureErrorMessage);
						return false;
					}

					if (!LocalPathModuleObject->CreateDataProperty(LocalPathConstantsContext, LocalPropertyName, LocalPathValue).FromMaybe(false) || PathConstantsFailure.HasCaught() || pIsolate->IsExecutionTerminating() || pIsolate->HasPendingException()) {
						RethrowV8InstallationFailure(pIsolate, PathConstantsFailure, kPathConstantsFailureErrorMessage);
						return false;
					}

					return true;
				};

				if (!InstallPathConstant("GAME_ROOT", PathGameRoot)) {
					return false;
				}

				if (!InstallPathConstant("ADDON_ROOT", PathGameRoot / "addons")) {
					return false;
				}

				if (!InstallPathConstant("DATA_ROOT", PathDataRoot)) {
					return false;
				}

				if (!InstallPathConstant("PLUGIN_ROOT", RuntimePathsInformation.GetPluginRootPath())) {
					return false;
				}

				if (!InstallPathConstant("EXTENSION_ROOT", RuntimePathsInformation.GetExtensionRootPath())) {
					return false;
				}

				if (!InstallPathConstant("PACKAGE_ROOT", PathPackageRoot)) {
					return false;
				}

				if (!InstallPathConstant("BASE_ROOT", PathAddonRoot)) {
					return false;
				}

				if (!InstallPathConstant("UPDATE_ROOT", PathUpdateRoot)) {
					return false;
				}

				if (!InstallPathConstant("UPDATE_DATA_ROOT", PathUpdateRoot / "addons" / "sourcejs" / "data")) {
					return false;
				}

				if (!InstallPathConstant("UPDATE_SOURCE_DATA_ROOT", PathUpdateRoot / "addons" / "sourcejs" / "data" / "sourcejs")) {
					return false;
				}

				if (!InstallPathConstant("DOCS_ROOT", PathDocumentationRoot)) {
					return false;
				}

				if (!InstallPathConstant("SOURCE_DOCS_ROOT", PathDocumentationRoot / "sourcejs")) {
					return false;
				}

				if (!InstallPathConstant("PLUGIN_DOCS_ROOT", PathDocumentationRoot / "plugins")) {
					return false;
				}

				if (!InstallPathConstant("CUSTOM_PACKAGE_DOCS_ROOT", PathDocumentationRoot / "custom")) {
					return false;
				}

				if (!InstallPathConstant("SOURCE_PACKAGE_ROOT", PathPackageRoot / "sourcejs")) {
					return false;
				}

				if (!InstallPathConstant("CUSTOM_PACKAGE_ROOT", PathPackageRoot / "custom")) {
					return false;
				}

				if (!InstallPathConstant("SITE_PACKAGE_ROOT", PathPackageRoot / "site-packages")) {
					return false;
				}

				if (!InstallPathConstant("CONFIG_ROOT", PathConfigurationRoot)) {
					return false;
				}

				if (!InstallPathConstant("LOG_ROOT", PathLogRoot)) {
					return false;
				}

				if (!InstallPathConstant("TRANSLATION_ROOT", PathResourceRoot / "translations")) {
					return false;
				}

				if (!InstallPathConstant("LANGUAGE_FILE", PathDataRoot / "languages.ini")) {
					return false;
				}

				if (!InstallPathConstant("TRANSLATION_CORE_ROOT", PathResourceRoot / "translations" / "_core")) {
					return false;
				}

				if (!InstallPathConstant("TRANSLATION_CORE_FILE", PathResourceRoot / "translations" / "_core" / "translations_strings.ini")) {
					return false;
				}

				if (!InstallPathConstant("EVENT_ROOT", PathResourceRoot / "events")) {
					return false;
				}

				if (!InstallPathConstant("SOUND_ROOT", PathGameRoot / "sound" / "sourcejs")) {
					return false;
				}

				if (!InstallPathConstant("SOURCE_DATA_ROOT", PathDataRoot / "sourcejs")) {
					return false;
				}

				if (!InstallPathConstant("CUSTOM_DATA_ROOT", PathDataRoot / "custom")) {
					return false;
				}

				if (!InstallPathConstant("PLUGIN_DATA_ROOT", PathDataRoot / "plugins")) {
					return false;
				}

				if (!InstallPathConstant("AUTH_CONFIG_ROOT", PathAuthenticationConfigurationRoot)) {
					return false;
				}

				if (!InstallPathConstant("BACKEND_ROOT", PathPackageRoot / "sourcejs" / "auth" / "backends")) {
					return false;
				}

				if (!InstallPathConstant("BACKEND_CONFIG_FILE", PathAuthenticationConfigurationRoot / "permissions.ini")) {
					return false;
				}

				if (!InstallPathConstant("AUTH_PLAYERS_FILE", PathAuthenticationConfigurationRoot / "players.json")) {
					return false;
				}

				if (!InstallPathConstant("AUTH_PARENTS_FILE", PathAuthenticationConfigurationRoot / "parents.json")) {
					return false;
				}

				if (!InstallPathConstant("AUTH_SIMPLE_FILE", PathAuthenticationConfigurationRoot / "simple.txt")) {
					return false;
				}

				if (!InstallPathConstant("AUTH_SQL_FILE", PathAuthenticationConfigurationRoot / "permissions.sqlite3")) {
					return false;
				}

				return true;
			} catch (std::exception const& Exception) {
				RethrowV8InstallationFailure(pIsolate, PathConstantsFailure, Exception.what());
				return false;
			} catch (...) {
				RethrowV8InstallationFailure(pIsolate, PathConstantsFailure, kPathConstantsFailureErrorMessage);
				return false;
			}
		}

