		bool InstallModule(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalModuleInstallationContext, v8::Local<v8::Object> const LocalSourceJSModuleObject, char const* const pszModuleName, v8::Local<v8::Object> const LocalInstalledModuleObject) {
			if (!pIsolate || LocalModuleInstallationContext.IsEmpty() || LocalSourceJSModuleObject.IsEmpty() || !pszModuleName || !pszModuleName[0] || LocalInstalledModuleObject.IsEmpty()) {
				return false;
			}

			if (!SetValue(pIsolate, LocalModuleInstallationContext, LocalSourceJSModuleObject, pszModuleName, LocalInstalledModuleObject)) {
				return false;
			}

			g_Application.GetModuleRegistry().RegisterNativeModule(pszModuleName);

			return true;
		}

		template <bool bAvailable>
		bool InstallSDKFunction(v8::Isolate* const pIsolate, v8::Local<v8::Context> const LocalContext, v8::Local<v8::Object> const LocalTargetModule, char const* const pszFunctionName, v8::FunctionCallback const Callback, v8::Local<v8::Value> const LocalCallbackData) {
			if constexpr (!bAvailable) {
				return true;
			}

			if (!pIsolate || LocalContext.IsEmpty() || LocalTargetModule.IsEmpty() || !pszFunctionName || !pszFunctionName[0] || !Callback) {
				return false;
			}

			return SetFunction(pIsolate, LocalContext, LocalTargetModule, pszFunctionName, Callback, LocalCallbackData);
		}

